function countryByCode(code) { return COUNTRIES_LIST.find(function(c){ return c.c === code; }); }
function countryFlag(code) { var c = countryByCode(code); return c ? c.f : '🏳️'; }
function countryFlagImg(code, size) {
  size = size || 18;
  var w = Math.round(size * 1.33);
  if (!code) {
    return '<span style="font-size:'+size+'px;line-height:1">🏳️</span>';
  }
  var lc = code.toLowerCase();
  return '<img src="https://flagcdn.com/w40/'+lc+'.png" data-cc="'+code+'" data-sz="'+size+'" alt="'+code+'" ' +
    'style="width:'+w+'px;height:'+size+'px;object-fit:cover;border-radius:var(--radius-2xs);vertical-align:middle;display:inline-block" ' +
    'onerror="flagImgFallback(this)" />';
}
// Rasm yuklanmasa (masalan internet uzilib qolsa), eski emoji-bayroqqa
// avtomatik qaytaradi — countryFlagImg() dagi <img onerror> shu funksiyani chaqiradi.
function flagImgFallback(img) {
  var code = img.getAttribute('data-cc');
  var size = img.getAttribute('data-sz') || 18;
  var span = document.createElement('span');
  span.style.fontSize = size + 'px';
  span.style.lineHeight = '1';
  span.textContent = countryFlag(code);
  img.replaceWith(span);
}
function countryName(code) { var c = countryByCode(code); return c ? c.n : ''; }

function targetSubjectMeta(code, otherLabel) {
  var map = {
    ielts: { icon: '📊', label: 'IELTS' },
    sat:   { icon: '📐', label: 'SAT' },
    cefr:  { icon: '📘', label: 'CEFR' },
    other: { icon: '📚', label: (otherLabel && otherLabel.trim()) ? otherLabel.trim() : t('pe_prep_none') }
  };
  return map[code] || map.other;
}

function renderSubjectBadgesHtml(subjects, size, otherLabel) {
  if (!subjects || !subjects.length) return '';
  var small = size === 'small';
  return subjects.map(function(code){
    var m = targetSubjectMeta(code, otherLabel);
    return '<span style="display:inline-flex;align-items:center;gap:3px;font-size:'+(small?'10px':'11.5px')+';font-weight:700;color:var(--accent);background:var(--accent-glow);border:1px solid var(--accent);border-radius:var(--radius-full);padding:'+(small?'2px 8px':'3px 10px')+'">'+m.icon+' '+esc(m.label)+'</span>';
  }).join(' ');
}

var SFX = (function () {
  var STORAGE_KEY = 'soundEnabled';
  var VOLUME_STORAGE_KEY = 'sfxVolume'; // 0..1 oralig'ida saqlanadi (Master Volume slider)
  var ctx = null;
  var master = null;      // barcha tovushlar shu orqali o'tadi — umumiy balandlik shu yerda cheklanadi
  var MASTER_CEILING = 0.25; // mayin, bezovta qilmaydigan umumiy balandlik (100% volume'dagi tepa nuqta)
  var enabled = true; // Alohida on/off switch olib tashlandi — endi mute faqat Master Volume (0%) orqali
  var volume = 1; // 0..1 — Master Volume slider qiymati (foizga bo'lingan)
  try {
    var savedVol = localStorage.getItem(VOLUME_STORAGE_KEY);
    volume = (savedVol === null) ? 1 : Math.max(0, Math.min(1, parseFloat(savedVol)));
    if (isNaN(volume)) volume = 1;
  } catch (e) { volume = 1; }

  function getCtx() {
    if (!ctx) {
      try {
        var AC = window.AudioContext || window.webkitAudioContext;
        ctx = new AC();
        master = ctx.createGain();
        master.gain.value = MASTER_CEILING * volume;
        master.connect(ctx.destination);
      } catch (e) { ctx = null; master = null; }
    }
    if (ctx && ctx.state === 'suspended') {
      try { ctx.resume(); } catch (e) {}
    }
    return ctx;
  }

  function unlockOnFirstGesture() {
    var c = getCtx();
    if (c && c.state === 'suspended') {
      try { c.resume(); } catch (e) {}
    }
  }
  ['pointerdown', 'touchstart', 'keydown'].forEach(function (evt) {
    document.addEventListener(evt, unlockOnFirstGesture, { once: true, passive: true });
  });

  function isOn() { return enabled; }

  function setEnabled(v) {
    enabled = !!v;
    try { localStorage.setItem(STORAGE_KEY, enabled ? '1' : '0'); } catch (e) {}
    return enabled;
  }

  function toggle() { return setEnabled(!enabled); }

  function getVolume() { return volume; }

  // v — 0..1 oralig'ida. localStorage'ga saqlaydi va agar AudioContext allaqachon
  // yaratilgan bo'lsa, joriy master gain'ni ham darhol (real-time) yangilaydi.
  function setVolume(v) {
    volume = Math.max(0, Math.min(1, v));
    try { localStorage.setItem(VOLUME_STORAGE_KEY, String(volume)); } catch (e) {}
    if (master) master.gain.value = MASTER_CEILING * volume;
    return volume;
  }

  // Test ovozi — "Sound Effects" o'chirilgan bo'lsa ham (foydalanuvchi sozlamani
  // eshitib ko'rishi uchun) vaqtincha yoqib, standart "coin" preset'ini chaladi.
  function playTest() {
    var wasEnabled = enabled;
    enabled = true;
    try { playCoin(); } finally { enabled = wasEnabled; }
  }

  // ---- Quyi darajadagi yordamchi generatorlar ----

  function applyADSR(gainNode, t0, cfg) {
    var peak    = Math.max(cfg.peak !== undefined ? cfg.peak : 0.5, 0.0001);
    var attack  = cfg.attack  !== undefined ? cfg.attack  : 0.03;
    var decay   = cfg.decay   !== undefined ? cfg.decay   : 0.16;
    var sustain = cfg.sustain !== undefined ? cfg.sustain : 0.4;   // sustain darajasi (peak'ga nisbatan, 0..1)
    var hold    = cfg.hold    !== undefined ? cfg.hold    : 0.03;  // sustain darajasida qancha tursin
    var release = cfg.release !== undefined ? cfg.release : 0.35;
    var sustainLevel = Math.max(peak * sustain, 0.0001);

    var g = gainNode.gain;
    g.cancelScheduledValues(t0);
    g.setValueAtTime(0.0001, t0);
    g.exponentialRampToValueAtTime(peak, t0 + attack);                 // Attack — yumshoq
    g.exponentialRampToValueAtTime(sustainLevel, t0 + attack + decay); // Decay -> Sustain — sekin pasayadi
    var relStart = t0 + attack + decay + hold;
    g.setValueAtTime(sustainLevel, relStart);
    g.exponentialRampToValueAtTime(0.0001, relStart + release);        // Release — uzun, ohista so'nish
    return relStart + release;
  }

  function tone(opts) {
    var c = getCtx();
    if (!c || !enabled) return;
    var t0 = c.currentTime + (opts.delay || 0);
    var osc = c.createOscillator();
    osc.type = 'sine'; // faqat sinus — robotsimon square/sawtooth ishlatilmaydi
    if (opts.detune) osc.detune.setValueAtTime(opts.detune, t0);
    osc.frequency.setValueAtTime(opts.freq || 440, t0);

    var gainNode = c.createGain();
    var endT = applyADSR(gainNode, t0, opts);

    // Pitch-glide (agar freqEnd berilsa) — butun ovoz davomiyligiga cho'ziladi
    if (opts.freqEnd !== undefined) {
      if (opts.freqCurve === 'lin') {
        osc.frequency.linearRampToValueAtTime(opts.freqEnd, endT);
      } else {
        osc.frequency.exponentialRampToValueAtTime(Math.max(opts.freqEnd, 1), endT);
      }
    }

    // Har doim lowpass filtr — tembrni yumshoq, tabiiy va "shisha/akustik"
    // holatga keltiradi (o'tkir highpass/bandpass ishlatilmaydi).
    var filt = c.createBiquadFilter();
    filt.type = 'lowpass';
    filt.Q.value = opts.filterQ !== undefined ? opts.filterQ : 0.7;
    filt.frequency.setValueAtTime(opts.filterFreq !== undefined ? opts.filterFreq : 3200, t0);
    if (opts.filterFreqEnd !== undefined) {
      filt.frequency.exponentialRampToValueAtTime(Math.max(opts.filterFreqEnd, 1), endT);
    }
    osc.connect(filt);
    filt.connect(gainNode).connect(master);

    osc.start(t0);
    osc.stop(endT + 0.05);
    return endT;
  }

  function noiseBurst(opts) {
    var c = getCtx();
    if (!c || !enabled) return;
    var dur    = opts.dur || 0.1;
    var start  = opts.delay || 0;
    var peak   = (opts.gain !== undefined) ? opts.gain : 0.15;
    var attack = opts.attack !== undefined ? opts.attack : 0.02;
    var filterFreqStart = opts.filterStart || 1000;
    var filterFreqEnd   = opts.filterEnd !== undefined ? opts.filterEnd : filterFreqStart;
    var t0 = c.currentTime + start;

    var bufferSize = Math.max(1, Math.floor(c.sampleRate * dur));
    var buffer = c.createBuffer(1, bufferSize, c.sampleRate);
    var data = buffer.getChannelData(0);
    for (var i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;

    var src = c.createBufferSource();
    src.buffer = buffer;

    var filter = c.createBiquadFilter();
    filter.type = 'lowpass'; // faqat lowpass — mayin, quloqni cho'zmaydigan tembr
    filter.frequency.setValueAtTime(filterFreqStart, t0);
    filter.frequency.exponentialRampToValueAtTime(Math.max(filterFreqEnd, 1), t0 + dur);
    filter.Q.value = opts.q !== undefined ? opts.q : 0.5;

    var gainNode = c.createGain();
    gainNode.gain.setValueAtTime(0.0001, t0);
    gainNode.gain.exponentialRampToValueAtTime(Math.max(peak, 0.0001), t0 + attack);
    gainNode.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);

    src.connect(filter).connect(gainNode).connect(master);
    src.start(t0);
    src.stop(t0 + dur + 0.02);
  }


  function playTaskCheck() {
    var chord = [440.00, 554.37, 659.25]; // A4, C#5, E5 — A-major uchburchagi
    chord.forEach(function (f, i) {
      var d = i * 0.05;
      tone({ freq: f, gain: 0.45, delay: d,
             attack: 0.03, decay: 0.16, sustain: 0.35, hold: 0.05, release: 0.5,
             filterFreq: 2600, filterFreqEnd: 1400 });
      // yumshoq overton qatlami — bell tembriga ozgina sayqal (faqat sine)
      tone({ freq: f * 2, gain: 0.06, delay: d,
             attack: 0.03, decay: 0.12, sustain: 0.15, hold: 0.0, release: 0.3,
             filterFreq: 2200 });
    });
  }

  // ✖️ O'chirish / bekor qilish — mayin pastlab tushuvchi sine "pop"
  function playDelete() {
    noiseBurst({ dur: 0.14, gain: 0.1, filterStart: 900, filterEnd: 200, q: 0.5, attack: 0.02 });
    tone({ freq: 280, freqEnd: 130, gain: 0.32, delay: 0.02,
           attack: 0.025, decay: 0.08, sustain: 0.3, hold: 0.02, release: 0.24,
           filterFreq: 1400, filterFreqEnd: 500 });
  }

  // 🎉 Firework — chiroyli, ko'tariluvchi va mayin arpeggio
  function playFirework() {
    noiseBurst({ dur: 0.3, gain: 0.13, filterStart: 1500, filterEnd: 350, q: 0.4, attack: 0.02 });
    var notes = [523.25, 659.25, 783.99, 1046.5]; // Do-Mi-Sol-Do
    notes.forEach(function (f, i) {
      tone({ freq: f, gain: 0.4, delay: 0.06 + i * 0.09,
             attack: 0.03, decay: 0.12, sustain: 0.4, hold: 0.03, release: 0.38,
             filterFreq: 3000, filterFreqEnd: 1800 });
    });
  }

  // 🎰 Ruletka — qisqa, juda yengil yog'och zarbi (Soft Wood Tap)
  function playSpinTick() {
    noiseBurst({ dur: 0.05, gain: 0.13, filterStart: 900, filterEnd: 280, q: 0.6, attack: 0.02 });
    tone({ freq: 480, freqEnd: 250, gain: 0.13, attack: 0.02, decay: 0.03,
           sustain: 0.15, hold: 0, release: 0.07, filterFreq: 1100, filterFreqEnd: 480 });
  }

  // 🎰 Ruletkada yutish — quvnoq, mayin ko'tariluvchi sine fanfare
  function playSpinWin() {
    var notes = [784, 988, 1175, 1568];
    notes.forEach(function (f, i) {
      tone({ freq: f, gain: 0.34, delay: i * 0.07,
             attack: 0.03, decay: 0.1, sustain: 0.4, hold: 0.02, release: 0.32,
             filterFreq: 3200, filterFreqEnd: 2000 });
    });
  }

  // 💥 Zarba olish — qisqa, pastlab tushuvchi noise+sine "hit"
  function playDamage() {
    noiseBurst({ dur: 0.12, gain: 0.16, filterStart: 1400, filterEnd: 200, q: 0.5, attack: 0.01 });
    tone({ freq: 220, freqEnd: 90, gain: 0.3, attack: 0.01, decay: 0.07,
           sustain: 0.2, hold: 0.0, release: 0.16, filterFreq: 900, filterFreqEnd: 300 });
  }

  // 💀 O'yin tugashi — pasayib boruvchi, xafa ohang
  function playGameOver() {
    var notes = [392.0, 349.23, 293.66, 261.63]; // G4 -> F4 -> D4 -> C4
    notes.forEach(function (f, i) {
      tone({ freq: f, gain: 0.32, delay: i * 0.16,
             attack: 0.02, decay: 0.14, sustain: 0.3, hold: 0.04, release: 0.4,
             filterFreq: 2200, filterFreqEnd: 900 });
    });
  }

  function playCoin() {
    function ding(freq, freqEnd, delay) {
      tone({ freq: freq, freqEnd: freqEnd, gain: 0.3, delay: delay,
             attack: 0.02, decay: 0.09, sustain: 0.3, hold: 0.02, release: 0.28,
             filterFreq: 4200, filterFreqEnd: 2200 });
      tone({ freq: freq * 2, gain: 0.07, delay: delay,
             attack: 0.02, decay: 0.07, sustain: 0.2, hold: 0.0, release: 0.2,
             filterFreq: 3400 });
    }
    ding(1568.0, 1760.0, 0.00);   // Ding! — G6 -> A6
    ding(2093.0, 2349.0, 0.11);   // Ding! — C7 -> D7 (birinchisidan yorqinroq)
  }

  // ⭐ Daraja oshishi — mayin ko'tariluvchi sine arpeggio
  function playLevelUp() {
    var notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach(function (f, i) {
      tone({ freq: f, gain: 0.4, delay: i * 0.1,
             attack: 0.03, decay: 0.1, sustain: 0.4, hold: 0.03, release: 0.32,
             filterFreq: 3200, filterFreqEnd: 2000 });
    });
  }

  // 🔀 Tab almashtirish / oddiy tugma bosish — deyarli bilinar-bilinmas
  // suv tomchisi tovushi (Soft Water Drop / Gentle Bubble)
  function playClick() {
    tone({ freq: 900, freqEnd: 480, gain: 0.08, attack: 0.02, decay: 0.05,
           sustain: 0.15, hold: 0, release: 0.13, filterFreq: 1600, filterFreqEnd: 850 });
  }

  return {
    isOn: isOn,
    toggle: toggle,
    setEnabled: setEnabled,
    getVolume: getVolume,
    setVolume: setVolume,
    test: playTest,
    taskCheck: playTaskCheck,
    delete: playDelete,
    firework: playFirework,
    spinTick: playSpinTick,
    spinWin: playSpinWin,
    damage: playDamage,
    gameOver: playGameOver,
    coin: playCoin,
    levelUp: playLevelUp,
    click: playClick
  };
})();

// Ovoz on/off switch'i olib tashlandi — Master Volume slider 0% ga tushirilganda
// tovush allaqachon to'liq o'chadi (qarang: SFX ichidagi master.gain.value).

// ---- Master Volume slider (Settings -> Ovoz va Audio) ----
function updateVolumeUI() {
  var slider = document.getElementById('master-volume-slider');
  var label = document.getElementById('master-volume-value');
  if (!slider || !label) return;
  var pct = Math.round(SFX.getVolume() * 100);
  slider.value = pct;
  label.textContent = pct + '%';
}
function onMasterVolumeInput(val) {
  var pct = Math.max(0, Math.min(100, parseInt(val, 10) || 0));
  SFX.setVolume(pct / 100);
  var label = document.getElementById('master-volume-value');
  if (label) label.textContent = pct + '%';
}
document.addEventListener('DOMContentLoaded', updateVolumeUI);

// ---- Test Sound tugmasi ----
function testSoundEffect() {
  SFX.test();
}

var FocusAudio = (function () {
  var actx = null, master = null, current = null, currentType = null, playing = false, masterPct = 45;
  var VOL_CEILING = 0.9;
  var pendingOld = null, switchToken = 0;
  function cancelPendingSwitch() {
    if (pendingOld) { teardown(pendingOld); pendingOld = null; }
  }

  function ac() {
    if (!actx) {
      var AC = window.AudioContext || window.webkitAudioContext;
      actx = new AC();
      master = actx.createGain();
      master.gain.value = 0.0001;
      master.connect(actx.destination);
    }
    if (actx.state === 'suspended') { try { actx.resume(); } catch (e) {} }
    return actx;
  }

  // ---- Shovqin (noise) buferlari — bir marta yaratiladi va qayta ishlatiladi ----
  var noiseBufCache = {};
  function whiteBuffer(seconds) {
    var key = 'w' + seconds;
    if (noiseBufCache[key]) return noiseBufCache[key];
    var c = ac(), len = Math.max(1, Math.floor(c.sampleRate * seconds));
    var buf = c.createBuffer(1, len, c.sampleRate);
    var d = buf.getChannelData(0);
    for (var i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    noiseBufCache[key] = buf;
    return buf;
  }
  function brownBuffer(seconds) {
    var key = 'b' + seconds;
    if (noiseBufCache[key]) return noiseBufCache[key];
    var c = ac(), len = Math.max(1, Math.floor(c.sampleRate * seconds));
    var buf = c.createBuffer(1, len, c.sampleRate);
    var d = buf.getChannelData(0);
    var last = 0;
    for (var i = 0; i < len; i++) {
      var white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      d[i] = last * 3.5;
    }
    noiseBufCache[key] = buf;
    return buf;
  }
  // Pushti (pink) shovqin — oq va jigarrang shovqin oralig'ida, Paul Kellet
  // algoritmi asosida (har oktavada teng energiya — tabiiyroq, yumshoqroq eshitiladi).
  function pinkBuffer(seconds) {
    var key = 'p' + seconds;
    if (noiseBufCache[key]) return noiseBufCache[key];
    var c = ac(), len = Math.max(1, Math.floor(c.sampleRate * seconds));
    var buf = c.createBuffer(1, len, c.sampleRate);
    var d = buf.getChannelData(0);
    var b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;
    for (var i = 0; i < len; i++) {
      var white = Math.random() * 2 - 1;
      b0 = 0.99886 * b0 + white * 0.0555179;
      b1 = 0.99332 * b1 + white * 0.0750759;
      b2 = 0.96900 * b2 + white * 0.1538520;
      b3 = 0.86650 * b3 + white * 0.3104856;
      b4 = 0.55000 * b4 + white * 0.5329522;
      b5 = -0.7616 * b5 - white * 0.0168980;
      var pink = b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362;
      b6 = white * 0.115926;
      d[i] = pink * 0.11;
    }
    noiseBufCache[key] = buf;
    return buf;
  }
  function noiseSource(buf, loop) {
    var src = ac().createBufferSource();
    src.buffer = buf;
    src.loop = loop !== false;
    return src;
  }

  // Biror AudioParam'ni sekin, tabiiy tarzda tebranadigan qiladi (masalan,
  // yomg'ir/shamol balandligining mayin "nafas olishi").
  function lfo(target, freq, depth) {
    var c = ac();
    var osc = c.createOscillator();
    osc.type = 'sine'; osc.frequency.value = freq;
    var g = c.createGain(); g.gain.value = depth;
    osc.connect(g); g.connect(target);
    osc.start();
    return osc;
  }

  function makeBus() {
    var g = ac().createGain(); g.gain.value = 1; g.connect(master); return g;
  }

  // Qisqa hodisa (momaqaldiroq guldurashi, olov chirsillashi) — filtrlangan
  // shovqinni zarb (envelope) bilan bir marta chaladi.
  function burst(bus, opts) {
    var c = ac(), now = c.currentTime;
    var dur = opts.dur;
    var buf = opts.brown ? brownBuffer(dur + 0.2) : whiteBuffer(dur + 0.2);
    var src = noiseSource(buf, false);
    var filt = c.createBiquadFilter();
    filt.type = opts.filterType || 'lowpass';
    filt.frequency.setValueAtTime(opts.freq, now);
    if (opts.freqEnd) filt.frequency.exponentialRampToValueAtTime(opts.freqEnd, now + dur);
    if (opts.q) filt.Q.value = opts.q;
    var g = c.createGain();
    var pan = c.createStereoPanner ? c.createStereoPanner() : null;
    src.connect(filt); filt.connect(g);
    if (pan) { g.connect(pan); pan.connect(bus); pan.pan.value = opts.pan || 0; } else { g.connect(bus); }
    g.gain.setValueAtTime(0.0001, now);
    g.gain.linearRampToValueAtTime(opts.peak, now + opts.attack);
    g.gain.exponentialRampToValueAtTime(0.0001, now + opts.attack + opts.release);
    src.start(now); src.stop(now + dur + 0.05);
  }

  // Tasodifiy oraliqda takrorlanadigan hodisani rejalashtiradi (qush sayrashi,
  // momaqaldiroq va h.k.). Qaytarilgan funksiya uni to'xtatadi.
  function scheduleRandom(minS, maxS, fn) {
    var timer = null, stopped = false;
    function tick() {
      if (stopped) return;
      fn();
      timer = setTimeout(tick, (minS + Math.random() * (maxS - minS)) * 1000);
    }
    timer = setTimeout(tick, (minS + Math.random() * (maxS - minS)) * 1000);
    return function stop() { stopped = true; if (timer) clearTimeout(timer); };
  }

  function birdChirp(bus) {
    var c = ac(), now = c.currentTime;
    var notes = 1 + (Math.random() < 0.5 ? 1 : 0);
    for (var n = 0; n < notes; n++) {
      var t0 = now + n * (0.1 + Math.random() * 0.06);
      var osc = c.createOscillator();
      osc.type = 'sine';
      var startF = 1800 + Math.random() * 1200;
      osc.frequency.setValueAtTime(startF, t0);
      osc.frequency.exponentialRampToValueAtTime(startF * (0.55 + Math.random() * 0.4), t0 + 0.12);
      var g = c.createGain();
      var pan = c.createStereoPanner ? c.createStereoPanner() : null;
      osc.connect(g);
      if (pan) { g.connect(pan); pan.connect(bus); pan.pan.value = (Math.random() * 2 - 1); } else { g.connect(bus); }
      g.gain.setValueAtTime(0.0001, t0);
      g.gain.linearRampToValueAtTime(0.07 + Math.random() * 0.05, t0 + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.18);
      osc.start(t0); osc.stop(t0 + 0.22);
    }
  }

  // Tungi chirildoq (kriket) ovozi — bir necha tez takrorlanuvchi yuqori
  // chastotali "tik" tovushlaridan iborat qisqa trill.
  function cricketChirp(bus) {
    var c = ac(), now = c.currentTime;
    var pulses = 3 + Math.floor(Math.random() * 4);
    var baseF = 2600 + Math.random() * 900;
    var pan = c.createStereoPanner ? c.createStereoPanner() : null;
    var panVal = (Math.random() * 2 - 1);
    for (var p = 0; p < pulses; p++) {
      var t0 = now + p * 0.045;
      var osc = c.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(baseF, t0);
      var g = c.createGain();
      osc.connect(g);
      if (pan) { g.connect(pan); pan.connect(bus); pan.pan.value = panVal; } else { g.connect(bus); }
      g.gain.setValueAtTime(0.0001, t0);
      g.gain.linearRampToValueAtTime(0.05, t0 + 0.006);
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.032);
      osc.start(t0); osc.stop(t0 + 0.04);
    }
  }

  function crackle(bus) {
    var c = ac(), now = c.currentTime;
    var dur = 0.05 + Math.random() * 0.05;
    var src = noiseSource(whiteBuffer(dur + 0.1), false);
    var filt = c.createBiquadFilter();
    filt.type = 'highpass'; filt.frequency.value = 1200 + Math.random() * 2500;
    var g = c.createGain();
    src.connect(filt); filt.connect(g); g.connect(bus);
    g.gain.setValueAtTime(0.0001, now);
    g.gain.linearRampToValueAtTime(0.22 + Math.random() * 0.25, now + 0.005);
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    src.start(now); src.stop(now + dur + 0.05);
  }

  // ---- Har bir tovush turi uchun "quruvchi" — bus va manbalar ro'yxatini qaytaradi ----
  function buildRain(heavy) {
    var c = ac(), bus = makeBus();
    var src = noiseSource(whiteBuffer(4));
    var filt = c.createBiquadFilter();
    filt.type = 'bandpass'; filt.frequency.value = heavy ? 900 : 1500; filt.Q.value = 0.6;
    var hp = c.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 250;
    var g = c.createGain(); g.gain.value = heavy ? 0.85 : 0.6;
    src.connect(filt); filt.connect(hp); hp.connect(g); g.connect(bus);
    var breathe = lfo(g.gain, 0.12, 0.07);
    src.start();
    var stops = [];
    if (heavy) {
      stops.push(scheduleRandom(6, 16, function () {
        burst(bus, { dur: 1.8, freq: 400, freqEnd: 90, filterType: 'lowpass', q: 0.6, peak: 0.85, attack: 0.2, release: 1.6, brown: true });
      }));
    }
    return { bus: bus, sources: [src, breathe], stops: stops };
  }

  function buildForest() {
    var c = ac(), bus = makeBus();
    var src = noiseSource(whiteBuffer(4));
    var filt = c.createBiquadFilter(); filt.type = 'lowpass'; filt.frequency.value = 700;
    var g = c.createGain(); g.gain.value = 0.5;
    src.connect(filt); filt.connect(g); g.connect(bus);
    var windGust = lfo(filt.frequency, 0.05, 250);
    var breathe = lfo(g.gain, 0.08, 0.1);
    src.start();
    var stops = [scheduleRandom(2.5, 7, function () { birdChirp(bus); })];
    return { bus: bus, sources: [src, windGust, breathe], stops: stops };
  }

  function buildOcean() {
    var c = ac(), bus = makeBus();
    var src = noiseSource(whiteBuffer(4));
    var filt = c.createBiquadFilter(); filt.type = 'lowpass'; filt.frequency.value = 500;
    var g = c.createGain(); g.gain.value = 0.35;
    src.connect(filt); filt.connect(g); g.connect(bus);
    var swell = lfo(g.gain, 0.09, 0.3);
    src.start();
    return { bus: bus, sources: [src, swell] };
  }

  function buildWhite() {
    var c = ac(), bus = makeBus();
    var src = noiseSource(whiteBuffer(4));
    var filt = c.createBiquadFilter(); filt.type = 'lowpass'; filt.frequency.value = 9000;
    var g = c.createGain(); g.gain.value = 0.45;
    src.connect(filt); filt.connect(g); g.connect(bus);
    src.start();
    return { bus: bus, sources: [src] };
  }

  function buildBrown() {
    var c = ac(), bus = makeBus();
    var src = noiseSource(brownBuffer(4));
    var g = c.createGain(); g.gain.value = 0.75;
    src.connect(g); g.connect(bus);
    src.start();
    return { bus: bus, sources: [src] };
  }

  function buildFire() {
    var c = ac(), bus = makeBus();
    var src = noiseSource(brownBuffer(4));
    var filt = c.createBiquadFilter(); filt.type = 'lowpass'; filt.frequency.value = 300;
    var g = c.createGain(); g.gain.value = 0.3;
    src.connect(filt); filt.connect(g); g.connect(bus);
    src.start();
    var stops = [scheduleRandom(0.12, 0.9, function () { crackle(bus); })];
    return { bus: bus, sources: [src], stops: stops };
  }

  function buildLofi() {
    var c = ac(), bus = makeBus();
    // Juda past ovozdagi "vinil" shovqini — lo-fi uchun issiq fon
    var hiss = noiseSource(whiteBuffer(4));
    var hissFilt = c.createBiquadFilter(); hissFilt.type = 'highpass'; hissFilt.frequency.value = 3000;
    var hissGain = c.createGain(); hissGain.gain.value = 0.02;
    hiss.connect(hissFilt); hissFilt.connect(hissGain); hissGain.connect(bus);
    hiss.start();

    var chords = [
      [261.63, 329.63, 392.00, 493.88], // Cmaj7
      [220.00, 261.63, 329.63, 392.00], // Am7
      [174.61, 220.00, 261.63, 349.23], // Fmaj7
      [196.00, 246.94, 293.66, 349.23]  // G7
    ];
    var padFilt = c.createBiquadFilter(); padFilt.type = 'lowpass'; padFilt.frequency.value = 1100;
    padFilt.connect(bus);
    var idx = 0, stopped = false, timer = null;

    function playChord() {
      if (stopped) return;
      var chord = chords[idx % chords.length]; idx++;
      var now = c.currentTime, dur = 6.5;
      chord.forEach(function (freq, i) {
        [1, 1.006].forEach(function (detune) {
          var osc = c.createOscillator();
          osc.type = i === 0 ? 'triangle' : 'sine';
          osc.frequency.value = freq * detune;
          var g = c.createGain(); g.gain.value = 0;
          osc.connect(g); g.connect(padFilt);
          g.gain.setValueAtTime(0.0001, now);
          g.gain.linearRampToValueAtTime(0.045, now + 1.4);
          g.gain.linearRampToValueAtTime(0.03, now + dur - 1.8);
          g.gain.linearRampToValueAtTime(0.0001, now + dur);
          osc.start(now); osc.stop(now + dur + 0.1);
        });
      });
      timer = setTimeout(playChord, dur * 1000 - 400);
    }
    playChord();
    return { bus: bus, sources: [hiss], stops: [function () { stopped = true; if (timer) clearTimeout(timer); }] };
  }

  function buildPink() {
    var c = ac(), bus = makeBus();
    var src = noiseSource(pinkBuffer(4));
    var filt = c.createBiquadFilter(); filt.type = 'lowpass'; filt.frequency.value = 7000;
    var g = c.createGain(); g.gain.value = 0.6;
    src.connect(filt); filt.connect(g); g.connect(bus);
    var breathe = lfo(g.gain, 0.06, 0.05);
    src.start();
    return { bus: bus, sources: [src, breathe] };
  }

  function buildCrickets() {
    var c = ac(), bus = makeBus();
    // Juda xira tungi shovqin foni (shamol/olis tabiat) + tasodifiy kriket trillari
    var src = noiseSource(whiteBuffer(4));
    var filt = c.createBiquadFilter(); filt.type = 'lowpass'; filt.frequency.value = 400;
    var g = c.createGain(); g.gain.value = 0.12;
    src.connect(filt); filt.connect(g); g.connect(bus);
    var breathe = lfo(g.gain, 0.05, 0.03);
    src.start();
    var stops = [scheduleRandom(0.5, 2.2, function () { cricketChirp(bus); })];
    return { bus: bus, sources: [src, breathe], stops: stops };
  }

  // Meditatsiya qo'ng'irog'i (singing bowl) — davomli uyg'unlashgan uzun
  // ton + vaqti-vaqti bilan yangi "zarba" bilan yangilanadigan rezonans.
  function buildBowl() {
    var c = ac(), bus = makeBus();
    var padFilt = c.createBiquadFilter(); padFilt.type = 'lowpass'; padFilt.frequency.value = 2600;
    padFilt.connect(bus);
    var fundamentals = [196.00, 261.63, 220.00];
    var ratios = [1, 2.756, 5.404, 8.933];
    var idx = 0, stopped = false, timer = null;
    function strike() {
      if (stopped) return;
      var base = fundamentals[idx % fundamentals.length]; idx++;
      var now = c.currentTime, dur = 9;
      ratios.forEach(function (r, i) {
        var osc = c.createOscillator();
        osc.type = 'sine';
        osc.frequency.value = base * r;
        var g = c.createGain(); g.gain.value = 0;
        osc.connect(g); g.connect(padFilt);
        var peak = 0.09 / (i + 1);
        g.gain.setValueAtTime(0.0001, now);
        g.gain.linearRampToValueAtTime(peak, now + 0.15);
        g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
        osc.start(now); osc.stop(now + dur + 0.1);
      });
      timer = setTimeout(strike, (dur - 1.5) * 1000);
    }
    strike();
    return { bus: bus, sources: [], stops: [function () { stopped = true; if (timer) clearTimeout(timer); }] };
  }

  // Kosmik tinch "drone" — sekin almashinuvchi, keng detune qilingan
  // uyg'unlashgan pad — melodiyasiz, atmosferik fon.
  function buildSpace() {
    var c = ac(), bus = makeBus();
    var padFilt = c.createBiquadFilter(); padFilt.type = 'lowpass'; padFilt.frequency.value = 900;
    padFilt.connect(bus);
    var sweep = lfo(padFilt.frequency, 0.025, 300);
    var chords = [
      [110.00, 164.81, 220.00],  // A + E + A
      [98.00, 146.83, 220.00],   // G + D + A
      [87.31, 130.81, 196.00]    // F + C + G
    ];
    var idx = 0, stopped = false, timer = null;
    function playPad() {
      if (stopped) return;
      var chord = chords[idx % chords.length]; idx++;
      var now = c.currentTime, dur = 13;
      chord.forEach(function (freq) {
        [1, 1.004, 0.997].forEach(function (detune) {
          var osc = c.createOscillator();
          osc.type = 'sine';
          osc.frequency.value = freq * detune;
          var g = c.createGain(); g.gain.value = 0;
          osc.connect(g); g.connect(padFilt);
          g.gain.setValueAtTime(0.0001, now);
          g.gain.linearRampToValueAtTime(0.05, now + 3);
          g.gain.linearRampToValueAtTime(0.03, now + dur - 4);
          g.gain.linearRampToValueAtTime(0.0001, now + dur);
          osc.start(now); osc.stop(now + dur + 0.1);
        });
      });
      timer = setTimeout(playPad, dur * 1000 - 800);
    }
    playPad();
    return { bus: bus, sources: [sweep], stops: [function () { stopped = true; if (timer) clearTimeout(timer); }] };
  }

  function buildGuitar() {
    var c = ac(), bus = makeBus();
    var padFilt = c.createBiquadFilter(); padFilt.type = 'lowpass'; padFilt.frequency.value = 1500;
    padFilt.connect(bus);
    // Juda past, uzun pad — gitaraga iliqlik/chuqurlik beradi
    var padOsc = c.createOscillator(); padOsc.type = 'sine'; padOsc.frequency.value = 98.00;
    var padGain = c.createGain(); padGain.gain.value = 0.025;
    padOsc.connect(padGain); padGain.connect(padFilt); padOsc.start();

    var pattern = [196.00, 246.94, 293.66, 246.94, 261.63, 220.00, 196.00, 246.94]; // G-B-D uslubidagi arpejio
    var idx = 0, stopped = false, timer = null;
    function pluck() {
      if (stopped) return;
      var now = c.currentTime;
      var freq = pattern[idx % pattern.length]; idx++;
      var osc = c.createOscillator();
      osc.type = 'triangle';
      osc.frequency.value = freq;
      var g = c.createGain(); g.gain.value = 0;
      osc.connect(g); g.connect(padFilt);
      g.gain.setValueAtTime(0.0001, now);
      g.gain.linearRampToValueAtTime(0.05, now + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, now + 1.3);
      osc.start(now); osc.stop(now + 1.4);
      timer = setTimeout(pluck, 620 + Math.random() * 90);
    }
    pluck();
    return { bus: bus, sources: [padOsc], stops: [function () { stopped = true; if (timer) clearTimeout(timer); }] };
  }

  function buildMarimba() {
    var c = ac(), bus = makeBus();
    var padFilt = c.createBiquadFilter(); padFilt.type = 'lowpass'; padFilt.frequency.value = 2200;
    padFilt.connect(bus);
    var padOsc = c.createOscillator(); padOsc.type = 'sine'; padOsc.frequency.value = 130.81;
    var padGain = c.createGain(); padGain.gain.value = 0.018;
    padOsc.connect(padGain); padGain.connect(padFilt); padOsc.start();

    var scale = [261.63, 293.66, 329.63, 392.00, 440.00, 523.25]; // C pentatonik gamma
    function drop() {
      var now = c.currentTime;
      var freq = scale[Math.floor(Math.random() * scale.length)];
      var osc = c.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = freq;
      var g = c.createGain(); g.gain.value = 0;
      osc.connect(g); g.connect(padFilt);
      g.gain.setValueAtTime(0.0001, now);
      g.gain.linearRampToValueAtTime(0.06, now + 0.008);
      g.gain.exponentialRampToValueAtTime(0.0001, now + 0.9);
      osc.start(now); osc.stop(now + 1.0);
    }
    var stops = [scheduleRandom(1.2, 3.2, drop)];
    return { bus: bus, sources: [padOsc], stops: stops };
  }

  var BUILDERS = {
    rain: function () { return buildRain(false); },
    storm: function () { return buildRain(true); },
    forest: buildForest,
    ocean: buildOcean,
    white: buildWhite,
    brown: buildBrown,
    fire: buildFire,
    lofi: buildLofi,
    pink: buildPink,
    crickets: buildCrickets,
    bowl: buildBowl,
    space: buildSpace,
    guitar: buildGuitar,
    marimba: buildMarimba
  };

  function teardown(node) {
    if (!node) return;
    (node.sources || []).forEach(function (n) { try { n.stop(); } catch (e) {} try { n.disconnect(); } catch (e) {} });
    (node.stops || []).forEach(function (fn) { try { fn(); } catch (e) {} });
    try { node.bus.disconnect(); } catch (e) {}
  }

  function currentMul() { return (Math.max(0, Math.min(100, masterPct || 0)) / 100) * VOL_CEILING; }

  function fadeMaster(toMul, seconds, cb) {
    var c = ac(), now = c.currentTime;
    master.gain.cancelScheduledValues(now);
    master.gain.setValueAtTime(Math.max(0.0001, master.gain.value), now);
    master.gain.linearRampToValueAtTime(Math.max(0.0001, toMul), now + seconds);
    if (cb) setTimeout(cb, seconds * 1000 + 20);
  }

  function startNew(type, pct) {
    ac();
    masterPct = pct;
    var build = BUILDERS[type] || BUILDERS.rain;
    current = build();
    currentType = type;
    fadeMaster(currentMul(), 0.5);
  }

  // Tovush turini almashtirish: joriysi mayin so'nadi, so'ng yangisi mayin
  // ko'tariladi — hech qanday "click" yoki uzilish bo'lmaydi.
  function play(type, pct) {
    if (currentType === type && current) { return resume(pct); }
    cancelPendingSwitch(); // avvalgi almashtirish hali tugamagan bo'lsa, uni darhol yakunlaymiz
    switchToken++;
    var myToken = switchToken;
    if (current) {
      var old = current;
      current = null; currentType = null;
      pendingOld = old;
      fadeMaster(0.0001, 0.3, function () {
        if (myToken !== switchToken) return; // eskirgan callback — yangisi allaqachon boshqargan
        teardown(old);
        pendingOld = null;
        startNew(type, pct);
      });
    } else {
      startNew(type, pct);
    }
    playing = true;
    return true;
  }

  function setVolume(pct) {
    masterPct = pct;
    if (!current) return;
    fadeMaster(currentMul(), 0.2);
  }

  function pause() {
    if (!current) { playing = false; return; }
    fadeMaster(0.0001, 0.3);
    playing = false;
  }

  function resume(pct) {
    if (!current) return false;
    masterPct = pct;
    fadeMaster(currentMul(), 0.4);
    playing = true;
    return true;
  }

  function stopAll() {
    switchToken++; // har qanday davom etayotgan crossfade callback'ini bekor qilamiz
    cancelPendingSwitch();
    if (current) {
      var old = current;
      fadeMaster(0.0001, 0.3, function () { teardown(old); });
    }
    current = null; currentType = null; playing = false;
  }

  function isPlaying() { return playing; }
  function getType() { return currentType; }

  return { play: play, pause: pause, resume: resume, setVolume: setVolume, stopAll: stopAll, isPlaying: isPlaying, getType: getType };
})();

// ---- Ambient Focus Sound: sozlamalar, UI va boshqaruv funksiyalari ----
var FOCUS_SOUNDS = {
  rain:   { icon: '🌧️', labelKey: 'focus_sound_rain' },
  storm:  { icon: '⛈️', labelKey: 'focus_sound_storm' },
  forest: { icon: '🌲', labelKey: 'focus_sound_forest' },
  ocean:  { icon: '🌊', labelKey: 'focus_sound_ocean' },
  white:  { icon: '🤍', labelKey: 'focus_sound_white' },
  brown:  { icon: '🟤', labelKey: 'focus_sound_brown' },
  fire:   { icon: '🔥', labelKey: 'focus_sound_fire' },
  lofi:   { icon: '🎹', labelKey: 'focus_sound_lofi' },
  pink:   { icon: '🌸', labelKey: 'focus_sound_pink' },
  crickets: { icon: '🦗', labelKey: 'focus_sound_crickets' },
  bowl:   { icon: '🎐', labelKey: 'focus_sound_bowl' },
  space:  { icon: '🌌', labelKey: 'focus_sound_space' },
  guitar: { icon: '🎸', labelKey: 'focus_sound_guitar' },
  marimba: { icon: '🎼', labelKey: 'focus_sound_marimba' }
};

function ensureAmbientFocusDefaults() {
  if (typeof S.ambientFocusEnabled === 'undefined' || S.ambientFocusEnabled === null) S.ambientFocusEnabled = false;
  if (!S.ambientFocusSound || !FOCUS_SOUNDS[S.ambientFocusSound]) S.ambientFocusSound = 'rain';
  if (typeof S.ambientFocusVolume !== 'number' || isNaN(S.ambientFocusVolume)) S.ambientFocusVolume = 45;
}

function setFocusIconsSpin(spin) {
  ['focus-fab-icon', 'focus-mini-icon', 'focus-open-player-icon'].forEach(function (id) {
    var el = document.getElementById(id);
    if (el) el.style.animation = spin ? 'focusNoteSpin 3.5s linear infinite' : 'none';
  });
}

function updateFocusToggleUI() {
  var sw = document.getElementById('focus-setting-switch');
  var knob = document.getElementById('focus-setting-knob');
  if (sw && knob) {
    var on = !!S.ambientFocusEnabled;
    sw.style.background = on ? 'var(--accent)' : 'var(--surface2)';
    sw.style.borderColor = on ? 'var(--accent)' : 'var(--border)';
    knob.style.left = on ? '22px' : '2px';
    knob.style.background = on ? '#fff' : 'var(--text-dim)';
  }
  var fab = document.getElementById('focus-fab');
  if (fab) fab.style.display = S.ambientFocusEnabled ? 'flex' : 'none';
  var openBtn = document.getElementById('focus-open-player-btn');
  if (openBtn) openBtn.style.display = S.ambientFocusEnabled ? 'flex' : 'none';
  if (!S.ambientFocusEnabled) {
    var mini = document.getElementById('focus-mini-player');
    if (mini) mini.style.display = 'none';
  }
}

function toggleAmbientFocusEnabled() {
  ensureAmbientFocusDefaults();
  S.ambientFocusEnabled = !S.ambientFocusEnabled;
  save();
  updateFocusToggleUI();
  try { SFX.click(); } catch (e) {}
  if (!S.ambientFocusEnabled) {
    FocusAudio.stopAll();
    closeFocusPlayer();
    setFocusIconsSpin(false);
  }
  try { toast(S.ambientFocusEnabled ? t('focus_enabled_toast') : t('focus_disabled_toast')); } catch (e) {}
}

function renderFocusSoundGrid() {
  var grid = document.getElementById('focus-sound-grid');
  if (!grid) return;
  grid.querySelectorAll('.focus-sound-btn').forEach(function (btn) {
    btn.classList.toggle('active', btn.getAttribute('data-sound') === S.ambientFocusSound);
  });
}

function updateFocusPlayUI() {
  var playing = FocusAudio.isPlaying();
  var btn = document.getElementById('focus-play-btn');
  if (btn) btn.textContent = playing ? '⏸️' : '▶️';
  var miniBtn = document.getElementById('focus-mini-toggle');
  if (miniBtn) miniBtn.textContent = playing ? '⏸️' : '▶️';
  setFocusIconsSpin(playing);
  syncPomoAmbientBubbleUI();
  if (typeof window.pomoSyncPipMusicUI === 'function') window.pomoSyncPipMusicUI();
}

// 🎧 Pomodoro ekranidagi pastki-chap "Ambient Focus" pufakchasini joriy
// tanlangan ohang va play/pause holatiga mos yangilab turadi.
function syncPomoAmbientBubbleUI() {
  var info = FOCUS_SOUNDS[S.ambientFocusSound] || FOCUS_SOUNDS.rain;
  var playing = FocusAudio.isPlaying();
  var iconEl = document.getElementById('pomo-ambient-bubble-icon');
  var titleEl = document.getElementById('pomo-ambient-bubble-title');
  var subEl = document.getElementById('pomo-ambient-bubble-sub');
  var playEl = document.getElementById('pomo-ambient-bubble-play');
  if (iconEl) iconEl.textContent = info.icon;
  if (titleEl) titleEl.textContent = t(info.labelKey);
  if (subEl) subEl.textContent = playing ? "chalinmoqda" : "tinch fon uchun bosing";
  if (playEl) playEl.textContent = playing ? '⏸' : '▶';
}

// ‹ / › tugmalari — joriy ohangdan keyingi yoki oldingi ohangga o'tadi
// va uni darhol chala boshlaydi (Spotify uslubidagi "next/prev track").
function focusCycleSound(direction) {
  ensureAmbientFocusDefaults();
  var keys = Object.keys(FOCUS_SOUNDS);
  var idx = keys.indexOf(S.ambientFocusSound);
  if (idx === -1) idx = 0;
  idx = (idx + direction + keys.length) % keys.length;
  selectFocusSound(keys[idx]);
}

// Pufakchaning markaziy (belgi + nom) qismi bosilganda — to'liq pleyer ochiladi.
// Play/Pause va ‹ › tugmalari alohida ishlaydi (stopPropagation orqali).
function onPomoAmbientBubbleClick(e) {
  openFocusPlayer();
}

function openFocusPlayer() {
  try { if (typeof window.pomoSetActiveNav === 'function' && document.getElementById('pomo-modal-overlay').classList.contains('open')) window.pomoSetActiveNav('pomo-nav-music'); } catch (e) {}
  ensureAmbientFocusDefaults();
  if (!S.ambientFocusEnabled) {
    // Pleyer FAB orqali ochilmoqchi bo'lsa ham, avval funksiyani yoqamiz
    S.ambientFocusEnabled = true;
    save();
    updateFocusToggleUI();
  }
  // To'liq pleyer ochilganda, avval "×" bilan vaqtincha yopilgan bo'lsa ham,
  // pufakcha keyingi safar qayta ko'rsatiladi.
  focusMiniDismissed = false;
  var ov = document.getElementById('focus-player-modal-overlay');
  if (ov) ov.classList.add('open');
  var mini = document.getElementById('focus-mini-player');
  if (mini) mini.style.display = 'none';
  renderFocusSoundGrid();
  updateFocusPlayUI();
  var slider = document.getElementById('focus-volume-slider');
  var valLabel = document.getElementById('focus-volume-value');
  if (slider) slider.value = S.ambientFocusVolume;
  if (valLabel) valLabel.textContent = S.ambientFocusVolume + '%';
  try { SFX.click(); } catch (e) {}
}

function closeFocusPlayer() {
  var ov = document.getElementById('focus-player-modal-overlay');
  if (ov) ov.classList.remove('open');
  if (FocusAudio.isPlaying()) {
    showFocusMiniPlayer();
  }
}

function isFocusModalOpen() {
  var ov = document.getElementById('focus-player-modal-overlay');
  return !!(ov && ov.classList.contains('open'));
}

function showFocusMiniPlayer() {
  if (!S.ambientFocusEnabled) return;
  if (focusMiniDismissed) return; // "×" bilan vaqtincha yopilgan — qayta ko'rsatilmaydi
  var pomoOv = document.getElementById('pomo-modal-overlay');
  if (pomoOv && pomoOv.classList.contains('open')) return;
  var mini = document.getElementById('focus-mini-player');
  if (!mini) return;
  var info = FOCUS_SOUNDS[S.ambientFocusSound] || FOCUS_SOUNDS.rain;
  var iconEl = document.getElementById('focus-mini-icon');
  var labelEl = document.getElementById('focus-mini-label');
  if (iconEl) iconEl.textContent = info.icon;
  if (labelEl) labelEl.textContent = t(info.labelKey);
  updateFocusPlayUI();
  mini.style.display = 'flex';
  applyFocusMiniPos();
}

// "×" tugmasi — pufakchani vaqtincha yashiradi (tovush chalinishda davom
// etadi). Sahifa qayta yuklansa yoki to'liq pleyer ochilsa, yana ko'rinadi.
var focusMiniDismissed = false;
function hideFocusMiniPlayerTemporarily() {
  focusMiniDismissed = true;
  var mini = document.getElementById('focus-mini-player');
  if (mini) mini.style.display = 'none';
  try { SFX.click(); } catch (e) {}
}

// ---- Pufakchani bosib turib (long-press) sudrab, joyini o'zgartirish ----
var focusMiniDrag = { active: false, moved: false, offsetX: 0, offsetY: 0, pressTimer: null };

function onFocusMiniClick(e) {
  // Agar pufakcha hozirgina sudralgan bo'lsa, bu "tap" emas — pleyerni ochmaymiz.
  if (focusMiniDrag.moved) { focusMiniDrag.moved = false; return; }
  openFocusPlayer();
}

function clampFocusMiniPos(el, left, top) {
  var w = el.offsetWidth || 200, h = el.offsetHeight || 48;
  var maxLeft = Math.max(6, window.innerWidth - w - 6);
  var maxTop = Math.max(6, window.innerHeight - h - 6);
  return { left: Math.max(6, Math.min(maxLeft, left)), top: Math.max(6, Math.min(maxTop, top)) };
}

function applyFocusMiniPos() {
  var el = document.getElementById('focus-mini-player');
  if (!el || !S.focusMiniPos || el.style.display === 'none') return;
  var pos = clampFocusMiniPos(el, S.focusMiniPos.left, S.focusMiniPos.top);
  el.style.left = pos.left + 'px';
  el.style.top = pos.top + 'px';
  el.style.right = 'auto';
  el.style.bottom = 'auto';
}

function initFocusMiniDraggable() {
  var el = document.getElementById('focus-mini-player');
  if (!el || el.dataset.dragInit) return;
  el.dataset.dragInit = '1';

  el.addEventListener('pointerdown', function (e) {
    var rect = el.getBoundingClientRect();
    focusMiniDrag.offsetX = e.clientX - rect.left;
    focusMiniDrag.offsetY = e.clientY - rect.top;
    focusMiniDrag.moved = false;
    clearTimeout(focusMiniDrag.pressTimer);
    // Bosib turish (long-press) kutiladi — shunda oddiy tap bilan
    // sudrash (drag) bir-biriga aralashmaydi.
    focusMiniDrag.pressTimer = setTimeout(function () {
      focusMiniDrag.active = true;
      el.style.cursor = 'grabbing';
      try { el.setPointerCapture(e.pointerId); } catch (err) {}
    }, 220);
  });

  el.addEventListener('pointermove', function (e) {
    if (!focusMiniDrag.active) return;
    focusMiniDrag.moved = true;
    var pos = clampFocusMiniPos(el, e.clientX - focusMiniDrag.offsetX, e.clientY - focusMiniDrag.offsetY);
    el.style.left = pos.left + 'px';
    el.style.top = pos.top + 'px';
    el.style.right = 'auto';
    el.style.bottom = 'auto';
  });

  function endDrag() {
    clearTimeout(focusMiniDrag.pressTimer);
    if (focusMiniDrag.active) {
      focusMiniDrag.active = false;
      el.style.cursor = 'grab';
      if (focusMiniDrag.moved) {
        S.focusMiniPos = {
          left: parseInt(el.style.left, 10) || 18,
          top: parseInt(el.style.top, 10) || 18
        };
        save();
      }
    }
  }
  el.addEventListener('pointerup', endDrag);
  el.addEventListener('pointercancel', endDrag);
  window.addEventListener('resize', function () { if (S.focusMiniPos) applyFocusMiniPos(); });
}

function selectFocusSound(type) {
  ensureAmbientFocusDefaults();
  if (!FOCUS_SOUNDS[type]) type = 'rain';
  S.ambientFocusSound = type;
  save();
  renderFocusSoundGrid();
  FocusAudio.play(type, S.ambientFocusVolume);
  updateFocusPlayUI();
  if (!isFocusModalOpen()) showFocusMiniPlayer();
  try { SFX.click(); } catch (e) {}
}

function toggleFocusPlayback() {
  ensureAmbientFocusDefaults();
  if (FocusAudio.isPlaying()) {
    FocusAudio.pause();
  } else if (FocusAudio.getType() === S.ambientFocusSound) {
    FocusAudio.resume(S.ambientFocusVolume);
  } else {
    FocusAudio.play(S.ambientFocusSound, S.ambientFocusVolume);
  }
  updateFocusPlayUI();
  if (!isFocusModalOpen()) showFocusMiniPlayer();
  try { SFX.click(); } catch (e) {}
}

function onFocusVolumeInput(val) {
  S.ambientFocusVolume = parseInt(val, 10) || 0;
  save();
  var valLabel = document.getElementById('focus-volume-value');
  if (valLabel) valLabel.textContent = S.ambientFocusVolume + '%';
  FocusAudio.setVolume(S.ambientFocusVolume);
}

document.addEventListener('DOMContentLoaded', function () {
  ensureAmbientFocusDefaults();
  updateFocusToggleUI();
  initFocusMiniDraggable();
  syncPomoAmbientBubbleUI();
});

// ⚙️ Settings ichidagi ixcham sub-kartalar (Interfeys/Ovoz/Fokus/O'yin qoidalari) — accordion
function toggleSettingsSubCard(cardId) {
  var card = document.getElementById(cardId);
  if (!card) return;
  var body = card.querySelector('.settings-sub-body');
  if (!body) return;
  var isOpen = body.style.display !== 'none';
  body.style.display = isOpen ? 'none' : 'block';
  card.classList.toggle('open', !isOpen);
  try { if (typeof SFX !== 'undefined' && SFX.click) SFX.click(); } catch (e) {}
}

// ⚠️ Strict Rules & Penalties — accordion: bosilganda hamma qoidalar ochiladi/yopiladi
function toggleStrictRulesPanel() {
  var card = document.getElementById('strict-rules-card');
  var panel = document.getElementById('strict-rules-panel');
  if (!panel) return;
  var isOpen = panel.style.display !== 'none';
  panel.style.display = isOpen ? 'none' : 'flex';
  if (card) card.classList.toggle('open', !isOpen);
  try { if (typeof SFX !== 'undefined' && SFX.click) SFX.click(); } catch (e) {}
}

function getLang() {
  try {
    if (typeof S !== 'undefined' && S && S.profile && S.profile.language) return S.profile.language;
  } catch(e) {}
  return 'en';
}

function t(key) {
  var lang = getLang();
  var dict = I18N[lang] || I18N.uz;
  return (dict && dict[key] !== undefined) ? dict[key] : (I18N.uz[key] !== undefined ? I18N.uz[key] : key);
}
// Alias — ba'zi funksiyalarda lokal 't' (task) parametri bo'lgani uchun ishlatiladi
function tr(key) { return t(key); }
// Level nomini joriy tilda qaytaradi (level_name_1..7 kalitlari orqali,
// tarjima topilmasa LEVELS massividagi standart (o'zbekcha) nomga qaytadi).
function levelName(lvObj) { return lvObj ? t('level_name_' + lvObj.level) : ''; }

function applyLanguage() {
  document.documentElement.lang = getLang();
  // data-i18n="key" -> textContent
  document.querySelectorAll('[data-i18n]').forEach(function(el) {
    el.textContent = t(el.getAttribute('data-i18n'));
  });
  // data-i18n-html="key" -> innerHTML (for strings containing tags like <br>)
  document.querySelectorAll('[data-i18n-html]').forEach(function(el) {
    el.innerHTML = t(el.getAttribute('data-i18n-html'));
  });
  // data-i18n-ph="key" -> placeholder
  document.querySelectorAll('[data-i18n-ph]').forEach(function(el) {
    el.placeholder = t(el.getAttribute('data-i18n-ph'));
  });
  // data-i18n-title="key" -> title attribute
  document.querySelectorAll('[data-i18n-title]').forEach(function(el) {
    el.title = t(el.getAttribute('data-i18n-title'));
  });
  // Sana labelini yangilash (kun nomi + oy nomi til-ga qarab)
  var dateEl = document.getElementById('date-label');
  if (dateEl) {
    var now = new Date();
    dateEl.textContent = getDaysArr()[now.getDay()] + ', ' + now.getDate() + ' ' + getMonthsArr()[now.getMonth()] + ' ' + now.getFullYear();
  }
  // Header'dagi ism (yoki neytral "Profile" so'zi) tilga qarab yangilansin
  try { if (typeof S !== 'undefined') updateHeaderUserTitle(); } catch(e) {}
  // 🍅 Pomodoro Tarix bo'limi ochiq bo'lsa, uning matnlari ham yangi tilda qayta chizilsin
  try { if (typeof window.pomoRenderHistoryIfOpen === 'function') window.pomoRenderHistoryIfOpen(); } catch(e) {}
  // Kalendar hafta-kunlari sarlavhasi va oy xulosasi ham til o'zgarganda
  // darhol yangi tilda qayta chizilsin (ilgari bular hardcoded edi).
  try { if (typeof renderCalendar === 'function' && document.getElementById('cal-grid')) renderCalendar(); } catch(e) {}
  // Maqsadlar kalendari ham til o'zgarganda qayta chizilsin
  try { if (typeof renderGoalsCalendar === 'function' && document.getElementById('gcal-grid')) renderGoalsCalendar(); } catch(e) {}
  // 👥 Do'stlar modali ochiq bo'lsa, uning matnlari ham yangi tilda qayta chizilsin
  try {
    var frOverlay = document.getElementById('friends-modal-overlay');
    if (frOverlay && frOverlay.classList.contains('open') && typeof renderFriendsAll === 'function') renderFriendsAll();
  } catch(e) {}
}
document.addEventListener('DOMContentLoaded', applyLanguage);
