// Level tizimi (XP asosida, tangadan alohida)
// Kuniga ~15 vazifa (~175 XP/kun), Lv2 uchun ~3 kun
var LEVELS = [
  {min:0,    max:524,  level:1, name:"Yangi boshlagan",  icon:'🌱', reward:0},
  {min:525,  max:1574, level:2, name:"Harakat qiluvchi", icon:'🔥', reward:50},
  {min:1575, max:3674, level:3, name:"Izchil o'quvchi",  icon:'📚', reward:100},
  {min:3675, max:7874, level:4, name:"Intizomli",         icon:'⚡', reward:200},
  {min:7875, max:16274,level:5, name:"Ustoz darajasi",    icon:'🎓', reward:400},
  {min:16275,max:33074,level:6, name:"Chempion",          icon:'🏆', reward:800},
  {min:33075,max:999999,level:7,name:"Legenda",           icon:'👑', reward:1500},
];
// XP manbalari — kuniga ~15 vazifa + 100% bonus = ~175 XP/kun
var XP_PER_TASK_EASY = 3;
var XP_PER_TASK_MED  = 6;
var XP_PER_TASK_HARD = 9;
var XP_DAILY_100 = 25;
var XP_STREAK_BONUS = {3:20, 5:35, 7:50, 10:80, 15:120, 20:180, 25:250, 30:350};

// ============ O'YIN QIYINLIGI (Game Difficulty) — Coin/XP ko'paytiruvchisi ============
// coinXp — vazifa bajarilganda/bajarilmaganda beriladigan Coin va XP miqdoriga ko'paytiruvchi.
var DIFFICULTY_MULTIPLIERS = {
  easy:     { coinXp: 1.5 },
  normal:   { coinXp: 1.0 },
  hardcore: { coinXp: 0.7 }
};
function getDifficultyMultipliers() {
  var d = (S && S.difficulty) || 'normal';
  return DIFFICULTY_MULTIPLIERS[d] || DIFFICULTY_MULTIPLIERS.normal;
}

function getLevel(xp) {
  const total = xp || 0;
  return LEVELS.find(l => total >= l.min && total <= l.max) || LEVELS[LEVELS.length-1];
}

function addXP(amount, reason) {
  if(!S.xp) S.xp = 0;
  const oldLevel = getLevel(S.xp).level;
  S.xp += amount;
  if(S.xp < 0) S.xp = 0; // XP manfiy bo'lib qolmasin (Undone qaytarilganda)
  const newLevel = getLevel(S.xp).level;
  if(newLevel > oldLevel) {
    const lv = getLevel(S.xp);
    setTimeout(function(){ showLevelUpModal(lv); }, 400);
  }
}

function taskXPValue(tsk) {
  if (taskCoinValue(tsk) === 0) return 0;
  var base = tsk.diff===3 ? XP_PER_TASK_HARD : tsk.diff===2 ? XP_PER_TASK_MED : XP_PER_TASK_EASY;
  return Math.max(1, Math.round(base * getDifficultyMultipliers().coinXp));
}

function showLevelUpModal(lv) {
  confetti(); confetti();
  SFX.levelUp();
  var reward = lv.reward || 0;
  var ov = document.createElement('div');
  ov.className = 'levelup-overlay';
  ov.innerHTML =
    '<div class="levelup-box">' +
      '<span class="levelup-icon">' + lv.icon + '</span>' +
      '<div class="levelup-title">⭐ ' + t('levelup_title') + ' ⭐</div>' +
      '<div class="levelup-name">' + levelName(lv) + '</div>' +
      '<div class="levelup-sub">' + t('levelup_sub').replace('{level}', lv.level) +
        (reward > 0 ? '<br><span style="color:var(--gold);font-weight:700;font-size:var(--fs-lg)">+' + reward + ' 🪙 ' + t('levelup_bonus_coins') + '</span>' : '') +
      '</div>' +
      '<button class="levelup-btn" id="lu-close">' + t('levelup_btn') + '</button>' +
    '</div>';
  document.body.appendChild(ov);
  if(reward > 0) {
    S.coins += reward;
    if(!S.totalCoins) S.totalCoins = 0;
    S.totalCoins += reward;
    addTarixLog('in', lv.icon + ' Level ' + lv.level + ' ' + t('levelup_log_suffix'), reward);
    setTimeout(function(){ SFX.coin(); }, 420);
    save(); render();
  }
  document.getElementById('lu-close').onclick = function(){ SFX.click(); ov.remove(); };
  ov.addEventListener('click', function(e){ if(e.target === ov) ov.remove(); });
}
