function normalizeImportedBackup(backup) {
  if (!backup || typeof backup !== 'object') return null;
  var keys = {};

  var rawType = backup.exportType;
  var exportTypeArr = Array.isArray(rawType) ? rawType.slice() : [rawType || 'all'];
  exportTypeArr = exportTypeArr.filter(Boolean);
  if (exportTypeArr.length === 0) exportTypeArr = ['all'];
  var isAll = exportTypeArr.indexOf('all') !== -1;

  if (backup.data && typeof backup.data === 'object') {
    // JORIY FORMAT (performExport tomonidan yaratiladi)
    if (isAll) {
      // "Barchasi" eksportida data — to'g'ridan-to'g'ri localStorage
      // kalit->qiymat xaritasi (allKeys).
      Object.keys(backup.data).forEach(function(k){
        if (k.indexOf(BACKUP_KEY_PREFIX) === 0 && typeof backup.data[k] === 'string') keys[k] = backup.data[k];
      });
    }
    if (typeof backup.data.state === 'string' && !keys[LOCAL_STATE_KEY]) keys[LOCAL_STATE_KEY] = backup.data.state;
    if (typeof backup.data.tasks === 'string' && !keys[LOCAL_TASKS_KEY]) keys[LOCAL_TASKS_KEY] = backup.data.tasks;
    if (typeof backup.data.exams === 'string') keys['__exams__'] = backup.data.exams;
  } else if (backup.keys && typeof backup.keys === 'object') {
    // Vaqtinchalik/eski "yangi format" — { keys: {...} }
    Object.keys(backup.keys).forEach(function(k){ keys[k] = backup.keys[k]; });
  } else if (Array.isArray(backup.tasks) || backup.state) {
    // Eng eski format — { tasks: [...], state: {...} }
    if (Array.isArray(backup.tasks)) keys[LOCAL_TASKS_KEY] = JSON.stringify(backup.tasks);
    if (backup.state) keys[LOCAL_STATE_KEY] = JSON.stringify(backup.state);
  }

  if (Object.keys(keys).length === 0) return null;

  return {
    keys: keys,
    exportType: exportTypeArr,
    isAll: isAll,
    meta: backup.meta || {},
    exported_at: backup.exported_at || null
  };
}

function importAppData(event) {
  var file = event.target.files && event.target.files[0];
  if (!file) return;
  var reader = new FileReader();
  reader.onload = function(e) {
    try {
      var backup = JSON.parse(e.target.result);
      var norm = normalizeImportedBackup(backup);
      if (!norm) {
        toast(t('data_import_error'));
        return;
      }
      showImportConfirmModal(norm);
    } catch(err) {
      console.warn('Import xatosi:', err);
      toast(t('data_import_error'));
    }
  };
  reader.readAsText(file);
}

