var _suppressAutoParentComplete = false;

// "Ha/Yo'q" so'rovi — sub-tasklari hali tugallanmagan vazifani Done
// qilishga urinilganda (faqat subtaskAskCompleteOnParentDone yoqilgan bo'lsa) chiqadi.
function askMarkSubtasksDoneModal(tsk, callback) {
  var ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.8);z-index:650;display:flex;align-items:center;justify-content:center;padding:20px';
  var box = document.createElement('div');
  box.style.cssText = "background:#1C1C25;border:2px solid rgba(124,92,252,0.4);border-radius:var(--radius-xl);padding:26px 22px;width:100%;max-width:320px;text-align:center;font-family:'DM Sans',sans-serif";
  box.innerHTML =
    '<div style="font-size:34px;margin-bottom:10px">🧩</div>' +
    '<div style="color:var(--text);font-size:var(--fs-sm);line-height:1.6;margin-bottom:20px">' + esc(t('subtask_ask_confirm_text')) + '</div>' +
    '<div style="display:flex;gap:10px">' +
      '<button id="smd-no" style="flex:1;padding:11px;border-radius:var(--radius-md);border:1px solid var(--border);background:transparent;color:var(--text-muted);font-weight:600;cursor:pointer;font-size:13px">' + t('subtask_ask_confirm_no') + '</button>' +
      '<button id="smd-yes" style="flex:1;padding:11px;border-radius:var(--radius-md);border:none;background:linear-gradient(135deg,#7C5CFC,#5B3FD4);color:#fff;font-weight:700;cursor:pointer;font-size:13px">' + t('subtask_ask_confirm_yes') + '</button>' +
    '</div>';
  ov.appendChild(box);
  document.body.appendChild(ov);
  function close(markAll) { ov.remove(); callback(markAll); }
  document.getElementById('smd-no').onclick = function () { close(false); };
  document.getElementById('smd-yes').onclick = function () { close(true); };
  ov.addEventListener('mousedown', function (e) { if (e.target === ov) close(false); });
}

function toggleTask(id) {
  var tsk = S.tasks.find(function (x) { return x.id === id; });
  if (!tsk) return;
  if (!tsk.done) {
    ensureSubtaskAutoSettingsDefaults();
    var _subs = ensureSubtasks(tsk);
    var _hasPending = _subs.some(function (s) { return !s.done && !s.skipped; });
    if (S.subtaskAskCompleteOnParentDone && _hasPending) {
      askMarkSubtasksDoneModal(tsk, function (markAll) {
        if (markAll) {
          _suppressAutoParentComplete = true;
          _subs.forEach(function (s) {
            if (!s.done && !s.skipped) toggleSubtask(tsk.id, s.id, null, true);
          });
          _suppressAutoParentComplete = false;
        }
        toggleTaskInternal(id);
      });
      return;
    }
  }
  toggleTaskInternal(id);
}

function toggleTaskInternal(id) {
  const tsk = S.tasks.find(x=>x.id===id); if(!tsk) return;
  tsk.done = !tsk.done;
  if (tsk.done) {
    SFX.taskCheck();
    tsk.doneDate = today(); tsk.skipped=false; tsk.skippedDate=null;
    if (tsk.repeat==='interval') { tsk.lastDoneDate=today(); tsk.nextDate=computeNextIntervalDate(tsk); }
    // Streak uchun kun tarixi — reset bo'lganda ham yo'qolmaydi
    if (!S.taskDoneLog) S.taskDoneLog = {};
    if (!S.taskDoneLog[tsk.id]) S.taskDoneLog[tsk.id] = [];
    var td0 = today();
    if (S.taskDoneLog[tsk.id].indexOf(td0) === -1) S.taskDoneLog[tsk.id].push(td0);
    // Soat bo'yicha tracking (eng samarali soat uchun)
    var doneHour = new Date().getHours();
    if (!S.taskDoneHourLog) S.taskDoneHourLog = {};
    S.taskDoneHourLog[doneHour] = (S.taskDoneHourLog[doneHour]||0) + 1;
    // Har safar bajarilganda alohida counter (streak log sanasi emas)
    if (!S.taskDoneCount) S.taskDoneCount = {};
    S.taskDoneCount[tsk.id] = (S.taskDoneCount[tsk.id]||0) + 1;
    bumpLifetimeTaskStat(tsk, 1);
    var _grantedCoins = grantTaskReward(tsk, td0);
    if (typeof friendsRecordTaskEvent === 'function') friendsRecordTaskEvent(1, _grantedCoins);
    if(!S.totalTasksDone) S.totalTasksDone=0; S.totalTasksDone++;
    // Haftalik haqiqiy counter (log emas, har bajarilganda +1)
    if(!S.weekDoneLog) S.weekDoneLog={};
    var wk = today();
    S.weekDoneLog[wk] = (S.weekDoneLog[wk]||0) + 1;
    if(tsk.diff===3){ if(!S.hardTasksDone) S.hardTasksDone=0; S.hardTasksDone++; }
    addTarixLog('in', tsk.name, _grantedCoins);
    // XP qo'shish
    var xpGain = taskXPValue(tsk);
    addXP(xpGain, tsk.name);
    toast(t('task_done_xp_toast').replace('{coins}', _grantedCoins).replace('{xp}', xpGain)); confetti();
    // Kunlik 100% tekshiruvi (kechiktirib)
    setTimeout(checkDailyComplete, 300);

    ensureSubtaskAutoSettingsDefaults();
    if (S.subtaskExtractOnDone) {
      extractPendingSubtasksOnParentDone(tsk);
    }

    var _foldedBack = false;
    if (tsk.fromParentId) {
      var _parent = S.tasks.find(function(x){ return x.id === tsk.fromParentId; });
      if (_parent) {
        foldExtractedTaskIntoParent(tsk, _parent, true, today());
        S.tasks = S.tasks.filter(function(x){ return x.id !== tsk.id; });
        _foldedBack = true;
      }
    }
  } else {
    SFX.click();
    tsk.doneDate=null;
    if (tsk.repeat==='interval') { tsk.nextDate=today(); }
    // Streak log dan ham olib tashlash
    if (S.taskDoneLog && S.taskDoneLog[tsk.id]) {
      var td1 = today();
      S.taskDoneLog[tsk.id] = S.taskDoneLog[tsk.id].filter(function(d){ return d !== td1; });
    }
    var _revokedCoins = revokeTaskReward(tsk, today());
    if (typeof friendsRecordTaskEvent === 'function') friendsRecordTaskEvent(-1, -_revokedCoins);
    if(S.totalTasksDone>0) S.totalTasksDone--;
    if(S.weekDoneLog && S.weekDoneLog[today()] > 0) S.weekDoneLog[today()]--;
    if(tsk.diff===3 && S.hardTasksDone>0) S.hardTasksDone--;
    if (S.taskDoneCount && S.taskDoneCount[tsk.id] > 0) S.taskDoneCount[tsk.id]--;
    bumpLifetimeTaskStat(tsk, -1);
    var xpLoss = taskXPValue(tsk);
    addXP(-xpLoss, tsk.name + ' (bekor qilindi)');
    var _pulledBack = S.tasks.filter(function(x){ return x.fromParentId === tsk.id && !x.done; });
    if (_pulledBack.length) {
      _pulledBack.forEach(function(pt) {
        foldExtractedTaskIntoParent(pt, tsk, false, null);
      });
      S.tasks = S.tasks.filter(function(x){ return !(x.fromParentId === tsk.id && !x.done); });
      ensureFullTaskOrder();
    }
  }
  save(); render();
  renderStats();
  renderBadges();
}

function checkDailyComplete() {
  var todayTasks = S.tasks.filter(function(t){
    if(t.postponedTo && t.postponedTo > today()) return false;
    return taskDueToday(t);
  });
  if(todayTasks.length===0) return;
  var allDone = todayTasks.every(function(t){ return t.done || t.skipped; });
  if(allDone && S.dailyBonusDate !== today()) {
    S.dailyBonusDate = today();
    addXP(XP_DAILY_100, 'Kunlik 100%');
    toast('🌟 ' + t('daily_100_toast').replace('{xp}', XP_DAILY_100));
    confetti();
    SFX.firework();
    save(); render();
  }
}

