function vibrateShort() {
  try { if (navigator.vibrate) navigator.vibrate(10); } catch(e) {}
}

// S.taskOrder massivini barcha mavjud vazifa ID'lari bilan to'ldiradi
// (o'chirilgan vazifalarni olib tashlaydi, yangilarini oxiriga qo'shadi).
function ensureFullTaskOrder() {
  var existing = Array.isArray(S.taskOrder) ? S.taskOrder.filter(function(id) {
    return S.tasks.some(function(x) { return x.id === id; });
  }) : [];
  var known = {};
  existing.forEach(function(id) { known[id] = true; });
  S.tasks.forEach(function(t) {
    if (!known[t.id]) { existing.push(t.id); known[t.id] = true; }
  });
  S.taskOrder = existing;
}

// Bitta ro'yxat (masalan #daily-list) ichida foydalanuvchi qo'lda
// o'zgartirgan tartibni o'qib, uni global S.taskOrder ichiga joylaydi.
function applySortableOrder(containerEl) {
  if (!containerEl) return;
  var visibleIds = Array.prototype.slice.call(containerEl.children)
    .map(function(el) { return parseInt(el.dataset && el.dataset.id, 10); })
    .filter(function(id) { return !isNaN(id); });
  if (!visibleIds.length) return;

  ensureFullTaskOrder();
  var visibleSet = {};
  visibleIds.forEach(function(id) { visibleSet[id] = true; });

  var result = [];
  var inserted = false;
  S.taskOrder.forEach(function(id) {
    if (visibleSet[id]) {
      if (!inserted) { result = result.concat(visibleIds); inserted = true; }
      // shu blokdagi qolgan id'lar allaqachon qo'shildi — o'tkazib yuboriladi
    } else {
      result.push(id);
    }
  });
  if (!inserted) result = result.concat(visibleIds);

  S.taskOrder = result;
  save();
}

var _taskSortableInited = false;
function initTaskSortable() {
  if (typeof Sortable === 'undefined') return; // kutubxona hali yuklanmagan bo'lsa
  if (_taskSortableInited) return;
  _taskSortableInited = true;
  ['daily-list', 'once-list'].forEach(function(listId) {
    var el = document.getElementById(listId);
    if (!el) return;
    Sortable.create(el, {
      draggable: '.task-card',
      filter: '.check-btn, .act-btn, .task-menu-btn, .task-note-toggle, .task-label-dot, .task-dots-btn, .task-dropdown-menu, .task-dropdown-item, .task-note, .subtask-add-quick-btn, .task-quick-btn, .subtask-done-toggle, .subtask-check',
      preventOnFilter: false,
      delay: 160,             // bosib turish kerak bo'lgan vaqt (ms)
      delayOnTouchOnly: true, // sichqonchada (desktop) darhol, mobil ekranda ushlab turish talab qilinadi
      touchStartThreshold: 6,
      animation: 180,
      ghostClass: 'drag-over',
      chosenClass: 'dragging',
      dragClass: 'dragging',
      forceFallback: false,
      fallbackTolerance: 3,
      onStart: function() {
        vibrateShort(); // yengil vibratsiya — sudrash boshlanganda
        clearSubtaskDragState();
      },
      onMove: function(evt) {
        return handleSubtaskHoverMove(evt);
      },
      onEnd: function(evt) {
        var popupOpen = !!_subtaskDragState.popupEl;
        if (!popupOpen) {
          clearSubtaskDragState();
          applySortableOrder(evt.to);
        }
      }
    });
  });
}
document.addEventListener('DOMContentLoaded', initTaskSortable);
if (document.readyState !== 'loading') initTaskSortable();

function applyColorSortOrder() {
  if (!Array.isArray(S.colorSortOrder) || !S.colorSortOrder.length) return;
  ensureFullTaskOrder();
  var colorRank = {};
  S.colorSortOrder.forEach(function(c, i) { colorRank[c] = i; });
  var maxRank = S.colorSortOrder.length;
  var idToTask = {};
  S.tasks.forEach(function(t) { idToTask[t.id] = t; });
  // Barqaror (stable) saralash: bir xil rangdagi vazifalarning o'zaro
  // nisbiy tartibi o'zgarmaydi — faqat ranglar guruhi bo'yicha ko'chadi.
  var withIndex = S.taskOrder.map(function(id, idx) { return { id: id, idx: idx }; });
  withIndex.sort(function(a, b) {
    var ta = idToTask[a.id], tb = idToTask[b.id];
    var ca = ta ? (ta.label || '') : '';
    var cb = tb ? (tb.label || '') : '';
    var ra = colorRank.hasOwnProperty(ca) ? colorRank[ca] : maxRank;
    var rb = colorRank.hasOwnProperty(cb) ? colorRank[cb] : maxRank;
    if (ra !== rb) return ra - rb;
    return a.idx - b.idx;
  });
  S.taskOrder = withIndex.map(function(x) { return x.id; });
}

var _lbSortableInited = false;
function initLabelBreakdownSortable() {
  if (typeof Sortable === 'undefined') return; // kutubxona hali yuklanmagan bo'lsa
  if (_lbSortableInited) return;
  var el = document.getElementById('label-breakdown-list');
  if (!el) return;
  _lbSortableInited = true;
  Sortable.create(el, {
    draggable: '.lb-row',
    delay: 120,
    delayOnTouchOnly: true,
    touchStartThreshold: 6,
    animation: 180,
    ghostClass: 'drag-over',
    chosenClass: 'dragging',
    dragClass: 'dragging',
    forceFallback: false,
    fallbackTolerance: 3,
    onStart: function() { vibrateShort(); },
    onEnd: function(evt) {
      var newOrder = Array.prototype.slice.call(evt.to.children)
        .map(function(row) { return row.getAttribute('data-color') || ''; });
      S.colorSortOrder = newOrder;
      applyColorSortOrder();
      save();
      render();
      try { toast(t('lb_order_changed_toast')); } catch (e) {}
    }
  });
}
document.addEventListener('DOMContentLoaded', initLabelBreakdownSortable);
if (document.readyState !== 'loading') initLabelBreakdownSortable();


function moveTask(id, dir) {
  ensureFullTaskOrder();
  var idx = S.taskOrder.indexOf(id);
  var newIdx = idx + dir;
  if (newIdx < 0 || newIdx >= S.taskOrder.length) return;
  // Swap
  var tmp = S.taskOrder[idx];
  S.taskOrder[idx] = S.taskOrder[newIdx];
  S.taskOrder[newIdx] = tmp;
  save(); render();
  // Scroll to card and highlight
  setTimeout(function(){
    var card = document.querySelector('[data-id="'+id+'"]');
    if (card) {
      card.scrollIntoView({ behavior:'smooth', block:'nearest' });
      card.style.transition = 'box-shadow 0.3s';
      card.style.boxShadow = '0 0 0 2px var(--accent)';
      setTimeout(function(){ card.style.boxShadow = ''; }, 600);
    }
  }, 60);
}

// ---- Rewards ----
// -- Reward form helpers --
var _rewardType = '';

function normalizeDigits(str) {
  if (str == null) return '';
  var map = {
    '۰':'0','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5','۶':'6','۷':'7','۸':'8','۹':'9', // fors-arab
    '٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9', // arab
    '०':'0','१':'1','२':'2','३':'3','४':'4','५':'5','६':'6','७':'7','८':'8','९':'9'  // devanagari
  };
  return String(str).replace(/[۰-۹٠-٩०-९]/g, function(ch){ return map[ch] || ch; })
                     .replace(/[^\d.\-]/g, ''); // bo'shliq, valyuta belgisi va h.k. ni tashlab yuboradi
}
function parseIntSafe(str) {
  var n = parseInt(normalizeDigits(str), 10);
  return isNaN(n) ? 0 : n;
}

