function rewardStepCheck() {}

function toggleAddReward() {
  var body = document.getElementById('add-reward-body');
  var arrow = document.getElementById('add-reward-arrow');
  var open = body.style.display !== 'none';
  body.style.display = open ? 'none' : '';
  arrow.style.transform = open ? '' : 'rotate(-90deg)';
}

var _addingRewardInProgress = false;

function addReward() {
  if (_addingRewardInProgress) return;

  if (getDebtTier() === 2) {
    toast('🚫 ' + t('debt_tier2_add_blocked_toast'));
    return;
  }

  var name = (document.getElementById('r-name').value||'').trim();
  var cost = parseIntSafe(document.getElementById('r-cost').value);
  var icon = (document.getElementById('r-icon').value||'').trim() || '🎁';
  var amount = parseIntSafe(document.getElementById('r-amount').value);

  var body = document.getElementById('add-reward-body');
  var domAttrType = body ? (body.getAttribute('data-selected-rtype') || '') : '';
  var timeBtn = document.getElementById('rtype-time');
  var countBtn = document.getElementById('rtype-count');
  var domClassType = timeBtn && /\bsel\b/.test(timeBtn.className) ? 'time'
                    : countBtn && /\bsel\b/.test(countBtn.className) ? 'count'
                    : '';
  var effectiveType = domAttrType || domClassType || _rewardType || '';
  if (effectiveType && effectiveType !== _rewardType) {
    console.warn('addReward(): rtype manbalari mos kelmadi (var="'+_rewardType+'", dom-attr="'+domAttrType+'", dom-class="'+domClassType+'"), DOM asosida to\'g\'irlandi ->', effectiveType);
  }
  _rewardType = effectiveType;

  if(!name){ document.getElementById('r-name').focus(); toast(t('reward_name_required_toast')); return; }
  if(!(cost>0)){ document.getElementById('r-cost').focus(); toast(t('reward_cost_required_toast')); return; }
  if(!_rewardType){ toast(t('reward_type_required_toast')); return; }
  if(!(amount>0)){ document.getElementById('r-amount').focus(); toast(_rewardType==='time'?t('reward_minutes_required_toast'):t('reward_amount_required_toast')); return; }

  _addingRewardInProgress = true;
  try {
    if(!S.rewards) S.rewards=[];
    if(!S.nextRid) S.nextRid=Date.now();

    var fullName;
    if(_rewardType === 'time') {
      var h = Math.floor(amount/60), m = amount%60;
      var timeStr = h>0 ? (h+' '+t('time_hour_unit')+(m>0?' '+m+' '+t('time_min_unit'):'')) : amount+' '+t('time_min_unit');
      fullName = name + ' ' + timeStr;
    } else {
      fullName = name;
    }

    var newReward = {
      id: S.nextRid++,
      name: fullName,
      icon: icon,
      cost: cost,
      rtype: _rewardType,      // 'time' | 'count'
      amount: amount,          // 'time' bo'lsa — daqiqa, 'count' bo'lsa — dona
      baseName: name
    };
    S.rewards.push(newReward);

    document.getElementById('r-name').value='';
    document.getElementById('r-cost').value='';
    document.getElementById('r-icon').value='';
    document.getElementById('r-amount').value='';
    document.getElementById('rstep-4').style.display='none';
    _rewardType='';
    if (body) body.removeAttribute('data-selected-rtype');
    document.getElementById('rtype-time').className='rtype-btn';
    document.getElementById('rtype-count').className='rtype-btn';
    document.querySelectorAll('.rcost-chip').forEach(function(b){b.className='rcost-chip';});
    document.querySelectorAll('.remoji-chip').forEach(function(b){b.className='remoji-chip';});

    save(); renderRewards(); toast(t('reward_added_toast'));
  } finally {
    _addingRewardInProgress = false;
  }
}


var _claimingRewardIds = {};

function claimReward(id) {
  if (_claimingRewardIds[id]) return;
  _claimingRewardIds[id] = true;
  try {
    if(!S.rewards)S.rewards=[];
    var r=S.rewards.find(function(x){return x.id===id;});
    if(!r){toast(t('reward_not_found_toast'));return;}
    if (isRewardBlockedByDebt(r.id)) {
      toast(getDebtTier() === 2 ? t('debt_tier2_toast') : t('reward_blocked_toast'));
      return;
    }
    S.coins=(S.coins||0)-safeCost;
    if(!S.rewardClaims)S.rewardClaims={};
    var addCount = (r.amount>0) ? r.amount : 1;
    S.rewardClaims[r.id]=(S.rewardClaims[r.id]||0)+addCount;
    S.totalPurchases=(S.totalPurchases||0)+1;
    recordPurchase(r, safeCost);
    addTarixLog('out',r.icon+' '+r.name+' '+t('reward_purchased_log_suffix'),-safeCost);
    toast(t('reward_claimed_toast').replace('{icon}', r.icon).replace('{name}', r.name).replace('{cost}', safeCost)); confetti(); SFX.click(); save(); render();
  } finally {
    _claimingRewardIds[id] = false;
  }
}

function deleteReward(id) {
  if (isRewardBlockedByDebt(id)) {
    toast('🚫 ' + t('reward_delete_blocked_debt_toast'));
    return;
  }
  S.rewards=S.rewards.filter(x=>x.id!==id);
  if (S.rewardClaims && (id in S.rewardClaims)) delete S.rewardClaims[id];
  if (S.usageLog && (id in S.usageLog)) delete S.usageLog[id];
  save();
  renderRewards();
}

function showProfileSubtab(name) {
  ['overview','stats','badges','settings'].forEach(function(n){
    var panel = document.getElementById('profile-subtab-'+n);
    if (panel) panel.style.display = (n===name) ? '' : 'none';
    var btn = document.querySelector('.profile-subtab-btn[data-subtab="'+n+'"]');
    if (btn) btn.className = 'tab profile-subtab-btn'+(n===name?' active':'');
  });
  // Statistika bo'limiga o'tilganda Pomodoro grafigini qayta chizamiz —
  // panel avval display:none bo'lgani uchun canvas kengligi 0 bo'lishi mumkin edi.
  if (name === 'stats' && typeof pomoStatsRender === 'function') pomoStatsRender();
  try { SFX.click(); } catch(e) {}
}

function showTab(tab) {
  if (tab === 'secret' && !S.personalCheckEnabled) { showTab('tasks'); return; }
  if (tab !== 'secret' && _secretUnlocked) {
    _secretUnlocked = false;
    _pinBuffer = '';
    if (typeof _pcClearAutoLockTimer === 'function') _pcClearAutoLockTimer();
  }
  if (tab !== 'stats' && tab !== 'calendar') SFX.click();
  ['tasks','rewards','spin','profile','tarix','secret','goals','chest','ielts','sat','cefr','reyting'].forEach(function(t){
    var el=document.getElementById('view-'+t);
    if(el) el.style.display=tab===t?'':'none';
    var tb=document.getElementById('tab-'+t);
    if(tb) tb.className='tab'+(tab===t?' active':'');
  });
  var _reytingPanel = document.getElementById('reyting-myrank-panel');
  if (_reytingPanel) _reytingPanel.style.display = (tab==='reyting') ? '' : 'none';
  if (tab !== 'reyting') { stopReytingCountdown(); stopReytingAutoRefresh(); }
  if(tab==='rewards') renderRewards();
  if(tab==='spin') renderSpin();
  if(tab==='profile') { renderProfile(); renderStats(); renderCalendar(); try{renderGoalsCalendar();}catch(e){} renderIeltsCountdown(); }
  if(tab==='tarix') renderTarix();
  if(tab==='secret') openSecretTab();
  if(tab==='goals') { checkNotifBar(); renderGoals(); renderGoalsCalendar(); }
  if(tab==='reyting') renderReyting();
  if(tab==='chest') renderChest();
  if(tab==='ielts') renderIeltsTab();
  if(tab==='sat') renderSatTab();
  if(tab==='cefr') renderCefrTab();
  if(tab==='stats') { showTab('profile'); return; }
  if(tab==='calendar') { showTab('profile'); return; }
}

var toastTimer;
function toast(msg) {
  const el=document.getElementById('toast'); el.textContent=msg;
  el.classList.add('show'); clearTimeout(toastTimer);
  toastTimer=setTimeout(()=>el.classList.remove('show'),2500);
}

var _lastConfettiSfxAt = 0;
function confetti() {
  const colors=['#7C5CFC','#F5A623','#34D399','#F87171','#B48EFF','#60A5FA'];
  for(let i=0;i<14;i++){
    const dot=document.createElement('div'); dot.className='confetti-dot';
    dot.style.cssText=`left:${Math.random()*100}vw;top:${Math.random()*30+20}vh;background:${colors[Math.floor(Math.random()*colors.length)]};width:${Math.random()*6+5}px;height:${Math.random()*6+5}px;`;
    document.body.appendChild(dot); setTimeout(()=>dot.remove(),1000);
  }
  var _now = Date.now();
  if (_now - _lastConfettiSfxAt > 150) {
    _lastConfettiSfxAt = _now;
    SFX.firework();
  }
}

function repeatLabel(t) {
  if (t.repeat==='daily') return {text:tr('badge_daily'), cls:'badge-repeat'};
  if (t.repeat==='weekdays') return {text:tr('badge_weekdays'), cls:'badge-weekly'};
  if (t.repeat==='custom-days') {
    const names=(t.days||[]).map(d=>getShortDaysArr()[d]).join(', ');
    return {text:names, cls:'badge-weekly'};
  }
  if (t.repeat==='interval') return {text:tr('badge_interval').replace('{n}', t.interval), cls:'badge-repeat'};
  return {text:tr('badge_once'), cls:'badge-once'};
}

function diffBadge(d) {
  if(d===3) return '<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#F87171;flex-shrink:0" title="'+tr('diff_hard_title')+'"></span>';
  if(d===2) return '<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#F5A623;flex-shrink:0" title="'+tr('diff_medium_title')+'"></span>';
  if(d===0) return '<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#F0EEF8;border:1px solid rgba(0,0,0,0.25);flex-shrink:0" title="'+tr('diff_free_title')+'"></span>';
  return '<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#34D399;flex-shrink:0" title="'+tr('diff_easy_title')+'"></span>';
}
// t.diff qiymati 0 bo'lishi mumkin (Bepul daraja) — shuning uchun "||1" o'rniga
// aniq undefined/null tekshiruvi ishlatiladi, aks holda 0 noto'g'ri 1'ga aylanib qolardi.
function taskDiffOrDefault(t) {
  return (t && t.diff !== undefined && t.diff !== null) ? t.diff : 1;
}

var editingRewardId = null;
var _editRewardType = '';

function selEditRewardType(type) {
  _editRewardType = type;
  document.getElementById('er-rtype-time').className = 'rtype-btn' + (type==='time'?' sel':'');
  document.getElementById('er-rtype-count').className = 'rtype-btn' + (type==='count'?' sel':'');
  var label = document.getElementById('er-amount-label');
  var inp = document.getElementById('er-amount');
  var labelKey = type === 'time' ? 'reward_time_label' : 'reward_count_label';
  var phKey = type === 'time' ? 'reward_time_ph' : 'reward_count_ph';
  label.setAttribute('data-i18n', labelKey);
  label.textContent = t(labelKey);
  inp.setAttribute('data-i18n-ph', phKey);
  inp.placeholder = t(phKey);
}

function openRewardEditModal(id) {
  const r = S.rewards.find(x=>x.id===id);
  if(!r){ toast(t('reward_not_found_toast')); return; }
  if (isRewardBlockedByDebt(id)) {
    toast(getDebtTier() === 2 ? t('debt_tier2_toast') : t('reward_blocked_toast'));
    return;
  }
  editingRewardId = id;
  document.getElementById('er-name').value = r.name;
  document.getElementById('er-cost').value = r.cost;
  document.getElementById('er-icon').value = r.icon;
  document.getElementById('er-amount').value = r.amount || '';
  selEditRewardType(r.rtype === 'time' ? 'time' : 'count');
  document.getElementById('reward-modal-overlay').classList.add('open');
  setTimeout(()=>document.getElementById('er-name').focus(),150);
}
function closeRewardModal() {
  document.getElementById('reward-modal-overlay').classList.remove('open');
  editingRewardId = null;
}
function saveRewardEdit() {
  const r = S.rewards.find(x=>x.id===editingRewardId); if(!r) return;
  const name = document.getElementById('er-name').value.trim();
  const costRaw = parseIntSafe(document.getElementById('er-cost').value);
  const cost = (costRaw > 0) ? costRaw : r.cost;
  const icon = document.getElementById('er-icon').value.trim()||r.icon;
  const amount = parseIntSafe(document.getElementById('er-amount').value);
  if(!name){ document.getElementById('er-name').focus(); toast(t('reward_name_required_toast')); return; }
  // XATOLIK TUZATILDI: `!amount` faqat 0/NaN'ni ushlardi, manfiy sonni
  // (masalan -10 daqiqa) o'tkazib yuborardi. Endi `amount>0` tekshiriladi.
  if(!(amount>0)){ document.getElementById('er-amount').focus(); toast(_editRewardType==='time'?t('reward_minutes_required_toast'):t('reward_amount_required_toast')); return; }
  const newRtype = _editRewardType || r.rtype || 'count';

  if (newRtype !== r.rtype) {
    var hadClaims = (S.rewardClaims && S.rewardClaims[r.id]) ? true : false;
    var hadUsage = (S.usageLog && S.usageLog[r.id] && S.usageLog[r.id].length) ? true : false;
    if (!S.rewardClaims) S.rewardClaims = {};
    if (!S.usageLog) S.usageLog = {};
    S.rewardClaims[r.id] = 0;
    S.usageLog[r.id] = [];
    if (hadClaims || hadUsage) toast('⚠️ ' + t('reward_type_changed_reset_toast'));
  }
  r.rtype = newRtype;
  r.amount = amount;
  r.name=name; r.cost=cost; r.icon=icon;
  save(); renderRewards(); closeRewardModal();
  toast(t('reward_updated_toast'));
}

function parseMinutes(name) {
  const soat = name.match(/(\d+)\s*soat/i);
  if (soat) return parseInt(soat[1]) * 60;
  const daq = name.match(/(\d+)\s*daqiqa/i);
  if (daq) return parseInt(daq[1]);
  const min = name.match(/(\d+)\s*min/i);
  if (min) return parseInt(min[1]);
  return null;
}

function fixInflatedTaskDoneCounts() {
  if (S._taskDoneCountFixed) return; // faqat bir marta ishlaydi
  if (!S.taskDoneLog) { S._taskDoneCountFixed = true; return; }
  if (!S.taskDoneCount) S.taskDoneCount = {};
  Object.keys(S.taskDoneLog).forEach(function(id) {
    var accurate = (S.taskDoneLog[id] || []).length;
    S.taskDoneCount[id] = accurate;
  });
  S._taskDoneCountFixed = true;
  save();
}

function migrateLegacyRewards() {
  if (!S.rewards || !S.rewards.length) return;
  if (!S.rewardClaims) S.rewardClaims = {};
  if (!S.usageLog) S.usageLog = {};
  var changed = false;
  S.rewards.forEach(function(r) {
    if (r.rtype) return; // yangi formatda — tegilmaydi
    changed = true;
    var mins = parseMinutes(r.name || '');
    if (mins) {
      r.rtype = 'time';
      r.amount = mins;
      // Eski buggy claimReward() har xariddan faqat +1 qo'shgan —
      // haqiqiy daqiqa yig'indisiga aylantiramiz.
      var oldClaims = S.rewardClaims[r.id] || 0;
      if (oldClaims > 0) S.rewardClaims[r.id] = oldClaims * mins;
      // Eski usageLog yozuvlarida "mins" maydoni bo'lmasligi mumkin edi —
      // "count" (dona) sifatida yozilgan bo'lsa, uni ham daqiqaga o'giramiz.
      (S.usageLog[r.id] || []).forEach(function(u) {
        if (u.mins == null) u.mins = (u.count || 1) * mins;
      });
    } else {
      r.rtype = 'count';
      if (!r.amount) r.amount = 1;
    }
  });
  if (changed) save();
}

function formatMinutes(total) {
  if (total >= 60) {
    const h = Math.floor(total/60), m = total%60;
    return h+' '+t('time_hour_unit')+(m ? ' '+m+' '+t('time_min_unit') : '');
  }
  return total+' '+t('time_min_unit');
}


function closeAllTaskDropdowns() {
  document.querySelectorAll('.task-dropdown-menu.open').forEach(function(m){ m.classList.remove('open'); });
  document.querySelectorAll('.task-dots-btn.active').forEach(function(b){ b.classList.remove('active'); });
}

function toggleTaskDropdown(id, btnEl, ev) {
  if (ev) { ev.stopPropagation(); ev.preventDefault(); }
  var menu = document.getElementById('task-dd-' + id);
  if (!menu) return;
  var willOpen = !menu.classList.contains('open');
  closeAllTaskDropdowns();
  closeAllSubtaskDropdowns();
  if (willOpen) {
    menu.classList.add('open');
    if (btnEl) btnEl.classList.add('active');
  }
}

// Menyudan tashqariga bosilganda yoki Escape bosilganda yopish
document.addEventListener('click', function(e) {
  if (e.target.closest && (e.target.closest('.task-dots-wrap'))) return;
  closeAllTaskDropdowns();
  closeAllSubtaskDropdowns();
});
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') { closeAllTaskDropdowns(); closeAllSubtaskDropdowns(); }
});
// Task ro'yxati sudrab-tashlanganda (drag boshlanganda) ochiq menyularni yopamiz
document.addEventListener('scroll', function(){ closeAllTaskDropdowns(); closeAllSubtaskDropdowns(); }, true);

function closeAllSubtaskDropdowns() {
  document.querySelectorAll('.subtask-dropdown-menu.open').forEach(function(m){ m.classList.remove('open'); });
  document.querySelectorAll('.subtask-dots-btn.active').forEach(function(b){ b.classList.remove('active'); });
}

function refreshCalDetailIfOpen() {
  var detail = document.getElementById('cal-detail');
  if (!detail || detail.style.display === 'none') return;
  var ds = detail.dataset.openDate;
  if (!ds) return;
  renderDayDetailContent(ds);
}

function toggleSubtaskDropdown(taskId, subId, btnEl, ev, ctx) {
  if (ev) { ev.stopPropagation(); ev.preventDefault(); }
  var menu = document.getElementById('subtask-dd-' + (ctx||'') + taskId + '-' + subId);
  if (!menu) return;
  var willOpen = !menu.classList.contains('open');
  closeAllSubtaskDropdowns();
  closeAllTaskDropdowns();
  if (willOpen) {
    menu.classList.add('open');
    if (btnEl) btnEl.classList.add('active');
  }
}

function ensureSubtasks(t) {
  if (!t.subtasks || !Array.isArray(t.subtasks)) t.subtasks = [];
  return t.subtasks;
}

function subtaskDueToday(s, dateStr) {
  dateStr = dateStr || today();
  if (!s.repeat || s.repeat === 'once') return true;
  var dow = new Date(dateStr + 'T00:00:00').getDay();
  if (s.repeat === 'daily') return true;
  if (s.repeat === 'weekdays') return dow >= 1 && dow <= 5;
  if (s.repeat === 'custom-days' || s.repeat === 'weekly') return (s.days||[]).indexOf(dow) !== -1;
  if (s.repeat === 'interval') return s.nextDate ? s.nextDate <= dateStr : true;
  return true;
}

function subtaskDoneOnDate(taskId, subId, dateStr) {
  var key = taskId + '_' + subId;
  return !!(S.subtaskDoneLog && S.subtaskDoneLog[key] && S.subtaskDoneLog[key].indexOf(dateStr) !== -1);
}

function subtaskItemHtml(t, s, ctx, dateStr) {
  ctx = ctx || '';
  dateStr = dateStr || today();
  const isDoneOnDate = subtaskDoneOnDate(t.id, s.id, dateStr);
  const tintStyle = '';
  const labelDot = s.label ? `<span class="subtask-label-dot" style="background:${s.label}"></span>` : '';
  const ddId = 'subtask-dd-' + ctx + t.id + '-' + s.id;
  const coinDisplay = taskCoinValue(s);
  return `
      <div class="subtask-item${isDoneOnDate?' done':''}${(s.skipped&&!isDoneOnDate)?' skipped':''}" style="${tintStyle}">
        <button class="subtask-check${isDoneOnDate?' checked':''}" onclick="event.stopPropagation();toggleSubtask(${t.id},${s.id},'${dateStr}')">
          ${isDoneOnDate?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>':''}
        </button>
        ${labelDot}<span class="subtask-name">${esc(s.name)}</span>
        ${coinDisplay ? `<span class="badge badge-coins">+${coinDisplay}🪙</span>` : ''}
        <div class="task-dots-wrap subtask-dots-wrap">
          <button class="task-dots-btn subtask-dots-btn" onclick="event.stopPropagation();toggleSubtaskDropdown(${t.id},${s.id},this,event,'${ctx}')" title="${tr('task_actions_title')}">⋮</button>
          <div class="task-dropdown-menu subtask-dropdown-menu" id="${ddId}">
            ${(!s.done&&!s.skipped)?`<button class="task-dropdown-item" onclick="event.stopPropagation();closeAllSubtaskDropdowns();skipSubtask(${t.id},${s.id})"><span class="tdi-icon">⏩</span>${tr('skip_dd_item')}</button>`:''}
            ${(s.skipped&&!s.done)?`<button class="task-dropdown-item" onclick="event.stopPropagation();closeAllSubtaskDropdowns();unskipSubtask(${t.id},${s.id})"><span class="tdi-icon">↩️</span>${tr('unskip_dd_item')}</button>`:''}
            <button class="task-dropdown-item" onclick="event.stopPropagation();closeAllSubtaskDropdowns();openSubtaskModal(${t.id},${s.id})"><span class="tdi-icon">✏️</span>${tr('subtask_edit_title')}</button>
            <button class="task-dropdown-item" onclick="event.stopPropagation();closeAllSubtaskDropdowns();extractSubtaskToTask(${t.id},${s.id})"><span class="tdi-icon">↗️</span>${tr('subtask_extract_title')}</button>
            <button class="task-dropdown-item danger" onclick="event.stopPropagation();closeAllSubtaskDropdowns();deleteSubtask(${t.id},${s.id})"><span class="tdi-icon">🗑</span>${tr('subtask_delete_title')}</button>
          </div>
        </div>
      </div>`;
}

function toggleSubtaskDoneSection(taskId, btn, count, ctx) {
  const el = document.getElementById('subtask-done-' + (ctx||'') + taskId);
  if (!el) return;
  const isOpen = btn.dataset.open === '1';
  if (isOpen) {
    el.style.display = 'none';
    btn.dataset.open = '0';
    btn.textContent = tr('subtask_done_toggle_show').replace('{n}', count);
  } else {
    el.style.display = 'flex';
    btn.dataset.open = '1';
    btn.textContent = tr('subtask_done_toggle_hide');
  }
}

function renderSubtasksHtml(t, ctx, dateStr) {
  ctx = ctx || '';
  dateStr = dateStr || today();
  const subs = ensureSubtasks(t);
  if (subs.length === 0) return '';
  const pending = subs.filter(function(s){ return !subtaskDoneOnDate(t.id, s.id, dateStr) && subtaskDueToday(s, dateStr); });
  const done = subs.filter(function(s){ return subtaskDoneOnDate(t.id, s.id, dateStr); });
  let html = '';
  if (pending.length) {
    html += '<div class="subtask-list">';
    pending.forEach(function(s){ html += subtaskItemHtml(t, s, ctx, dateStr); });
    html += '</div>';
  }
  if (done.length) {
    html += `<button type="button" class="subtask-done-toggle" data-open="0" onclick="event.stopPropagation();toggleSubtaskDoneSection(${t.id}, this, ${done.length}, '${ctx}')">${tr('subtask_done_toggle_show').replace('{n}', done.length)}</button>`;
    html += `<div class="subtask-list subtask-list-done" id="subtask-done-${ctx}${t.id}" style="display:none">`;
    done.forEach(function(s){ html += subtaskItemHtml(t, s, ctx, dateStr); });
    html += '</div>';
  }
  if (pending.length + done.length > 0) {
    html += `<div class="subtask-progress">${tr('subtask_progress_label').replace('{done}', done.length).replace('{total}', pending.length + done.length)}</div>`;
  }
  return html;
}

var expandedSubtaskTasks = new Set();

var expandedCalSubtaskTasks = new Set();

function toggleCalSubtaskExpand(taskId, event) {
  if (event) event.stopPropagation();
  var wrap = document.getElementById('cal-subtask-wrap-' + taskId);
  var indicator = document.getElementById('cal-subtask-indicator-' + taskId);
  if (!wrap) return;
  var isOpen = expandedCalSubtaskTasks.has(taskId);
  if (isOpen) {
    expandedCalSubtaskTasks.delete(taskId);
    wrap.style.display = 'none';
  } else {
    expandedCalSubtaskTasks.add(taskId);
    wrap.style.display = 'block';
  }
  if (indicator) indicator.textContent = isOpen ? '▸' : '▾';
}

function toggleSubtaskExpand(taskId, event) {
  if (event) event.stopPropagation();
  var wrap = document.getElementById('subtask-wrap-' + taskId);
  var indicator = document.getElementById('subtask-indicator-' + taskId);
  if (!wrap) return;
  var isOpen = expandedSubtaskTasks.has(taskId);
  if (isOpen) {
    expandedSubtaskTasks.delete(taskId);
    wrap.style.display = 'none';
  } else {
    expandedSubtaskTasks.add(taskId);
    wrap.style.display = 'block';
  }
  if (indicator) indicator.textContent = isOpen ? '▸' : '▾';
}

// Hozir sub-task qo'shilayotgan/tahrirlanayotgan asosiy task id'si (popup ochiq bo'lganda)
var _subtaskParentId = null;
var _subtaskEditId = null;

function openSubtaskModal(taskId, subId) {
  _subtaskParentId = taskId;
  _subtaskEditId = (subId === undefined) ? null : subId;
  const input = document.getElementById('subtask-name-input');
  const titleEl = document.getElementById('subtask-modal-title');
  const stInt = document.getElementById('st-interval');
  const stSd = document.getElementById('st-startdate');
  const stDd = document.getElementById('st-duedate');

  let existing = null;
  if (_subtaskEditId !== null) {
    const tk = S.tasks.find(function(x){ return x.id === taskId; });
    existing = tk ? ensureSubtasks(tk).find(function(s){ return s.id === _subtaskEditId; }) : null;
  }

  if (existing) {
    // Tahrirlash rejimi — mavjud sub-task qiymatlari bilan to'ldiramiz.
    if (input) input.value = existing.name;
    stDiff = existing.diff||0; stRepeat = existing.repeat||'daily';
    stDays = Array.isArray(existing.days) ? [...existing.days] : [];
    stLabel = existing.label||'';
    if (stInt) stInt.value = existing.interval ? String(existing.interval) : '4';
    if (stSd) stSd.value = existing.startDate || today();
    if (stDd) stDd.value = existing.dueDate || '';
    if (titleEl) titleEl.textContent = t('subtask_modal_title_edit');
  } else {
    // Yangi qo'shish rejimi — standart qiymatlarga qaytaramiz.
    if (input) input.value = '';
    stDiff=1; stRepeat='daily'; stDays=[]; stLabel='';
    if (stInt) stInt.value='4';
    if (stSd) stSd.value = today();
    if (stDd) stDd.value = '';
    if (titleEl) titleEl.textContent = t('subtask_modal_title');
  }
  stSelDiff(stDiff); stSelRepeat(stRepeat); stSelLabel(stLabel);
  document.querySelectorAll('#subtask-modal-box .day-btn').forEach(function(el){
    el.classList.toggle('sel', stDays.includes(parseInt(el.dataset.d)));
  });
  document.getElementById('subtask-modal-overlay').classList.add('open');
  setTimeout(function(){ if(input) input.focus(); }, 150);
}

function closeSubtaskModal() {
  document.getElementById('subtask-modal-overlay').classList.remove('open');
  _subtaskParentId = null;
  _subtaskEditId = null;
}

function saveSubtaskModal() {
  const input = document.getElementById('subtask-name-input');
  const name = input ? input.value.trim() : '';
  if (!name) { if(input) input.focus(); return; }
  if (stRepeat==='custom-days' && stDays.length===0) { toast(t('task_select_day_toast')); return; }
  if (_subtaskParentId === null) return;
  const tk = S.tasks.find(function(x){ return x.id === _subtaskParentId; });
  if (!tk) { closeSubtaskModal(); return; }
  const stInt = document.getElementById('st-interval');
  const stSd = document.getElementById('st-startdate');
  const stDd = document.getElementById('st-duedate');
  const stStartDate = stRepeat==='interval' ? (stSd&&stSd.value||today()) : null;
  const stDueDate = (stDd && stDd.value) ? stDd.value : null;

  if (_subtaskEditId !== null) {
    // TAHRIRLASH: mavjud sub-taskni joyida yangilaymiz (id/done/doneDate saqlanadi).
    const sub = ensureSubtasks(tk).find(function(s){ return s.id === _subtaskEditId; });
    if (!sub) { closeSubtaskModal(); return; }
    sub.name = name;
    sub.diff = stDiff; sub.coins = stDiff;
    sub.repeat = stRepeat;
    sub.days = stRepeat==='custom-days' ? [...stDays] : null;
    sub.interval = stRepeat==='interval' ? (parseInt(stInt&&stInt.value)||4) : null;
    sub.startDate = stStartDate;
    // Takrorlanish turi o'zgargan bo'lishi mumkin — nextDate'ni ham
    // yangi boshlanish sanasiga moslab qo'yamiz (aks holda eski sanada qolib ketardi).
    sub.nextDate = stRepeat==='interval' ? stStartDate : sub.nextDate;
    sub.label = stLabel;
    if (sub.dueDate !== stDueDate) { sub.lastPenalizedDate = null; sub.penalizedDaysCount = 0; }
    sub.dueDate = stDueDate;
    try { refreshStalePenaltyAmts(S.subtaskDayFlags && S.subtaskDayFlags[sub.id], sub); } catch (e) {}
    save(); render();
    refreshCalDetailIfOpen();
    closeSubtaskModal();
    toast(t('subtask_updated_toast'));
    return;
  }

  ensureSubtasks(tk).push({
    id: genSubtaskId(), name: name, done: false,
    diff: stDiff, coins: stDiff,
    repeat: stRepeat,
    days: stRepeat==='custom-days' ? [...stDays] : null,
    interval: stRepeat==='interval' ? (parseInt(stInt&&stInt.value)||4) : null,
    startDate: stStartDate,
    nextDate: stStartDate,
    // BUG FIX: rang (label) tanlansa ham hech qachon saqlanmasdi — shu
    // sababli sub-taskda rang hech qachon ko'rinmasdi. stLabel endi obyektga yoziladi.
    label: stLabel,
    // 3-band: ixtiyoriy muddat (dueDate) — belgilansa, 1 kundan ortiq
    // kechikish uchun proporsional jarima qo'llanadi.
    dueDate: stDueDate,
    lastPenalizedDate: null, overduePenaltyTotal: 0, penalizedDaysCount: 0,
    subtasks: [] // ichki (nested) sub-tasklar zaxira maydoni — hozircha bo'sh
  });
  save(); render();
  closeSubtaskModal();
  toast(t('subtask_added_toast'));
}

function foldExtractedTaskIntoParent(pt, parent, asDone, doneDateStr) {
  var meta = pt.fromSubtaskMeta || {};
  var subsArr = ensureSubtasks(parent);
  subsArr.push({
    id: asDone ? genSubtaskId() : pt.id, name: pt.name, done: !!asDone, doneDate: asDone ? (doneDateStr || today()) : null,
    diff: meta.diff || pt.diff || 0, coins: meta.coins || pt.coins || 0,
    repeat: meta.repeat || pt.repeat || 'once',
    days: meta.days || pt.days || null,
    interval: meta.interval || pt.interval || null,
    startDate: meta.startDate || null,
    nextDate: asDone ? null : (pt.nextDate || null),
    label: meta.label || pt.label || null,
    subtasks: []
  });
  // O'zining ichida orttirgan (nested) sub-tasklari bo'lsa, ularni ham
  // ota-vazifaning asosiy .subtasks[] ro'yxatiga tekis qilib qo'shamiz.
  if (Array.isArray(pt.subtasks) && pt.subtasks.length) {
    pt.subtasks.forEach(function (nested) { subsArr.push(nested); });
  }
}

function extractSubtaskToTask(taskId, subId) {
  const tk = S.tasks.find(function(x){ return x.id === taskId; });
  if (!tk) return;
  const subs = ensureSubtasks(tk);
  const idx = subs.findIndex(function(s){ return s.id === subId; });
  if (idx === -1) return;
  const sub = subs[idx];
  const _isOriginalTaskId = typeof sub.id === 'number' && sub.id < 1e11 && !S.tasks.some(function(x){ return x.id === sub.id; });
  const newTask = {
    id: _isOriginalTaskId ? sub.id : S.nextId++, name: sub.name, diff: sub.diff||0, coins: sub.coins||0,
    repeat: sub.repeat || 'daily',
    days: sub.repeat==='custom-days' ? (sub.days||[]) : null,
    interval: sub.repeat==='interval' ? (sub.interval||4) : null,
    nextDate: sub.repeat==='interval' ? (sub.nextDate || sub.startDate || today()) : null,
    done: !!sub.done, doneDate: sub.doneDate||null, skipped:false, skippedDate:null, lastDoneDate:null,
    createdAt: sub.repeat==='interval' ? (sub.startDate || today()) : today(),
    label: sub.label || null,
    note: null, emoji: null,
    isFrozen: false, frozenAt: null,
    subtasks: Array.isArray(sub.subtasks) ? sub.subtasks : [],
    fromParentId: taskId,
    fromParentName: tk.name,
    fromSubtaskMeta: {
      diff: sub.diff||0, coins: sub.coins||0, repeat: sub.repeat||'daily',
      days: sub.repeat==='custom-days' ? (sub.days||[]) : null,
      interval: sub.repeat==='interval' ? (sub.interval||4) : null,
      startDate: sub.startDate || null,
      label: sub.label || null,
    },
  };
  S.tasks.push(newTask);
  subs.splice(idx, 1);
  ensureFullTaskOrder();
  save(); render();
  refreshCalDetailIfOpen();
  toast(t('subtask_extracted_toast'));
}

function extractPendingSubtasksOnParentDone(tk) {
  if (!tk) return;
  const subs = ensureSubtasks(tk);
  if (!subs.length) return;
  const pending = subs.filter(function (s) { return !s.done && !s.skipped; });
  if (!pending.length) return;
  pending.forEach(function (sub) {
    const newTask = {
      id: S.nextId++, name: sub.name, diff: sub.diff||0, coins: sub.coins||0,
      repeat: sub.repeat || 'daily',
      days: sub.repeat==='custom-days' ? (sub.days||[]) : null,
      interval: sub.repeat==='interval' ? (sub.interval||4) : null,
      nextDate: sub.repeat==='interval' ? (sub.nextDate || sub.startDate || today()) : null,
      done: false, doneDate: null, skipped: false, skippedDate: null, lastDoneDate: null,
      createdAt: sub.repeat==='interval' ? (sub.startDate || today()) : today(),
      label: sub.label || null,
      note: null, emoji: null,
      isFrozen: false, frozenAt: null,
      subtasks: Array.isArray(sub.subtasks) ? sub.subtasks : [],
      fromParentId: tk.id,
      fromParentName: tk.name,
      fromSubtaskMeta: {
        diff: sub.diff||0, coins: sub.coins||0, repeat: sub.repeat||'daily',
        days: sub.repeat==='custom-days' ? (sub.days||[]) : null,
        interval: sub.repeat==='interval' ? (sub.interval||4) : null,
        startDate: sub.startDate || null,
        label: sub.label || null,
      },
    };
    S.tasks.push(newTask);
  });
  tk.subtasks = subs.filter(function (s) { return s.done || s.skipped; });
  ensureFullTaskOrder();
  toast(t('subtask_extracted_toast'));
}

function taskDoneOnDate(taskId, dateStr) {
  if (dateStr === today()) {
    var _tsk = S.tasks.find(function (x) { return x.id === taskId; });
    return !!(_tsk && _tsk.done);
  }
  return !!(S.taskDoneLog && S.taskDoneLog[taskId] && S.taskDoneLog[taskId].indexOf(dateStr) !== -1);
}

function toggleSubtask(taskId, subId, dateStr, silent) {
  dateStr = dateStr || today();
  const tk = S.tasks.find(function(x){ return x.id === taskId; });
  if (!tk) return;
  const sub = ensureSubtasks(tk).find(function(s){ return s.id === subId; });
  if (!sub) return;

  const isToday = dateStr === today();
  const logKey = taskId + '_' + subId;
  if (!S.subtaskDoneLog) S.subtaskDoneLog = {};
  if (!S.subtaskDoneLog[logKey]) S.subtaskDoneLog[logKey] = [];
  const logIdx = S.subtaskDoneLog[logKey].indexOf(dateStr);
  const willBeDone = logIdx === -1; // hozir shu sanada belgilanmagan — demak endi belgilanadi

  const amt = taskCoinValue(sub);
  // Asosiy vazifalar kabi (taskXPValue), sub-taskning o'z qiyinlik
  // darajasiga (diff) qarab XP hisoblanadi — avval bu umuman berilmasdi.
  const xpAmt = taskXPValue(sub);

  if (willBeDone) {
    S.subtaskDoneLog[logKey].push(dateStr);
    if (isToday) {
      sub.done = true;
      sub.doneDate = dateStr;
      // "Har N kunda" turi uchun — keyingi muddatni oldinga suramiz
      // (asosiy tasklardagi nextDate mantig'i bilan bir xil).
      if (sub.repeat === 'interval') { sub.nextDate = addDays(dateStr, Number(sub.interval)||1); }
    }
    if (!S.subRewardGiven) S.subRewardGiven = {};
    S.subRewardGiven[logKey + '|' + dateStr] = { c: amt, x: xpAmt };
    if (amt) {
      S.coins = (S.coins||0) + amt;
      S.totalCoins = (S.totalCoins||0) + amt;
      setTimeout(function(){ SFX.coin(); }, 80);
    }
    var _subRefunded = refundSubtaskPenalty(sub, dateStr);
    if (_subRefunded > 0) addTarixLog('in', t('penalty_returned_log'), _subRefunded, null, dateStr);
    if (!S.totalTasksDone) S.totalTasksDone = 0;
    S.totalTasksDone++;
    addXP(xpAmt, sub.name);
    SFX.taskCheck();
    confetti();
    if (!silent) toast(t('task_done_xp_toast').replace('{coins}', amt).replace('{xp}', xpAmt));
  } else {
    S.subtaskDoneLog[logKey].splice(logIdx, 1);
    if (isToday) {
      sub.done = false;
      sub.doneDate = null;
      if (sub.repeat === 'interval') { sub.nextDate = dateStr; }
    }
    // Done paytida aynan nima berilgan bo'lsa, shuni qaytarib olamiz
    // (oradagi tahrir tufayli tanga/XP ortib ketmasligi uchun).
    var _given = S.subRewardGiven && S.subRewardGiven[logKey + '|' + dateStr];
    var undoAmt = _given ? _given.c : amt, undoXp = _given ? _given.x : xpAmt;
    if (_given) delete S.subRewardGiven[logKey + '|' + dateStr];
    if (undoAmt) {
      S.coins = (S.coins||0) - undoAmt;
      S.totalCoins = (S.totalCoins||0) - undoAmt;
    }
    if (S.totalTasksDone > 0) S.totalTasksDone--;
    addXP(-undoXp, sub.name + ' (bekor qilindi)');
    if (!silent) SFX.click();
  }

  if (!_suppressAutoParentComplete) {
    ensureSubtaskAutoSettingsDefaults();
    if (S.subtaskAutoCompleteParent) {
      var _allSubs = ensureSubtasks(tk);
      var _allResolved = _allSubs.length > 0 && _allSubs.every(function (s) {
        return subtaskDoneOnDate(tk.id, s.id, dateStr) || s.skipped;
      });
      var _parentDoneOnDate = taskDoneOnDate(tk.id, dateStr);
      if (_allResolved && !_parentDoneOnDate) {
        // Barcha sub-tasklar shu sanada tugallangan, ota-vazifa esa hali
        // shu sanada Done emas — avtomatik Done qilamiz.
        if (isToday) toggleTask(tk.id); else calToggleTaskDone(tk.id, dateStr);
      } else if (!_allResolved && _parentDoneOnDate) {
        // Sub-task qaytadan "bajarilmagan"ga o'tdi, lekin ota-vazifa shu
        // sanada hali ham Done bo'lib turibdi — uni ham qaytaramiz.
        if (isToday) toggleTask(tk.id); else calToggleTaskDone(tk.id, dateStr);
      }
    }
  }

  if (!silent) {
    save(); render();
    refreshCalDetailIfOpen();
  }
}

function skipSubtask(taskId, subId) {
  const tk = S.tasks.find(function(x){ return x.id === taskId; });
  if (!tk) return;
  const sub = ensureSubtasks(tk).find(function(s){ return s.id === subId; });
  if (!sub || sub.done || sub.skipped) return;
  sub.skipped = true; sub.skippedDate = today();
  if (sub.repeat === 'interval') { sub.nextDate = addDays(today(), Number(sub.interval)||1); }
  save(); render();
  refreshCalDetailIfOpen();
  toast(t('subtask_skipped_toast'));
}

function unskipSubtask(taskId, subId) {
  const tk = S.tasks.find(function(x){ return x.id === taskId; });
  if (!tk) return;
  const sub = ensureSubtasks(tk).find(function(s){ return s.id === subId; });
  if (!sub || !sub.skipped) return;
  sub.skipped = false; sub.skippedDate = null;
  if (sub.repeat === 'interval') { sub.nextDate = today(); }
  save(); render();
  refreshCalDetailIfOpen();
  toast(t('subtask_unskipped_toast'));
}

function deleteSubtask(taskId, subId) {
  const tk = S.tasks.find(function(x){ return x.id === taskId; });
  if (!tk) return;
  const sub = ensureSubtasks(tk).find(function(s){ return s.id === subId; });
  if (!sub) return;
  var _title = t('subtask_delete_confirm_title');
  var _warning = t('subtask_delete_confirm_warning');
  var _cancelBtn = t('btn_cancel');
  var _confirmBtn = t('delete_task_confirm_btn');
  var _toastMsg = t('subtask_deleted_toast');
  var ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.72);z-index:400;display:flex;align-items:center;justify-content:center;padding:20px';
  var box = document.createElement('div');
  box.style.cssText = 'background:#1C1C25;border:1px solid rgba(248,113,113,0.3);border-radius:var(--radius-lg);padding:24px;width:100%;max-width:320px;text-align:center';
  box.innerHTML =
    '<div style="font-size:var(--fs-4xl);margin-bottom:10px">🗑️</div>' +
    '<div style="font-family:Syne,sans-serif;font-size:var(--fs-base);font-weight:700;color:var(--text);margin-bottom:8px">'+_title+'</div>' +
    '<div style="font-size:var(--fs-sm);color:var(--text-muted);margin-bottom:20px;line-height:1.5">«' + esc(sub.name) + '»<br><span style="color:#F87171;font-size:var(--fs-xs)">'+_warning+'</span></div>' +
    '<div style="display:flex;gap:10px">' +
      '<button id="stdel-no"  style="flex:1;padding:12px;border-radius:var(--radius-md);border:1px solid var(--border);background:transparent;color:var(--text-muted);font-size:var(--fs-base);cursor:pointer">'+_cancelBtn+'</button>' +
      '<button id="stdel-yes" style="flex:2;padding:12px;border-radius:var(--radius-md);border:none;background:#F87171;color:#fff;font-size:var(--fs-base);font-weight:600;cursor:pointer">'+_confirmBtn+'</button>' +
    '</div>';
  ov.appendChild(box);
  document.body.appendChild(ov);
  document.getElementById('stdel-no').onclick = function(){ SFX.click(); ov.remove(); };
  document.getElementById('stdel-yes').onclick = function(){
    SFX.delete();
    ov.remove();
    moveSubtaskToTrash(taskId, subId);
    toast(_toastMsg);
  };
  ov.addEventListener('mousedown', function(e){ if(e.target===ov) ov.remove(); });
  ov.addEventListener('touchend', function(e){ if(e.target===ov) ov.remove(); });
}

function moveSubtaskToTrash(taskId, subId) {
  const tk = S.tasks.find(function(x){ return x.id === taskId; });
  if (!tk) return;
  const subs = ensureSubtasks(tk);
  const idx = subs.findIndex(function(s){ return s.id === subId; });
  if (idx === -1) return;
  const sub = subs[idx];
  if (!Array.isArray(S.deletedSubtasks)) S.deletedSubtasks = [];
  S.deletedSubtasks.unshift({
    subtask: JSON.parse(JSON.stringify(sub)),
    parentId: taskId,
    parentName: tk.name,
    deletedAt: today()
  });
  subs.splice(idx, 1);
  save(); render();
  refreshCalDetailIfOpen();
  renderTrashList();
}

function restoreSubtask(index) {
  if (!Array.isArray(S.deletedSubtasks)) return;
  var entry = S.deletedSubtasks[index];
  if (!entry) return;
  var parent = S.tasks.find(function(x){ return x.id === entry.parentId; });
  if (!parent) { toast(t('trash_perm_delete_warning')); return; }
  ensureSubtasks(parent).push(entry.subtask);
  S.deletedSubtasks.splice(index, 1);
  save(); render();
  renderTrashList();
  toast(t('subtask_restored_toast'));
}

function permanentlyDeleteSubtask(index) {
  if (!Array.isArray(S.deletedSubtasks)) return;
  S.deletedSubtasks.splice(index, 1);
  save();
  renderTrashList();
  toast(t('trash_perm_deleted_toast'));
}

// Bitta asosiy taskni boshqa asosiy taskning sub-taski qilib qo'shish
// (sudrab-tashlab, ustida 5 soniya ushlab turgach tasdiqlanganda chaqiriladi).
function addTaskAsSubtask(childId, parentId) {
  if (childId === parentId) return;
  const parent = S.tasks.find(function(x){ return x.id === parentId; });
  const childIdx = S.tasks.findIndex(function(x){ return x.id === childId; });
  if (!parent || childIdx === -1) return;
  const child = S.tasks[childIdx];
  const parentSubs = ensureSubtasks(parent);
  parentSubs.push({
    id: child.id,
    name: child.name,
    done: !!child.done,
    doneDate: child.doneDate || null,
    skipped: !!child.skipped,
    skippedDate: child.skippedDate || null,
    diff: taskDiffOrDefault(child),
    coins: child.coins,
    repeat: child.repeat || 'daily',
    days: child.days || null,
    interval: child.interval || null,
    startDate: child.nextDate || null,
    nextDate: child.nextDate || null,
    label: child.label || null,
    subtasks: [] // nested sub-tasklar quyida alohida "flatten" qilinadi
  });
  if (Array.isArray(child.subtasks) && child.subtasks.length) {
    child.subtasks.forEach(function(cs){ parentSubs.push(cs); });
  }
  S.tasks.splice(childIdx, 1);
  if (Array.isArray(S.taskOrder)) S.taskOrder = S.taskOrder.filter(function(id){ return id !== childId; });
  save(); render();
  toast(t('subtask_converted_toast'));
}

// ================= /SUB-TASKLAR =================

var _subtaskDragState = { timer: null, targetId: null, draggedId: null, popupEl: null, targetEl: null, keyHandler: null };

function clearSubtaskDragState() {
  if (_subtaskDragState.timer) { clearTimeout(_subtaskDragState.timer); _subtaskDragState.timer = null; }
  if (_subtaskDragState.targetEl) { _subtaskDragState.targetEl.classList.remove('subtask-hover-target'); }
  _subtaskDragState.targetId = null;
  _subtaskDragState.targetEl = null;
  removeSubtaskConfirmPopup();
}

function removeSubtaskConfirmPopup() {
  if (_subtaskDragState.keyHandler) { document.removeEventListener('keydown', _subtaskDragState.keyHandler, true); _subtaskDragState.keyHandler = null; }
  if (_subtaskDragState.popupEl) { _subtaskDragState.popupEl.remove(); _subtaskDragState.popupEl = null; }
}

function showSubtaskConfirmPopup(x, y, draggedId, targetId) {
  removeSubtaskConfirmPopup();
  var div = document.createElement('div');
  div.className = 'subtask-drop-confirm';
  var vw = window.innerWidth, vh = window.innerHeight;
  var left = Math.min(Math.max(x, 10), vw - 230);
  var top = Math.min(Math.max(y, 10), vh - 90);
  div.style.left = left + 'px';
  div.style.top = top + 'px';
  div.innerHTML = '<div class="sdc-text">' + esc(t('subtask_convert_confirm_text')) + '</div>' +
    '<div class="sdc-btns"><button type="button" class="sdc-yes">' + esc(t('btn_yes_simple')) + '</button><button type="button" class="sdc-no">' + esc(t('btn_no_simple')) + '</button></div>';
  document.body.appendChild(div);
  _subtaskDragState.popupEl = div;
  div.querySelector('.sdc-yes').addEventListener('click', function(e) {
    e.stopPropagation();
    addTaskAsSubtask(draggedId, targetId);
    clearSubtaskDragState();
  });
  div.querySelector('.sdc-no').addEventListener('click', function(e) {
    e.stopPropagation();
    clearSubtaskDragState();
    render(); // sudrash paytida vizual o'zgargan tartibni asl holiga qaytaramiz
  });

  function keyHandler(e) {
    if (e.key === 'Enter') {
      e.preventDefault(); e.stopPropagation();
      addTaskAsSubtask(draggedId, targetId);
      clearSubtaskDragState();
    } else if (e.key === 'Escape') {
      e.preventDefault(); e.stopPropagation();
      clearSubtaskDragState();
      render();
    }
  }
  _subtaskDragState.keyHandler = keyHandler;
  document.addEventListener('keydown', keyHandler, true);
}

// SortableJS onMove callback — sudralayotgan karta boshqa task-card ustida
// bo'lganini kuzatib, 5 soniyalik taymer ishga tushiradi.
function handleSubtaskHoverMove(evt) {
  try {
    if (_subtaskDragState.popupEl) return true;
    var draggedEl = evt.dragged;
    var relatedEl = evt.related;
    if (!draggedEl || !relatedEl || !relatedEl.classList || !relatedEl.classList.contains('task-card')) {
      clearSubtaskDragState();
      return true;
    }
    var draggedId = parseInt(draggedEl.dataset.id, 10);
    var targetId = parseInt(relatedEl.dataset.id, 10);
    if (isNaN(draggedId) || isNaN(targetId) || draggedId === targetId) {
      clearSubtaskDragState();
      return true;
    }
    if (_subtaskDragState.targetId !== targetId) {
      clearSubtaskDragState();
      _subtaskDragState.targetId = targetId;
      _subtaskDragState.draggedId = draggedId;
      _subtaskDragState.targetEl = relatedEl;
      relatedEl.classList.add('subtask-hover-target');
      var oe = evt.originalEvent || {};
      var px = (oe.clientX || (relatedEl.getBoundingClientRect().left + 20)) + 14;
      var py = (oe.clientY || (relatedEl.getBoundingClientRect().top + 20)) + 14;
      _subtaskDragState.timer = setTimeout(function() {
        showSubtaskConfirmPopup(px, py, draggedId, targetId);
      }, 5000);
    }
    return true; // odatdagi qayta tartiblashga (reorder) ruxsat beramiz
  } catch (err) { return true; }
}
