// Vazifa qancha kundan keyin chiqishini hisoblaydi

// ---- Sub-tasklar: "Hammasi" (All) rejimida kelajakdagi sub-tasklarni ko'rsatish ----
function daysUntilSubtask(sub) {
  var td = today();
  if (sub.repeat === 'interval' && sub.nextDate && sub.nextDate > td) {
    return Math.round((new Date(sub.nextDate + 'T00:00:00') - new Date(td + 'T00:00:00')) / 86400000);
  }
  for (var i = 1; i <= 7; i++) {
    var ds = addDays(td, i);
    if (subtaskDueToday(sub, ds)) return i;
  }
  return 1;
}
// Ota-task kelajak ro'yxatida emas, lekin uning ayrim sub-tasklari bugun navbatda emas
function collectFutureSubtasks(td) {
  var out = [];
  (S.tasks || []).forEach(function (tk) {
    if (tk.isFrozen) return;
    if (tk.repeat === 'once' && tk.done) return;
    if (taskIsFuture(tk, td)) return; // ota-task kartasining o'zida hammasi ko'rinadi
    ensureSubtasks(tk).forEach(function (sub) {
      if (sub.done) return;
      if (subtaskDueToday(sub, td)) return;
      out.push({ task: tk, sub: sub, days: daysUntilSubtask(sub) });
    });
  });
  return out;
}
function makeFutureSubEl(tk, sub, days) {
  var d = document.createElement('div');
  d.className = 'task-card future-readonly';
  d.dataset.id = 'sub-' + tk.id + '-' + sub.id;
  var rl = {cls: 'badge-daily', text: ''};
  try { rl = repeatLabel(sub); } catch (e) {}
  var coin = 0; try { coin = taskCoinValue(sub); } catch (e) {}
  d.innerHTML =
    '<div class="task-card-top">' +
      (sub.label ? '<span class="task-label-dot" style="background:' + sub.label + '"></span>' : '') +
      '<div class="task-info">' +
        '<div class="task-name"><span class="task-parent-badge">' + esc(tk.name) + ' ›</span> ' + esc(sub.name) + '</div>' +
        '<div class="task-sub">' + daysBadge(days) + '</div>' +
      '</div>' +
      '<div class="task-badges">' +
        (rl.text ? '<span class="badge ' + rl.cls + '">' + esc(rl.text) + '</span>' : '') +
        (coin ? '<span class="badge badge-coins">+' + coin + '🪙</span>' : '') +
      '</div>' +
      '<button class="task-quick-btn qb-edit" onclick="openSubtaskModal(' + tk.id + ',' + sub.id + ')" title="' + esc(tr('edit_dd_item')) + '">✏️</button>' +
    '</div>';
  return d;
}
// Kelajak ota-task kartasida sub-tasklar (bajarilmaganlari) faqat o'qish uchun ko'rinadi
function renderFutureSubtasksHtml(t) {
  var subs = ensureSubtasks(t).filter(function (s) { return !s.done; });
  if (!subs.length) return '';
  var html = '<div class="subtask-list">';
  subs.forEach(function (s) {
    var due = subtaskDueToday(s);
    var info = due ? '' : daysBadge(daysUntilSubtask(s));
    html += '<div class="subtask-item" style="opacity:.75"><span class="subtask-name">' + esc(s.name) + '</span> ' + info + '</div>';
  });
  return html + '</div>';
}

function daysUntilTask(t) {
  var td = today();
  if (t.repeat === 'interval' && t.nextDate && t.nextDate > td) {
    return Math.round((new Date(t.nextDate) - new Date(td)) / 86400000);
  }
  if (t.repeat === 'once' && t.postponedTo && t.postponedTo > td) {
    return Math.round((new Date(t.postponedTo) - new Date(td)) / 86400000);
  }
  // custom-days va weekdays: keyingi mos kunni topamiz (max 7 kun oldinga)
  if (t.repeat === 'custom-days' || t.repeat === 'weekdays') {
    var allowedDays;
    if (t.repeat === 'weekdays') {
      allowedDays = [1, 2, 3, 4, 5];
    } else {
      allowedDays = t.days || [];
    }
    for (var i = 1; i <= 7; i++) {
      var checkDate = new Date(new Date(td + 'T00:00:00').getTime() + i * 86400000);
      if (allowedDays.indexOf(checkDate.getDay()) !== -1) {
        return i;
      }
    }
  }
  return 0;
}

function taskIsFuture(t, td) {
  if (t.isFrozen) return false;
  if (t.repeat === 'interval' && t.nextDate && t.nextDate > td) return true;
  if (t.repeat === 'once' && t.postponedTo && t.postponedTo > td) return true;
  if (t.repeat === 'custom-days') {
    var days = t.days || [];
    if (!days.length) return false;
    var todayDow = new Date(td + 'T00:00:00').getDay();
    return days.indexOf(todayDow) === -1; // bugun emas, demak kelajakda
  }
  if (t.repeat === 'weekdays') {
    var dow = new Date(td + 'T00:00:00').getDay();
    return dow === 0 || dow === 6; // shanba yoki yakshanba
  }
  return false;
}

function daysBadge(days) {
  if (days <= 0) return '';
  if (days === 1) return '<span class="future-days-badge">' + t('daysbadge_tomorrow') + '</span>';
  return '<span class="future-days-badge">' + t('daysbadge_in_days').replace('{n}', days) + '</span>';
}

function renderTaskList() {
  var q = (document.getElementById('task-search')||{value:''}).value.toLowerCase().trim();
  var td = today();

  // Bugungi vazifalar
  var todayTasks = S.tasks.filter(function(t) {
    if (t.postponedTo && t.postponedTo > td) return false;
    return taskDueToday(t);
  });
  var onceTasks = S.tasks.filter(function(t){
    return !t.isFrozen && t.repeat==='once' && (!t.postponedTo || t.postponedTo<=td) && !t.done;
  });

  // Kelajakdagi vazifalar (faqat showAllTasks=true da)
  var futureTasks = [];
  if (showAllTasks) {
    futureTasks = S.tasks.filter(function(t) {
      return taskIsFuture(t, td);
    });
    // Sanasi yaqinroqdan tartibda
    futureTasks.sort(function(a, b) {
      return daysUntilTask(a) - daysUntilTask(b);
    });
  }

  function applySearch(arr) {
    if (!q) return arr;
    // Har bir so'z alohida (tartibi muhim emas) qidiriladi — masalan "ishi uy"
    // yozilsa ham "Uy ishi" nomli vazifa topiladi (avval faqat aniq ibora ishlagan).
    var words = q.split(/\s+/).filter(Boolean);
    return arr.filter(function(t){
      var hay = t.name.toLowerCase() + ' ' + (t.note ? t.note.toLowerCase() : '');
      return words.every(function(w){ return hay.includes(w); });
    });
  }

  var recurringTasks  = todayTasks.filter(function(t){ return t.repeat!=='once'; });
  var filteredRecurring = applySearch(recurringTasks);
  var filteredOnce    = applySearch(onceTasks);
  var filteredFuture  = applySearch(futureTasks);

  function sortByOrder(arr) {
    var base = arr;
    if (S.taskOrder && S.taskOrder.length) {
      base = [...arr].sort(function(a,b){
        var ai=S.taskOrder.indexOf(a.id), bi=S.taskOrder.indexOf(b.id);
        if(ai===-1&&bi===-1) return 0; if(ai===-1) return 1; if(bi===-1) return -1; return ai-bi;
      });
    }
    // 📌 Muhim (pinned) deb belgilangan vazifalar — o'zaro nisbiy tartibini
    // saqlagan holda (stable sort) — har doim ro'yxat boshiga chiqariladi.
    return base.slice().sort(function(a, b){
      var pa = a.pinned ? 1 : 0, pb = b.pinned ? 1 : 0;
      return pb - pa;
    });
  }

  var dList=document.getElementById('daily-list'); dList.innerHTML='';
  var oList=document.getElementById('once-list');  oList.innerHTML='';
  var fList=document.getElementById('future-list'); fList.innerHTML='';

  if (q) {
    sortByOrder(filteredRecurring).forEach(function(t){ dList.appendChild(makeTaskEl(t)); });
    sortByOrder(filteredOnce).forEach(function(t){ oList.appendChild(makeTaskEl(t)); });
  } else {
    var active  = sortByOrder(filteredRecurring.filter(function(t){return !t.done&&!t.skipped;}));
    var skipped = sortByOrder(filteredRecurring.filter(function(t){return t.skipped&&!t.done;}));
    active.forEach(function(t){dList.appendChild(makeTaskEl(t));});
    if(skipped.length){
      var s=document.createElement('div');
      s.style.cssText='font-size:var(--fs-2xs);color:var(--text-dim);letter-spacing:0.06em;text-transform:uppercase;padding:8px 2px 4px;';
      s.textContent=t('section_skipped');
      dList.appendChild(s);
      skipped.forEach(function(t){dList.appendChild(makeTaskEl(t));});
    }
    sortByOrder(filteredOnce).forEach(function(t){ oList.appendChild(makeTaskEl(t)); });
  }

  // Kelajakdagi sub-tasklar (ota-task bugun navbatda, lekin sub-taskning o'z jadvali bo'yicha emas)
  var futureSubs = [];
  if (showAllTasks) {
    futureSubs = collectFutureSubtasks(td);
    if (q) {
      var _w = q.split(/\s+/).filter(Boolean);
      futureSubs = futureSubs.filter(function (fs) {
        var hay = (fs.sub.name + ' ' + fs.task.name).toLowerCase();
        return _w.every(function (w) { return hay.includes(w); });
      });
    }
  }
  // Kelajakdagi vazifalar ro'yxati (vazifalar + sub-tasklar, sanasi yaqinidan)
  var _futEntries = filteredFuture.map(function (t) { return { days: daysUntilTask(t), task: t }; })
    .concat(futureSubs.map(function (fs) { return { days: fs.days, fs: fs }; }));
  _futEntries.sort(function (a, b) { return a.days - b.days; });
  if (showAllTasks && _futEntries.length) {
    _futEntries.forEach(function (en) {
      if (en.fs) { fList.appendChild(makeFutureSubEl(en.fs.task, en.fs.sub, en.days)); return; }
      var t = en.task;
      var el = makeTaskEl(t, true);
      // "nechi kundan keyin" badge qo'shamiz task-sub qismiga
      var days = daysUntilTask(t);
      var subEl = el.querySelector('.task-sub');
      if (subEl) {
        subEl.innerHTML = subEl.innerHTML + daysBadge(days);
      } else {
        var taskInfo = el.querySelector('.task-info');
        if (taskInfo) {
          var newSub = document.createElement('div');
          newSub.className = 'task-sub';
          newSub.innerHTML = daysBadge(days);
          taskInfo.appendChild(newSub);
        }
      }
      fList.appendChild(el);
    });
  }

  document.getElementById('daily-section').style.display = filteredRecurring.length ? '' : 'none';
  document.getElementById('once-section').style.display  = filteredOnce.length ? '' : 'none';
  document.getElementById('future-section').style.display = (showAllTasks && (filteredFuture.length + futureSubs.length)) ? '' : 'none';

  var emptyMsg = document.getElementById('empty-msg');
  if (emptyMsg) emptyMsg.style.display = (filteredRecurring.length===0 && filteredOnce.length===0) ? '' : 'none';

  updateBulkBar();
}

