// === SOAT 00:00 DA AVTOMATIK RESET ===
// Sahifa ochiq turib kun o'tib ketsa ham reset ishlaydi
(function setupMidnightReset() {
  function msToMidnight() {
    var now = new Date();
    var midnight = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 5); // 00:00:05
    return midnight - now;
  }
  function scheduleMidnight() {
    var delay = msToMidnight();
    setTimeout(function() {
      ensureFreezeGrants();
      checkReset(); // jazo va reset
      if (typeof pomoRolloverStaleActivities === 'function') {
        pomoRolloverStaleActivities(); // 🍅 to'xtatilgan amaliyliklarning kunlik hisoblagichini ham shu yerda tozalaymiz
        if (typeof pomoRenderActivityList === 'function') pomoRenderActivityList();
      }
      render();
      if(S.pendingMissedMsg){ toast(S.pendingMissedMsg); S.pendingMissedMsg=null; save(); }
      if(S.pendingSubtaskPenaltyMsg){ setTimeout(function(){ toast(S.pendingSubtaskPenaltyMsg); S.pendingSubtaskPenaltyMsg=null; save(); }, 500); }
      if(S.pendingStreakMsg){ setTimeout(function(){ toast(S.pendingStreakMsg); confetti(); SFX.firework(); S.pendingStreakMsg=null; save(); }, 800); }
      if(S.pendingFreezeGrantMsg){ setTimeout(function(){ toast(S.pendingFreezeGrantMsg); S.pendingFreezeGrantMsg=null; save(); renderProfile(); }, 1300); }
      scheduleMidnight(); // keyingi kunga rejalashtir
    }, delay);
  }
  scheduleMidnight();
})();
function startEditTitle(){
  var s=document.getElementById('user-title'),p=s.nextElementSibling,inp=document.getElementById('title-input');
  inp.value=s.textContent;s.style.display='none';p.style.display='none';
  inp.style.display='inline-block';inp.focus();inp.select();
}
function saveTitle(){
  var s=document.getElementById('user-title'),p=s.nextElementSibling,inp=document.getElementById('title-input');
  var v=inp.value.trim();
  // Mehmon o'zining avtomatik nomini (user5) o'zgartirmasdan saqlasa — xato emas
  if (v && !(S.profile && S.profile.name) && S.profile && S.profile.autoUsername === v) v = '';
  if(v){
    var currentName = S.profile && S.profile.name;
    if (v.length < 3) { toast(t('pe_username_short')); }
    else if (v.length > USERNAME_MAX_LEN) { toast(t('pe_username_too_long')); }
    else if (!USERNAME_ALLOWED_REGEX.test(v)) { toast(t('pe_username_invalid_chars')); }
    else if (isGuestStyleUsername(v)) { toast(t('pe_username_guest_style')); }
    else if (isUsernameBlocked(v)) { toast(t('pe_username_blocked')); }
    else if (isUsernameTaken(v, currentName)) { toast(t('pe_username_taken')); }
    else {
      if(!S.profile)S.profile={};
      applyUsernameChange(v);
      S.kiName=v;
    }
  }
  save();
  updateHeaderUserTitle();
  inp.style.display='none';s.style.display='';p.style.display='';
}

// ---- Kuchli iroda ----
function kiDs(d){return d.toISOString().slice(0,10);}
function kiLabel(str){var d=new Date(str);return d.getDate()+'-'+getMonthsArr()[d.getMonth()];}
function kiMissed(){
  var start=S.kiStart;
  if(!start){start=kiDs(new Date());S.kiStart=start;save();}
  var ans=S.kiAns||{};
  var skipped=S.kiSkipped||{};
  var missed=[];
  var cur=new Date(start);
  var yest=new Date();yest.setDate(yest.getDate()-1);
  while(cur<=yest){var s=kiDs(cur);if(!ans[s]&&!skipped[s])missed.push(s);cur.setDate(cur.getDate()+1);}
  return missed;
}
window._kiQ=[];
window._kiOv=null;
function checkKI(){
  if(!S.personalCheckEnabled)return; // Personal Check o'chiq bo'lsa, umuman so'ralmaydi
  var q=kiMissed(); // faqat kecha va o'tgan javob berilmagan kunlar
  if(!q.length)return;
  window._kiQ=q;
  showKI(window._kiQ.shift());
}
function showKI(dateStr){
  if(window._kiOv)window._kiOv.remove();
  var label=kiLabel(dateStr)+t('ki_day_suffix');
  var ov=document.createElement('div');
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:300;display:flex;align-items:center;justify-content:center;padding:20px';
  var box=document.createElement('div');
  box.style.cssText='position:relative;background:#1C1C25;border:1px solid rgba(255,255,255,0.1);border-radius:var(--radius-xl);padding:28px 24px;width:100%;max-width:320px;text-align:center';
  var bClose=document.createElement('button');
  bClose.setAttribute('aria-label','close');
  bClose.style.cssText='position:absolute;top:10px;right:10px;width:28px;height:28px;border:none;border-radius:var(--radius-sm);background:transparent;color:var(--text-muted);font-size:var(--fs-lg);line-height:1;cursor:pointer;display:flex;align-items:center;justify-content:center';
  bClose.textContent='✕';
  bClose.onclick=function(){kiCloseAll(dateStr);};
  var em=document.createElement('div');em.style.cssText='font-size:var(--fs-4xl);margin-bottom:12px';em.textContent='🔐';
  var h3=document.createElement('h3');h3.style.cssText='font-family:Syne,sans-serif;font-size:var(--fs-md);font-weight:700;color:var(--text);margin-bottom:8px';h3.textContent=t('ki_title');
  var p=document.createElement('p');p.style.cssText='font-size:var(--fs-sm);color:var(--text-muted);margin-bottom:24px;line-height:1.6';p.textContent=label+t('ki_question_suffix');
  var row=document.createElement('div');row.style.cssText='display:flex;gap:10px';
  var bNo=document.createElement('button');
  bNo.style.cssText='flex:1;padding:12px;border-radius:var(--radius-md);border:1px solid rgba(248,113,113,0.4);background:rgba(248,113,113,0.08);color:#F87171;font-size:var(--fs-base);cursor:pointer;font-family:DM Sans,sans-serif';
  bNo.textContent=t('ki_btn_failed');bNo.onclick=function(){kiAns(false,dateStr);};
  var bYes=document.createElement('button');
  bYes.style.cssText='flex:2;padding:12px;border-radius:var(--radius-md);border:none;background:var(--accent);color:#fff;font-size:var(--fs-base);font-weight:600;cursor:pointer;font-family:DM Sans,sans-serif';
  bYes.textContent=t('ki_btn_succeeded');bYes.onclick=function(){kiAns(true,dateStr);};
  row.appendChild(bNo);row.appendChild(bYes);
  box.appendChild(bClose);box.appendChild(em);box.appendChild(h3);box.appendChild(p);box.appendChild(row);
  ov.appendChild(box);document.body.appendChild(ov);window._kiOv=ov;
}
function kiCloseAll(dateStr){
  var skipped=S.kiSkipped||{};
  skipped[dateStr]=1;
  if(window._kiQ&&window._kiQ.length){
    window._kiQ.forEach(function(d){skipped[d]=1;});
    window._kiQ=[];
  }
  S.kiSkipped=skipped;
  save();
  if(window._kiOv){window._kiOv.remove();window._kiOv=null;}
}
function kiAns(ok,dateStr){
  if(window._kiOv){window._kiOv.remove();window._kiOv=null;}
  var ans=S.kiAns||{};
  ans[dateStr]=ok?1:-1;
  S.kiAns=ans;
  try{
    var sd=getSecretData();if(!sd.log)sd.log={};
    sd.log[dateStr]=ok?'clean':'fail';
    var streak=calcSecretStreak(sd.log);
    if(!sd.history)sd.history=[];
    sd.history.unshift({date:dateStr,status:ok?'clean':'fail',coins:ok?3:-5,streak:ok?streak:0});
    if(sd.history.length>60)sd.history=sd.history.slice(0,60);
    saveSecretData(sd);if(_secretUnlocked)renderSecretContent();
  }catch(e){}
  if(ok){S.coins=(S.coins||0)+3;addTarixLog('in',t('secret_success_log'),3);save();render();toast(t('secret_success_toast'));confetti();SFX.coin();}
  else{S.coins=(S.coins||0)-5;addTarixLog('out',t('secret_fail_log'),-5);save();render();toast(t('secret_fail_toast'));}
  setTimeout(function(){if(window._kiQ&&window._kiQ.length>0)showKI(window._kiQ.shift());},900);
}
setInterval(checkKI,5*60*1000);
setTimeout(function(){
  try{var n=S.kiName;if(n)document.getElementById('user-title').textContent=n;}catch(e){}
  checkKI();
},2000);

// -- logUsage: vaqtli yoki donali mukofot ishlatish --
function logUsage(id) {
  var r=S.rewards.find(function(x){return x.id===id;}); if(!r) return;
  if (isRewardBlockedByDebt(r.id)) {
    toast(getDebtTier() === 2 ? t('debt_tier2_toast') : t('reward_blocked_toast'));
    return;
  }
  var ov=document.getElementById('usage-modal'); if(ov) ov.remove();

  var isTimeReward = r.rtype === 'time';
  var unitMins = r.amount || 0; // bitta xariddagi daqiqa miqdori (masalan 10)
  var claims=(S.rewardClaims||{})[r.id]||0;

  // === DONALI mukofot (daqiqa yo'q) ===
  if(!isTimeReward){
    // nechta ishlatilganini hisoblash
    var usedCount=(S.usageLog&&S.usageLog[id]) ? S.usageLog[id].reduce(function(a,x){return a+(x.count||1);},0) : 0;
    var remaining=claims-usedCount;

    var overlay=document.createElement('div');
    overlay.id='usage-modal';
    overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:200;display:flex;align-items:center;justify-content:center;padding:20px';
    var box=document.createElement('div');
    box.style.cssText='background:#1C1C25;border:1px solid rgba(255,255,255,0.15);border-radius:var(--radius-xl);padding:24px;width:100%;max-width:340px;text-align:center';

    var statusColor = remaining>0 ? '#34D399' : '#F87171';
    var infoHtml='<div style="background:var(--surface2);border-radius:var(--radius-sm);padding:12px 14px;margin-bottom:16px;font-size:var(--fs-sm);line-height:1.9;text-align:left">'+
      t('reward_bought_label')+' <b style="color:var(--gold)">'+claims+' '+t('reward_unit_count')+'</b><br>'+
      t('reward_used_label')+' <b style="color:#60A5FA">'+usedCount+' '+t('reward_unit_count')+'</b><br>'+
      t('reward_remaining_label')+' <b style="color:'+statusColor+'">'+Math.max(0,remaining)+' '+t('reward_unit_count')+'</b>'+
    '</div>';

    var warningHtml = remaining<=0
      ? '<div style="background:rgba(248,113,113,0.1);border:1px solid rgba(248,113,113,0.3);border-radius:var(--radius-sm);padding:10px 12px;margin-bottom:14px;font-size:var(--fs-xs);color:#F87171">'+t('usage_expired_warning').replace('{pen}', Math.ceil(r.cost*1))+'</div>'
      : '';

    box.innerHTML=
      '<p style="font-size:var(--fs-md);font-weight:600;color:var(--text);margin-bottom:16px">'+esc(r.icon)+' '+esc(r.name)+'</p>'+
      infoHtml+warningHtml+
      '<div style="display:flex;gap:10px">'+
        '<button id="usage-cancel" style="flex:1;padding:11px;border-radius:var(--radius-md);border:1px solid var(--border);background:transparent;color:var(--text-muted);font-size:var(--fs-base);cursor:pointer">'+t('btn_cancel')+'</button>'+
        '<button id="usage-confirm" style="flex:2;padding:11px;border-radius:var(--radius-md);border:none;background:'+(remaining>0?'var(--accent)':'#F87171')+';color:#fff;font-size:var(--fs-base);font-weight:500;cursor:pointer">'+(remaining>0?t('reward_use_btn'):t('usage_anyway_btn'))+'</button>'+
      '</div>';

    overlay.appendChild(box);
    document.body.appendChild(overlay);

    document.getElementById('usage-cancel').onclick=function(){overlay.remove();};
    document.getElementById('usage-confirm').onclick=function(){
      if(!S.usageLog)S.usageLog={};
      if(!S.usageLog[id])S.usageLog[id]=[];
      S.usageLog[id].push({count:1,date:today()});
      if(remaining<=0){
        var pen=Math.ceil(r.cost*1);
        spendCoins(pen);
        addTarixLog('out',r.icon+' '+r.name+' '+t('usage_overused_log_suffix'),-pen);
        toast(t('usage_over_penalty_toast').replace('{pen}', pen));
        recordUsage(r, 1, pen);
        // Jarima tolandi — qarz yopildi, hisob tozalanadi (keyingi xaridga otmaydi)
        S.rewardClaims[id]=0; S.usageLog[id]=[];
      } else {
        toast(t('usage_used_toast').replace('{icon}', r.icon).replace('{name}', r.name));
        recordUsage(r, 1, 0);
        if(remaining-1<=0){ S.rewardClaims[id]=0; S.usageLog[id]=[]; }
      }
      overlay.remove();
      save(); render();
    };
    overlay.addEventListener('mousedown',function(e){if(e.target===overlay)overlay.remove();});
    return;
  }

  var totalBoughtMins=claims>0 ? claims : null;
  var usedLog=(S.usageLog||{})[id]||[];
  var alreadyUsedMins=usedLog.reduce(function(a,x){return a+(x.mins||0);},0);
  var remainingMins=totalBoughtMins!=null ? Math.max(0,totalBoughtMins-alreadyUsedMins) : null;

  var overlay=document.createElement('div');
  overlay.id='usage-modal';
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:200;display:flex;align-items:center;justify-content:center;padding:20px';
  var box=document.createElement('div');
  box.style.cssText='background:#1C1C25;border:1px solid rgba(255,255,255,0.15);border-radius:var(--radius-xl);padding:24px;width:100%;max-width:340px';

  var presets=[5,10,15,20,30,45,60,90];
  var pHTML='<div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-bottom:12px">';
  presets.forEach(function(m){ pHTML+='<button data-m="'+m+'" style="padding:7px 12px;border-radius:var(--radius-full);border:1px solid var(--border);background:var(--surface2);color:var(--text-muted);font-size:var(--fs-sm);cursor:pointer">'+(m>=60?(m/60)+' '+t('time_hour_unit'):m+' '+t('time_min_unit'))+'</button>'; });
  pHTML+='</div>';

  var infoHtml='';
  if(totalBoughtMins!=null){
    var remMinsModal = totalBoughtMins - alreadyUsedMins;
    infoHtml='<div style="background:var(--surface2);border-radius:var(--radius-sm);padding:10px 12px;margin-bottom:12px;font-size:var(--fs-xs);color:var(--text-muted);line-height:1.7">'+
      t('reward_remaining_label')+' <b style="color:'+(remMinsModal>0?'#34D399':'#F87171')+'">'+formatMinutes(Math.max(0,remMinsModal))+'</b><br>'+
      '('+t('reward_bought_label')+' <b style="color:var(--gold)">'+formatMinutes(totalBoughtMins)+'</b>, '+t('reward_used_label').toLowerCase()+' <b style="color:#60A5FA">'+formatMinutes(alreadyUsedMins)+'</b>)'+
    '</div>';
  } else {
    var freeRateNote = (Number(r.cost)||0) === 0 ? (' ' + t('free_reward_penalty_rate_note').replace('{mins}', DEFAULT_MINUTES_PER_COIN)) : '';
    infoHtml='<div style="background:rgba(248,113,113,0.08);border:1px solid rgba(248,113,113,0.25);border-radius:var(--radius-sm);padding:10px 12px;margin-bottom:12px;font-size:var(--fs-xs);color:#F87171;line-height:1.7">'+
      t('usage_not_purchased_title')+'<br>'+
      '<span style="color:var(--text-muted)">'+t('usage_not_purchased_note')+freeRateNote+'</span>'+
    '</div>';
  }

  box.innerHTML=
    '<p style="font-size:var(--fs-base);font-weight:600;color:var(--text);text-align:center;margin-bottom:4px">'+esc(r.icon)+' '+esc(r.name)+'</p>'+
    '<p style="font-size:var(--fs-sm);color:var(--text-muted);text-align:center;margin-bottom:14px">'+t('usage_minutes_question')+'</p>'+
    infoHtml+pHTML+
    '<div style="display:flex;gap:8px;margin-bottom:12px">'+
      '<input id="usage-inp" type="number" min="1" max="600" placeholder="'+t('time_min_unit')+'..." style="flex:1;padding:10px 12px;background:var(--surface2);border:1px solid var(--border);border-radius:var(--radius-sm);color:var(--text);font-size:var(--fs-base);outline:none"/>'+
      '<span style="display:flex;align-items:center;font-size:var(--fs-sm);color:var(--text-muted)">'+t('time_min_unit')+'</span>'+
    '</div>'+
    '<div id="usage-prev" style="text-align:center;font-size:var(--fs-sm);min-height:36px;margin-bottom:14px;line-height:1.7"></div>'+
    '<div style="display:flex;gap:10px">'+
      '<button id="usage-cancel" style="flex:1;padding:11px;border-radius:var(--radius-md);border:1px solid var(--border);background:transparent;color:var(--text-muted);font-size:var(--fs-base);cursor:pointer">'+t('btn_cancel')+'</button>'+
      '<button id="usage-confirm" style="flex:2;padding:11px;border-radius:var(--radius-md);border:none;background:var(--accent);color:#fff;font-size:var(--fs-base);font-weight:500;cursor:pointer">'+t('btn_confirm')+'</button>'+
    '</div>';

  overlay.appendChild(box);
  document.body.appendChild(overlay);

  var inp=document.getElementById('usage-inp');
  var prev=document.getElementById('usage-prev');

  function calcPenalty(m){
    var minutesPer = (unitMins>0 && r.cost>0) ? (unitMins / r.cost) : DEFAULT_MINUTES_PER_COIN;
    if(totalBoughtMins!=null){
      var over=(alreadyUsedMins+m)-totalBoughtMins;
      if(over<=0) return 0;
      return Math.ceil((over/minutesPer)*1);
    } else {
      return Math.ceil((m/minutesPer)*1);
    }
  }

  function upd(){
    var m=parseInt(inp.value); if(!m||isNaN(m)||m<1){prev.innerHTML='';return;}
    var pen=calcPenalty(m);
    if(pen>0){
      if(totalBoughtMins!=null){
        var over=(alreadyUsedMins+m)-totalBoughtMins;
        prev.innerHTML='<span style="color:#34D399">'+t('usage_paid_closed')+'</span> &nbsp;|&nbsp; <span style="color:#F87171">&#9888; '+t('usage_over_penalty_preview').replace('{mins}', formatMinutes(over)).replace('{pen}', pen)+'</span>';
      } else {
        prev.innerHTML='<span style="color:#F87171">&#9888; '+t('usage_not_purchased_penalty').replace('{pen}', pen)+'</span>';
      }
    } else {
      prev.innerHTML='<span style="color:#34D399">'+t('usage_within_range')+'</span>';
    }
  }

  inp.addEventListener('input',upd);
  box.querySelectorAll('[data-m]').forEach(function(btn){
    btn.addEventListener('click',function(){
      inp.value=btn.getAttribute('data-m'); upd();
      box.querySelectorAll('[data-m]').forEach(function(b){
        var sel=b===btn;
        b.style.background=sel?'var(--accent)':'var(--surface2)';
        b.style.color=sel?'#fff':'var(--text-muted)';
        b.style.borderColor=sel?'transparent':'var(--border)';
      });
    });
  });

  document.getElementById('usage-cancel').onclick=function(){overlay.remove();};
  document.getElementById('usage-confirm').onclick=function(){
    var m=parseInt(inp.value);
    if(!m||isNaN(m)||m<1){inp.style.borderColor='#F87171';inp.focus();return;}
    var pen=calcPenalty(m);
    if(!S.usageLog)S.usageLog={};
    if(!S.usageLog[id])S.usageLog[id]=[];
    S.usageLog[id].push({mins:m,date:today()});
    if(pen>0){
      spendCoins(pen);
      addTarixLog('out',r.icon+' '+r.name+' ('+formatMinutes(m)+') '+t('usage_over_minutes_log_suffix'),-pen);
      toast(t('usage_over_minutes_toast').replace('{m}', formatMinutes(m)).replace('{pen}', pen));
      recordUsage(r, m, pen);
      // Jarima tolandi — qarz yopildi, hisob tozalanadi (keyingi xaridga otmaydi)
      S.rewardClaims[id]=0; S.usageLog[id]=[];
    } else {
      toast(t('usage_within_limit_toast').replace('{m}', formatMinutes(m)));
      recordUsage(r, m, 0);
      if(totalBoughtMins!=null && (alreadyUsedMins+m)>=totalBoughtMins){
        S.rewardClaims[id]=0; S.usageLog[id]=[];
      }
    }
    overlay.remove();
    save(); render();
  };
  overlay.addEventListener('mousedown',function(e){if(e.target===overlay)overlay.remove();});
}

