// 🚫 "user1", "user25" kabi nomlar mehmon (guest) sifatida kirganlarga
// avtomatik beriladi (qarang: getAutoUsername) — qo'lda tanlab bo'lmaydi.
function isGuestStyleUsername(name) {
  return /^user\d+$/i.test(String(name || '').trim());
}

function isUsernameBlocked(newUsername) {
  if (!newUsername) return false;
  var normalized = newUsername.trim().toLowerCase();
  if (isGuestStyleUsername(normalized)) return true;
  if (USERNAME_RESERVED.indexOf(normalized) !== -1) return true;
  return USERNAME_PROFANITY.some(function(bad){ return normalized.indexOf(bad) !== -1; });
}


function isUsernameTaken(newUsername, currentName) {
  if (!newUsername) return false;
  var normalized = newUsername.trim().toLowerCase();
  if (currentName && normalized === String(currentName).trim().toLowerCase()) return false;
  var reg = ensureUsernameRegistry();
  if (reg.reservedNicks && reg.reservedNicks[normalized]) return true;
  return false;
}

function ensureUsernameRegistry() {
  if (!S.usernameRegistry) S.usernameRegistry = {};
  var reg = S.usernameRegistry;
  if (typeof reg.nextNum !== 'number' || reg.nextNum < 1) reg.nextNum = 1;
  if (!Array.isArray(reg.freedNums)) reg.freedNums = [];
  if (!reg.reservedNicks || typeof reg.reservedNicks !== 'object') reg.reservedNicks = {};
  return reg;
}

function allocateUsernameNumber() {
  var reg = ensureUsernameRegistry();
  if (reg.freedNums.length > 0) {
    reg.freedNums.sort(function(a, b){ return a - b; });
    return reg.freedNums.shift();
  }
  var n = reg.nextNum;
  reg.nextNum = n + 1;
  return n;
}

// Berilgan raqamni registrga "ozod" sifatida qaytaradi — keyingi
// foydalanuvchiga shu raqam qayta berilishi mumkin bo'ladi.
function freeUsernameNumber(num) {
  if (num == null) return;
  var reg = ensureUsernameRegistry();
  if (reg.freedNums.indexOf(num) === -1) reg.freedNums.push(num);
}

function getAutoUsername() {
  if (!S.profile) S.profile = {};
  if (S.profile.autoUsername) return S.profile.autoUsername;
  var num = allocateUsernameNumber();
  var uname = 'user' + num;
  S.profile.autoUsername = uname;
  S.profile.autoUsernameNum = num;
  return uname;
}

// Ekranda ko'rsatiladigan ism: agar custom nik saqlangan bo'lsa o'shani,
// aks holda avtomatik userN nomini qaytaradi (statik "Profile" o'rniga).
function getDisplayUsername() {
  var custom = S.profile && S.profile.name;
  if (custom) return custom;
  return getAutoUsername();
}

function applyUsernameChange(newName) {
  if (!S.profile) S.profile = {};
  var reg = ensureUsernameRegistry();
  var oldCustom = S.profile.name;
  var oldAutoNum = S.profile.autoUsernameNum;

  // Eski custom nikni ozod qilamiz (agar bo'lsa va yangisi undan farq qilsa)
  if (oldCustom) {
    var oldNorm = String(oldCustom).trim().toLowerCase();
    if (!newName || oldNorm !== String(newName).trim().toLowerCase()) {
      delete reg.reservedNicks[oldNorm];
    }
  }
  if (oldAutoNum != null) {
    freeUsernameNumber(oldAutoNum);
    S.profile.autoUsernameNum = null;
    S.profile.autoUsername = null;
  }

  if (newName) {
    S.profile.name = newName;
    reg.reservedNicks[String(newName).trim().toLowerCase()] = true;
  } else {
    S.profile.name = null;
    getAutoUsername();
  }
}

// Nom input maydoni ustida real-vaqt validatsiya ko'rsatgichini yangilaydi.
// Qaytadi: true — agar forma saqlash uchun yaroqli bo'lsa, aks holda false.
function pe_validateUsernameLive(currentName) {
  var inp = document.getElementById('pe-name');
  var fb = document.getElementById('pe-name-feedback');
  var saveBtn = document.getElementById('pe-save');
  if (!inp || !fb) return true;
  var val = inp.value.trim();
  var valid = true;
  if (!val) {
    fb.textContent = '';
    valid = true; // Bo'sh ism ruxsat etiladi (avtomatik ism ishlatiladi)
  } else if (val.length < 3) {
    fb.textContent = t('pe_username_short');
    fb.style.color = '#FBBF24';
    valid = false;
  } else if (val.length > USERNAME_MAX_LEN) {
    fb.textContent = t('pe_username_too_long');
    fb.style.color = '#FBBF24';
    valid = false;
  } else if (!USERNAME_ALLOWED_REGEX.test(val)) {
    // 🎮 Minecraft nikidagi kabi: faqat harf/raqam/pastki chiziq — bo'sh joy,
    // emoji va boshqa maxsus belgilar (stiker va h.k.) taqiqlanadi.
    fb.textContent = t('pe_username_invalid_chars');
    fb.style.color = '#F87171';
    valid = false;
  } else if (isGuestStyleUsername(val)) {
    fb.textContent = t('pe_username_guest_style');
    fb.style.color = '#F87171';
    valid = false;
  } else if (isUsernameBlocked(val)) {
    fb.textContent = t('pe_username_blocked');
    fb.style.color = '#F87171';
    valid = false;
  } else if (isUsernameTaken(val, currentName)) {
    fb.textContent = t('pe_username_taken');
    fb.style.color = '#F87171';
    valid = false;
  } else {
    fb.textContent = t('pe_username_available');
    fb.style.color = '#4ADE80';
    valid = true;
  }
  if (saveBtn) {
    saveBtn.disabled = !valid;
    saveBtn.style.opacity = valid ? '1' : '0.5';
    saveBtn.style.cursor = valid ? 'pointer' : 'not-allowed';
  }
  return valid;
}

function openPhotoCropModal(srcDataUrl, onDone) {
  var img = new Image();
  img.onload = function () {
    var FRAME = Math.min(280, window.innerWidth - 64); // ekran chetiga tegmasin
    var OUT = 512;

    var overlay = document.createElement('div');
    overlay.id = 'photo-crop-modal';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:260;display:flex;align-items:center;justify-content:center;padding:20px';

    var box = document.createElement('div');
    box.style.cssText = 'background:#1C1C25;border:1px solid rgba(255,255,255,0.15);border-radius:var(--radius-xl);padding:18px;width:100%;max-width:360px;text-align:center';

    box.innerHTML =
      '<h3 style="font-family:Syne,sans-serif;font-size:var(--fs-base);font-weight:700;color:var(--text);margin-bottom:10px">Rasmni moslashtiring</h3>' +
      '<div style="font-size:var(--fs-2xs);color:var(--text-muted);margin-bottom:14px">Surish uchun ushlab torting, kattalashtirish uchun g\'ildirak / ikki barmoq</div>' +
      '<div id="pcm-frame-wrap" style="position:relative;width:' + FRAME + 'px;height:' + FRAME + 'px;margin:0 auto 16px;border-radius:50%;overflow:hidden;background:#000;box-shadow:0 0 0 3px var(--accent),0 0 24px rgba(124,92,252,0.35);touch-action:none;cursor:grab">' +
        '<canvas id="pcm-canvas" width="' + FRAME + '" height="' + FRAME + '" style="display:block;width:' + FRAME + 'px;height:' + FRAME + 'px"></canvas>' +
      '</div>' +
      '<div style="display:flex;align-items:center;gap:8px;margin-bottom:16px">' +
        '<span style="font-size:var(--fs-sm);color:var(--text-dim)">🔍</span>' +
        '<input id="pcm-zoom-range" type="range" min="100" max="300" value="100" style="flex:1;accent-color:var(--accent)" />' +
      '</div>' +
      '<div style="display:flex;gap:10px">' +
        '<button id="pcm-cancel" style="flex:1;padding:9px;border-radius:var(--radius-md);border:1px solid var(--border);background:transparent;color:var(--text-muted);font-size:var(--fs-sm);cursor:pointer">Bekor qilish</button>' +
        '<button id="pcm-save" style="flex:2;padding:9px;border-radius:var(--radius-md);border:none;background:var(--accent);color:#fff;font-size:var(--fs-sm);font-weight:600;cursor:pointer">Saqlash</button>' +
      '</div>';

    overlay.appendChild(box);
    document.body.appendChild(overlay);

    var canvas = document.getElementById('pcm-canvas');
    var ctx = canvas.getContext('2d');
    var frameWrap = document.getElementById('pcm-frame-wrap');
    var zoomRange = document.getElementById('pcm-zoom-range');

    var baseScale = Math.max(FRAME / img.width, FRAME / img.height); // "cover" — frame har doim to'lib turadi
    var zoom = 1;     // 1..3, zoomRange bilan bog'liq (100..300)
    var panX = 0, panY = 0; // rasm markazining frame markazidan siljishi (px)

    function effScale() { return baseScale * zoom; }

    function clampPan() {
      var s = effScale();
      var maxX = Math.max(0, (img.width * s - FRAME) / 2);
      var maxY = Math.max(0, (img.height * s - FRAME) / 2);
      panX = Math.min(maxX, Math.max(-maxX, panX));
      panY = Math.min(maxY, Math.max(-maxY, panY));
    }

    function draw() {
      ctx.clearRect(0, 0, FRAME, FRAME);
      ctx.save();
      ctx.translate(FRAME / 2 + panX, FRAME / 2 + panY);
      ctx.scale(effScale(), effScale());
      ctx.drawImage(img, -img.width / 2, -img.height / 2);
      ctx.restore();
    }

    clampPan();
    draw();

    // -- Drag (sichqoncha/touch) va pinch-zoom, Pointer Events orqali --
    var pointers = {};
    var dragLast = null;
    var pinchStartDist = null;
    var pinchStartZoom = 1;

    function pinchDist() {
      var ids = Object.keys(pointers);
      var a = pointers[ids[0]], b = pointers[ids[1]];
      return Math.hypot(a.x - b.x, a.y - b.y);
    }

    frameWrap.addEventListener('pointerdown', function (e) {
      frameWrap.setPointerCapture(e.pointerId);
      pointers[e.pointerId] = { x: e.clientX, y: e.clientY };
      var ids = Object.keys(pointers);
      if (ids.length === 1) { dragLast = { x: e.clientX, y: e.clientY }; frameWrap.style.cursor = 'grabbing'; }
      else if (ids.length === 2) { pinchStartDist = pinchDist(); pinchStartZoom = zoom; dragLast = null; }
    });
    frameWrap.addEventListener('pointermove', function (e) {
      if (!pointers[e.pointerId]) return;
      pointers[e.pointerId] = { x: e.clientX, y: e.clientY };
      var ids = Object.keys(pointers);
      if (ids.length === 1 && dragLast) {
        panX += e.clientX - dragLast.x;
        panY += e.clientY - dragLast.y;
        dragLast = { x: e.clientX, y: e.clientY };
        clampPan(); draw();
      } else if (ids.length === 2 && pinchStartDist) {
        var d = pinchDist();
        zoom = Math.min(3, Math.max(1, pinchStartZoom * (d / pinchStartDist)));
        zoomRange.value = Math.round(zoom * 100);
        clampPan(); draw();
      }
    });
    function releasePointer(e) {
      delete pointers[e.pointerId];
      var ids = Object.keys(pointers);
      if (ids.length < 2) pinchStartDist = null;
      dragLast = ids.length === 1 ? pointers[ids[0]] : null;
      if (ids.length === 0) frameWrap.style.cursor = 'grab';
    }
    frameWrap.addEventListener('pointerup', releasePointer);
    frameWrap.addEventListener('pointercancel', releasePointer);
    frameWrap.addEventListener('pointerleave', function (e) { if (pointers[e.pointerId]) releasePointer(e); });

    // -- Desktopda sichqoncha g'ildiragi bilan zoom --
    frameWrap.addEventListener('wheel', function (e) {
      e.preventDefault();
      zoom = Math.min(3, Math.max(1, zoom * (e.deltaY < 0 ? 1.08 : 0.92)));
      zoomRange.value = Math.round(zoom * 100);
      clampPan(); draw();
    }, { passive: false });

    // -- Slider orqali zoom --
    zoomRange.addEventListener('input', function () {
      zoom = zoomRange.value / 100;
      clampPan(); draw();
    });

    document.getElementById('pcm-cancel').onclick = function () { overlay.remove(); };

    document.getElementById('pcm-save').onclick = function () {
      var outCanvas = document.createElement('canvas');
      outCanvas.width = OUT; outCanvas.height = OUT;
      var octx = outCanvas.getContext('2d');
      var ratio = OUT / FRAME;
      octx.save();
      octx.translate(OUT / 2 + panX * ratio, OUT / 2 + panY * ratio);
      octx.scale(effScale() * ratio, effScale() * ratio);
      octx.drawImage(img, -img.width / 2, -img.height / 2);
      octx.restore();
      var result = outCanvas.toDataURL('image/jpeg', 0.8);
      overlay.remove();
      onDone(result);
    };
  };
  img.onerror = function () { toast('⚠️ Rasmni ochib bo\'lmadi'); };
  img.src = srcDataUrl;
}

function _buildProfileGoalBox(examType) {
  var data = _examTrendBuildSeries(examType);
  var points = data.points;
  if (points.length === 0) return '';

  var current = points[points.length - 1].value;
  var label = examType === 'ielts' ? 'IELTS' : 'SAT';
  var goal = _examTrendGoal(examType);
  var adv = computeAdvancedExamForecast(examType);

  var etaHtml = '';
  if (goal === null) {
    etaHtml = '<div style="font-size:var(--fs-2xs);color:var(--text-dim);margin-top:4px">' + esc(t('exam_forecast_no_goal')) + '</div>';
  } else if (adv && adv.goalReached) {
    etaHtml = '<div style="font-size:var(--fs-2xs);color:#34D399;margin-top:4px;font-weight:600">🎉 Maqsadga yetdingiz!</div>';
  } else if (adv && adv.etaToGoal) {
    var weeks = Math.ceil(adv.etaToGoal.days / 7);
    var etaLabel = weeks <= 1 ? '~1 hafta' : (weeks <= 8 ? ('~' + weeks + ' hafta') : ('~' + Math.round(weeks / 4.33) + ' oy'));
    etaHtml = '<div style="font-size:var(--fs-2xs);color:var(--gold);margin-top:4px">🔮 Shu tempda maqsadga <b>' + etaLabel + '</b>da yetasiz</div>';
  } else if (adv && adv.etaTooFar) {
    etaHtml = '<div style="font-size:var(--fs-2xs);color:var(--text-dim);margin-top:4px">' + esc(t('exam_forecast_eta_too_far')) + '</div>';
  } else {
    etaHtml = '<div style="font-size:var(--fs-2xs);color:var(--text-dim);margin-top:4px">' + esc(t('exam_forecast_low_data')) + '</div>';
  }

  return '<div style="background:linear-gradient(135deg,rgba(124,92,252,0.14),rgba(180,142,255,0.05));border:1px solid rgba(124,92,252,0.3);border-radius:var(--radius-md);padding:10px 16px;text-align:center;min-width:150px;flex:1">' +
      '<div style="font-size:var(--fs-3xs);color:#B48EFF;letter-spacing:0.05em;text-transform:uppercase">' + label + ' · O\'rtacha</div>' +
      '<div style="font-family:Syne,sans-serif;font-size:var(--fs-3xl);font-weight:700;color:#B48EFF;line-height:1.15;margin-top:2px">' + current + (goal !== null ? '<span style="font-size:var(--fs-xs);color:var(--text-dim);font-weight:500"> / ' + goal + '</span>' : '') + '</div>' +
      etaHtml +
    '</div>';
}
function _buildCefrProfileGoalBox() {
  var overall = (typeof cefrComputeOverall === 'function') ? cefrComputeOverall() : null;
  if (!overall || !overall.level) return '';

  var saved = getExamDate('cefr');
  var goal = (saved && saved.target) ? saved.target : null;

  var etaHtml = '';
  if (!goal) {
    etaHtml = '<div style="font-size:var(--fs-2xs);color:var(--text-dim);margin-top:4px">' + esc(t('exam_forecast_no_goal')) + '</div>';
  } else if (overall.rank !== null && cefrLevelToRank(goal) !== null && overall.rank >= cefrLevelToRank(goal)) {
    etaHtml = '<div style="font-size:var(--fs-2xs);color:#34D399;margin-top:4px;font-weight:600">🎉 Maqsadga yetdingiz!</div>';
  } else if (saved && saved.date) {
    var examDate = new Date(saved.date + 'T00:00:00');
    var nowDate = new Date(); nowDate.setHours(0,0,0,0);
    var diffDays = Math.round((examDate - nowDate) / 86400000);
    etaHtml = diffDays >= 0
      ? '<div style="font-size:var(--fs-2xs);color:var(--gold);margin-top:4px">🔮 Imtihongacha <b>' + diffDays + ' kun</b></div>'
      : '';
  }

  return '<div style="background:linear-gradient(135deg,rgba(124,92,252,0.14),rgba(180,142,255,0.05));border:1px solid rgba(124,92,252,0.3);border-radius:var(--radius-md);padding:10px 16px;text-align:center;min-width:150px;flex:1">' +
      '<div style="font-size:var(--fs-3xs);color:#B48EFF;letter-spacing:0.05em;text-transform:uppercase">CEFR · Overall</div>' +
      '<div style="font-family:Syne,sans-serif;font-size:var(--fs-3xl);font-weight:700;color:#B48EFF;line-height:1.15;margin-top:2px">' + overall.level + (goal ? '<span style="font-size:var(--fs-xs);color:var(--text-dim);font-weight:500"> / ' + goal + '</span>' : '') + '</div>' +
      etaHtml +
    '</div>';
}
function renderProfileGoalWidget() {
  var box = document.getElementById('profile-header-goal-widget');
  if (!box) return;

  var subjects = [];
  if (hasExamSubject('ielts')) subjects.push('ielts');
  if (hasExamSubject('sat')) subjects.push('sat');

  var boxesHtml = subjects.map(_buildProfileGoalBox).filter(Boolean).join('');
  if (hasExamSubject('cefr')) boxesHtml += _buildCefrProfileGoalBox();

  if (!boxesHtml) {
    box.style.display = 'none';
    box.innerHTML = '';
    return;
  }

  box.style.cssText = 'display:flex;flex-wrap:wrap;gap:10px;justify-content:center';
  box.innerHTML = boxesHtml;
}

