var SPIN_PRIZES = getSpinPrizes();

function pickWeightedSpinIndex() {
  var totalW = 0;
  for (var i = 0; i < SPIN_PRIZES.length; i++) totalW += (SPIN_PRIZES[i].weight || 1);
  var r = Math.random() * totalW;
  for (var j = 0; j < SPIN_PRIZES.length; j++) {
    r -= (SPIN_PRIZES[j].weight || 1);
    if (r <= 0) return j;
  }
  return SPIN_PRIZES.length - 1;
}

var spinRunning=false;
var spinState='idle'; // 'idle' | 'spinning' | 'result' — track qayta qurilishini boshqaradi
var SPIN_ITEM_W = 84; // karta kengligi (76px) + gap (8px) — drawSpinReel bilan bir xil bo'lishi shart

function hasSpunToday() {
  if (!S.spinDone) S.spinDone = {};
  return S.spinDone[today()] === 1;
}
function markSpunToday() {
  if (!S.spinDone) S.spinDone = {};
  S.spinDone[today()] = 1;
  // Eski spin kunlarini tozalash (30 kundan eski)
  try {
    var cutoff = new Date(); cutoff.setDate(cutoff.getDate() - 30);
    var cutStr = cutoff.getFullYear()+'-'+String(cutoff.getMonth()+1).padStart(2,'0')+'-'+String(cutoff.getDate()).padStart(2,'0');
    Object.keys(S.spinDone).forEach(function(k){
      if (k < cutStr) delete S.spinDone[k];
    });
  } catch(e) {}
  save();
}
function getNextSpinCountdown() {
  var now = new Date();
  var tomorrow = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0);
  var diff = tomorrow - now;
  var h = Math.floor(diff / 3600000);
  var m = Math.floor((diff % 3600000) / 60000);
  return h + ' soat ' + m + ' daqiqa';
}

// Bitta sovg'a kartasi HTML'i (case-opening kartasi) — doSpin va idle preview
// ikkalasida ham ishlatiladi, kenglik SPIN_ITEM_W bilan mos bo'lishi kerak.
function spinItemCardHtml(p) {
  return '<div class="spin-item-card" style="flex-shrink:0;width:76px;height:76px;border-radius:var(--radius-md);background:'+p.color+';display:flex;align-items:center;justify-content:center;text-align:center;font-size:var(--fs-xs);font-weight:700;color:#fff;font-family:Syne,sans-serif;box-shadow:inset 0 0 0 1px rgba(255,255,255,0.18);padding:4px;box-sizing:border-box;transition:transform 0.2s,box-shadow 0.2s">'+p.label+'</div>';
}

// Spin bosilmaganda (idle holatda) reelda tasodifiy kartalarni ko'rsatib
// turadi — faqat vitrina, ko'rsatkichga moslashtirilmaydi.
function buildIdleSpinReel(track) {
  var n = SPIN_PRIZES.length, count = 12, items = [];
  for (var i = 0; i < count; i++) items.push(SPIN_PRIZES[Math.floor(Math.random() * n)]);
  track.innerHTML = items.map(spinItemCardHtml).join('');
  track.style.transition = 'none';
  track.style.transform = 'translateX(0px)';
}

function renderSpin() {
  var track = document.getElementById('spin-track'); if(!track) return;
  if (spinState === 'idle') buildIdleSpinReel(track);

  // Header spin button state
  var hBtn = document.getElementById('header-spin-btn');
  var hLbl = document.getElementById('header-spin-label');
  if (hBtn && hLbl) {
    if (!hasSpunToday()) {
      hLbl.textContent = t('spin_label_active');
      hBtn.style.borderColor = 'rgba(52,211,153,0.6)';
      hBtn.style.background  = 'rgba(52,211,153,0.1)';
      hBtn.style.color       = '#34D399';
    } else {
      hLbl.textContent = t('spin_label');
      hBtn.style.borderColor = 'var(--border)';
      hBtn.style.background  = 'var(--theme-toggle-bg)';
      hBtn.style.color       = 'var(--text-muted)';
    }
  }
  var done  = hasSpunToday();
  var badge = document.getElementById('spin-free-badge');
  var costInfo = document.getElementById('spin-cost-info');
  var btn   = document.getElementById('spin-btn');

  if(!done) {
    if(badge){ badge.textContent=t('spin_free_badge'); badge.style.background='rgba(52,211,153,0.15)'; badge.style.color='#34D399'; badge.style.borderColor='rgba(52,211,153,0.3)'; }
    if(costInfo) costInfo.textContent='';
    if(btn){ btn.textContent=t('spin_free_btn'); btn.style.opacity='1'; btn.style.cursor='pointer'; }
  } else {
    if(badge){ badge.textContent=t('spin_used_badge'); badge.style.background='rgba(248,113,113,0.1)'; badge.style.color='#F87171'; badge.style.borderColor='rgba(248,113,113,0.3)'; }
    if(costInfo){
      costInfo.innerHTML = t('spin_next_countdown')+'<b style="color:var(--accent)">'+getNextSpinCountdown()+'</b>'+t('spin_next_countdown_suffix');
    }
    if(btn){
      btn.textContent = t('spin_tomorrow_btn');
      btn.style.opacity = '0.45';
      btn.style.cursor  = 'not-allowed';
    }
  }
}

// Standoff2/CS-uslubidagi "case opening" reel: kartalar gorizontal qatorda
// tizilib, chapga siljib boradi va markaziy ko'rsatkich ostida to'xtaydi.
function doSpin() {
  if(spinRunning) return;
  if(hasSpunToday()){ toast(t('spin_already_used_toast')); return; }

  markSpunToday();
  spinRunning = true;
  spinState = 'spinning';

  var track    = document.getElementById('spin-track');
  var viewport = document.getElementById('spin-viewport');
  var n   = SPIN_PRIZES.length;
  var idx = pickWeightedSpinIndex();
  var itemW = SPIN_ITEM_W;

  // Uzun reel quramiz: oxiridan biroz oldinroqqa yutuqni joylashtiramiz,
  // shunda animatsiya tugagach reelning oxiri ko'rinmaydi (bufer qoladi).
  var reelLen   = 56;
  var landIndex = reelLen - 10;
  var items = [];
  for (var i = 0; i < reelLen; i++) {
    items.push(i === landIndex ? SPIN_PRIZES[idx] : SPIN_PRIZES[Math.floor(Math.random() * n)]);
  }
  track.innerHTML = items.map(spinItemCardHtml).join('');
  track.style.transition = 'none';
  track.style.transform  = 'translateX(0px)';

  var viewportWidth = viewport.clientWidth;
  // Kartaning aniq markazi emas, ichida tasodifiy nuqtaga tushishi —
  // tabiiyroq ko'rinish uchun (real case-opening'lardagi kabi).
  var randomOffset = (Math.random() - 0.5) * itemW * 0.55;
  var targetX = -(landIndex * itemW + itemW / 2 - viewportWidth / 2) + randomOffset;

  var duration = 4200;
  var start = null;
  var lastTickIdx = null;
  function ease(t){ return 1 - Math.pow(1 - t, 4); }
  function frame(ts){
    if(!start) start = ts;
    var p = Math.min((ts - start) / duration, 1);
    var x = targetX * ease(p);
    track.style.transform = 'translateX(' + x + 'px)';
    // Ko'rsatkich ostidan yangi karta o'tganda "tik" ovozi — ease-out
    // bo'lgani uchun boshida tez-tez, oxirida sekinlashib chaladi.
    var curIdx = Math.round(-x / itemW);
    if (curIdx !== lastTickIdx) { lastTickIdx = curIdx; SFX.spinTick(); }
    if(p < 1){ requestAnimationFrame(frame); }
    else {
      track.style.transform = 'translateX(' + targetX + 'px)';
      spinRunning = false;
      spinState = 'result';
      var prize = SPIN_PRIZES[idx];
      // Yutgan kartani ajratib ko'rsatish
      var cards = track.children;
      if (cards[landIndex]) {
        cards[landIndex].style.boxShadow = '0 0 0 3px #fff, 0 0 18px ' + prize.color;
        cards[landIndex].style.transform = 'scale(1.1)';
        cards[landIndex].style.zIndex = '5';
      }
      if(prize.type === 'coins' && prize.coins > 0){
        S.coins += prize.coins;
        if(!S.totalCoins) S.totalCoins = 0; S.totalCoins += prize.coins;
        addTarixLog('in', t('spin_log').replace('{label}', prize.label), prize.coins);
        save(); render();
        SFX.spinWin();
        setTimeout(function(){ toast('+' + prize.coins + t('spin_prize_toast') + prize.label + '!'); confetti(); renderSpin(); }, 300);
      } else if (prize.type === 'freeze') {
        // ❄️ +1 Freeze — tanga o'rniga muzlatish imkoniyati beriladi.
        if (typeof S.freezeCount !== 'number' || isNaN(S.freezeCount)) S.freezeCount = 0;
        S.freezeCount++;
        addTarixLog('in', t('spin_log').replace('{label}', prize.label), 0);
        save(); render();
        SFX.spinWin();
        setTimeout(function(){ toast(t('spin_prize_freeze_toast')); confetti(); renderSpin(); }, 300);
      } else if (prize.type === 'reward') {
        var _wonReward = (S.rewards && S.rewards.length) ? S.rewards[Math.floor(Math.random() * S.rewards.length)] : null;
        if (_wonReward) {
          if (!S.rewardClaims) S.rewardClaims = {};
          var _addCount = (_wonReward.amount > 0) ? _wonReward.amount : 1;
          S.rewardClaims[_wonReward.id] = (S.rewardClaims[_wonReward.id] || 0) + _addCount;
          addTarixLog('in', '🎰 ' + (_wonReward.icon||'') + ' ' + _wonReward.name + ' (Spin)', 0);
          save(); render();
          if (typeof renderRewards === 'function') renderRewards();
          SFX.spinWin();
          setTimeout(function(){ toast(t('spin_prize_reward_toast').replace('{name}', (_wonReward.icon||'')+' '+_wonReward.name)); confetti(); renderSpin(); }, 300);
        } else {
          // Foydalanuvchida hali birorta ham sovg'a qo'shilmagan bo'lsa —
          // tanga ham, hech narsa ham yo'qotilmaydi, faqat xabar beriladi.
          SFX.spinWin();
          setTimeout(function(){ toast(t('spin_prize_reward_fallback_toast')); renderSpin(); }, 300);
        }
      } else if (prize.type === 'respin') {
        // 🔄 Yana bir marta Spin qilish imkoni — bugungi "ishlatildi"
        // bayrog'i bekor qilinadi, tugma darhol qayta faollashadi.
        if (S.spinDone) delete S.spinDone[today()];
        save();
        SFX.spinWin();
        setTimeout(function(){ toast(t('spin_prize_respin_toast')); confetti(); renderSpin(); }, 300);
      } else if (prize.type === 'xp') {
        // ⭐ Darhol XP beradi (level darajasiga yaqinlashtiradi).
        var _xpAmt = 15;
        addXP(_xpAmt, 'Spin');
        save(); render();
        SFX.spinWin();
        setTimeout(function(){ toast(t('spin_prize_xp_toast').replace('{amt}', _xpAmt)); confetti(); renderSpin(); }, 300);
      } else if (prize.type === 'double') {
        S.spinDoubleNextTaskActive = true;
        save();
        SFX.spinWin();
        setTimeout(function(){ toast(t('spin_prize_double_toast')); confetti(); renderSpin(); }, 300);
      } else {
        SFX.delete();
        setTimeout(function(){ toast(t('spin_unlucky_toast')); renderSpin(); }, 300);
      }
    }
  }
  requestAnimationFrame(frame);
}

// doSpin is defined above in renderSpin section

function showSpinOddsModal() {
  var old = document.getElementById('spin-odds-modal'); if (old) old.remove();
  var totalW = 0;
  SPIN_PRIZES.forEach(function(p){ totalW += (p.weight || 1); });

  var merged = {};
  var order = [];
  SPIN_PRIZES.forEach(function(p){
    var key = p.coins + '|' + p.label;
    if (!merged[key]) { merged[key] = {coins:p.coins, label:p.label, color:p.color, weight:0}; order.push(key); }
    merged[key].weight += (p.weight || 1);
  });
  var rows = order.map(function(k){ return merged[k]; });
  rows.sort(function(a,b){ return b.coins - a.coins; });

  var overlay = document.createElement('div');
  overlay.id = 'spin-odds-modal';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:200;display:flex;align-items:center;justify-content:center;padding:20px';
  var box = document.createElement('div');
  box.style.cssText = 'position:relative;background:#1C1C25;border:1px solid rgba(255,255,255,0.15);border-radius:var(--radius-xl);padding:18px;width:100%;max-width:360px;max-height:80vh;display:flex;flex-direction:column';

  var rowsHtml = rows.map(function(r){
    var pct = (r.weight / totalW * 100);
    var pctStr = pct < 1 ? pct.toFixed(2) : (pct < 10 ? pct.toFixed(1) : Math.round(pct));
    var isEmptyRow = (r.coins === 0 && r.label === t('spin_no_luck'));
    var dotStyle = isEmptyRow ? 'background:transparent;border:2px solid var(--text-dim)' : 'background:' + r.color;
    return '<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 4px;border-bottom:1px solid var(--border)">' +
      '<div style="display:flex;align-items:center;gap:9px;min-width:0">' +
        '<span style="width:14px;height:14px;border-radius:50%;flex-shrink:0;' + dotStyle + '"></span>' +
        '<span style="color:var(--text);font-size:var(--fs-sm);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + esc(r.label) + '</span>' +
      '</div>' +
      '<span style="font-weight:700;color:var(--accent);font-size:var(--fs-sm);flex-shrink:0;margin-left:8px">' + pctStr + '%</span>' +
    '</div>';
  }).join('');

  box.innerHTML =
    '<button id="spin-odds-close" style="position:absolute;top:10px;right:10px;width:24px;height:24px;border-radius:50%;border:1px solid var(--border);background:var(--surface2);color:var(--text-muted);font-size:var(--fs-base);cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1;padding:0">✕</button>' +
    '<div style="font-family:Syne,sans-serif;font-size:var(--fs-md);font-weight:700;color:var(--text);margin-bottom:4px;padding-right:26px">' + t('spin_odds_title') + '</div>' +
    '<div style="font-size:var(--fs-xs);color:var(--text-dim);margin-bottom:12px">' + t('spin_odds_desc') + '</div>' +
    '<div style="overflow-y:auto;flex:1;margin:0 -4px;padding:0 4px">' + rowsHtml + '</div>';

  overlay.appendChild(box);
  document.body.appendChild(overlay);
  var closeIt = function(){ overlay.remove(); };
  document.getElementById('spin-odds-close').onclick = closeIt;
  overlay.addEventListener('click', function(e){ if (e.target === overlay) closeIt(); });
}


function ensureTarixTotals() {
  if(S.tarixTotalIn === undefined || S.tarixTotalOut === undefined) {
    var all = S.tarix || [];
    S.tarixTotalIn  = all.filter(function(i){return i.amount>0;}).reduce(function(s,i){return s+i.amount;},0);
    S.tarixTotalOut = all.filter(function(i){return i.amount<0;}).reduce(function(s,i){return s+Math.abs(i.amount);},0);
  }
}
function addTarixLog(type, desc, amount, uniqueKey, forceDate) {
  if(!S.tarix) S.tarix=[];
  ensureTarixTotals();
  var t = forceDate || today();
  // Agar uniqueKey berilsa -- bugun shu kalit bilan yozuv bor bo'lsa yangilasin, yangi qo'shmasin
  if(uniqueKey) {
    var idx = S.tarix.findIndex(function(r){ return r.uniqueKey===uniqueKey && r.date===t; });
    if(idx !== -1) {
      // Eski yozuvning ulushi umrbod jami balansdan olib tashlanadi, so'ng
      // yangi qiymat qo'shiladi — shu tarzda hisoblagich har doim to'g'ri qoladi.
      var old = S.tarix[idx];
      if(old.amount>0) S.tarixTotalIn -= old.amount;
      else if(old.amount<0) S.tarixTotalOut -= Math.abs(old.amount);
      S.tarix[idx] = {type:type, desc:desc, amount:amount, date:t, ts:Date.now(), uniqueKey:uniqueKey};
      if(amount>0) S.tarixTotalIn += amount;
      else if(amount<0) S.tarixTotalOut += Math.abs(amount);
      return;
    }
  }
  S.tarix.unshift({type:type, desc:desc, amount:amount, date:t, ts:Date.now(), uniqueKey:uniqueKey||null});
  if(amount>0) S.tarixTotalIn += amount;
  else if(amount<0) S.tarixTotalOut += Math.abs(amount);
  // Faqat KO'RINADIGAN ro'yxat 200 taga cheklanadi — umrbod jami
  // (S.tarixTotalIn/Out) bundan tegilmaydi.
  if(S.tarix.length>200) S.tarix.pop();
}

// "Tozalash" bosilganda darhol o'chirish o'rniga — tasdiqlash modali.
