function pcSetSessionPin(pin) {
  _pcSessionPin = pin;
}
function pcGetSessionPin() { return _pcSessionPin; }

function ensurePersonalCheckDefaults() {
  if (typeof S.personalCheckEnabled === 'undefined' || S.personalCheckEnabled === null) {
    S.personalCheckEnabled = pcHasPinSet();
  }
  if (typeof S.pcPinProtectionEnabled === 'undefined' || S.pcPinProtectionEnabled === null) {
    S.pcPinProtectionEnabled = pcHasPinSet();
  }
}

function updatePcToggleUI() {
  var sw = document.getElementById('pc-toggle-switch');
  var knob = document.getElementById('pc-toggle-knob');
  var pinRow = document.getElementById('pc-pin-protection-row');
  var pinSw = document.getElementById('pc-pin-toggle-switch');
  var pinKnob = document.getElementById('pc-pin-toggle-knob');
  var chBtn = document.getElementById('pc-change-pin-btn');
  if (!sw || !knob) return;
  var on = !!S.personalCheckEnabled;
  sw.style.background = on ? 'var(--accent)' : 'var(--surface2)';
  sw.style.borderColor = on ? 'var(--accent)' : 'var(--border)';
  knob.style.left = on ? '22px' : '2px';
  knob.style.background = on ? '#fff' : 'var(--text-dim)';
  // Personal Check o'chirilgan bo'lsa, PIN himoyasi qatori butunlay yashiriladi
  if (pinRow) pinRow.style.display = on ? '' : 'none';
  var pinOn = !!S.pcPinProtectionEnabled;
  if (pinSw && pinKnob) {
    pinSw.style.background = pinOn ? 'var(--accent)' : 'var(--surface2)';
    pinSw.style.borderColor = pinOn ? 'var(--accent)' : 'var(--border)';
    pinKnob.style.left = pinOn ? '22px' : '2px';
    pinKnob.style.background = pinOn ? '#fff' : 'var(--text-dim)';
  }
  // "PIN ni o'zgartirish" tugmasi faqat PIN himoyasi yoqilgan bo'lsagina kerak
  if (chBtn) chBtn.style.display = (on && pinOn) ? '' : 'none';

  // "Tezkor kirishdan yashirish" qatori — Personal Check yoqilgan bo'lsagina ko'rinadi
  var hideRow = document.getElementById('pc-hide-quickaccess-row');
  var hideSw = document.getElementById('pc-hide-toggle-switch');
  var hideKnob = document.getElementById('pc-hide-toggle-knob');
  if (hideRow) hideRow.style.display = on ? '' : 'none';
  var hideOn = !!S.pcHiddenFromQuickAccess;
  if (hideSw && hideKnob) {
    hideSw.style.background = hideOn ? 'var(--accent)' : 'var(--surface2)';
    hideSw.style.borderColor = hideOn ? 'var(--accent)' : 'var(--border)';
    hideKnob.style.left = hideOn ? '22px' : '2px';
    hideKnob.style.background = hideOn ? '#fff' : 'var(--text-dim)';
  }
}

