// ⚔️ O'yin qiyinligi — Settings ichidagi select. Faqat Coin/XP ko'paytiruvchisiga
// ta'sir qiladi (qarang: getDifficultyMultipliers()).
function updateDifficultySelectUI() {
  var sel = document.getElementById('difficulty-select');
  if (!sel) return;
  if (S.difficulty === 'hard') { S.difficulty = 'hardcore'; save(); } // eski nom migratsiyasi
  sel.value = S.difficulty || 'normal';
}
function changeDifficulty(val) {
  if (!DIFFICULTY_MULTIPLIERS[val]) val = 'normal';
  S.difficulty = val;
  save();
  updateDifficultySelectUI();
  try { SFX.click(); } catch (e) {}
  try { toast(t('difficulty_changed_toast')); } catch (e) {}
  try { renderBadges(); } catch (e) {}
  try { render(); } catch (e) {}
}
document.addEventListener('DOMContentLoaded', updateDifficultySelectUI);

function toggleSettingsPanel() {
  var panel = document.getElementById('settings-panel');
  var arrow = document.getElementById('settings-accordion-arrow');
  if (!panel) return;
  var isOpen = panel.style.display !== 'none';
  panel.style.display = isOpen ? 'none' : '';
  if (arrow) arrow.style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';
  try { localStorage.setItem('settingsPanelOpen', isOpen ? '0' : '1'); } catch (e) {}
  if (!isOpen) SFX.click();
}

// Sahifa yuklanganda oldingi holatni tiklaymiz
(function restoreSettingsPanelState() {
  try {
    if (localStorage.getItem('settingsPanelOpen') === '1') {
      document.addEventListener('DOMContentLoaded', function () {
        var panel = document.getElementById('settings-panel');
        var arrow = document.getElementById('settings-accordion-arrow');
        if (panel) panel.style.display = '';
        if (arrow) arrow.style.transform = 'rotate(180deg)';
      });
    }
  } catch (e) {}
})();

function togglePersonalCheck() {
  if (S.personalCheckEnabled) {
    if (pcHasPinSet()) {
      openPcVerifyPinModal('disablePc');
      return;
    }
    S.personalCheckEnabled = false;
    save();
    if(window._kiOv){window._kiOv.remove();window._kiOv=null;}
    window._kiQ=[];
    updatePcToggleUI();
    renderDsShortcuts();
    toast(t('pc_disabled_toast'));
  } else {
    // ON: avval tushuntirish oynasi, so'ng "Parol qo'yilsinmi?" va
    // "Tezkor kirishdan yashirilsinmi?" savollari (pcSetup* oqimi).
    openPcInfoModal();
  }
}

