function _pcSetupFinish(hide) {
  S.pcHiddenFromQuickAccess = !!hide;
  S.personalCheckEnabled = true;
  save();
  document.getElementById('pc-setup-overlay').style.display = 'none';
  _pcSetupInProgress = false;
  updatePcToggleUI();
  renderDsShortcuts();
  toast(t('pc_enabled_toast'));
}

function togglePinProtection() {
  if (S.pcPinProtectionEnabled) {
    // OFF: PIN himoyasini o'chirishdan oldin joriy PIN kodni tasdiqlash
    // shart — shu bilan faqat PIN'ni biladigan kishigina o'chira oladi.
    openPcVerifyPinModal('disablePin');
  } else if (pcHasPinSet()) {
    S.pcPinProtectionEnabled = true;
    save();
    updatePcToggleUI();
    toast(t('pc_pin_enabled_toast'));
  } else {
    // PIN hali o'rnatilmagan — avval yangi PIN yaratish so'raladi
    openPcCreatePinModal();
  }
}

