document.addEventListener('keydown', function(e) {
  // Tushuntirish oynasi ochiq bo'lsa — faqat Enter uni yopib, keyingi qadamga o'tkazadi
  var infoOv = document.getElementById('pc-info-overlay');
  if (infoOv && infoOv.style.display === 'flex') {
    if (e.key === 'Enter') { e.preventDefault(); confirmPcInfoModal(); }
    return;
  }

  var isDigit = (e.key >= '0' && e.key <= '9');
  var isBackspace = (e.key === 'Backspace');
  var isEnter = (e.key === 'Enter');
  if (!isDigit && !isBackspace && !isEnter) return;
  var action = isBackspace ? 'del' : (isEnter ? 'ok' : e.key);

  var viewSecret = document.getElementById('view-secret');
  var secretPinOv = document.getElementById('secret-pin-overlay');
  var createOv = document.getElementById('pc-create-pin-overlay');
  var verifyOv = document.getElementById('pc-verify-pin-overlay');
  var changeOv = document.getElementById('change-pin-overlay');

  if (createOv && createOv.style.display === 'flex') {
    e.preventDefault(); pcCreateKey(action);
  } else if (verifyOv && verifyOv.style.display === 'flex') {
    e.preventDefault(); pcVerifyKey(action);
  } else if (changeOv && changeOv.style.display === 'flex') {
    e.preventDefault(); chpinKey(action);
  } else if (viewSecret && viewSecret.style.display !== 'none' && secretPinOv && secretPinOv.style.display !== 'none') {
    e.preventDefault(); pinKey(action);
  }
});

// Streak milestone coins
var SEC_STREAK_BONUSES = {5:8, 10:20, 20:45, 40:90, 75:180};
var SEC_DEFAULT_CFG = { daily:3, fail:5, fail2x:10, tiers:{5:8, 10:20, 20:45, 40:90, 75:180} };
function secCfg() {
  var c = S.secretCfg || {};
  function n(v, d, mx) { v = Math.round(Number(v)); if (isNaN(v)) return d; return Math.max(0, Math.min(mx, v)); }
  var o = { daily:n(c.daily, 3, 1000), fail:n(c.fail, 5, 1000), fail2x:n(c.fail2x, 10, 1000), tiers:{} };
  [5,10,20,40,75].forEach(function(k){ o.tiers[k] = n(c.tiers && c.tiers[k], SEC_DEFAULT_CFG.tiers[k], 5000); });
  return o;
}
function secCfgSet(key, val) {
  if (!S.secretCfg) S.secretCfg = { tiers:{} };
  if (!S.secretCfg.tiers) S.secretCfg.tiers = {};
  var v = Math.max(0, Math.min(key.indexOf('t')===0 ? 5000 : 1000, Math.round(Number(val) || 0)));
  if (key.indexOf('t') === 0) S.secretCfg.tiers[key.slice(1)] = v; else S.secretCfg[key] = v;
  save();
}
function secCfgReset() {
  S.secretCfg = null; save(); renderSecCoinTable();
  try { toast(_cl('Standart narxlar tiklandi','Defaults restored','Значения по умолчанию')); } catch(e){}
}
var _secCfgEdit = false;
function secCfgToggleEdit() { _secCfgEdit = !_secCfgEdit; renderSecCoinTable(); }
function renderSecCoinTable() {
  var box = document.getElementById('sec-coin-table'); if (!box) return;
  var c = secCfg();
  var rows = [
    ['daily', _cl('✅ Har kun (qilmadim)','✅ Each clean day','✅ Каждый чистый день'), c.daily, 1],
    ['t5',  _cl('🥉 Daraja 1 (5 kun)','🥉 Level 1 (5 days)','🥉 Уровень 1 (5 дней)'), c.tiers[5], 1],
    ['t10', _cl('🥈 Daraja 2 (10 kun)','🥈 Level 2 (10 days)','🥈 Уровень 2 (10 дней)'), c.tiers[10], 1],
    ['t20', _cl('🥇 Daraja 3 (20 kun)','🥇 Level 3 (20 days)','🥇 Уровень 3 (20 дней)'), c.tiers[20], 1],
    ['t40', _cl('🏅 Daraja 4 (40 kun)','🏅 Level 4 (40 days)','🏅 Уровень 4 (40 дней)'), c.tiers[40], 1],
    ['t75', _cl('👑 Daraja 5 (75 kun)','👑 Level 5 (75 days)','👑 Уровень 5 (75 дней)'), c.tiers[75], 1],
    null,
    ['fail', _cl('❌ Yiqilsa (jazo)','❌ Slip (penalty)','❌ Срыв (штраф)'), c.fail, -1],
    ['fail2x', _cl('⚠️ 3 kun ketma-ket (2x jazo)','⚠️ 3 in a row (2x penalty)','⚠️ 3 подряд (2x штраф)'), c.fail2x, -1]
  ];
  var h = '';
  rows.forEach(function(r){
    if (!r) { h += '<div style="height:1px;background:var(--border);margin:4px 0"></div>'; return; }
    var col = r[3] > 0 ? '#34D399' : '#F87171';
    var val = _secCfgEdit
      ? '<span style="display:flex;align-items:center;gap:4px;color:' + col + '">' + (r[3]>0?'+':'−') + '<input type="number" min="0" max="' + (r[0].charAt(0)==='t'?5000:1000) + '" value="' + r[2] + '" inputmode="numeric" onchange="secCfgSet(\'' + r[0] + '\',this.value);renderSecCoinTable()" style="width:70px;padding:5px 8px;background:var(--surface2);border:1px solid var(--border);border-radius:var(--radius-sm);color:var(--text);font-size:var(--fs-sm);text-align:right" /> 🪙</span>'
      : '<span style="color:' + col + ';font-weight:600">' + (r[3]>0?'+':'−') + r[2] + ' 🪙</span>';
    h += '<div style="display:flex;justify-content:space-between;align-items:center"><span>' + r[1] + '</span>' + val + '</div>';
  });
  box.innerHTML = h;
  var eb = document.getElementById('sec-cfg-edit-btn');
  if (eb) eb.textContent = _secCfgEdit ? _cl('✔ Tayyor','✔ Done','✔ Готово') : _cl('✏️ Narxlarni o\'zgartirish','✏️ Edit prices','✏️ Изменить цены');
  var rb = document.getElementById('sec-cfg-reset-btn');
  if (rb) rb.style.display = _secCfgEdit ? '' : 'none';
}
var SEC_STREAK_TIER_ICON = {5:'🥉', 10:'🥈', 20:'🥇', 40:'🏅', 75:'👑'};

function calcSecretStreak(log) {
  var streak = 0;
  var d3 = new Date();
  var todayKey = d3.getFullYear()+'-'+String(d3.getMonth()+1).padStart(2,'0')+'-'+String(d3.getDate()).padStart(2,'0');
  // Bugun hali kiritilmagan bo'lsa — bugunni o'tkazib kechadan boshla
  if (log[todayKey] !== 'clean') {
    d3.setDate(d3.getDate() - 1);
  }
  while(true){
    var k = d3.getFullYear()+'-'+String(d3.getMonth()+1).padStart(2,'0')+'-'+String(d3.getDate()).padStart(2,'0');
    if(log[k]==='clean'){ streak++; d3.setDate(d3.getDate()-1); }
    else break;
  }
  return streak;
}

function yesterday() {
  var d2 = new Date();
  d2.setDate(d2.getDate() - 1);
  return d2.getFullYear()+'-'+String(d2.getMonth()+1).padStart(2,'0')+'-'+String(d2.getDate()).padStart(2,'0');
}

function isYesterdayMode() {
  return S.useYesterdayMode !== false;
}

// Joriy rejimga qarab "hisoblanadigan kun"ni qaytaradi — rejim yoqilgan
// bo'lsa kecha, o'chirilgan bo'lsa bugun.
function trackDate() {
  return isYesterdayMode() ? yesterday() : today();
}

function ensureYesterdayModeDefaults() {
  if (typeof S.useYesterdayMode === 'undefined' || S.useYesterdayMode === null) {
    S.useYesterdayMode = true;
  }
}

function updateYdayModeToggleUI() {
  var sw = document.getElementById('yday-mode-switch');
  var knob = document.getElementById('yday-mode-knob');
  if (!sw || !knob) return;
  var on = isYesterdayMode();
  sw.style.background = on ? 'var(--accent)' : 'var(--surface2)';
  sw.style.borderColor = on ? 'var(--accent)' : 'var(--border)';
  knob.style.left = on ? '22px' : '2px';
  knob.style.background = on ? '#fff' : 'var(--text-dim)';
}

function toggleYesterdayMode() {
  ensureYesterdayModeDefaults();
  S.useYesterdayMode = !S.useYesterdayMode;
  save();
  updateYdayModeToggleUI();
  try { renderGoals(); } catch (e) {}
  try { renderSecretContent(); } catch (e) {}
  try { SFX.click(); } catch (e) {}
  try { toast(isYesterdayMode() ? t('yday_mode_on_toast') : t('yday_mode_off_toast')); } catch (e) {}
}
document.addEventListener('DOMContentLoaded', function () {
  ensureYesterdayModeDefaults();
  updateYdayModeToggleUI();
});

function secretLog(status, when) {
  var d = getSecretData();
  var logDate = (when === 'yesterday') ? trackDate() : today();
  var prevStatus = d.log[logDate];

  // Streak bonus: sana+milestone bo'yicha saqlash (e.g. "2026-06-11_3")
  if(!d.streakBonusGiven) d.streakBonusGiven = {};
  if(!d.streakBonusByDate) d.streakBonusByDate = {};

  // ── 1. ROLLBACK: avvalgi tanlov effektlarini bekor qilish ──────────────────
  if(prevStatus) {
    var prevAmount = d.logCoins[logDate];
    if (prevAmount === undefined) {
      prevAmount = prevStatus === 'clean' ? 3 : (prevStatus === 'fail2x' ? -10 : -5);
    }
    if(prevStatus === 'clean') {
      spendCoins(prevAmount);
      // Shu kun uchun berilgan streak bonusini qaytarish (bitta kalit)
      var bonusKey = logDate + '_milestone';
      if(d.streakBonusByDate[bonusKey]) {
        var mB = d.streakBonusByDate[bonusKey];
        spendCoins(mB);
        delete d.streakBonusByDate[bonusKey];
      }
      // Tarixdan shu kunga tegishli yozuvlarni o'chirish (spam oldini olish)
      if(S.tarix) S.tarix = S.tarix.filter(function(r){
        return r.uniqueKey !== 'secret_clean_'+logDate && r.uniqueKey !== 'secret_bonus_'+logDate;
      });
    } else if(prevStatus === 'fail' || prevStatus === 'fail2x') {
      S.coins = (S.coins || 0) - prevAmount; // prevAmount manfiy, shuning uchun ayirish = qo'shish
      // Tarixdan shu kunga tegishli jazo yozuvini o'chirish
      if(S.tarix) S.tarix = S.tarix.filter(function(r){ return r.uniqueKey !== 'secret_fail_'+logDate; });
    }
    delete d.logCoins[logDate];
    // secret history dan bu kun yozuvini o'chirish
    if(d.history) d.history = d.history.filter(function(h){ return h.date !== logDate; });
    save();
  }

  d.log[logDate] = status;

  // ── 2. YANGI TANLOV effektlarini qo'llash ────────────────────────────────────
  if(status === 'clean') {
    var coinGain = secCfg().daily;
    var actualCoinGain = addLifetimeCoins(coinGain); // ijobiy topilgan tanga — S.totalCoins ham to'g'ri oshadi
    d.logCoins[logDate] = actualCoinGain; // earnedOrPenalizedCoins — aynan shu kun uchun (streak bonusisiz)
    // uniqueKey bilan yozsak, fikr o'zgartirish tarixga spam qilmaydi
    addTarixLog('in', tr('secret_clean_log'), actualCoinGain, 'secret_clean_'+logDate);

    // Streak bonuslarini tekshir (d.log[logDate] allaqachon 'clean' qilib yozilgan)
    var newStreak = calcSecretStreak(d.log);
    var totalCoinGain = actualCoinGain;
    var streakBonusKey = logDate + '_milestone';
    if(!d.streakBonusByDate[streakBonusKey]) {
      var mBonus = 0, mLabel = 0;
      if      (newStreak >= 75) { mBonus = secCfg().tiers[75]; mLabel = 75; }
      else if (newStreak >= 40) { mBonus = secCfg().tiers[40]; mLabel = 40; }
      else if (newStreak >= 20) { mBonus = secCfg().tiers[20]; mLabel = 20; }
      else if (newStreak >= 10) { mBonus = secCfg().tiers[10]; mLabel = 10; }
      else if (newStreak >= 5)  { mBonus = secCfg().tiers[5];  mLabel = 5;  }
      if(mBonus > 0) {
        // 🐛 Xuddi yuqoridagi kabi — endi HAQIQIY (chegirmali) bonus miqdori saqlanadi.
        var actualBonus = addLifetimeCoins(mBonus); // ijobiy bonus — S.totalCoins ham oshadi
        d.streakBonusByDate[streakBonusKey] = actualBonus; // rollback + spam himoya
        totalCoinGain += actualBonus;
        addTarixLog('in', tr('secret_streak_bonus_log').replace('{label}', mLabel), actualBonus, 'secret_bonus_'+logDate);
        setTimeout(function(ml, mb){ return function(){ toast(t('secret_streak_bonus_toast').replace('{ml}', ml).replace('{mb}', mb)); }; }(mLabel, actualBonus), 400);
      }
    }
    save();

    if(!d.history) d.history = [];
    // unshift (filter yuqorida allaqachon bajarildi) — bir kunda bitta yozuv
    d.history.unshift({date: logDate, status: 'clean', coins: totalCoinGain, streak: newStreak});
    if(d.history.length > 60) d.history = d.history.slice(0, 60);

  } else if(status === 'fail') {
    var consecutiveFails = 0;
    var checkDate = new Date(logDate + 'T00:00:00');
    checkDate.setDate(checkDate.getDate() - 1);
    for(var ci = 0; ci < 30; ci++) {
      var ck = checkDate.getFullYear()+'-'+String(checkDate.getMonth()+1).padStart(2,'0')+'-'+String(checkDate.getDate()).padStart(2,'0');
      if(d.log[ck] === 'fail' || d.log[ck] === 'fail2x') { consecutiveFails++; checkDate.setDate(checkDate.getDate()-1); }
      else break;
    }
    var _sc = secCfg(); var penalty = (consecutiveFails >= 2) ? _sc.fail2x : _sc.fail;
    d.logCoins[logDate] = -penalty; // earnedOrPenalizedCoins — aynan shu kun uchun yechilgan miqdor
    // 🔴 TUZATILDI (1.2): streak jarimasi S.totalCoins (umrbod hisoblagich)ni
    // ASLO kamaytirmaydi — faqat joriy balansdan (S.coins) ayiriladi.
    spendCoins(penalty);
    // uniqueKey bilan: bir kunda faqat bitta jazo yozuvi
    addTarixLog('out', tr('secret_fail_penalty_log').replace('{x2}', consecutiveFails >= 2 ? tr('secret_fail_2x_suffix') : ''), -penalty, 'secret_fail_'+logDate);
    save();
    setTimeout(function(){
      if(consecutiveFails >= 2) toast(t('secret_2x_penalty_toast').replace('{penalty}', penalty));
      else toast(t('secret_penalty_toast').replace('{penalty}', penalty));
    }, 200);

    // Streak singanida — milestone flaglarini tozalash (keyingi streakda qayta olsin)
    d.streakBonusGiven = {};

    if(!d.history) d.history = [];
    var failLabel = consecutiveFails >= 2 ? 'fail2x' : 'fail';
    // bir kunda bitta yozuv (filter yuqorida allaqachon bajarildi)
    d.history.unshift({date: logDate, status: failLabel, coins: -penalty, streak: 0});
    if(d.history.length > 60) d.history = d.history.slice(0, 60);
  }

  saveSecretData(d);
  render();
  renderSecretContent();
}

// Qaysi kun uchun log qilish kerakligini aniqlash:
// Agar kecha kiritilmagan bo'lsa → kecha; aks holda → bugun
var _secretLogTarget = 'yesterday'; // 'yesterday' yoki 'today'

function revealSecretLogButtons() {
  var btnRow = document.getElementById('secret-log-buttons');
  var statusEl = document.getElementById('secret-today-status');
  if(btnRow) btnRow.style.display = 'flex';
  if(statusEl) { statusEl.style.marginTop = '12px'; statusEl.innerHTML = ''; }
}

function secretEditLog() {
  // Tugmalarni qayta yoqish — foydalanuvchi javobni o'zgartira olsin
  var btnYes = document.getElementById('sec-btn-yes');
  var btnNo  = document.getElementById('sec-btn-no');
  var statusEl = document.getElementById('secret-today-status');
  if(btnYes){
    btnYes.disabled=false; btnYes.style.opacity='1';
    btnYes.style.borderWidth='1px'; btnYes.style.borderColor='rgba(52,211,153,0.3)';
    btnYes.style.background='rgba(52,211,153,0.08)';
  }
  if(btnNo){
    btnNo.disabled=false; btnNo.style.opacity='1';
    btnNo.style.borderWidth='1px'; btnNo.style.borderColor='rgba(248,113,113,0.3)';
    btnNo.style.background='rgba(248,113,113,0.08)';
  }
  // Avvalgi javobni log dan o'chirish va tangalarni qaytarish
  var d = getSecretData();
  var yday = trackDate();
  var prevStatus = d.log[yday];
  if(!d.streakBonusByDate) d.streakBonusByDate = {};
  if(!d.streakBonusGiven) d.streakBonusGiven = {};
  if(!d.logCoins) d.logCoins = {};
  // AYNAN o'sha paytda ta'sir qilgan tanga miqdori (earnedOrPenalizedCoins).
  // Eski (logCoins yozilmasdan oldingi) yozuvlar uchun fallback standart qiymatlar.
  var prevAmount = d.logCoins[yday];
  if (prevAmount === undefined && prevStatus) {
    prevAmount = prevStatus === 'clean' ? 3 : (prevStatus === 'fail2x' ? -10 : -5);
  }
  if(prevStatus === 'clean') {
    // 🔴 TUZATILDI (1.2): rollback S.totalCoins ga tegmaydi — faqat
    // joriy balansdan (S.coins) ayiriladi (spendCoins orqali).
    spendCoins(prevAmount);
    // Shu kun uchun berilgan streak bonusini qaytarish (bitta kalit)
    var bonusKey = yday + '_milestone';
    if(d.streakBonusByDate[bonusKey]) {
      var mB = d.streakBonusByDate[bonusKey];
      spendCoins(mB);
      delete d.streakBonusByDate[bonusKey];
    }
    save();
  } else if(prevStatus === 'fail' || prevStatus === 'fail2x') {
    var refund = -prevAmount;
    S.coins = (S.coins||0) + refund;
    save();
  }
  delete d.logCoins[yday];
  // Log va historydan o'chirish
  delete d.log[yday];
  if(d.history) d.history = d.history.filter(function(h){ return h.date !== yday; });
  saveSecretData(d);
  if(statusEl) statusEl.textContent = t('ki_select_answer');
  render();
}

function secretLogCurrent(status) {
  secretLog(status, _secretLogTarget);
}

function renderSecretContent() {
  try { renderSecCoinTable(); } catch (e) {}
  var d = getSecretData();
  var log = d.log || {};
  var t = today();
  var yday = yesterday();
  var ydMode = isYesterdayMode();

  if(ydMode && !log[yday] && log[t]) { delete log[t]; d.log = log; saveSecretData(d); }
  _secretLogTarget = 'yesterday';
  var activeDate = trackDate();
  var activeStatus = log[activeDate];
  var labelEl = document.getElementById('secret-log-label');
  if(labelEl) {
    var adParts = activeDate.split('-');
    var adNice = adParts[2] + '.' + adParts[1];
    labelEl.textContent = tr(ydMode ? 'ki_yesterday_caps' : 'ki_today_caps') + ' (' + adNice + ')';
  }
  var statusEl = document.getElementById('secret-today-status');
  var btnRow = document.getElementById('secret-log-buttons');
  var btnYes = document.getElementById('sec-btn-yes');
  var btnNo  = document.getElementById('sec-btn-no');
  if(activeStatus === 'clean') {
    if(btnRow) btnRow.style.display = 'flex';
    statusEl.style.marginTop = '12px';
    statusEl.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px"><span style="color:#34D399;font-weight:600">✅ '+tr(ydMode ? 'ki_yesterday_clean' : 'ki_today_clean')+'</span><button onclick="secretEditLog()" style="padding:4px 10px;border-radius:var(--radius-sm);border:1px solid var(--border);background:transparent;color:var(--text-muted);font-size:var(--fs-2xs);cursor:pointer;font-family:DM Sans,sans-serif">✏️ '+tr('btn_edit')+'</button></div>';
    if(btnYes){btnYes.style.borderWidth='2px';btnYes.style.borderColor='#34D399';btnYes.style.background='rgba(52,211,153,0.2)';btnYes.style.opacity='1';btnYes.disabled=true;}
    if(btnNo){btnNo.style.opacity='0.35';btnNo.disabled=true;}
  } else if(activeStatus === 'fail' || activeStatus === 'fail2x') {
    if(btnRow) btnRow.style.display = 'flex';
    statusEl.style.marginTop = '12px';
    var realPenalty = Math.abs(d.logCoins && d.logCoins[activeDate] || 5);
    var penText = realPenalty >= 10 ? tr('ki_pen_2x') : tr('ki_pen_normal');
    statusEl.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px"><span style="color:#F87171;font-weight:600">'+tr('ki_fail_label')+' '+penText+'</span><button onclick="secretEditLog()" style="padding:4px 10px;border-radius:var(--radius-sm);border:1px solid var(--border);background:transparent;color:var(--text-muted);font-size:var(--fs-2xs);cursor:pointer;font-family:DM Sans,sans-serif">✏️ '+tr('btn_edit')+'</button></div>';
    if(btnNo){btnNo.style.borderWidth='2px';btnNo.style.borderColor='#F87171';btnNo.style.background='rgba(248,113,113,0.2)';btnNo.style.opacity='1';btnNo.disabled=true;}
    if(btnYes){btnYes.style.opacity='0.35';btnYes.disabled=true;}
  } else {
    if(btnRow) btnRow.style.display = 'none';
    if(btnYes){btnYes.style.opacity='1';btnYes.style.background='rgba(52,211,153,0.08)';btnYes.style.borderColor='rgba(52,211,153,0.3)';btnYes.disabled=false;}
    if(btnNo){btnNo.style.opacity='1';btnNo.style.background='rgba(248,113,113,0.08)';btnNo.style.borderColor='rgba(248,113,113,0.3)';btnNo.disabled=false;}
    statusEl.style.marginTop = '0';
    statusEl.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px"><span>'+tr(ydMode ? 'ki_not_entered_yet' : 'ki_not_entered_today')+'</span><button onclick="revealSecretLogButtons()" style="padding:6px 12px;border-radius:var(--radius-sm);border:1px solid var(--border-hover);background:var(--surface2);color:var(--text);font-size:var(--fs-2xs);font-weight:600;cursor:pointer;font-family:DM Sans,sans-serif">✏️ '+tr('sec_mark_btn')+'</button></div>';
  }
    // Calendar — last 30 days
  var cal = document.getElementById('secret-calendar');
  if(cal) {
    var html = '';
    var now = new Date();
    for(var i=29;i>=0;i--){
      var d2 = new Date(now); d2.setDate(now.getDate()-i);
      var key = d2.getFullYear()+'-'+String(d2.getMonth()+1).padStart(2,'0')+'-'+String(d2.getDate()).padStart(2,'0');
      var val = log[key];
      var bg = val==='clean' ? '#34D399' : val==='fail2x' ? '#FF8C00' : val==='fail' ? '#F87171' : 'var(--surface2)';
      var opacity = val ? '1' : '0.5';
      var day = d2.getDate();
      html += '<div title="'+key+'" style="aspect-ratio:1;border-radius:var(--radius-2xs);background:'+bg+';opacity:'+opacity+';display:flex;align-items:center;justify-content:center;font-size:var(--fs-3xs);color:'+(val?'rgba(0,0,0,0.6)':'var(--text-dim)')+'">'+day+'</div>';
    }
    cal.innerHTML = html;
  }

  // Streak & stats
  var streak = calcSecretStreak(log);
  var best = 0; var total = 0;
  var allDays = Object.keys(log).sort();
  allDays.forEach(function(k){ if(log[k]==='clean') total++; });
  var tmpStreak = 0;
  allDays.forEach(function(k){
    if(log[k]==='clean'){ tmpStreak++; if(tmpStreak>best) best=tmpStreak; }
    else tmpStreak=0;
  });

  var startDateStr = d.startDate || allDays[0] || t;
  var startDateObj = new Date(startDateStr + 'T00:00:00');
  var todayObj = new Date(t + 'T00:00:00');
  var daysSinceStart = Math.round((todayObj - startDateObj) / 86400000) + 1;
  if (daysSinceStart < 1) daysSinceStart = 1;

  var el1=document.getElementById('sec-stat-streak'); if(el1) el1.textContent=streak;
  var el2=document.getElementById('sec-stat-total');  if(el2) el2.textContent=total + '/' + daysSinceStart;
  var el3=document.getElementById('sec-stat-best');   if(el3) el3.textContent=best;
  var badge=document.getElementById('secret-streak-badge');
  if(badge) {
    var tierIcon = '';
    var tierThresholds = [75,40,20,10,5];
    for (var ti=0; ti<tierThresholds.length; ti++) {
      if (streak >= tierThresholds[ti]) { tierIcon = SEC_STREAK_TIER_ICON[tierThresholds[ti]] + ' '; break; }
    }
    badge.textContent = streak>0 ? (tierIcon + tr('sec_streak_badge_active').replace('{n}', streak)) : tr('sec_streak_badge_none');
  }

  // History list
  var histEl = document.getElementById('secret-history-list');
  if(histEl) {
    var hist = d.history || [];
    if(hist.length === 0) {
      histEl.innerHTML = '<div style="color:var(--text-dim);font-size:var(--fs-sm);text-align:center;padding:12px 0">'+tr('sec_history_empty')+'</div>';
    } else {
      var hhtml = '';
      hist.forEach(function(item) {
        var isClean = item.status === 'clean';
        var is2x = item.status === 'fail2x';
        var color = isClean ? '#34D399' : '#F87171';
        var icon = isClean ? '✅' : (is2x ? '⚠️' : '❌');
        var coinStr = (item.coins > 0 ? '+' : '') + item.coins + ' 🪙';
        var coinColor = item.coins > 0 ? '#34D399' : '#F87171';
        var streakStr = isClean && item.streak > 0 ? ' · 🔥'+item.streak : (is2x ? ' · '+tr('sec_history_2x_label') : '');
        hhtml += '<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 10px;background:var(--surface2);border-radius:var(--radius-sm)">'
          + '<div style="display:flex;align-items:center;gap:8px">'
          + '<span style="font-size:var(--fs-base)">'+icon+'</span>'
          + '<div><div style="font-size:var(--fs-sm);color:var(--text)">'+item.date+streakStr+'</div>'
          + '</div></div>'
          + '<span style="font-size:var(--fs-sm);font-weight:700;color:'+coinColor+'">'+coinStr+'</span>'
          + '</div>';
      });
      histEl.innerHTML = hhtml;
    }
  }

  // Haftalik trend
  (function() {
    var now = new Date();
    function dateKey(d2) {
      return d2.getFullYear()+'-'+String(d2.getMonth()+1).padStart(2,'0')+'-'+String(d2.getDate()).padStart(2,'0');
    }
    // Bu hafta: bugundan 6 kun oldin (0..6)
    var thisWeek = 0, lastWeek = 0;
    for (var i = 0; i < 7; i++) {
      var d2 = new Date(now); d2.setDate(now.getDate() - i);
      if (log[dateKey(d2)] === 'clean') thisWeek++;
      var d3 = new Date(now); d3.setDate(now.getDate() - i - 7);
      if (log[dateKey(d3)] === 'clean') lastWeek++;
    }

    var elLast  = document.getElementById('sec-trend-last');
    var elThis  = document.getElementById('sec-trend-this');
    var elArrow = document.getElementById('sec-trend-arrow');
    var elMsg   = document.getElementById('sec-trend-msg');
    if (!elLast || !elThis || !elArrow || !elMsg) return;

    elLast.textContent = lastWeek + '/7';
    elThis.textContent = thisWeek + '/7';

    var diff = thisWeek - lastWeek;
    var arrow, color, bg, msg;
    if (diff > 0) {
      arrow = '📈'; color = '#34D399'; bg = 'rgba(52,211,153,0.1)';
      msg = tr('sec_trend_up').replace('{diff}', diff);
    } else if (diff < 0) {
      arrow = '📉'; color = '#F87171'; bg = 'rgba(248,113,113,0.1)';
      msg = tr('sec_trend_down').replace('{diff}', Math.abs(diff));
    } else if (thisWeek === 0 && lastWeek === 0) {
      arrow = '➡️'; color = 'var(--text-muted)'; bg = 'var(--surface2)';
      msg = tr('sec_trend_no_data');
    } else {
      arrow = '➡️'; color = '#F5A623'; bg = 'rgba(245,166,35,0.1)';
      msg = tr('sec_trend_same').replace('{n}', thisWeek);
    }

    elArrow.textContent = arrow;
    elThis.style.color  = color;
    elMsg.textContent   = msg;
    elMsg.style.background = bg;
    elMsg.style.color   = color;
  })();
}


var _editingGoalId = null;

var gmRepeat = 'daily', gmDays = [], gmInterval = 4;

function gmSelRepeat(r) {
  gmRepeat = r;
  document.querySelectorAll('#goal-modal-box .repeat-opt').forEach(function(el) {
    el.classList.toggle('sel', el.dataset.rep === r);
  });
  document.getElementById('gm-field-custom-days').style.display = r==='custom-days' ? '' : 'none';
  document.getElementById('gm-field-interval').style.display = r==='interval' ? '' : 'none';
  document.getElementById('gm-field-startdate').style.display = '';
  // "Bir marta" tanlanganda muddat (necha kun) maydoni ma'nosiz bo'lib
  // qoladi — chunki bunday maqsad faqat BIR marta belgilanadi.
  document.getElementById('gm-field-duration').style.display = r==='once' ? 'none' : '';
}

function gmToggleDay(d) {
  var idx = gmDays.indexOf(d);
  if (idx>=0) gmDays.splice(idx,1); else gmDays.push(d);
  document.querySelectorAll('#goal-modal-box .day-btn').forEach(function(el) {
    el.classList.toggle('sel', gmDays.includes(parseInt(el.dataset.d)));
  });
}

function isGoalDueOnDate(g, dateStr) {
  // Maqsad hali yaratilmagan kunlarga ta'sir qilmaydi.
  if (g.startDate && dateStr < g.startDate) return false;
  if (g.daysChecked && g.daysChecked[dateStr]) return true;
  if (typeof goalPausedOn === 'function' && goalPausedOn(g, dateStr)) return false;
  var rep = g.repeat || 'daily';
  if (rep === 'daily') return true;
  if (rep === 'custom-days') {
    var dow = new Date(dateStr + 'T00:00:00').getDay();
    return (g.days||[]).indexOf(dow) !== -1;
  }
  if (rep === 'interval') {
    var origin = g.intervalStart || g.startDate || dateStr;
    var originTime = new Date(origin + 'T00:00:00').getTime();
    var dateTime = new Date(dateStr + 'T00:00:00').getTime();
    var diffDays = Math.round((dateTime - originTime) / 86400000);
    if (diffDays < 0) return false;
    var interval = Math.max(1, Number(g.interval) || 1);
    return diffDays % interval === 0;
  }
  if (rep === 'once') {
    return (dateStr === today() || dateStr === trackDate()) && !g.done;
  }
  return true;
}

function goalDueToday(g) {
  return isGoalDueOnDate(g, today());
}

function openGoalModal(id) {
  _editingGoalId = id || null;
  var title = document.getElementById('goal-modal-title');
  if(id) {
    var g = (S.goals||[]).find(function(x){return x.id===id;});
    if(!g) return;
    title.textContent = t('gm_title_edit');
    document.getElementById('gm-name').value = g.name || '';
    document.getElementById('gm-desc').value = g.desc || '';
    document.getElementById('gm-duration').value = g.duration || '';
    document.getElementById('gm-emoji').value = g.emoji || '🎯';
    setGoalCoins((typeof g.coins === 'number') ? g.coins : 1);
    gmRepeat = g.repeat || 'daily';
    gmDays = g.days ? [...g.days] : [];
    gmInterval = g.interval || 4;
    document.getElementById('gm-interval').value = gmInterval;
    document.getElementById('gm-startdate').value = g.intervalStart || g.startDate || today();
    gmSelRepeat(gmRepeat);
    document.querySelectorAll('#goal-modal-box .day-btn').forEach(function(el){
      el.classList.toggle('sel', gmDays.includes(parseInt(el.dataset.d)));
    });
    gmOngoing = !g.duration && (g.repeat || 'daily') !== 'once';
    gmFillHabitFields(g);
    syncGoalDurChips();
    gmSyncCoinChips();
    gmShowPage(1);
  } else {
    title.textContent = t('gm_title_new');
    document.getElementById('gm-name').value = '';
    document.getElementById('gm-desc').value = '';
    document.getElementById('gm-duration').value = '';
    document.getElementById('gm-emoji').value = '🎯';
    setGoalCoins(1);
    gmRepeat = 'daily'; gmDays = []; gmInterval = 4;
    document.getElementById('gm-interval').value = '4';
    document.getElementById('gm-startdate').value = trackDate();
    gmSelRepeat('daily');
    document.querySelectorAll('#goal-modal-box .day-btn').forEach(function(el){ el.classList.remove('sel'); });
    gmOngoing = false;
    gmFillHabitFields(null);
    syncGoalDurChips();
    gmSyncCoinChips();
    gmShowPage(1);
  }
  document.getElementById('goal-modal-overlay').classList.add('open');
  setTimeout(function(){ document.getElementById('gm-name').focus(); }, 150);
}

function closeGoalModal() {
  document.getElementById('goal-modal-overlay').classList.remove('open');
  _editingGoalId = null;
}

function setGoalEmoji(e) {
  document.getElementById('gm-emoji').value = e;
  document.querySelectorAll('#goal-modal-box .remoji-chip').forEach(function(b){
    b.className = 'remoji-chip' + (b.textContent.trim() === e ? ' sel' : '');
  });
}

function setGoalCoins(val) {
  var v = parseInt(val); if (isNaN(v)) v = 0;
  v = Math.max(0, Math.min(30, v));
  document.getElementById('gm-coins').value = v;
  gmSyncCoinChips();
}
function gmCoinsInput() {
  var el = document.getElementById('gm-coins');
  if (el.value === '') { gmSyncCoinChips(); return; }
  var v = parseInt(el.value);
  if (isNaN(v)) { el.value = ''; return; }
  if (v > 30) el.value = 30; else if (v < 0) el.value = 0;
  gmSyncCoinChips();
}
function gmSyncCoinChips() {
  var cur = parseInt(document.getElementById('gm-coins').value);
  document.querySelectorAll('#gm-coin-opts .rcost-chip').forEach(function (b) {
    b.className = 'rcost-chip' + (parseInt(b.dataset.v) === cur ? ' sel' : '');
  });
}
var gmPage = 1;
function gmShowPage(n) {
  gmPage = n;
  document.querySelectorAll('#goal-modal-box .gm-page').forEach(function (el) { el.style.display = (+el.dataset.page === n) ? '' : 'none'; });
  document.getElementById('gm-step-label').textContent = n + ' / 2';
  document.getElementById('gm-dot-1').style.background = 'var(--accent)';
  document.getElementById('gm-dot-2').style.background = n === 2 ? 'var(--accent)' : 'var(--surface2)';
  document.getElementById('gm-btn-cancel').style.display = n === 1 ? '' : 'none';
  document.getElementById('gm-btn-next').style.display = n === 1 ? '' : 'none';
  document.getElementById('gm-btn-back').style.display = n === 2 ? '' : 'none';
  document.getElementById('gm-btn-save').style.display = n === 2 ? '' : 'none';
  var nx = document.getElementById('gm-btn-next'); if (nx) nx.textContent = _cl('Keyingi →', 'Next →', 'Далее →');
  var bk = document.getElementById('gm-btn-back'); if (bk) bk.textContent = _cl('← Orqaga', '← Back', '← Назад');
  var box = document.getElementById('goal-modal-box'); if (box) box.scrollTop = 0;
}
function gmNext() {
  var name = (document.getElementById('gm-name').value || '').trim();
  if (!name) { document.getElementById('gm-name').focus(); toast(t('gm_name_required_toast')); return; }
  gmShowPage(2);
}

function saveGoal() {
  var name = (document.getElementById('gm-name').value || '').trim();
  var desc = (document.getElementById('gm-desc').value || '').trim();
  var emoji = (document.getElementById('gm-emoji').value || '').trim() || '🎯';
  var coinsRaw = parseInt(document.getElementById('gm-coins').value);
  var coins = isNaN(coinsRaw) ? 1 : Math.max(0, Math.min(30, coinsRaw));
  var dur = (gmRepeat === 'once') ? 1 : (gmOngoing ? 0 : (parseInt(document.getElementById('gm-duration').value) || 0));
  var penVal = Math.max(0, Math.min(30, parseInt((document.getElementById('gm-penalty') || {}).value) || 0));
  var remindVal = ((document.getElementById('gm-remind') || {}).value || '').trim() || null;
  var interval = Math.max(1, parseInt(document.getElementById('gm-interval').value) || 4);
  var startDateInput = document.getElementById('gm-startdate').value || today();
  if(!name) { document.getElementById('gm-name').focus(); toast(t('gm_name_required_toast')); return; }
  if(gmRepeat !== 'once' && !gmOngoing && !dur)  { document.getElementById('gm-duration').focus(); toast(t('goal_duration_required_toast')); return; }
  if(gmRepeat === 'custom-days' && gmDays.length === 0) { toast(t('task_select_day_toast')); return; }

  if(!S.goals) S.goals = [];
  if(_editingGoalId) {
    var g = S.goals.find(function(x){return x.id===_editingGoalId;});
    if(g){
      g.name=name; g.desc=desc; g.emoji=emoji; g.coins=coins; g.penalty=penVal; g.remind=remindVal;
      var repeatChanged = (g.repeat||'daily') !== gmRepeat;
      g.repeat = gmRepeat;
      g.days = gmRepeat==='custom-days' ? [...gmDays] : null;
      g.interval = gmRepeat==='interval' ? interval : null;
      if (gmRepeat==='interval' && (repeatChanged || g.intervalStart !== startDateInput)) {
        g.intervalStart = startDateInput;
      } else if (gmRepeat !== 'interval') {
        g.intervalStart = null;
      }
      if (startDateInput && startDateInput !== g.startDate) {
        g.startDate = startDateInput;
        if (gmRepeat === 'daily' && dur > 0) g.endDate = addDays(g.startDate, dur - 1);
      }
      if (g.duration !== dur || repeatChanged) {
        g.duration = dur;
        g.endDate = (gmRepeat === 'daily' && dur > 0) ? addDays(g.startDate || today(), dur - 1) : null;
      }
    }
  } else {
    var startDate = startDateInput; // standart: trackDate() (kecha rejimida kecha); kelajak sana = kelajakdagi odat
    var endDate = (gmRepeat === 'daily' && dur > 0) ? addDays(startDate, dur - 1) : null;
    S.goals.push({
      id: Date.now(), name:name, desc:desc, duration:dur, emoji:emoji,
      startDate:startDate, endDate:endDate, done:false, daysChecked:{}, coins:coins,
      repeat: gmRepeat, penalty: penVal, remind: remindVal, pauses: [], daysPenalty: {},
      days: gmRepeat==='custom-days' ? [...gmDays] : null,
      interval: gmRepeat==='interval' ? interval : null,
      intervalStart: gmRepeat==='interval' ? startDateInput : null
    });
    toast(emoji + t('gm_added_toast'));
  }
  save(); closeGoalModal(); renderGoals(); renderGoalsCalendar();
  try { scheduleGoalReminders(); } catch (e) {}
}

function _goalToggleDateCore(g, dateStr) {
  if(!g.daysChecked) g.daysChecked = {};
  if(!g.daysCoinsGiven) g.daysCoinsGiven = {};
  var coinAward = (typeof g.coins === 'number') ? g.coins : 1;
  var nowChecked;
  if(g.daysChecked[dateStr]) {
    delete g.daysChecked[dateStr];
    var frozenAward = g.daysCoinsGiven[dateStr];
    if(frozenAward) {
      delete g.daysCoinsGiven[dateStr];
      // 1.2: S.totalCoins (umrbod hisoblagich) bu yerda ASLO kamaytirilmaydi —
      // faqat joriy balans S.coins dan ayiriladi (spendCoins yordamchisi orqali).
      spendCoins(frozenAward);
      addTarixLog('out', g.name+' '+t('btn_cancel').toLowerCase(), -frozenAward, 'goal_'+g.id);
    }
    nowChecked = false;
  } else {
    // Check — faqat shu kun uchun hali tanga berilmagan bo'lsa ber, va
    // aynan shu miqdorni (coinAward) o'sha kun uchun "muzlatib" saqlaymiz.
    g.daysChecked[dateStr] = 1;
    if (g.daysPenalty && g.daysPenalty[dateStr]) {
      var _refund = g.daysPenalty[dateStr];
      delete g.daysPenalty[dateStr];
      S.coins = (S.coins || 0) + _refund;
      addTarixLog('in', '↩️ ' + g.emoji + ' ' + g.name, _refund, null, dateStr);
    }
    if(!g.daysCoinsGiven[dateStr]) {
      var actualAward = addLifetimeCoins(coinAward);
      g.daysCoinsGiven[dateStr] = actualAward;
      addTarixLog('in', g.emoji+' '+g.name, actualAward, 'goal_'+g.id);
      coinAward = actualAward; // toast/natija ham haqiqiy berilgan miqdorni ko'rsatsin
    }
    nowChecked = true;
  }

  var daysDone = g.daysChecked ? Object.keys(g.daysChecked).length : 0;
  var wasDone = !!g.done;
  g.done = (g.duration > 0 || g.repeat === 'once') ? daysDone >= (g.duration || 1) : false;
  return { nowChecked: nowChecked, coinAward: coinAward, justCompleted: (g.done && !wasDone) };
}

function goalCheckToday(id) {
  var g = (S.goals||[]).find(function(x){return x.id===id;}); if(!g) return;
  var yd = trackDate();
  if (!isGoalDueOnDate(g, yd)) { toast(t('goal_not_today')); return; }
  var result = _goalToggleDateCore(g, yd);

  if (result.nowChecked) {
    toast(g.emoji + ' ' + t('goal_day_added_toast').replace('{coins}', result.coinAward));
    confetti();
    SFX.coin();
  } else {
    toast(t('goal_mark_removed_toast'));
  }
  if (result.justCompleted) toast('🏆 ' + g.emoji + ' ' + t('goal_completed'));

  save(); renderGoals(); renderGoalsCalendar(); render();
}

var _goalCalId = null, _goalCalYear = null, _goalCalMonth = null;

function openGoalCalendar(id) {
  var g = (S.goals||[]).find(function(x){return x.id===id;});
  if (!g) return;
  _goalCalId = id;
  var now = new Date();
  _goalCalYear = now.getFullYear();
  _goalCalMonth = now.getMonth();
  renderGoalCalendar();
  document.getElementById('goal-cal-modal-overlay').classList.add('open');
}

function closeGoalCalendar() {
  document.getElementById('goal-cal-modal-overlay').classList.remove('open');
  _goalCalId = null;
}

function goalCalPrevMonth() {
  _goalCalMonth--;
  if (_goalCalMonth < 0) { _goalCalMonth = 11; _goalCalYear--; }
  renderGoalCalendar();
}

function goalCalNextMonth() {
  _goalCalMonth++;
  if (_goalCalMonth > 11) { _goalCalMonth = 0; _goalCalYear++; }
  renderGoalCalendar();
}

function goalCalToggleDay(id, dateStr) {
  var g = (S.goals||[]).find(function(x){return x.id===id;}); if(!g) return;
  var td = today();
  if (dateStr > td) return; // kelajak kunni belgilab bo'lmaydi
  if (!isGoalDueOnDate(g, dateStr)) { toast(t('goal_not_today')); return; }

  var result = _goalToggleDateCore(g, dateStr);
  if (result.nowChecked) {
    toast(g.emoji + ' ' + dateStr + ' — +' + result.coinAward + ' 🪙');
  } else {
    toast(t('goal_mark_removed_toast'));
  }
  if (result.justCompleted) toast('🏆 ' + g.emoji + ' ' + t('goal_completed'));

  save(); renderGoalCalendar(); renderGoals(); render();
}

function renderGoalCalendar() {
  var g = (S.goals||[]).find(function(x){return x.id===_goalCalId;});
  var overlay = document.getElementById('goal-cal-modal-overlay');
  if (!g) { if (overlay) overlay.classList.remove('open'); return; }

  var titleEl = document.getElementById('goal-cal-title');
  if (titleEl) titleEl.textContent = (g.emoji||'🎯') + ' ' + g.name;

  var label = document.getElementById('goal-cal-month-label');
  if (label) label.textContent = getMonthsFullArr()[_goalCalMonth] + ' ' + _goalCalYear;

  // Hafta kunlari sarlavhasi — mavjud getShortDaysArr() orqali joriy tilga
  // moslashtiriladi (0=Yak...6=Sha), kalendar esa Dushanbadan boshlanadi.
  var weekdaysEl = document.getElementById('goal-cal-weekdays');
  if (weekdaysEl) {
    var sd = getShortDaysArr();
    var order = [1,2,3,4,5,6,0];
    weekdaysEl.innerHTML = order.map(function(d){
      return '<div style="text-align:center;font-size:var(--fs-3xs);color:var(--text-dim);font-weight:600">' + esc(sd[d]) + '</div>';
    }).join('');
  }

  var grid = document.getElementById('goal-cal-grid');
  if (!grid) return;
  grid.innerHTML = '';

  var firstDay = new Date(_goalCalYear, _goalCalMonth, 1).getDay(); // 0=Yak
  var startOffset = (firstDay === 0) ? 6 : firstDay - 1; // Dushanbadan boshlanadi
  var daysInMonth = new Date(_goalCalYear, _goalCalMonth + 1, 0).getDate();
  var todayStr = today();

  for (var i = 0; i < startOffset; i++) {
    var empty = document.createElement('div');
    empty.style.cssText = 'aspect-ratio:1;max-height:48px;';
    grid.appendChild(empty);
  }

  for (var day = 1; day <= daysInMonth; day++) {
    var dateStr = getDateStr(_goalCalYear, _goalCalMonth, day);
    var isFuture = dateStr > todayStr;
    var isToday = dateStr === todayStr;
    var notCreatedYet = g.startDate && dateStr < g.startDate;
    var isChecked = !!(g.daysChecked && g.daysChecked[dateStr]);
    var isDue = !notCreatedYet && isGoalDueOnDate(g, dateStr);

    var bg, opacity = '1', icon = '';
    if (notCreatedYet) {
      bg = 'transparent'; opacity = '0.2';
    } else if (isChecked) {
      bg = '#34D399'; icon = '✅';
    } else if (!isDue) {
      bg = 'var(--surface2)'; opacity = '0.45';
    } else if (isFuture) {
      bg = 'transparent'; opacity = '0.35';
    } else {
      // Due edi, lekin belgilanmagan va bugundan oldingi kun — o'tkazib
      // yuborilgan (❌) deb ko'rsatiladi.
      bg = 'rgba(248,113,113,0.7)'; icon = '❌';
    }

    var canToggle = !notCreatedYet && !isFuture && isDue;

    var cell = document.createElement('div');
    cell.dataset.date = dateStr;
    cell.style.cssText =
      'aspect-ratio:1;max-height:48px;border-radius:var(--radius-sm);background:' + bg +
      ';opacity:' + opacity +
      ';display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;font-size:var(--fs-2xs);font-weight:600' +
      ';color:' + (bg === 'transparent' || bg === 'var(--surface2)' ? 'var(--text-dim)' : 'rgba(0,0,0,0.75)') +
      ';cursor:' + (canToggle ? 'pointer' : 'default') +
      ';transition:transform 0.15s;position:relative;' +
      (isToday ? 'box-shadow:0 0 0 2px var(--accent);' : '');

    var dayNumEl = document.createElement('span');
    dayNumEl.style.cssText = 'line-height:1';
    dayNumEl.textContent = day;
    cell.appendChild(dayNumEl);

    if (icon) {
      var iconEl = document.createElement('span');
      iconEl.style.cssText = 'font-size:9px;line-height:1';
      iconEl.textContent = icon;
      cell.appendChild(iconEl);
    }

    if (canToggle) {
      cell.title = isChecked ? t('goal_check_done_today') : t('goal_check_todo_today');
      cell.addEventListener('click', function(e) {
        goalCalToggleDay(_goalCalId, e.currentTarget.dataset.date);
      });
      cell.addEventListener('mouseenter', function(e){ e.currentTarget.style.transform = 'scale(1.12)'; });
      cell.addEventListener('mouseleave', function(e){ e.currentTarget.style.transform = ''; });
    }

    grid.appendChild(cell);
  }
}

var _gCalYear = new Date().getFullYear();
var _gCalMonth = new Date().getMonth();

function goalsCalPrevMonth() {
  _gCalMonth--;
  if (_gCalMonth < 0) { _gCalMonth = 11; _gCalYear--; }
  renderGoalsCalendar();
}
function goalsCalNextMonth() {
  _gCalMonth++;
  if (_gCalMonth > 11) { _gCalMonth = 0; _gCalYear++; }
  renderGoalsCalendar();
}
function goalsCalGoToday() {
  var d = new Date();
  _gCalYear = d.getFullYear();
  _gCalMonth = d.getMonth();
  renderGoalsCalendar();
}

function renderGoalsCalDayHeaders() {
  var el = document.getElementById('gcal-day-headers');
  if (!el) return;
  var shortDays = getShortDaysArr();
  var mondayFirstOrder = [1,2,3,4,5,6,0];
  var html = '';
  for (var i = 0; i < mondayFirstOrder.length; i++) {
    var dow = mondayFirstOrder[i];
    var isSunday = dow === 0;
    html += '<div style="text-align:center;font-size:var(--fs-3xs);color:' +
      (isSunday ? 'var(--accent)' : 'var(--text-dim)') + ';padding:3px 0">' + esc(shortDays[dow]) + '</div>';
  }
  el.innerHTML = html;
}

function getGoalsDayStats(dateStr) {
  var due = 0, done = 0;
  (S.goals || []).forEach(function(g) {
    if (g.startDate && dateStr < g.startDate) return;
    if (!isGoalDueOnDate(g, dateStr)) return;
    due++;
    if (g.daysChecked && g.daysChecked[dateStr]) done++;
  });
  return { due: due, done: done };
}

function renderGoalsCalendar() {
  if (!document.getElementById("gcal-grid")) return;
  var label = document.getElementById('gcal-month-label');
  if (label) label.textContent = getMonthsFullArr()[_gCalMonth] + ' ' + _gCalYear;

  renderGoalsCalDayHeaders();

  var grid = document.getElementById('gcal-grid');
  if (!grid) return;
  grid.innerHTML = '';

  var detail = document.getElementById('gcal-detail');
  if (detail) detail.style.display = 'none';

  var firstDay = new Date(_gCalYear, _gCalMonth, 1).getDay();
  var startOffset = (firstDay === 0) ? 6 : firstDay - 1;
  var daysInMonth = new Date(_gCalYear, _gCalMonth + 1, 0).getDate();
  var todayStr = today();

  for (var i = 0; i < startOffset; i++) {
    var empty = document.createElement('div');
    empty.style.cssText = 'aspect-ratio:1;max-height:48px;';
    grid.appendChild(empty);
  }

  for (var day = 1; day <= daysInMonth; day++) {
    var dateStr = getDateStr(_gCalYear, _gCalMonth, day);
    var isFuture = dateStr > todayStr;
    var isToday = dateStr === todayStr;

    var stats = isFuture ? { due: 0, done: 0 } : getGoalsDayStats(dateStr);

    var bg, opacity = '1';
    if (isFuture) {
      bg = 'transparent'; opacity = '0.35';
    } else if (stats.due === 0) {
      bg = 'var(--surface2)'; opacity = '0.5';
    } else {
      var pct = stats.done / stats.due;
      if (pct >= 1)      bg = '#34D399';
      else if (pct > 0)  bg = '#F5A623';
      else               bg = '#F87171';
    }

    var cell = document.createElement('div');
    cell.dataset.date = dateStr;
    cell.style.cssText =
      'aspect-ratio:1;max-height:48px;border-radius:var(--radius-sm);background:' + bg +
      ';opacity:' + opacity +
      ';display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;font-size:var(--fs-2xs);font-weight:600' +
      ';color:' + (bg === 'transparent' || bg === 'var(--surface2)' ? 'var(--text-dim)' : 'rgba(0,0,0,0.75)') +
      ';cursor:' + (isFuture ? 'default' : 'pointer') +
      ';transition:transform 0.15s;position:relative;' +
      (isToday ? 'box-shadow:0 0 0 2px var(--accent);' : '');

    var dayNumEl = document.createElement('span');
    dayNumEl.style.cssText = 'line-height:1';
    dayNumEl.textContent = day;
    cell.appendChild(dayNumEl);

    if (!isFuture && stats.due > 0) {
      var miniEl = document.createElement('span');
      miniEl.style.cssText = 'font-size:7px;line-height:1;font-weight:700;opacity:0.85';
      miniEl.textContent = stats.done + '/' + stats.due;
      cell.appendChild(miniEl);
      cell.title = stats.done + '/' + stats.due;
    }

    if (!isFuture) {
      cell.tabIndex = 0;
      cell.setAttribute('role', 'button');
      cell.setAttribute('aria-label', dateStr + (stats.due > 0 ? ', ' + stats.done + '/' + stats.due : ''));

      cell.addEventListener('click', function(e) {
        var ds = e.currentTarget.dataset.date;
        showGoalsDayDetail(ds);
        grid.querySelectorAll('[data-date]').forEach(function(c) { c.style.outline = ''; });
        e.currentTarget.style.outline = '2px solid var(--accent)';
        e.currentTarget.style.outlineOffset = '2px';
      });
      cell.addEventListener('mouseenter', function(e) { if(!e.currentTarget.style.outline) e.currentTarget.style.transform='scale(1.12)'; });
      cell.addEventListener('mouseleave', function(e) { e.currentTarget.style.transform=''; });
      cell.addEventListener('keydown', function(e) {
        var dayCells = Array.prototype.slice.call(grid.querySelectorAll('[data-date]'));
        var idx = dayCells.indexOf(e.currentTarget);
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.currentTarget.click(); }
        else if (e.key === 'ArrowRight') { e.preventDefault(); if (dayCells[idx+1]) dayCells[idx+1].focus(); }
        else if (e.key === 'ArrowLeft')  { e.preventDefault(); if (dayCells[idx-1]) dayCells[idx-1].focus(); }
        else if (e.key === 'ArrowDown')  { e.preventDefault(); if (dayCells[idx+7]) dayCells[idx+7].focus(); }
        else if (e.key === 'ArrowUp')    { e.preventDefault(); if (dayCells[idx-7]) dayCells[idx-7].focus(); }
      });
    }

    grid.appendChild(cell);
  }
}

function toggleGoalsCalDetail() {
  var body  = document.getElementById('gcal-detail-body');
  var arrow = document.getElementById('gcal-detail-arrow');
  if (!body) return;
  var isOpen = body.style.display !== 'none';
  body.style.display  = isOpen ? 'none' : '';
  if (arrow) arrow.style.transform = isOpen ? '' : 'rotate(90deg)';
}

function renderGoalsDayDetailContent(dateStr) {
  var detail = document.getElementById('gcal-detail');
  var title  = document.getElementById('gcal-detail-title');
  var list   = document.getElementById('gcal-detail-list');
  if (!detail || !title || !list) return;

  var d = new Date(dateStr + 'T00:00:00');
  var dayName = getDaysArr()[d.getDay()];
  title.textContent = dayName + ', ' + d.getDate() + ' ' + getMonthsArr()[d.getMonth()] + ' ' + d.getFullYear();

  var html = '';
  var anyGoal = false, totalCount = 0, doneCount = 0;

  (S.goals || []).forEach(function(g) {
    if (g.startDate && dateStr < g.startDate) return;
    if (!isGoalDueOnDate(g, dateStr)) return;
    anyGoal = true;

    var checked = !!(g.daysChecked && g.daysChecked[dateStr]);
    totalCount++;
    if (checked) doneCount++;

    var icon  = checked ? '✅' : '⬜';
    var coins = checked ? ('+' + g.coins + ' 🪙') : '';

    html +=
      '<div style="display:flex;align-items:center;gap:10px;padding:9px 12px;background:rgba(124,92,252,0.08);border:1px solid rgba(124,92,252,0.25);border-radius:var(--radius-sm)">' +
        '<button onclick="gcalToggleGoal(' + g.id + ',\'' + dateStr + '\')" title="' + esc(t('goal_check_done_today')) + '" ' +
          'style="background:none;border:none;padding:0;margin:0;cursor:pointer;font-size:var(--fs-md);flex-shrink:0;line-height:1">' + icon + '</button>' +
        '<span style="flex:1;font-size:var(--fs-sm);color:var(--text)">' + esc(g.emoji||'🎯') + ' ' + esc(g.name) + '</span>' +
        '<span style="font-size:var(--fs-xs);color:#F5A623;font-weight:600">' + coins + '</span>' +
      '</div>';
  });

  if (!anyGoal) {
    html = '<div style="color:var(--text-dim);font-size:var(--fs-sm);text-align:center;padding:12px">' + esc(t('goals_cal_day_empty')) + '</div>';
  }

  list.innerHTML = html;

  var progressEl = document.getElementById('gcal-detail-progress');
  if (progressEl) {
    if (anyGoal) {
      progressEl.textContent = doneCount + '/' + totalCount;
      progressEl.style.color = doneCount === totalCount ? '#34D399' : 'var(--text-dim)';
    } else {
      progressEl.textContent = '';
    }
  }
}

function showGoalsDayDetail(dateStr) {
  var detail = document.getElementById('gcal-detail');
  if (!detail) return;

  renderGoalsDayDetailContent(dateStr);

  var arrow = document.getElementById('gcal-detail-arrow');
  var body  = document.getElementById('gcal-detail-body');
  var alreadyOpen = detail.dataset.openDate === dateStr && body && body.style.display !== 'none';
  detail.style.display = '';
  detail.dataset.openDate = dateStr;
  if (body) body.style.display = alreadyOpen ? 'none' : '';
  if (arrow) arrow.style.transform = alreadyOpen ? '' : 'rotate(90deg)';

  if (!alreadyOpen) {
    setTimeout(function () {
      try { detail.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); } catch (e) {}
    }, 50);
  }
}

function gcalToggleGoal(id, dateStr) {
  var g = (S.goals || []).find(function(x){ return x.id === id; });
  if (!g) return;
  var td = today();
  if (dateStr > td) return;
  if (!isGoalDueOnDate(g, dateStr)) { toast(t('goal_not_today')); return; }

  var result = _goalToggleDateCore(g, dateStr);
  if (result.nowChecked) {
    toast(g.emoji + ' ' + dateStr + ' — +' + result.coinAward + ' 🪙');
    if (dateStr === td) { confetti(); SFX.coin(); }
  } else {
    toast(t('goal_mark_removed_toast'));
  }
  if (result.justCompleted) toast('🏆 ' + g.emoji + ' ' + t('goal_completed'));

  save(); renderGoalsCalendar(); showGoalsDayDetail(dateStr); renderGoals(); render();
}


function deleteGoal(id) {
  var g = (S.goals||[]).find(function(x){return x.id===id;});
  if (!g) return;
  var name = g.name || '';
  var msg = esc(t('goal_delete_confirm').replace('{name}', name));
  showConfirmModal(msg, function(){
    try{SFX.delete();}catch(e){}
    S.goals = (S.goals||[]).filter(function(x){return x.id!==id;});
    save(); renderGoals(); renderGoalsCalendar(); toast(t('goal_deleted_toast'));
  }, { icon: '🗑️' });
}

// ============================================================
// 🎯 MAQSADLAR = ODATLAR (habits): doimiy rejim, streak, pauza,
// o'tkazib yuborilgan kun uchun jarima, eslatma, 7 kunlik lenta, filtr.
// ============================================================
var gmOngoing = false;
var _goalsFilter = 'today'; // today | all | paused | done

function goalPausedOn(g, dateStr) {
  return (g.pauses || []).some(function (p) { return dateStr >= p.from && (!p.to || dateStr < p.to); });
}
function goalIsPaused(g) {
  var ps = g.pauses || [];
  return ps.length > 0 && !ps[ps.length - 1].to;
}
function goalTogglePause(id) {
  var g = (S.goals || []).find(function (x) { return x.id === id; }); if (!g) return;
  if (!g.pauses) g.pauses = [];
  var d = trackDate();
  if (goalIsPaused(g)) {
    g.pauses[g.pauses.length - 1].to = d;
    toast('▶️ ' + _cl('Odat davom ettirildi', 'Habit resumed', 'Привычка возобновлена'));
  } else {
    g.pauses.push({ from: d, to: null });
    toast('⏸ ' + _cl('Odat pauzada: jarima va talab yo\'q', 'Habit paused: no penalty or requirement', 'Привычка на паузе: без штрафов'));
  }
  save(); renderGoals(); try { renderGoalsCalendar(); } catch (e) {}
}

function goalStreak(g) {
  if (g.repeat === 'once') return { cur: 0, best: 0 };
  var end = trackDate(), d = g.startDate || end, run = 0, best = 0, guard = 0;
  while (d <= end && guard++ < 1500) {
    if (g.daysChecked && g.daysChecked[d]) { run++; if (run > best) best = run; }
    else if (isGoalDueOnDate(g, d)) { if (d !== end) run = 0; }
    d = addDays(d, 1);
  }
  return { cur: run, best: best };
}
function goalRate30(g) {
  var end = trackDate(), due = 0, done = 0;
  for (var i = 0; i < 30; i++) {
    var d = addDays(end, -i);
    if (g.startDate && d < g.startDate) break;
    var chk = !!(g.daysChecked && g.daysChecked[d]);
    if (chk) { due++; done++; }
    else if (isGoalDueOnDate(g, d) && d !== end) due++;
  }
  return due ? Math.round(done / due * 100) : 0;
}

function gmToggleOngoing() {
  gmOngoing = !gmOngoing;
  if (gmOngoing) document.getElementById('gm-duration').value = '';
  syncGoalDurChips();
}
function syncGoalDurChips() {
  var inp = document.getElementById('gm-duration');
  var val = parseInt(inp.value) || 0;
  document.querySelectorAll('#gm-duration-presets .rcost-chip').forEach(function (b) {
    if (b.id === 'gm-dur-inf') { b.className = 'rcost-chip' + (gmOngoing ? ' sel' : ''); return; }
    b.className = 'rcost-chip' + (!gmOngoing && parseInt(b.textContent) === val ? ' sel' : '');
  });
  inp.disabled = gmOngoing;
}
function setGoalDur(val) {
  gmOngoing = false;
  document.getElementById('gm-duration').value = val;
  syncGoalDurChips();
}
function gmFillHabitFields(g) {
  var L = function (id, uz, en, ru) { var el = document.getElementById(id); if (el) el.textContent = _cl(uz, en, ru); };
  L('gm-dur-inf', '♾ Doimiy', '♾ Ongoing', '♾ Постоянно');
  L('gm-penalty-label', 'Jarima (kun o\'tkazib yuborilsa)', 'Penalty (if a day is missed)', 'Штраф (за пропуск дня)');
  L('gm-remind-label', 'Eslatma vaqti (ixtiyoriy)', 'Reminder time (optional)', 'Время напоминания (необязательно)');
  var pen = document.getElementById('gm-penalty'), rem = document.getElementById('gm-remind');
  if (pen) pen.value = String(g && g.penalty ? g.penalty : 0);
  if (rem) rem.value = (g && g.remind) || '';
  if (pen) pen.placeholder = _cl('0 = jarimasiz (0–30 🪙)', '0 = no penalty (0–30 🪙)', '0 = без штрафа (0–30 🪙)');
}

// O'tkazib yuborilgan (kechagi) kun uchun jarima — checkReset() chaqiradi.
function goalsApplyMissedPenalty(ps) {
  var td = today();
  if (ps !== addDays(td, -1)) return;
  if (S.noOvernightPenalty) return;
  if (S.penaltyPausedUntil && td < S.penaltyPausedUntil) return;
  if (isDateFrozen(ps)) return;
  var total = 0, n = 0;
  (S.goals || []).forEach(function (g) {
    var pen = Number(g.penalty) || 0;
    if (pen <= 0 || g.done || g.repeat === 'once') return;
    if (g.daysChecked && g.daysChecked[ps]) return;
    if (!isGoalDueOnDate(g, ps)) return;
    if (g.endDate && ps > g.endDate) return;
    if (!g.daysPenalty) g.daysPenalty = {};
    if (g.daysPenalty[ps]) return;
    g.daysPenalty[ps] = pen; S.coins = (S.coins || 0) - pen; total += pen; n++;
  });
  if (total > 0) {
    addTarixLog('out', '😔 ' + n + ' ' + _cl('ta odat bajarilmadi', 'habits missed', 'привычек пропущено'), -total, null, ps);
    if (!S.pendingMissedMsg) S.pendingMissedMsg = '😔 ' + n + ' ' + _cl('ta odat bajarilmadi', 'habits missed', 'привычек пропущено') + ' (−' + total + ' 🪙)';
  }
}

// 7 kunlik lentadan (yoki istalgan sanadan) belgilash/bekor qilish
function goalStripToggle(id, dateStr) {
  var g = (S.goals || []).find(function (x) { return x.id === id; }); if (!g) return;
  var chk = !!(g.daysChecked && g.daysChecked[dateStr]);
  if (!chk && !isGoalDueOnDate(g, dateStr)) { toast(t('goal_not_today')); return; }
  var r = _goalToggleDateCore(g, dateStr);
  if (r.nowChecked) { try { SFX.coin(); } catch (e) {} }
  if (r.justCompleted) toast('🏆 ' + g.emoji + ' ' + t('goal_completed'));
  save(); renderGoals(); try { renderGoalsCalendar(); } catch (e) {} try { render(); } catch (e) {}
}

// Eslatmalar (sahifa ochiq bo'lganda ishlaydi)
var _goalRemTimers = [];
function scheduleGoalReminders() {
  _goalRemTimers.forEach(clearTimeout); _goalRemTimers = [];
  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
  var now = new Date(), td = today();
  (S.goals || []).forEach(function (g) {
    if (!g.remind || g.done || goalIsPaused(g) || !isGoalDueOnDate(g, td)) return;
    var hm = g.remind.split(':'), at = new Date(now.getFullYear(), now.getMonth(), now.getDate(), +hm[0] || 0, +hm[1] || 0);
    if (at <= now) return;
    _goalRemTimers.push(setTimeout(function () {
      var gg = (S.goals || []).find(function (x) { return x.id === g.id; });
      if (!gg || (gg.daysChecked && gg.daysChecked[today()])) return;
      try { new Notification((gg.emoji || '🎯') + ' ' + gg.name, { body: _cl('Odatni bajarish vaqti!', 'Time for your habit!', 'Пора выполнить привычку!') }); } catch (e) {}
    }, at - now));
  });
}
if (typeof Notification !== 'undefined' && Notification.permission === 'granted') setTimeout(scheduleGoalReminders, 3500);

function setGoalsFilter(f) { _goalsFilter = f; renderGoals(); }

function renderGoalsStats() {
  var elActive = document.getElementById('goals-stat-active');
  var elDone = document.getElementById('goals-stat-done');
  var elToday = document.getElementById('goals-stat-today');
  if (!elActive || !elDone || !elToday) return;
  var goals = S.goals || [], td = trackDate();
  var doneCount = goals.filter(function (g) { return g.done; }).length;
  var activeCount = goals.filter(function (g) { return !g.done && !goalIsPaused(g); }).length;
  var dueList = goals.filter(function (g) { return !g.done && (isGoalDueOnDate(g, td)); });
  var checked = dueList.filter(function (g) { return g.daysChecked && g.daysChecked[td]; }).length;
  elActive.textContent = activeCount;
  elDone.textContent = doneCount;
  elToday.textContent = checked + '/' + dueList.length;
}

function renderGoals() {
  var list = document.getElementById('goals-list');
  var empty = document.getElementById('goals-empty');
  var bar = document.getElementById('goals-filter-bar');
  renderGoalsStats();
  if (!list) return;
  var goals = S.goals || [];
  if (bar) {
    var F = [['today', _cl('Bugun', 'Today', 'Сегодня')], ['all', '🗂 ' + _cl('Hammasi (kelajak ham)', 'All (incl. future)', 'Все (и будущие)')],
             ['paused', '⏸ ' + _cl('Pauza', 'Paused', 'Пауза')], ['done', '🏆 ' + _cl('Tugagan', 'Completed', 'Завершены')]];
    bar.innerHTML = goals.length ? F.map(function (f) {
      var on = _goalsFilter === f[0];
      return '<button onclick="setGoalsFilter(\'' + f[0] + '\')" style="padding:6px 12px;border-radius:var(--radius-full);border:1px solid ' + (on ? 'var(--accent)' : 'var(--border)') + ';background:' + (on ? 'var(--accent)' : 'transparent') + ';color:' + (on ? '#fff' : 'var(--text-muted)') + ';font-size:var(--fs-xs);cursor:pointer">' + f[1] + '</button>';
    }).join('') : '';
  }
  if (goals.length === 0) { list.innerHTML = ''; if (empty) empty.style.display = ''; return; }
  if (empty) empty.style.display = 'none';

  var td = today(), tk = trackDate();
  var info = goals.map(function (g) {
    var days = g.daysChecked ? Object.keys(g.daysChecked).length : 0;
    var ongoing = !g.duration && g.repeat !== 'once';
    var total = g.duration || 1;
    var completed = !ongoing && (!!g.done || days >= total);
    var paused = goalIsPaused(g);
    var expired = !!(g.endDate && g.endDate < td && !completed);
    var due = isGoalDueOnDate(g, tk);
    var checked = !!(g.daysChecked && g.daysChecked[tk]);
    var future = !!(g.startDate && g.startDate > tk);
    var rank = completed ? 5 : paused ? 4 : expired ? 3 : future ? 2.5 : (due && !checked) ? 0 : checked ? 1 : 2;
    return { future: future, g: g, days: days, ongoing: ongoing, total: total, completed: completed, paused: paused, expired: expired, due: due, checked: checked, rank: rank };
  });
  var shown = info.filter(function (x) {
    if (_goalsFilter === 'today') return x.due && !x.completed && !x.paused;
    if (_goalsFilter === 'paused') return x.paused;
    if (_goalsFilter === 'done') return x.completed;
    return true;
  }).sort(function (a, b) { return a.rank - b.rank; });

  list.innerHTML = '';
  if (!shown.length) {
    list.innerHTML = '<div style="text-align:center;padding:28px;color:var(--text-dim);font-size:var(--fs-sm);line-height:1.6">' + (_goalsFilter === 'today'
      ? _cl('Bugun uchun odat yo\'q 🎉<br>Boshqa kunlardagi va kelajakdagi odatlarni ko\'rish uchun «Hammasi» ni bosing', 'No habits for today 🎉<br>Tap “All” to see other days and future habits', 'На сегодня привычек нет 🎉<br>Нажмите «Все», чтобы увидеть остальные и будущие')
      : _cl('Bu bo\'limda hech narsa yo\'q', 'Nothing here', 'Здесь пусто')) + '</div>';
    return;
  }
  var dayNames = getShortDaysArr();
  shown.forEach(function (x) {
    var g = x.g, rl = repeatLabel(g), st = goalStreak(g);
    var pct = x.ongoing ? goalRate30(g) : Math.min(100, Math.round(x.days / x.total * 100));
    var coinAward = (typeof g.coins === 'number') ? g.coins : 1;
    var coinLabel = coinAward === 0 ? '🆓 +0 🪙' : (coinAward >= 10 ? '🏆 ' : coinAward >= 3 ? '🥇 ' : coinAward === 2 ? '🥈 ' : '🥉 ') + '+' + coinAward + ' 🪙';
    var coinColor = coinAward >= 3 ? '#F5A623' : coinAward === 2 ? '#60A5FA' : '#a3a3a3';
    var daysLeft = g.endDate ? Math.max(0, Math.ceil((new Date(g.endDate) - new Date(td)) / 86400000)) : 0;
    var statusText = x.future ? '📅 ' + _cl('Boshlanadi', 'Starts', 'Начало') + ': ' + g.startDate : x.completed ? t('goal_completed') : x.paused ? '⏸ ' + _cl('Pauzada', 'Paused', 'На паузе') : x.expired ? t('goal_expired')
      : x.ongoing ? '♾ ' + _cl('30 kun', '30 days', '30 дней') + ': ' + pct + '%' : (g.endDate ? (daysLeft + ' ' + t('goal_days_left')) : rl.text);
    var statusColor = x.completed ? '#34D399' : x.expired ? '#F87171' : 'var(--text-muted)';
    var btn = 'background:none;border:1px solid var(--border);border-radius:var(--radius-sm);padding:5px 8px;font-size:var(--fs-2xs);color:var(--text-muted);cursor:pointer';

    // 7 kunlik lenta
    var strip = '';
    for (var i = 6; i >= 0; i--) {
      var d = addDays(tk, -i);
      if (g.startDate && d < g.startDate) { strip += '<div style="flex:1"></div>'; continue; }
      var chk = !!(g.daysChecked && g.daysChecked[d]);
      var dueD = isGoalDueOnDate(g, d);
      var dow = new Date(d + 'T00:00:00').getDay();
      var lab = dayNames[dow] || '';
      var circ = chk ? 'background:#34D399;border:2px solid #34D399;color:#fff' :
        (dueD && d !== tk) ? 'background:transparent;border:2px solid rgba(248,113,113,0.7);color:#F87171' :
        dueD ? 'background:transparent;border:2px solid var(--accent);color:var(--accent)' :
        'background:var(--surface2);border:2px solid transparent;color:var(--text-dim)';
      var mark = chk ? '✓' : (dueD && d !== tk) ? '✕' : dueD ? '·' : '–';
      strip += '<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:2px">' +
        '<div style="font-size:9px;color:var(--text-dim)">' + esc(String(lab).slice(0, 2)) + '</div>' +
        '<button ' + ((chk || dueD) ? 'onclick="goalStripToggle(' + g.id + ',\'' + d + '\')"' : 'disabled') + ' style="width:24px;height:24px;border-radius:50%;font-size:11px;line-height:1;padding:0;cursor:' + ((chk || dueD) ? 'pointer' : 'default') + ';' + circ + '">' + mark + '</button></div>';
    }

    var card = document.createElement('div');
    card.style.cssText = 'background:var(--surface);border:1px solid ' + (x.completed ? 'rgba(52,211,153,0.4)' : x.expired ? 'rgba(248,113,113,0.3)' : 'var(--border)') + ';border-radius:var(--radius-lg);padding:16px;' + (x.paused ? 'opacity:.7;' : '');
    card.innerHTML =
      '<div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:10px;gap:8px">' +
        '<div style="display:flex;align-items:center;gap:8px;min-width:0">' +
          '<span style="font-size:var(--fs-xl)">' + (g.emoji || '🎯') + '</span>' +
          '<div style="min-width:0"><div style="font-size:var(--fs-base);font-weight:600;color:var(--text);word-break:break-word">' + esc(g.name) + '</div>' +
          (g.desc ? '<div style="font-size:var(--fs-xs);color:var(--text-muted);margin-top:1px">' + esc(g.desc) + '</div>' : '') + '</div>' +
        '</div>' +
        '<div style="display:flex;align-items:center;gap:4px;flex-shrink:0">' +
          '<button onclick="openGoalCalendar(' + g.id + ')" title="' + esc(t('goal_cal_subtitle')) + '" style="' + btn + '">📅</button>' +
          '<button onclick="goalTogglePause(' + g.id + ')" title="' + esc(_cl('Pauza', 'Pause', 'Пауза')) + '" style="' + btn + '">' + (x.paused ? '▶️' : '⏸') + '</button>' +
          '<button onclick="openGoalModal(' + g.id + ')" style="' + btn + '">✏️</button>' +
          '<button onclick="deleteGoal(' + g.id + ')" style="' + btn + '">🗑</button>' +
        '</div>' +
      '</div>' +
      '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">' +
        '<span style="font-size:var(--fs-2xs);font-weight:600;color:' + coinColor + ';background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.1);border-radius:var(--radius-full);padding:3px 8px">' + coinLabel + '</span>' +
        (g.endDate ? '' : '<span class="' + rl.cls + '" style="font-size:var(--fs-2xs)">' + esc(rl.text) + '</span>') +
        (st.best > 0 ? '<span style="font-size:var(--fs-2xs);font-weight:600;color:#F5A623;background:rgba(245,166,35,0.1);border:1px solid rgba(245,166,35,0.3);border-radius:var(--radius-full);padding:3px 8px">🔥 ' + st.cur + ' <span style="opacity:.7">(' + _cl('rekord', 'best', 'рекорд') + ' ' + st.best + ')</span></span>' : '') +
        ((Number(g.penalty) || 0) > 0 ? '<span style="font-size:var(--fs-2xs);color:#F87171;border:1px solid rgba(248,113,113,0.3);border-radius:var(--radius-full);padding:3px 8px">⚠️ −' + g.penalty + ' 🪙</span>' : '') +
        (g.remind ? '<span style="font-size:var(--fs-2xs);color:var(--text-muted);border:1px solid var(--border);border-radius:var(--radius-full);padding:3px 8px">⏰ ' + esc(g.remind) + '</span>' : '') +
      '</div>' +
      '<div style="display:flex;gap:2px;margin-bottom:10px">' + strip + '</div>' +
      '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">' +
        '<span style="font-size:var(--fs-xs);color:var(--text-muted)">' + (x.ongoing ? x.days + ' ' + t('goal_days_unit') : x.days + '/' + x.total + ' ' + t('goal_days_unit')) + '</span>' +
        '<span style="font-size:var(--fs-xs);color:' + statusColor + '">' + statusText + '</span>' +
      '</div>' +
      '<div style="height:6px;background:var(--surface2);border-radius:var(--radius-full);overflow:hidden;margin-bottom:12px">' +
        '<div style="height:100%;width:' + pct + '%;background:linear-gradient(90deg,var(--accent),#B48EFF);border-radius:var(--radius-full);transition:width 0.5s ease"></div>' +
      '</div>' +
      (!x.completed && !x.expired && !x.paused ?
        (x.due ?
          '<button onclick="goalCheckToday(' + g.id + ')" style="width:100%;padding:10px;border-radius:var(--radius-sm);border:' + (x.checked ? '2px solid #34D399' : '1px solid var(--border)') + ';background:' + (x.checked ? 'rgba(52,211,153,0.12)' : 'var(--surface2)') + ';color:' + (x.checked ? '#34D399' : 'var(--text)') + ';font-size:var(--fs-sm);font-weight:600;cursor:pointer;font-family:\'DM Sans\',sans-serif">' +
            (x.checked ? t(isYesterdayMode() ? 'goal_check_done' : 'goal_check_done_today') : t(isYesterdayMode() ? 'goal_check_todo' : 'goal_check_todo_today')) +
          '</button>'
        :
          '<div style="width:100%;padding:10px;border-radius:var(--radius-sm);border:1px dashed var(--border);color:var(--text-muted);font-size:var(--fs-sm);font-weight:600;text-align:center">' + t('goal_not_today') + '</div>'
        ) : '');
    list.appendChild(card);
  });
}

function checkNotifBar() {
  var bar = document.getElementById('notif-request-bar');
  if(!bar) return;
  if(typeof Notification === 'undefined') { bar.style.display='none'; return; }
  if(Notification.permission === 'default') {
    bar.style.display = 'flex';
  } else {
    bar.style.display = 'none';
  }
}

function requestNotifPermission() {
  if(typeof Notification === 'undefined') { toast(t('notif_not_supported_toast')); return; }
  Notification.requestPermission().then(function(perm) {
    checkNotifBar();
    if(perm === 'granted') {
      toast(t('notif_enabled_toast'));
      scheduleNotifications();
    }
  });
}

function scheduleNotifications() {
  // Service Worker yo'q, shuning uchun faqat sahifa ochiq bo'lganda ishlaydi
  // Har kuni ertalab 9:00 da va kechqurun spin uchun eslatma
  if(typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
  var now = new Date();
  // Spin eslatmasi (agar bugun ishlatilmagan bo'lsa)
  if(!hasSpunToday()) {
    var spinTime = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 10, 0, 0);
    if(spinTime > now) {
      var delay = spinTime - now;
      setTimeout(function(){
        if(!hasSpunToday()) {
          try { new Notification('🎰 Spin vaqti!', { body: 'Bugungi tekin spiningizni unutmang!', icon: '🎰' }); } catch(e){}
        }
      }, delay);
    }
  }
  // Vazifa eslatmasi soat 8:00
  var taskTime = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 8, 0, 0);
  if(taskTime > now) {
    setTimeout(function(){
      var todayTasks = (S.tasks||[]).filter(function(t){ return taskDueToday(t) && !t.done; });
      if(todayTasks.length > 0) {
        try { new Notification('📋 Vazifalaringiz kutmoqda!', { body: todayTasks.length + ' ta vazifa bajarilmagan', icon: '📋' }); } catch(e){}
      }
    }, taskTime - now);
  }
}

// Sahifa ochilganda eslatmalarni rejalashtirish
if(typeof Notification !== 'undefined' && Notification.permission === 'granted') {
  setTimeout(scheduleNotifications, 3000);
}

function ensureStatsTooltip() {
  var tip = document.getElementById('stats-hover-tooltip');
  if (!tip) {
    tip = document.createElement('div');
    tip.id = 'stats-hover-tooltip';
    tip.style.cssText = 'position:fixed;z-index:9999;pointer-events:none;background:#1C1C25;border:1px solid var(--border);border-radius:var(--radius-sm);padding:7px 11px;font-size:var(--fs-2xs);line-height:1.5;color:var(--text);white-space:nowrap;display:none;box-shadow:0 6px 18px rgba(0,0,0,0.4)';
    document.body.appendChild(tip);
  }
  return tip;
}
function showStatsTooltip(clientX, clientY, html) {
  var tip = ensureStatsTooltip();
  tip.innerHTML = html;
  tip.style.display = 'block';
  var pad = 14;
  var left = clientX + pad, top = clientY + pad;
  // Avval taxminiy joylashtiramiz, keyin ekrandan chiqib ketmasligi uchun tuzatamiz
  tip.style.left = left + 'px';
  tip.style.top = top + 'px';
  var r = tip.getBoundingClientRect();
  if (r.right > window.innerWidth)  left = clientX - r.width - pad;
  if (r.bottom > window.innerHeight) top = clientY - r.height - pad;
  tip.style.left = Math.max(4, left) + 'px';
  tip.style.top  = Math.max(4, top)  + 'px';
}
function hideStatsTooltip() {
  var tip = document.getElementById('stats-hover-tooltip');
  if (tip) tip.style.display = 'none';
}

var _statsChartRangeTasks = 'week'; // 'week' | '30d' | 'all' — faqat "Bajarilgan vazifalar" grafigi uchun
var _statsChartRangeCoins = 'week'; // 'week' | '30d' | 'all' — faqat "Tanga tarixi" grafigi uchun

function setStatsChartRange(range, chart) {
  chart = chart || 'tasks';
  if (chart === 'coins') { _statsChartRangeCoins = range; } else { _statsChartRangeTasks = range; }
  document.querySelectorAll('.stats-chart-range-btn[data-chart="' + chart + '"]').forEach(function(btn) {
    btn.classList.toggle('sel', btn.dataset.range === range);
  });
  renderStats();
}

// "Barchasi" davri qayerdan boshlanishini aniqlash uchun — mavjud
// ma'lumotlardagi eng qadimgi sanani topadi (tarix va taskDoneLog ichidan).
function getStatsEarliestDate() {
  var dates = [];
  (S.tarix || []).forEach(function(item) { if (item.date) dates.push(item.date); });
  var doneLog = S.taskDoneLog || {};
  Object.keys(doneLog).forEach(function(id) {
    (doneLog[id] || []).forEach(function(d) { if (d) dates.push(d); });
  });
  if (!dates.length) return today();
  dates.sort();
  return dates[0];
}

function buildStatsChartBuckets(range) {
  var todayD = new Date(); todayD.setHours(0, 0, 0, 0);
  var startStr, totalDays, bucketSize;

  if (range === '30d') {
    var d30 = new Date(todayD.getFullYear(), todayD.getMonth(), todayD.getDate() - 29);
    startStr = localDateStr(d30);
    totalDays = 30;
    bucketSize = 1;
  } else if (range === 'all') {
    startStr = getStatsEarliestDate();
    var startD0 = new Date(startStr + 'T00:00:00');
    totalDays = Math.round((todayD - startD0) / 86400000) + 1;
    if (totalDays < 7) {
      var d7 = new Date(todayD.getFullYear(), todayD.getMonth(), todayD.getDate() - 6);
      startStr = localDateStr(d7);
      totalDays = 7;
    }
    bucketSize = totalDays <= 30 ? 1 : Math.ceil(totalDays / 30);
  } else { // 'week' — joriy hafta, Dushanbadan boshlanadi
    var dow = todayD.getDay();
    var daysSinceMonday = (dow === 0) ? 6 : dow - 1;
    var monday = new Date(todayD.getFullYear(), todayD.getMonth(), todayD.getDate() - daysSinceMonday);
    startStr = localDateStr(monday);
    totalDays = 7;
    bucketSize = 1;
  }

  var startD = new Date(startStr + 'T00:00:00');
  var bucketCount = Math.ceil(totalDays / bucketSize);
  var buckets = [];
  for (var b = 0; b < bucketCount; b++) {
    var bStartOffset = b * bucketSize;
    var bEndOffset = Math.min(bStartOffset + bucketSize - 1, totalDays - 1);
    var bStartD = new Date(startD.getFullYear(), startD.getMonth(), startD.getDate() + bStartOffset);
    var bEndD   = new Date(startD.getFullYear(), startD.getMonth(), startD.getDate() + bEndOffset);
    buckets.push({ start: localDateStr(bStartD), end: localDateStr(bEndD), taskCount: 0, coinNet: 0 });
  }
  return buckets;
}

function statsFindBucketIndex(buckets, dateStr) {
  for (var i = 0; i < buckets.length; i++) {
    if (dateStr >= buckets[i].start && dateStr <= buckets[i].end) return i;
  }
  return -1;
}

function _csvEscape(val) {
  var s = String(val === undefined || val === null ? '' : val);
  if (/[",\n]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
}
function _diffLabelPlain(d) {
  if (d === 3) return tr('diff_hard_title');
  if (d === 2) return tr('diff_medium_title');
  if (d === 0) return tr('diff_free_title');
  return tr('diff_easy_title');
}
function exportStatsCSV() {
  var rows = [];
  rows.push(['Bo\'lim', 'Ko\'rsatkich', 'Qiymat']);
  rows.push(['Umumiy', 'Jami bajarilgan vazifalar', S.totalTasksDone || 0]);
  rows.push(['Umumiy', 'Jami topilgan tanga (lifetime)', S.totalCoins || 0]);
  rows.push(['Umumiy', 'Joriy tanga balansi', S.coins || 0]);
  rows.push(['Umumiy', 'Rekord streak', S.bestStreak || S.streak || 0]);
  rows.push(['Umumiy', 'Hozirgi streak', S.streak || 0]);
  rows.push(['Umumiy', 'Jami XP', S.xp || 0]);
  rows.push(['Umumiy', 'Eksport sanasi', today()]);
  rows.push([]);
  rows.push(['Vazifa nomi', 'Qiyinlik', 'Takrorlanish', 'Necha marta bajarilgan (lifetime)', 'Muhim (pin)', 'Holati']);

  var existingIds = {};
  (S.tasks || []).forEach(function(tk){
    existingIds[tk.id] = true;
    var lifetime = (S.taskLifetimeStats && S.taskLifetimeStats[tk.id])
      ? S.taskLifetimeStats[tk.id].count
      : ((S.taskDoneCount && S.taskDoneCount[tk.id]) || 0);
    rows.push([
      tk.name,
      _diffLabelPlain(taskDiffOrDefault(tk)),
      tk.repeat,
      lifetime,
      tk.pinned ? 'Ha' : "Yo'q",
      tk.done ? 'Bajarilgan' : (tk.skipped ? "O'tkazib yuborilgan" : 'Faol')
    ]);
  });

  if (S.taskLifetimeStats) {
    Object.keys(S.taskLifetimeStats).forEach(function(id){
      if (existingIds[id]) return;
      var rec = S.taskLifetimeStats[id];
      rows.push([rec.name, _diffLabelPlain(rec.diff), '-', rec.count, '-', "O'chirilgan"]);
    });
  }

  var csv = rows.map(function(r){ return r.map(_csvEscape).join(','); }).join('\r\n');
  var blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = 'vazifalar_statistikasi_' + today() + '.csv';
  document.body.appendChild(a);
  a.click();
  setTimeout(function(){ document.body.removeChild(a); URL.revokeObjectURL(url); }, 200);
  toast(t('stats_export_toast'));
}

function renderStats() {
  // Haftalik hisoblar — joriy hafta Dushanbadan boshlanadi
  var now = new Date();
  var weekDays = [];
  // JavaScript: 0=Yakshanba, 1=Du, ..., 6=Shanba
  // Haftaning Dushanbasi: bugundan (dow-1) kun orqaga
  var dow = now.getDay(); // 0=Ya, 1=Du, ..., 6=Sh
  var daysSinceMonday = (dow === 0) ? 6 : dow - 1; // Yakshanba bo'lsa 6 kun orqaga
  var monday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - daysSinceMonday);
  for(var i=0; i<7; i++) {
    var d = new Date(monday.getFullYear(), monday.getMonth(), monday.getDate() + i);
    weekDays.push(d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0'));
  }

  // Tarix bo'yicha kun qidirish
  var tarix = S.tarix || [];

  // Kunlik bajarilgan vazifalar soni — taskDoneLog dan (ishonchli)
  var dayTaskCounts = {};
  var dayCoinCounts = {};
  weekDays.forEach(function(d){ dayTaskCounts[d]=0; dayCoinCounts[d]=0; });

  // taskDoneLog: {taskId: [date1, date2, ...]} — har kuni qancha bajardik
  var doneLog = S.taskDoneLog || {};
  Object.keys(doneLog).forEach(function(taskId) {
    var dates = doneLog[taskId] || [];
    dates.forEach(function(dateStr) {
      if(weekDays.indexOf(dateStr) === -1) return;
      dayTaskCounts[dateStr] = (dayTaskCounts[dateStr]||0) + 1;
    });
  });

  // Tanga tarixi esa tarixdan olinadi
  tarix.forEach(function(item) {
    if(weekDays.indexOf(item.date) === -1) return;
    if(item.amount > 0) {
      dayCoinCounts[item.date] = (dayCoinCounts[item.date]||0) + item.amount;
    }
  });

  var weekDone = weekDays.reduce(function(s,d){ return s+(dayTaskCounts[d]||0); }, 0);
  var weekCoins = weekDays.reduce(function(s,d){ return s+(dayCoinCounts[d]||0); }, 0);

  var wdEl = document.getElementById('stats-week-done');
  var wcEl = document.getElementById('stats-week-coins');
  if(wdEl) wdEl.textContent = weekDone;
  if(wcEl) wcEl.textContent = weekCoins + ' 🪙';

  // Bar chart — endi tanlangan davrga (_statsChartRange: hafta/30 kun/
  // barchasi) qarab quriladi, doim joriy haftaning 7 kuni bilan cheklanmaydi.
  var barChart   = document.getElementById('stats-bar-chart');
  var barLabels  = document.getElementById('stats-bar-labels');
  if(barChart && barLabels) {
    var chartBucketsTasks = buildStatsChartBuckets(_statsChartRangeTasks);
    // Bucketlarni to'ldirish — taskDoneLog (bajarilgan sanalar) va tarix
    // (musbat tanga yozuvlari) chart oralig'idagi barcha kunlar bo'yicha.
    Object.keys(doneLog).forEach(function(taskId) {
      (doneLog[taskId] || []).forEach(function(dateStr) {
        var idx = statsFindBucketIndex(chartBucketsTasks, dateStr);
        if (idx !== -1) chartBucketsTasks[idx].taskCount++;
      });
    });
    tarix.forEach(function(item) {
      if (item.amount > 0) {
        var idx2 = statsFindBucketIndex(chartBucketsTasks, item.date);
        if (idx2 !== -1) chartBucketsTasks[idx2].coinNet += item.amount;
      }
    });

    var maxVal = Math.max.apply(null, chartBucketsTasks.map(function(bk){ return bk.taskCount; }).concat([0]));
    if(maxVal === 0) maxVal = 1;
    barChart.innerHTML = '';
    barLabels.innerHTML = '';
    var dayNames = getShortDaysArr();
    var isSingleDayBucket = chartBucketsTasks.length && chartBucketsTasks[0].start === chartBucketsTasks[0].end;
    var labelStep = Math.max(1, Math.ceil(chartBucketsTasks.length / 6));
    chartBucketsTasks.forEach(function(bk, bi) {
      var val = bk.taskCount;
      var pct = Math.round(val / maxVal * 100);
      var isToday = bk.start === today() && bk.end === today();
      // Container 80px, label 18px => bar area = 62px
      var BAR_AREA = 62;
      var barPx = val === 0 ? 2 : Math.max(4, Math.round(pct / 100 * BAR_AREA));
      var barColor = isToday ? 'var(--accent)' : 'rgba(124,92,252,0.75)';
      var numColor = (val === 0 || !isSingleDayBucket) ? 'transparent' : 'var(--text-muted)';
      var bar = document.createElement('div');
      bar.style.cssText = 'flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:3px;height:80px;';
      bar.innerHTML =
        '<div style="font-size:var(--fs-3xs);color:'+numColor+';height:14px;line-height:14px">' + ((isSingleDayBucket && val)||'') + '</div>' +
        '<div style="width:100%;height:'+barPx+'px;background:'+barColor+';border-radius:var(--radius-2xs) 4px 0 0;transition:height 0.5s ease"></div>';
      barChart.appendChild(bar);

      // Sichqonchani ustiga olib borganda — o'sha aniq kun(lar)da nechta
      // vazifa bajarilgani va qancha tanga topilganini ko'rsatadi.
      (function(bkCap, valCap) {
        bar.style.cursor = 'pointer';
        bar.addEventListener('mousemove', function(e) {
          var label;
          if (bkCap.start === bkCap.end) {
            var dObj2 = new Date(bkCap.start + 'T00:00:00');
            label = getDaysArr()[dObj2.getDay()] + ', ' + bkCap.start.slice(5);
          } else {
            label = bkCap.start.slice(5) + '–' + bkCap.end.slice(5);
          }
          var html =
            '<div style="font-weight:700;margin-bottom:3px">' + label + '</div>' +
            '<div>✅ ' + valCap + '</div>' +
            '<div style="color:#F5A623">🪙 +' + bkCap.coinNet + '</div>';
          showStatsTooltip(e.clientX, e.clientY, html);
        });
        bar.addEventListener('mouseleave', hideStatsTooltip);
      })(bk, val);

      var lbl = document.createElement('div');
      lbl.style.cssText = 'flex:1;text-align:center;font-size:var(--fs-3xs);color:' + (isToday?'var(--accent)':'var(--text-dim)') + ';font-weight:' + (isToday?'700':'400');
      if (isSingleDayBucket) {
        if (chartBucketsTasks.length <= 7) {
          var dObj = new Date(bk.start + 'T00:00:00');
          lbl.textContent = dayNames[dObj.getDay()];
        } else {
          lbl.textContent = (bi % labelStep === 0) ? bk.start.slice(5) : '';
        }
      } else {
        lbl.textContent = (bi % labelStep === 0) ? bk.start.slice(5) : '';
      }
      barLabels.appendChild(lbl);
    });
  }

  // Coin line chart via canvas — bar chart bilan bir xil davr/bucket
  // holatidan (_statsChartRange) foydalanadi.
  var canvas = document.getElementById('stats-coins-chart');
  if(canvas) {
    var H = 80;
    var W = canvas.offsetWidth || 300;
    var dpr = window.devicePixelRatio || 1;
    canvas.width = W * dpr; canvas.height = H * dpr;
    canvas.style.height = H + 'px';
    var ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0,0,W,H);

    var chartBucketsCoins = buildStatsChartBuckets(_statsChartRangeCoins);
    tarix.forEach(function(item) {
      if (item.amount > 0) {
        var idxC = statsFindBucketIndex(chartBucketsCoins, item.date);
        if (idxC !== -1) chartBucketsCoins[idxC].coinNet += item.amount;
      }
    });
    var coinVals = chartBucketsCoins.map(function(bk){ return bk.coinNet; });
    var maxC = Math.max.apply(null, coinVals); if(maxC<1) maxC=1;
    var pad = 10;
    var segW = (W - pad*2) / Math.max(1, coinVals.length - 1);

    // Grid line
    ctx.strokeStyle='rgba(255,255,255,0.05)'; ctx.lineWidth=1;
    for(var i=0;i<4;i++){ var y=pad+i*(80-pad*2)/3; ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(W-pad,y);ctx.stroke(); }

    // Gradient fill
    var grad = ctx.createLinearGradient(0,0,0,80);
    grad.addColorStop(0,'rgba(124,92,252,0.35)');
    grad.addColorStop(1,'rgba(124,92,252,0)');
    ctx.beginPath();
    coinVals.forEach(function(v,i){
      var x=pad+i*segW, y=pad+(1-v/maxC)*(80-pad*2);
      if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    });
    ctx.lineTo(pad+(coinVals.length-1)*segW, 80-pad);
    ctx.lineTo(pad, 80-pad);
    ctx.closePath();
    ctx.fillStyle=grad; ctx.fill();

    // Line
    ctx.beginPath();
    ctx.strokeStyle='#7C5CFC'; ctx.lineWidth=2;
    coinVals.forEach(function(v,i){
      var x=pad+i*segW, y=pad+(1-v/maxC)*(80-pad*2);
      if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    });
    ctx.stroke();

    // Dots — 30 kun/Barchasi rejimida nuqtalar juda zich bo'lib
    // ketmasligi uchun faqat yetarlicha keng oraliqda chizamiz.
    var dotStep = coinVals.length > 30 ? Math.ceil(coinVals.length / 30) : 1;
    coinVals.forEach(function(v,i){
      if (i % dotStep !== 0 && i !== coinVals.length - 1) return;
      var x=pad+i*segW, y=pad+(1-v/maxC)*(80-pad*2);
      ctx.beginPath(); ctx.arc(x,y,3,0,2*Math.PI);
      ctx.fillStyle=i===coinVals.length-1?'#F5A623':'#B48EFF';
      ctx.fill();
    });

    // Labels
    var coinLabels = document.getElementById('stats-coins-labels');
    if(coinLabels) {
      var dayNamesShort = getShortDaysArr();
      coinLabels.innerHTML = '';
      var isSingleDayBucketC = chartBucketsCoins.length && chartBucketsCoins[0].start === chartBucketsCoins[0].end;
      var labelStepC = Math.max(1, Math.ceil(chartBucketsCoins.length / 6));
      chartBucketsCoins.forEach(function(bk, i) {
        var isToday = bk.start === today() && bk.end === today();
        var lbl = document.createElement('div');
        lbl.style.cssText = 'font-size:var(--fs-3xs);text-align:center;color:' + (isToday ? 'var(--accent)' : 'var(--text-dim)') + ';font-weight:' + (isToday ? '700' : '400') + ';flex:1;';
        if (isSingleDayBucketC && chartBucketsCoins.length <= 7) {
          var dObj = new Date(bk.start + 'T00:00:00');
          lbl.textContent = dayNamesShort[dObj.getDay()];
        } else {
          lbl.textContent = (i % labelStepC === 0) ? bk.start.slice(5) : '';
        }
        coinLabels.appendChild(lbl);
      });
    }

    // Sichqonchani grafik ustida olib borganda — eng yaqin kun/davrni
    // topib, o'sha davrda qancha tanga topilganini ko'rsatadi.
    canvas.style.cursor = 'pointer';
    canvas.onmousemove = function(e) {
      var rect = canvas.getBoundingClientRect();
      var mx = e.clientX - rect.left;
      var idx = coinVals.length > 1 ? Math.round((mx - pad) / segW) : 0;
      idx = Math.max(0, Math.min(coinVals.length - 1, idx));
      var bkHover = chartBucketsCoins[idx];
      var label;
      if (bkHover.start === bkHover.end) {
        var dObjHover = new Date(bkHover.start + 'T00:00:00');
        label = getDaysArr()[dObjHover.getDay()] + ', ' + bkHover.start.slice(5);
      } else {
        label = bkHover.start.slice(5) + '–' + bkHover.end.slice(5);
      }
      var v = coinVals[idx];
      var html =
        '<div style="font-weight:700;margin-bottom:3px">' + label + '</div>' +
        '<div style="color:#F5A623">🪙 +' + v + '</div>';
      showStatsTooltip(e.clientX, e.clientY, html);
    };
    canvas.onmouseleave = function() { hideStatsTooltip(); };
  }

  // Kengaytirilgan Balans trendi (7 kun/Oy/Chorak) — Coin History moduli bilan bir xil hisoblagichdan
  renderTarixChart();

  // Jami statistika
  var el;
  el=document.getElementById('stats-total-tasks'); if(el) el.textContent=S.totalTasksDone||0;
  // S.totalCoins — barcha vaqt uchun to'g'ri counter (tarix cheklangan bo'lishi mumkin)
  el=document.getElementById('stats-total-coins'); if(el) el.textContent=(S.totalCoins||0)+' 🪙';
  el=document.getElementById('stats-best-streak'); if(el) el.textContent=(S.bestStreak||S.streak||0)+' 🔥';
  el=document.getElementById('stats-cur-streak');  if(el) el.textContent=(S.streak||0)+' 🔥';

  // ── Eng ko'p bajariladigan vazifa ──────────────────────────
  (function() {
    var lifetime = S.taskLifetimeStats || {};
    var topTask = null, topCount = 0;
    Object.keys(lifetime).forEach(function(id) {
      var rec = lifetime[id];
      if (rec && rec.count > topCount) { topCount = rec.count; topTask = rec; }
    });

    var iconEl   = document.getElementById('stat-top-task-icon');
    var nameEl   = document.getElementById('stat-top-task-name');
    var countEl  = document.getElementById('stat-top-task-count');
    if (!iconEl || !nameEl || !countEl) return;

    if (topTask && topCount > 0) {
      var diffIcons = ['🟢','🟡','🔴'];
      iconEl.textContent  = diffIcons[(topTask.diff||1)-1];
      nameEl.textContent  = topTask.name;
      countEl.textContent = topCount + t('stat_times_done');
    } else {
      iconEl.textContent  = '📝';
      nameEl.textContent  = t('stat_no_data');
      countEl.textContent = t('stat_do_tasks');
    }
  })();

  // ── Eng samarali soat ──────────────────────────────────────
  (function() {
    var hourLog = S.taskDoneHourLog || {};
    var hours = Object.keys(hourLog).map(Number);

    var iconEl   = document.getElementById('stat-best-hour-icon');
    var valEl    = document.getElementById('stat-best-hour-val');
    var labelEl  = document.getElementById('stat-best-hour-label');
    var detailEl = document.getElementById('stat-best-hour-detail');
    var barsEl   = document.getElementById('stat-hour-bars');
    if (!iconEl || !valEl || !labelEl || !detailEl) return;

    if (hours.length === 0) {
      iconEl.textContent  = '⏳';
      valEl.textContent   = '—';
      labelEl.textContent = t('stat_no_data');
      detailEl.textContent = t('stat_do_tasks');
      if (barsEl) barsEl.innerHTML = '';
      return;
    }

    // Eng ko'p bajariladigan soat
    var bestHour = hours.reduce(function(a, b) {
      return (hourLog[a]||0) >= (hourLog[b]||0) ? a : b;
    });
    var bestCount = hourLog[bestHour] || 0;

    // Soat belgisi
    var hourEmoji;
    if (bestHour >= 5 && bestHour < 9)       hourEmoji = '🌅';
    else if (bestHour >= 9 && bestHour < 12)  hourEmoji = '☀️';
    else if (bestHour >= 12 && bestHour < 14) hourEmoji = '🌞';
    else if (bestHour >= 14 && bestHour < 18) hourEmoji = '🌤️';
    else if (bestHour >= 18 && bestHour < 21) hourEmoji = '🌆';
    else                                       hourEmoji = '🌙';

    var ampm = bestHour < 12 ? 'AM' : 'PM';
    var h12  = bestHour % 12 || 12;

    iconEl.textContent  = hourEmoji;
    valEl.textContent   = h12 + ':00 ' + ampm;
    labelEl.textContent = bestCount + ' ' + t('stat_tasks_completed');
    detailEl.textContent = t('stat_most_productive_hour_detail');

    // Mini bar chart (24 soat ichida eng faol 8 soatni ko'rsat)
    if (barsEl) {
      barsEl.innerHTML = '';
      var maxC = Math.max.apply(null, hours.map(function(h){ return hourLog[h]||0; }));
      if (maxC < 1) maxC = 1;
      // 0-23 soat, lekin faqat ma'lumot borlarinigina ko'rsat (max 12)
      var sortedHours = hours.slice().sort(function(a,b){ return (hourLog[b]||0)-(hourLog[a]||0); }).slice(0,12).sort(function(a,b){return a-b;});
      sortedHours.forEach(function(h) {
        var cnt = hourLog[h] || 0;
        var pct = Math.round(cnt / maxC * 100);
        var barH = Math.max(4, Math.round(pct / 100 * 24));
        var isBest = h === bestHour;
        var bar = document.createElement('div');
        bar.title = h + ':00 — ' + cnt + ' ' + t('stat_unit_tasks');
        bar.style.cssText = 'flex:1;max-width:14px;height:' + barH + 'px;border-radius:var(--radius-2xs) 3px 0 0;' +
          'background:' + (isBest ? 'var(--accent)' : 'rgba(124,92,252,0.35)') + ';' +
          'min-height:3px;transition:height 0.4s ease;cursor:default;';
        barsEl.appendChild(bar);
      });
    }
  })();

  renderExamTrendChart();
  renderExamForecastCard();
  if (typeof pomoStatsRender === 'function') pomoStatsRender();
}

function _examTrendBuildSeries(forExamType) {
  var examType = forExamType || getExamType();
  if (examType === 'ielts') {
    var results = S.ieltsResults || [];
    if (results.length === 0) return { points: [], unit: '', max: 9 };
    var dates = Array.from(new Set(results.map(function(r){ return r.date; }))).sort();
    var points = [];
    dates.forEach(function(d) {
      var cum = results.filter(function(r){ return r.date <= d; });
      var secs = ['listening','reading','writing','speaking'];
      var vals = [];
      secs.forEach(function(s) {
        var b = calcSectionBandFromParts(s, cum, 'all');
        if (b !== null && !isNaN(b)) vals.push(b);
      });
      if (vals.length === 0) return;
      var avg = vals.reduce(function(a,b){ return a+b; }, 0) / vals.length;
      avg = Math.round(avg * 2) / 2;
      points.push({ date: d, value: avg });
    });
    return { points: points, unit: '', max: 9 };
  } else if (examType === 'sat') {
    var results = S.satResults || [];
    if (results.length === 0) return { points: [], unit: '', max: 1600 };
    var dates = Array.from(new Set(results.map(function(r){ return r.date; }))).sort();
    var points = [];
    dates.forEach(function(d) {
      var cum = results.filter(function(r){ return r.date <= d; });
      var avgRw   = calcSatSectionAvg('rw', cum, 'all');
      var avgMath = calcSatSectionAvg('math', cum, 'all');
      var total;
      if (avgRw !== null && avgMath !== null) total = avgRw + avgMath;
      else if (avgRw !== null) total = avgRw * 2;
      else if (avgMath !== null) total = avgMath * 2;
      else return;
      points.push({ date: d, value: Math.round(total) });
    });
    return { points: points, unit: '', max: 1600 };
  } else if (examType === 'cefr') {
    var allHist = ((typeof S !== 'undefined' && S.cefr && S.cefr.history) || [])
      .filter(function (r) { return CEFR_SECTIONS.indexOf(r.section) !== -1 && r.date; });
    if (allHist.length === 0) return { points: [], unit: '', max: 6 };
    var cefrDates = Array.from(new Set(allHist.map(function (r) { return r.date; }))).sort();
    var cefrPoints = [];
    cefrDates.forEach(function (d) {
      var cum = allHist.filter(function (r) { return r.date <= d; });
      var vals = [];
      CEFR_SECTIONS.forEach(function (sec) {
        var secEntries = cum.filter(function (r) { return r.section === sec; })
          .sort(function (a, b) { return (a.date || '').localeCompare(b.date || ''); });
        if (!secEntries.length) return;
        var rank = cefrLevelToRank(secEntries[secEntries.length - 1].level);
        if (rank !== null) vals.push(rank);
      });
      if (vals.length === 0) return;
      var avg = vals.reduce(function (a, b) { return a + b; }, 0) / vals.length;
      cefrPoints.push({ date: d, value: Math.round(avg * 100) / 100 });
    });
    return { points: cefrPoints, unit: '', max: 6 };
  }
  return { points: [], unit: '', max: 100 };
}

function _examTrendGoal(forExamType) {
  var examType = forExamType || getExamType();
  var saved = getExamDate(examType);
  if (!saved || !saved.target) return null;
  if (examType === 'cefr') {
    // CEFR maqsadi son emas, daraja (A1-C2) — rank (1-6) ga aylantiramiz.
    return (typeof cefrLevelToRank === 'function') ? cefrLevelToRank(saved.target) : null;
  }
  var v = parseFloat(String(saved.target).replace(',', '.'));
  if (isNaN(v)) return null;
  if (examType === 'ielts' && (v <= 0 || v > 9)) return null;
  if (examType === 'sat' && (v < 200 || v > 1600)) return null;
  return v;
}

function renderExamTrendChart() {
  var card      = document.getElementById('exam-trend-card');
  var emptyCard = document.getElementById('exam-trend-empty-card');
  if (!card || !emptyCard) return;

  var examType = getExamType();
  if (examType === 'none') {
    card.style.display = 'none';
    emptyCard.style.display = 'none';
    return;
  }

  var data = _examTrendBuildSeries();
  var points = data.points;

  if (points.length < 2) {
    card.style.display = 'none';
    emptyCard.style.display = 'block';
    return;
  }
  emptyCard.style.display = 'none';
  card.style.display = 'block';

  var titleEl = document.getElementById('exam-trend-title');
  if (titleEl) { titleEl.removeAttribute('data-i18n'); titleEl.textContent = t('exam_trend_title'); }

  var goal = _examTrendGoal();
  var goalBadge = document.getElementById('exam-trend-goal-badge');
  if (goal !== null && goalBadge) {
    goalBadge.style.display = 'inline-block';
    goalBadge.textContent = t('exam_trend_goal_label').replace('{v}', goal);
  } else if (goalBadge) {
    goalBadge.style.display = 'none';
  }

  // ── Canvas chizish ──
  var canvas = document.getElementById('exam-trend-chart');
  if (canvas) {
    var W = canvas.offsetWidth || 300, H = 110;
    canvas.width = W; canvas.height = H;
    var ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, W, H);

    var vals = points.map(function(p){ return p.value; });
    var lo = Math.min.apply(null, vals);
    var hi = Math.max.apply(null, vals);
    if (goal !== null) { lo = Math.min(lo, goal); hi = Math.max(hi, goal); }
    if (hi === lo) { hi += 1; lo -= 1; }
    var padY = (hi - lo) * 0.18;
    hi += padY; lo -= padY;

    var padX = 10, padTop = 10, padBot = 14;
    var plotH = H - padTop - padBot;
    var segW = points.length > 1 ? (W - padX*2) / (points.length - 1) : 0;

    function xFor(i){ return padX + i*segW; }
    function yFor(v){ return padTop + (1 - (v - lo)/(hi - lo)) * plotH; }

    // Grid
    ctx.strokeStyle = 'rgba(255,255,255,0.05)'; ctx.lineWidth = 1;
    for (var i=0;i<3;i++) { var gy = padTop + i*plotH/2; ctx.beginPath(); ctx.moveTo(padX,gy); ctx.lineTo(W-padX,gy); ctx.stroke(); }

    // Goal dashed line
    if (goal !== null) {
      var gyGoal = yFor(goal);
      ctx.save();
      ctx.setLineDash([4,4]);
      ctx.strokeStyle = 'rgba(180,142,255,0.6)'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(padX, gyGoal); ctx.lineTo(W-padX, gyGoal); ctx.stroke();
      ctx.restore();
    }

    // Gradient fill under line
    var grad = ctx.createLinearGradient(0,0,0,H);
    grad.addColorStop(0,'rgba(52,211,153,0.30)');
    grad.addColorStop(1,'rgba(52,211,153,0)');
    ctx.beginPath();
    points.forEach(function(p,i){ var x=xFor(i), y=yFor(p.value); if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y); });
    ctx.lineTo(xFor(points.length-1), H-padBot);
    ctx.lineTo(xFor(0), H-padBot);
    ctx.closePath();
    ctx.fillStyle = grad; ctx.fill();

    // Line
    ctx.beginPath();
    ctx.strokeStyle = '#34D399'; ctx.lineWidth = 2.5; ctx.lineJoin = 'round';
    points.forEach(function(p,i){ var x=xFor(i), y=yFor(p.value); if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y); });
    ctx.stroke();

    // Dots + value labels
    ctx.font = '10px DM Sans, sans-serif';
    points.forEach(function(p,i){
      var x=xFor(i), y=yFor(p.value);
      ctx.beginPath(); ctx.arc(x,y,3.5,0,2*Math.PI);
      ctx.fillStyle = (i===points.length-1) ? '#F5A623' : '#34D399';
      ctx.fill();
      if (i===0 || i===points.length-1) {
        ctx.fillStyle = 'rgba(255,255,255,0.85)';
        ctx.textAlign = (i===0) ? 'left' : 'right';
        ctx.fillText(String(p.value), x + (i===0?4:-4), y - 8);
      }
    });
  }

  // ── Sana labellari (birinchi va oxirgi) ──
  var labelsEl = document.getElementById('exam-trend-labels');
  if (labelsEl) {
    var first = points[0], last = points[points.length-1];
    labelsEl.innerHTML =
      '<div style="font-size:var(--fs-3xs);color:var(--text-dim)">' + _ieltsPrettyDate(first.date) + '</div>' +
      '<div style="font-size:var(--fs-3xs);color:var(--text-dim)">' + _ieltsPrettyDate(last.date) + '</div>';
  }

  // ── Maqsadgacha qolgan farq ──
  var gapEl = document.getElementById('exam-trend-gap');
  if (gapEl) {
    if (goal === null) {
      gapEl.textContent = '';
    } else {
      var current = points[points.length-1].value;
      var diff = Math.round((goal - current) * 2) / 2;
      if (diff <= 0) {
        gapEl.textContent = t('exam_trend_gap_reached');
        gapEl.style.color = '#34D399';
      } else {
        gapEl.textContent = t('exam_trend_gap_left').replace('{v}', diff);
        gapEl.style.color = 'var(--text-muted)';
      }
    }
  }

  var forecastEl = document.getElementById('exam-trend-forecast');
  if (forecastEl) forecastEl.style.display = 'none';
}

function _examForecastConfidenceSuffix(pace) {
  if (!pace) return '';
  if (pace.confidence === 'low') return ' ' + t('exam_forecast_confidence_low');
  if (pace.confidence === 'medium') return ' ' + t('exam_forecast_confidence_medium');
  return '';
}
function _examScoreLabel(examType, v) {
  if (examType === 'ielts') return (Math.round(v * 2) / 2).toFixed(1);
  if (examType === 'cefr') {
    var levels = (typeof CEFR_LEVELS !== 'undefined') ? CEFR_LEVELS : ['A1','A2','B1','B2','C1','C2'];
    var rank = Math.max(1, Math.min(levels.length, Math.round(v)));
    return levels[rank - 1] || String(rank);
  }
  return String(Math.round(v));
}
function _examFormatEtaDate(days) {
  var d = new Date(Date.now() + days * 86400000);
  return _ieltsPrettyDate(d.toISOString().slice(0, 10));
}

function _buildExamForecastBlockHtml(examType, examLabel) {
  var adv = computeAdvancedExamForecast(examType);
  if (!adv) return '';

  var rows = [];

  // ── 1) "Imtihon kunigacha qanday natijaga erisha olaman?" ──
  if (adv.examDate && adv.forecastByExamDate) {
    var scoreLabel = _examScoreLabel(examType, adv.forecastByExamDate.value);
    var dateLabel = _ieltsPrettyDate(adv.examDate);
    rows.push('<div style="display:flex;align-items:flex-start;gap:8px"><span style="font-size:16px;line-height:1.3">📅</span><div style="font-size:var(--fs-xs);color:var(--text);line-height:1.5">' +
      t('exam_forecast_by_date_label').replace('{date}', esc(dateLabel)).replace('{score}', '<b style="color:#B48EFF">' + esc(scoreLabel) + '</b>') +
      '<span style="color:var(--text-dim)">' + esc(_examForecastConfidenceSuffix(adv.pace)) + '</span></div></div>');
  } else if (!adv.examDate) {
    rows.push('<div style="font-size:var(--fs-2xs);color:var(--text-dim);display:flex;align-items:center;gap:8px"><span style="font-size:16px">📅</span>' + esc(t('exam_forecast_no_exam_date')) + '</div>');
  }

  // ── 2) "Maqsadimga qachon erishaman?" ──
  if (adv.goal === null) {
    rows.push('<div style="font-size:var(--fs-2xs);color:var(--text-dim);display:flex;align-items:center;gap:8px"><span style="font-size:16px">🎯</span>' + esc(t('exam_forecast_no_goal')) + '</div>');
  } else if (adv.goalReached) {
    rows.push('<div style="font-size:var(--fs-xs);color:#34D399;font-weight:700;display:flex;align-items:center;gap:8px"><span style="font-size:16px">🎉</span>' + esc(t('exam_forecast_goal_reached')) + '</div>');
  } else if (adv.etaToGoal) {
    var etaDateLabel = _examFormatEtaDate(adv.etaToGoal.days);
    var goalLabel = _examScoreLabel(examType, adv.goal);
    rows.push('<div style="display:flex;align-items:flex-start;gap:8px"><span style="font-size:16px;line-height:1.3">🎯</span><div style="font-size:var(--fs-xs);color:var(--text);line-height:1.5">' +
      t('exam_forecast_eta_label').replace('{goal}', '<b style="color:var(--gold)">' + esc(goalLabel) + '</b>').replace('{date}', '<b>' + esc(etaDateLabel) + '</b>').replace('{days}', adv.etaToGoal.days) +
      '<span style="color:var(--text-dim)">' + esc(_examForecastConfidenceSuffix(adv.pace)) + '</span></div></div>');
  } else if (adv.etaTooFar) {
    rows.push('<div style="font-size:var(--fs-2xs);color:var(--text-dim);display:flex;align-items:center;gap:8px"><span style="font-size:16px">🐢</span>' + esc(t('exam_forecast_eta_too_far')) + '</div>');
  } else if (!adv.pace) {
    rows.push('<div style="font-size:var(--fs-2xs);color:var(--text-dim);display:flex;align-items:center;gap:8px"><span style="font-size:16px">🎯</span>' + esc(t('exam_forecast_low_data')) + '</div>');
  }

  // ── 3) Ko'nikmalar (Listening/Reading/Writing/Speaking yoki RW/Math) ──
  var skills = computeExamSkillsBreakdown(examType);
  var withData = skills.filter(function (s) { return s.hasData; });
  var skillsHtml = '';
  if (withData.length) {
    var weakStrong = computeExamWeakStrong(skills);
    var skillRows = '';
    skills.forEach(function (s) {
      if (!s.hasData) return;
      var isWeak = weakStrong && weakStrong.weakest.key === s.key;
      var isStrong = weakStrong && weakStrong.strongest.key === s.key;
      var badge = isWeak ? ('<span style="font-size:var(--fs-3xs);font-weight:700;color:#F87171;background:rgba(248,113,113,0.14);border-radius:var(--radius-full);padding:2px 8px">' + esc(t('exam_forecast_weakest_badge')) + '</span>')
        : (isStrong ? ('<span style="font-size:var(--fs-3xs);font-weight:700;color:#34D399;background:rgba(52,211,153,0.14);border-radius:var(--radius-full);padding:2px 8px">' + esc(t('exam_forecast_strongest_badge')) + '</span>') : '');
      var curLabel = _examScoreLabel(examType, s.current);
      var hoursLabel = Math.round(s.hoursToNext);
      skillRows += '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px 12px;background:var(--surface2);border-radius:var(--radius-sm)">' +
        '<div style="display:flex;align-items:center;gap:8px;min-width:0"><span style="font-size:var(--fs-xs);font-weight:600;color:var(--text);white-space:nowrap">' + t(s.labelKey) + '</span>' + badge + '</div>' +
        '<div style="text-align:right;flex-shrink:0"><div style="font-size:var(--fs-sm);font-weight:700;color:var(--text)">' + esc(curLabel) + '</div>' +
        '<div style="font-size:var(--fs-3xs);color:var(--text-dim)">' + t('exam_forecast_hours_to_next').replace('{hours}', hoursLabel) + '</div></div>' +
        '</div>';
    });

    var recHtml = '';
    if (weakStrong) {
      var w = weakStrong.weakest;
      var nextLabel = _examScoreLabel(examType, w.nextLevel);
      var wCurLabel = _examScoreLabel(examType, w.current);
      recHtml = '<div style="margin-top:8px;padding:10px 12px;background:rgba(52,211,153,0.1);border:1px solid rgba(52,211,153,0.3);border-radius:var(--radius-sm);font-size:var(--fs-2xs);color:#34D399;line-height:1.5">💡 ' +
        t('exam_forecast_recommendation_text')
          .replace('{skill}', '<b>' + t(w.labelKey) + '</b>')
          .replace('{current}', esc(wCurLabel))
          .replace('{next}', '<b>' + esc(nextLabel) + '</b>')
          .replace('{hours}', Math.round(w.hoursToNext)) +
        '</div>';
    }

    skillsHtml = '<div style="margin-top:16px">' +
      '<div style="font-size:var(--fs-2xs);color:var(--text-dim);letter-spacing:0.05em;text-transform:uppercase;margin-bottom:10px" data-i18n="exam_forecast_skills_title">' + esc(t('exam_forecast_skills_title')) + '</div>' +
      '<div style="display:flex;flex-direction:column;gap:8px">' + skillRows + '</div>' +
      recHtml +
    '</div>';
  }

  var headerHtml = examLabel ? '<div style="font-size:var(--fs-xs);font-weight:700;color:var(--text);margin-bottom:10px">' + esc(examLabel) + '</div>' : '';
  return '<div style="display:flex;flex-direction:column;gap:10px">' + headerHtml + rows.join('') + skillsHtml + '</div>';
}

function renderExamForecastCard() {
  var card = document.getElementById('exam-forecast-card');
  if (!card) return;

  var subjects = [];
  if (hasExamSubject('ielts')) subjects.push({ type: 'ielts', label: '📊 IELTS' });
  if (hasExamSubject('sat')) subjects.push({ type: 'sat', label: '📐 SAT' });
  if (hasExamSubject('cefr')) subjects.push({ type: 'cefr', label: '📘 CEFR' });

  var bodyEl = document.getElementById('exam-forecast-body');
  var lowDataEl = document.getElementById('exam-forecast-low-data');

  var showLabels = subjects.length > 1; // faqat bir nechtasi faol bo'lsa fan nomi ko'rsatiladi
  var blocks = subjects.map(function (s) {
    return _buildExamForecastBlockHtml(s.type, showLabels ? s.label : null);
  }).filter(Boolean);

  if (!blocks.length) {
    card.style.display = 'none';
    if (lowDataEl) lowDataEl.style.display = 'none';
    return;
  }

  card.style.display = 'block';
  if (bodyEl) {
    bodyEl.innerHTML = blocks.join('<div style="height:1px;background:var(--border);margin:16px 0"></div>');
  }
  if (lowDataEl) lowDataEl.style.display = 'none';
}


var _ttCalYear = null, _ttCalMonth = null;
var _ttFilterDates = new Set();   // tanlangan sanalar (YYYY-MM-DD)
var _ttFilterActive = false;      // "Saqlash" bosilgandan keyin true bo'ladi
var _ttIsDragging = false;
var _ttDragMode = 'select';       // 'select' | 'deselect' — drag boshlangan katakning holatiga qarab

function openTopTaskModal() {
  renderTopTaskList();
  var panel = document.getElementById('tt-filter-panel');
  if (panel) panel.style.display = 'none';
  document.getElementById('top-task-modal-overlay').classList.add('open');
}

function closeTopTaskModal() {
  document.getElementById('top-task-modal-overlay').classList.remove('open');
  _ttIsDragging = false;
}

function toggleTopTaskFilter() {
  var panel = document.getElementById('tt-filter-panel');
  if (!panel) return;
  var willOpen = panel.style.display === 'none';
  panel.style.display = willOpen ? '' : 'none';
  if (willOpen) {
    if (_ttCalYear === null) {
      var now = new Date();
      _ttCalYear = now.getFullYear();
      _ttCalMonth = now.getMonth();
    }
    renderTTCalendar();
  }
}

function ttCalPrevMonth() {
  _ttCalMonth--;
  if (_ttCalMonth < 0) { _ttCalMonth = 11; _ttCalYear--; }
  renderTTCalendar();
}
function ttCalNextMonth() {
  _ttCalMonth++;
  if (_ttCalMonth > 11) { _ttCalMonth = 0; _ttCalYear++; }
  renderTTCalendar();
}

function ttCellVisual(cell, isSelected, isFuture) {
  cell.style.background = isSelected ? 'var(--accent)' : 'var(--surface)';
  cell.style.color = isSelected ? '#fff' : (isFuture ? 'var(--text-dim)' : 'var(--text)');
  cell.style.border = '1px solid ' + (isSelected ? 'transparent' : 'var(--border)');
}

function ttApplyDragToCell(cell) {
  if (!cell || !cell.dataset || !cell.dataset.ttDate) return;
  var ds = cell.dataset.ttDate;
  if (cell.dataset.ttFuture === '1') return;
  if (_ttDragMode === 'select') { if (!_ttFilterDates.has(ds)) _ttFilterDates.add(ds); }
  else { if (_ttFilterDates.has(ds)) _ttFilterDates.delete(ds); }
  ttCellVisual(cell, _ttFilterDates.has(ds), false);
}

function renderTTCalendar() {
  var label = document.getElementById('tt-cal-month-label');
  if (label) label.textContent = getMonthsFullArr()[_ttCalMonth] + ' ' + _ttCalYear;

  var grid = document.getElementById('tt-cal-grid');
  if (!grid) return;
  grid.innerHTML = '';

  var firstDay = new Date(_ttCalYear, _ttCalMonth, 1).getDay();
  var startOffset = (firstDay === 0) ? 6 : firstDay - 1;
  var daysInMonth = new Date(_ttCalYear, _ttCalMonth + 1, 0).getDate();
  var todayStr = today();

  for (var i = 0; i < startOffset; i++) {
    var empty = document.createElement('div');
    empty.style.cssText = 'aspect-ratio:1;';
    grid.appendChild(empty);
  }

  for (var day = 1; day <= daysInMonth; day++) {
    var dateStr = getDateStr(_ttCalYear, _ttCalMonth, day);
    var isFuture = dateStr > todayStr;
    var isSelected = _ttFilterDates.has(dateStr);

    var cell = document.createElement('div');
    cell.dataset.ttDate = dateStr;
    cell.dataset.ttFuture = isFuture ? '1' : '0';
    cell.textContent = day;
    cell.style.cssText =
      'aspect-ratio:1;border-radius:var(--radius-sm);display:flex;align-items:center;justify-content:center;' +
      'font-size:var(--fs-2xs);font-weight:600;user-select:none;-webkit-user-select:none;' +
      'cursor:' + (isFuture ? 'default' : 'pointer') + ';' +
      'opacity:' + (isFuture ? '0.35' : '1') + ';';
    ttCellVisual(cell, isSelected, isFuture);

    if (!isFuture) {
      cell.addEventListener('mousedown', function(e) {
        e.preventDefault();
        var ds = e.currentTarget.dataset.ttDate;
        _ttDragMode = _ttFilterDates.has(ds) ? 'deselect' : 'select';
        _ttIsDragging = true;
        ttApplyDragToCell(e.currentTarget);
      });
      cell.addEventListener('mouseenter', function(e) {
        if (!_ttIsDragging) return;
        ttApplyDragToCell(e.currentTarget);
      });
      // Mobil qurilmalarda barmoq bilan "sudrab" tanlash uchun
      cell.addEventListener('touchstart', function(e) {
        e.preventDefault();
        var ds = e.currentTarget.dataset.ttDate;
        _ttDragMode = _ttFilterDates.has(ds) ? 'deselect' : 'select';
        _ttIsDragging = true;
        ttApplyDragToCell(e.currentTarget);
      }, {passive:false});
    }

    grid.appendChild(cell);
  }
}

// Barmoq bilan sudrab tanlashda qaysi katak ustida turganini aniqlaymiz
document.addEventListener('touchmove', function(e) {
  if (!_ttIsDragging) return;
  var grid = document.getElementById('tt-cal-grid');
  if (!grid || grid.style.display === 'none') return;
  var touch = e.touches[0]; if (!touch) return;
  var el = document.elementFromPoint(touch.clientX, touch.clientY);
  if (el && el.dataset && el.dataset.ttDate) { e.preventDefault(); ttApplyDragToCell(el); }
}, {passive:false});

// Sichqoncha/barmoq qo'yib yuborilganda drag-select rejimi tugaydi
document.addEventListener('mouseup', function(){ _ttIsDragging = false; });
document.addEventListener('touchend', function(){ _ttIsDragging = false; });

function ttFilterClear() {
  _ttFilterDates.clear();
  _ttFilterActive = false;
  renderTTCalendar();
  var summary = document.getElementById('tt-filter-summary');
  if (summary) summary.textContent = '';
  renderTopTaskList();
}

function ttFilterApply() {
  if (_ttFilterDates.size === 0) { toast(t('top_task_filter_pick_toast')); return; }
  _ttFilterActive = true;
  renderTopTaskList();
  var summary = document.getElementById('tt-filter-summary');
  if (summary) summary.textContent = t('top_task_filter_applied').replace('{n}', _ttFilterDates.size);
  toast(t('top_task_filter_applied_toast').replace('{n}', _ttFilterDates.size));
}

function renderTopTaskList() {
  var listEl = document.getElementById('top-task-list');
  if (!listEl) return;

  var doneLog   = S.taskDoneLog   || {};
  var doneCount = S.taskDoneCount || {};

  var rows = (S.tasks || []).map(function(tk) {
    var cnt;
    if (_ttFilterActive && _ttFilterDates.size > 0) {
      var dates = doneLog[tk.id] || [];
      cnt = dates.filter(function(d) { return _ttFilterDates.has(d); }).length;
    } else {
      cnt = doneCount[tk.id] != null ? doneCount[tk.id] : (doneLog[tk.id] || []).length;
    }
    return { task: tk, count: cnt };
  });

  // Ko'pdan kamga qarab saralanadi — 0 marta bajarilganlar tabiiy ravishda eng pastda qoladi
  rows.sort(function(a, b) { return b.count - a.count; });

  if (rows.length === 0) {
    listEl.innerHTML = '<p style="color:var(--text-muted);font-size:var(--fs-sm);text-align:center;padding:14px 0">' + t('top_task_empty') + '</p>';
    return;
  }

  var diffIcons = ['🟢', '🟡', '🔴'];
  var html = '';
  rows.forEach(function(r) {
    var icon = r.task.emoji || diffIcons[(r.task.diff || 1) - 1];
    var countColor = r.count > 0 ? 'var(--accent)' : 'var(--text-dim)';
    html +=
      '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;background:var(--surface2);border-radius:var(--radius-sm);padding:10px 14px">' +
        '<span style="font-size:var(--fs-sm);color:var(--text);flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + icon + ' ' + esc(r.task.name) + '</span>' +
        '<span style="font-size:var(--fs-xs);font-weight:700;color:' + countColor + ';white-space:nowrap;flex-shrink:0">' + r.count + t('top_task_times_short') + '</span>' +
      '</div>';
  });
  listEl.innerHTML = html;
}

