function formatHourLabel12(h) {
  var ampm = h < 12 ? 'AM' : 'PM';
  var h12 = h % 12 || 12;
  return h12 + ':00 ' + ampm;
}

function renderHourStatsList() {
  var listEl = document.getElementById('hour-stats-list');
  if (!listEl) return;

  var hourLog = S.taskDoneHourLog || {};
  var rows = [];
  for (var h = 0; h < 24; h++) {
    rows.push({ hour: h, count: hourLog[h] || 0 });
  }
  // Ko'pdan kamga qarab saralanadi — eng ko'p bajarilgan soat birinchi keladi
  rows.sort(function(a, b) { return b.count - a.count; });

  var maxCount = rows.length ? rows[0].count : 0;
  if (maxCount === 0) {
    listEl.innerHTML = '<p style="color:var(--text-muted);font-size:var(--fs-sm);text-align:center;padding:14px 0">' + t('stat_no_data') + '</p>';
    return;
  }

  var html = '';
  rows.forEach(function(r, idx) {
    var pct = maxCount > 0 ? Math.round(r.count / maxCount * 100) : 0;
    var isTop = idx === 0 && r.count > 0;
    var barColor = isTop ? 'var(--accent)' : 'rgba(124,92,252,0.45)';
    var countColor = r.count > 0 ? 'var(--text)' : 'var(--text-dim)';
    var labelColor = isTop ? 'var(--accent)' : 'var(--text-muted)';
    html +=
      '<div style="display:flex;align-items:center;gap:10px;padding:7px 0">' +
        '<span style="font-size:var(--fs-xs);color:' + labelColor + ';font-weight:' + (isTop ? '700' : '500') + ';width:78px;flex-shrink:0">' + (isTop ? '🏆 ' : '') + formatHourLabel12(r.hour) + '</span>' +
        '<div style="flex:1;background:var(--surface2);border-radius:var(--radius-2xs);height:16px;overflow:hidden">' +
          '<div style="width:' + pct + '%;height:100%;background:' + barColor + ';border-radius:var(--radius-2xs);transition:width 0.4s ease"></div>' +
        '</div>' +
        '<span style="font-size:var(--fs-xs);font-weight:700;color:' + countColor + ';width:24px;text-align:right;flex-shrink:0">' + r.count + '</span>' +
      '</div>';
  });
  listEl.innerHTML = html;
}

