(function setupTabDrag() {
  var DEFAULT_ORDER = ['tasks','rewards','goals','chest','ielts','sat','pomo'];
  var LONG_PRESS_MS = 300;
  var MOVE_CANCEL_PX = 8;

  var dragSrcTab = null;
  var dragActive = false;
  var pressTimer = null;
  var startX = 0, startY = 0;
  var activePointerId = null;
  var _tabDragInited = false; // ikki marta ro'yxatdan o'tishning oldini oladi

  function getTabOrder() {
    var saved = S.tabOrder || null;
    if (!Array.isArray(saved) || saved.length === 0) return DEFAULT_ORDER;
    // Eski saqlangan tartibda yo'q bo'lgan yangi tablarni (masalan ielts) oxiriga qo'shamiz
    var merged = saved.filter(function(id){ return DEFAULT_ORDER.indexOf(id) !== -1; });
    DEFAULT_ORDER.forEach(function(id) {
      if (merged.indexOf(id) === -1) merged.push(id);
    });
    return merged;
  }

  function saveTabOrder(order) {
    S.tabOrder = order;
    save();
  }

  function applyTabOrder() {
    var bar = document.getElementById('tabs-bar');
    if (!bar) return;
    getTabOrder().forEach(function(tabId) {
      var btn = document.getElementById('tab-' + tabId);
      if (btn) bar.appendChild(btn);
    });
  }
  window.applyTabOrder = applyTabOrder;

  function clearDragOverStyles(bar) {
    bar.querySelectorAll('[data-tab]').forEach(function(b) { b.classList.remove('tab-drag-over'); });
  }

  function resetDragState(bar) {
    clearTimeout(pressTimer);
    pressTimer = null;
    if (dragSrcTab) dragSrcTab.classList.remove('tab-dragging');
    clearDragOverStyles(bar);
    dragActive = false;
    dragSrcTab = null;
    activePointerId = null;
  }

  function initTabDrag() {
    applyTabOrder();
    var bar = document.getElementById('tabs-bar');
    if (!bar) return;
    if (_tabDragInited) return;
    _tabDragInited = true;

    bar.addEventListener('pointerdown', function(e) {
      var btn = e.target.closest('[data-tab]');
      if (!btn) return;
      startX = e.clientX;
      startY = e.clientY;
      clearTimeout(pressTimer);
      pressTimer = setTimeout(function() {
        dragSrcTab = btn;
        dragActive = true;
        activePointerId = e.pointerId;
        try { btn.setPointerCapture(e.pointerId); } catch (err) {}
        btn.classList.add('tab-dragging');
        if (navigator.vibrate) navigator.vibrate(30);
      }, LONG_PRESS_MS);
    });

    bar.addEventListener('pointermove', function(e) {
      if (!dragActive) {
        // Drag hali boshlanmagan — agar barmoq/kursor sezilarli siljisa
        // (oddiy skroll/bosish bo'lsa), rejalashtirilgan drag bekor qilinadi.
        if (pressTimer) {
          var dx = Math.abs(e.clientX - startX), dy = Math.abs(e.clientY - startY);
          if (dx > MOVE_CANCEL_PX || dy > MOVE_CANCEL_PX) {
            clearTimeout(pressTimer);
            pressTimer = null;
          }
        }
        return;
      }
      if (activePointerId !== null && e.pointerId !== activePointerId) return;
      e.preventDefault();
      var el = document.elementFromPoint(e.clientX, e.clientY);
      var target = el && el.closest('[data-tab]');
      clearDragOverStyles(bar);
      if (target && target !== dragSrcTab) target.classList.add('tab-drag-over');
    }, { passive: false });

    function finishDrag(e) {
      if (activePointerId !== null && e.pointerId !== activePointerId) return;
      if (!dragActive || !dragSrcTab) { resetDragState(bar); return; }
      if (dragSrcTab) { try { dragSrcTab.releasePointerCapture(e.pointerId); } catch (err) {} }
      var el = document.elementFromPoint(e.clientX, e.clientY);
      var target = el && el.closest('[data-tab]');
      if (target && target !== dragSrcTab) {
        var allBtns = Array.from(bar.querySelectorAll('[data-tab]'));
        var srcIdx = allBtns.indexOf(dragSrcTab);
        var tgtIdx = allBtns.indexOf(target);
        if (srcIdx < tgtIdx) {
          bar.insertBefore(dragSrcTab, target.nextSibling);
        } else {
          bar.insertBefore(dragSrcTab, target);
        }
        var newOrder = Array.from(bar.querySelectorAll('[data-tab]')).map(function(b) { return b.dataset.tab; });
        saveTabOrder(newOrder);
        if (navigator.vibrate) navigator.vibrate(20);
      }
      resetDragState(bar);
    }

    bar.addEventListener('pointerup', finishDrag);
    bar.addEventListener('pointercancel', function() { resetDragState(bar); });
  }

  document.addEventListener('DOMContentLoaded', initTabDrag);
  // Fallback if DOMContentLoaded already fired
  if (document.readyState !== 'loading') initTabDrag();
})();


