// Tur holati (state) — 2-qismdagi navigatsiya funksiyalari shu obyektni ishlatadi
var onboardingState = {
  active: false,
  steps: [],
  idx: 0
};

function getOnboardingTargetRect(selector, padding) {
  padding = (typeof padding === 'number') ? padding : 8;
  var el = document.querySelector(selector);
  if (!el) return null;
  var r = el.getBoundingClientRect();
  if (r.width === 0 && r.height === 0) return null; // display:none bo'lsa
  return {
    top: r.top - padding,
    left: r.left - padding,
    width: r.width + padding * 2,
    height: r.height + padding * 2,
    bottom: r.bottom + padding,
    right: r.right + padding,
    centerX: r.left + r.width / 2,
    centerY: r.top + r.height / 2
  };
}

// Spotlight qutisini berilgan to'rtburchak ustiga joylaydi
function positionOnboardingSpotlight(rect) {
  var spot = document.getElementById('onboarding-spotlight');
  if (!spot || !rect) return;
  spot.style.top = rect.top + 'px';
  spot.style.left = rect.left + 'px';
  spot.style.width = rect.width + 'px';
  spot.style.height = rect.height + 'px';
}

// Tooltip'ni spotlight to'rtburchagiga nisbatan berilgan yo'nalishda (top/bottom/left/right)
// joylaydi va ekran chetidan chiqib ketmasligi uchun (clamp) chegaralaydi.
function positionOnboardingTooltip(rect, placement) {
  var tip = document.getElementById('onboarding-tooltip');
  var arrow = document.getElementById('onboarding-tooltip-arrow');
  if (!tip || !rect) return;

  tip.classList.remove('arrow-top', 'arrow-bottom', 'arrow-left', 'arrow-right');

  var tipW = tip.offsetWidth || 280;
  var tipH = tip.offsetHeight || 220;
  var gap = 16;
  var vw = window.innerWidth;
  var vh = window.innerHeight;
  var top, left, arrowClass;

  if (placement === 'left') {
    left = rect.left - tipW - gap;
    top = rect.centerY - tipH / 2;
    arrowClass = 'arrow-right'; // tooltip chapda -> strelka o'ngga qaraydi
    if (left < 12) { // joy yetmasa pastga tushiramiz
      left = rect.centerX - tipW / 2;
      top = rect.bottom + gap;
      arrowClass = 'arrow-top';
    }
  } else if (placement === 'right') {
    left = rect.right + gap;
    top = rect.centerY - tipH / 2;
    arrowClass = 'arrow-left';
    if (left + tipW > vw - 12) {
      left = rect.centerX - tipW / 2;
      top = rect.bottom + gap;
      arrowClass = 'arrow-top';
    }
  } else if (placement === 'top') {
    left = rect.centerX - tipW / 2;
    top = rect.top - tipH - gap;
    arrowClass = 'arrow-bottom';
    if (top < 12) {
      top = rect.bottom + gap;
      arrowClass = 'arrow-top';
    }
  } else { // 'bottom' (standart)
    left = rect.centerX - tipW / 2;
    top = rect.bottom + gap;
    arrowClass = 'arrow-top';
    if (top + tipH > vh - 12) {
      top = rect.top - tipH - gap;
      arrowClass = 'arrow-bottom';
    }
  }

  // Gorizontal chegaralash — tooltip ekrandan chiqib ketmasin
  if (left < 12) left = 12;
  if (left + tipW > vw - 12) left = vw - tipW - 12;
  // Vertikal chegaralash
  if (top < 12) top = 12;
  if (top + tipH > vh - 12) top = vh - tipH - 12;

  tip.style.top = top + 'px';
  tip.style.left = left + 'px';
  tip.classList.add(arrowClass);
}

function onboardingKeyHandler(e) {
  if (!onboardingState.active) return;
  if (e.key === 'Enter' || e.key === ' ' || e.code === 'Space' || e.key === 'ArrowRight') {
    e.preventDefault();
    if (typeof onboardingNext === 'function') onboardingNext();
  } else if (e.key === 'ArrowLeft') {
    e.preventDefault();
    if (typeof onboardingBack === 'function') onboardingBack();
  } else if (e.key === 'Escape') {
    e.preventDefault();
    if (typeof onboardingClose === 'function') onboardingClose();
  }
}

// Oyna o'lchami o'zgarsa (masalan mobil klaviatura ochilsa yoki resize),
// joriy qadam bo'yicha spotlight/tooltip qayta joylashtiriladi.
window.addEventListener('resize', function () {
  if (!onboardingState.active) return;
  var step = onboardingState.steps[onboardingState.idx];
  if (!step) return;
  var rect = getOnboardingTargetRect(step.target);
  if (rect) {
    positionOnboardingSpotlight(rect);
    positionOnboardingTooltip(rect, step.placement);
  }
});


function getOnboardingActiveTab() {
  var activeBtn = document.querySelector('.tab.active');
  return activeBtn ? activeBtn.getAttribute('data-tab') : null;
}

function onboardingWaitForStableRect(selector, maxFrames, cb) {
  var lastKey = null;
  var stableCount = 0;
  var frames = 0;
  function check() {
    frames++;
    var el = document.querySelector(selector);
    if (!el) { cb(null); return; }
    var r = el.getBoundingClientRect();
    var key = Math.round(r.top) + '_' + Math.round(r.left) + '_' + Math.round(r.width) + '_' + Math.round(r.height);
    if (key === lastKey) {
      stableCount++;
    } else {
      stableCount = 0;
      lastKey = key;
    }
    if (stableCount >= 2 || frames >= maxFrames) {
      cb(el);
    } else {
      requestAnimationFrame(check);
    }
  }
  requestAnimationFrame(check);
}

function onboardingGoToStepTarget(step, cb) {
  if (step.tab && getOnboardingActiveTab() !== step.tab) {
    showTab(step.tab);
  }
  // Ba'zi nishonlar (masalan Musiqa kartasi) standart holatda yopiq
  // accordion ichida yashiringan — shu step uchun avval ularni ochib qo'yamiz.
  if (typeof step.prepare === 'function') {
    try { step.prepare(); } catch (e) {}
  }
  var attempts = 0;
  function tryFind() {
    attempts++;
    var el = document.querySelector(step.target);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
      // Scroll qachon tugashi qurilma/masofaga qarab farq qiladi — shuning uchun
      // taxminiy vaqt kutish o'rniga elementning joylashuvi barqarorlashguncha kutamiz.
      onboardingWaitForStableRect(step.target, 40, cb);
    } else if (attempts < 25) {
      requestAnimationFrame(tryFind);
    } else {
      cb(null); // nishon topilmadi — bu qadam avtomatik o'tkazib yuboriladi
    }
  }
  requestAnimationFrame(tryFind);
}

function onboardingRenderStep() {
  var step = onboardingState.steps[onboardingState.idx];
  if (!step) { onboardingClose(); return; }

  onboardingGoToStepTarget(step, function (el) {
    if (!onboardingState.active) return; // shu oraliqda tur yopilgan bo'lishi mumkin
    if (!el) { onboardingNext(); return; }

    var rect = getOnboardingTargetRect(step.target);
    if (!rect) { onboardingNext(); return; }

    positionOnboardingSpotlight(rect);
    positionOnboardingTooltip(rect, step.placement);

    document.getElementById('onboarding-tt-icon').textContent = step.icon || '';
    document.getElementById('onboarding-tt-title').textContent = step.title || '';
    document.getElementById('onboarding-tt-desc').textContent = step.desc || '';
    document.getElementById('onboarding-step-label').textContent =
      (onboardingState.idx + 1) + ' / ' + onboardingState.steps.length;
    document.getElementById('onboarding-skip-btn').textContent = t('onb_skip_btn');
    document.getElementById('onboarding-skip-btn').onclick = onboardingClose;

    var advToggle = document.getElementById('onboarding-advanced-toggle');
    var advLabel = document.getElementById('onboarding-advanced-toggle-label');
    var advBody = document.getElementById('onboarding-tt-advanced');
    if (step.advanced) {
      advToggle.style.display = 'flex';
      advBody.style.display = 'none';
      advBody.textContent = step.advanced;
      advToggle.classList.remove('open');
      advLabel.textContent = t('onb_advanced_show');
      advToggle.onclick = function () {
        var isOpen = advBody.style.display !== 'none';
        if (isOpen) {
          advBody.style.display = 'none';
          advToggle.classList.remove('open');
          advLabel.textContent = t('onb_advanced_show');
        } else {
          advBody.style.display = 'block';
          advToggle.classList.add('open');
          advLabel.textContent = t('onb_advanced_hide');
        }
        // Kontent balandligi o'zgargani sababli, tooltip/spotlight'ni
        // yangi o'lcham asosida qayta joylashtiramiz.
        requestAnimationFrame(function () {
          var r = getOnboardingTargetRect(step.target);
          if (r) {
            positionOnboardingSpotlight(r);
            positionOnboardingTooltip(r, step.placement);
          }
        });
      };
    } else {
      advToggle.style.display = 'none';
      advBody.style.display = 'none';
    }

    // Nuqtalar (dots) — o'tilgan qadamlar xiraroq, joriy qadam kengroq
    var dotsHtml = onboardingState.steps.map(function (_, i) {
      var cls = i === onboardingState.idx ? 'active' : (i < onboardingState.idx ? 'done' : '');
      return '<span class="' + cls + '"></span>';
    }).join('');
    document.getElementById('onboarding-tt-dots').innerHTML = dotsHtml;

    // Orqaga tugmasi — faqat birinchi qadamdan keyin ko'rinadi
    var backBtn = document.getElementById('onboarding-back-btn');
    if (onboardingState.idx > 0) {
      backBtn.style.display = '';
      backBtn.textContent = t('guide_back_btn');
      backBtn.onclick = onboardingBack;
    } else {
      backBtn.style.display = 'none';
    }

    // Keyingi / Tugatish tugmasi
    var nextBtn = document.getElementById('onboarding-next-btn');
    var isLast = onboardingState.idx === onboardingState.steps.length - 1;
    nextBtn.textContent = isLast ? t('guide_done_btn') : t('guide_next_btn');
    nextBtn.onclick = onboardingNext;

    requestAnimationFrame(function () {
      var freshRect = getOnboardingTargetRect(step.target);
      if (freshRect) {
        positionOnboardingSpotlight(freshRect);
        positionOnboardingTooltip(freshRect, step.placement);
      }
    });
  });
}

function startOnboardingTour() {
  var peModal = document.getElementById('profile-edit-modal');
  if (peModal) peModal.remove();
  var oldGuide = document.getElementById('app-guide-modal');
  if (oldGuide) oldGuide.remove();

  onboardingState.steps = getOnboardingTourSteps();
  onboardingState.idx = 0;
  onboardingState.active = true;

  document.getElementById('onboarding-overlay').style.display = 'block';
  document.getElementById('onboarding-spotlight').style.display = 'block';
  document.getElementById('onboarding-tooltip').style.display = 'block';

  document.addEventListener('keydown', onboardingKeyHandler);

  onboardingRenderStep();
}

// Keyingi qadamga o'tadi; oxirgi qadamda bo'lsa turni yakunlaydi.
function onboardingNext() {
  if (!onboardingState.active) return;
  if (onboardingState.idx < onboardingState.steps.length - 1) {
    onboardingState.idx++;
    onboardingRenderStep();
  } else {
    onboardingFinish();
  }
}

// Oldingi qadamga qaytadi (birinchi qadamda hech narsa qilmaydi).
function onboardingBack() {
  if (!onboardingState.active) return;
  if (onboardingState.idx > 0) {
    onboardingState.idx--;
    onboardingRenderStep();
  }
}

// Barcha qadamlar ko'rib chiqilgach chaqiriladi — turni yopadi va
// tabriklovchi toast xabarini ko'rsatadi.
function onboardingFinish() {
  onboardingClose();
  if (typeof toast === 'function') toast(t('onb_finish_toast'));
}

// Turni istalgan vaqtda yopadi (Esc, "O'tkazib yuborish" yoki oxirgi qadam).
function onboardingClose() {
  onboardingState.active = false;
  document.getElementById('onboarding-overlay').style.display = 'none';
  document.getElementById('onboarding-spotlight').style.display = 'none';
  document.getElementById('onboarding-tooltip').style.display = 'none';
  document.removeEventListener('keydown', onboardingKeyHandler);
}


var wsState = {
  step: 0, name: '', goal: null, goalOther: '', ref: null, refOther: '',
  ambientFocusEnabled: false, difficulty: 'normal',
  authMode: null, regName: ''
};
var WS_TOTAL_STEPS = 3;

function showWelcomeSurvey() {
  var old = document.getElementById('welcome-survey-modal');
  if (old) old.remove();
  wsState = {
    step: 0, name: '', goal: null, goalOther: '', ref: null, refOther: '',
    ambientFocusEnabled: !!(typeof S !== 'undefined' && S.ambientFocusEnabled),
    difficulty: (typeof S !== 'undefined' && S.difficulty) || 'normal',
    authMode: null, regName: ''
  };

  var overlay = document.createElement('div');
  overlay.id = 'welcome-survey-modal';
  overlay.className = 'ws-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:260;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.innerHTML = '<div class="ws-blob ws-blob-1"></div><div class="ws-blob ws-blob-2"></div><div class="ws-blob ws-blob-3"></div>';
  var box = document.createElement('div');
  box.id = 'ws-box';
  box.className = 'ws-box';
  box.style.cssText = 'position:relative;border:1px solid var(--border);border-radius:var(--radius-xl);padding:22px 18px 18px;width:100%;max-width:360px;max-height:90vh;overflow-y:auto;z-index:1';
  overlay.appendChild(box);
  document.body.appendChild(overlay);
  wsRenderShell();
}

function closeWelcomeSurvey() {
  var ov = document.getElementById('welcome-survey-modal');
  if (ov) ov.remove();
}

function openAccountLinkModal() {
  var old = document.getElementById('welcome-survey-modal');
  if (old) old.remove();
  wsState = {
    step: 2, name: (S.profile && S.profile.name) || '', goal: null, goalOther: '', ref: null, refOther: '',
    ambientFocusEnabled: !!(typeof S !== 'undefined' && S.ambientFocusEnabled),
    difficulty: (typeof S !== 'undefined' && S.difficulty) || 'normal',
    authMode: null, regName: '', miniMode: true
  };

  var overlay = document.createElement('div');
  overlay.id = 'welcome-survey-modal';
  overlay.className = 'ws-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:260;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.innerHTML = '<div class="ws-blob ws-blob-1"></div><div class="ws-blob ws-blob-2"></div><div class="ws-blob ws-blob-3"></div>';
  var box = document.createElement('div');
  box.id = 'ws-box';
  box.className = 'ws-box';
  box.style.cssText = 'position:relative;border:1px solid var(--border);border-radius:var(--radius-xl);padding:22px 18px 18px;width:100%;max-width:360px;max-height:90vh;overflow-y:auto;z-index:1';
  overlay.appendChild(box);
  document.body.appendChild(overlay);
  wsRenderShell();
}

function wsLangRowHtml() {
  var cur = getLang();
  var langs = [
    { code: 'uz', flag: '🇺🇿', label: "O'zbekcha" },
    { code: 'en', flag: '🇬🇧', label: 'English' },
    { code: 'ru', flag: '🇷🇺', label: 'Русский' }
  ];
  return '<div id="ws-lang-row" style="display:flex;justify-content:center;gap:6px;margin-bottom:12px">' +
    langs.map(function (l) {
      var isSel = cur === l.code;
      return '<button type="button" class="ws-lang-btn" data-lang="' + l.code + '" title="' + l.label + '" style="padding:5px 10px;border-radius:var(--radius-full);border:1px solid ' + (isSel ? 'var(--accent)' : 'var(--border)') + ';background:' + (isSel ? 'rgba(124,92,252,0.15)' : 'var(--surface2)') + ';color:var(--text);font-size:var(--fs-xs);font-weight:700;cursor:pointer;font-family:\'DM Sans\',sans-serif;line-height:1">' + l.flag + ' ' + l.code.toUpperCase() + '</button>';
    }).join('') +
  '</div>';
}

function wsAttachLangHandlers() {
  document.querySelectorAll('.ws-lang-btn').forEach(function (btn) {
    btn.onclick = function () {
      var code = btn.getAttribute('data-lang');
      if (getLang() === code) return;
      if (!S.profile) S.profile = {};
      S.profile.language = code;
      try { save(); } catch (e) {}
      try { applyLanguage(); } catch (e) {}
      wsRenderShell(); // wsState (step, tanlovlar) saqlanib qoladi — faqat matnlar yangi tilga o'tadi
    };
  });
}

function wsRenderShell() {
  var box = document.getElementById('ws-box');
  if (!box) return;
  box.innerHTML =
    '<div id="ws-skip-row"></div>' +
    wsLangRowHtml() +
    (wsState.miniMode ? '' :
      '<div style="text-align:center;font-family:Syne,sans-serif;font-size:var(--fs-md);font-weight:700;color:var(--text);margin-bottom:4px">' + t('ws_modal_title') + '</div>' +
      '<div class="onboarding-tt-dots" id="ws-dots" style="justify-content:center;margin:10px 0 16px"></div>'
    ) +
    '<div id="ws-body"></div>';
  wsAttachLangHandlers();
  wsRenderStep();
}

function wsRenderSkipRow() {
  var row = document.getElementById('ws-skip-row');
  if (!row) return;
  if (wsState.step >= 2) { row.innerHTML = ''; return; }
  row.innerHTML = '<div style="display:flex;justify-content:flex-end;margin-bottom:2px">' +
    '<button type="button" id="ws-skip-btn" style="background:none;border:none;color:var(--text-muted);font-size:var(--fs-xs);font-weight:600;cursor:pointer;padding:4px 2px;font-family:\'DM Sans\',sans-serif">' + t('ws_skip_btn') + '</button>' +
  '</div>';
  var skipBtn = document.getElementById('ws-skip-btn');
  if (skipBtn) skipBtn.onclick = function () {
    wsState.step = 2;
    wsState.authMode = null;
    wsRenderStep();
  };
}

function wsUpdateDots() {
  var dotsEl = document.getElementById('ws-dots');
  if (!dotsEl) return;
  var html = '';
  for (var i = 0; i < WS_TOTAL_STEPS; i++) {
    var cls = i === wsState.step ? 'active' : (i < wsState.step ? 'done' : '');
    html += '<span class="' + cls + '"></span>';
  }
  dotsEl.innerHTML = html;
}

function wsCanProceed() {
  if (wsState.step === 0) {
    if (!wsState.goal) return false;
    if (wsState.goal === 'other' && !(wsState.goalOther || '').trim()) return false;
    return true;
  }
  if (wsState.step === 1) {
    if (!wsState.ref) return false;
    if (wsState.ref === 'other' && !(wsState.refOther || '').trim()) return false;
    return true;
  }
  return true;
}

function wsUpdateNextButtonState() {
  var btn = document.getElementById('ws-next-btn');
  if (!btn) return;
  btn.disabled = !wsCanProceed();
}

// Har bir qadamni #ws-body ichiga chizadi (input/pill/tugmalar bilan birga).
function wsRenderStep() {
  var body = document.getElementById('ws-body');
  if (!body) return;
  wsUpdateDots();
  wsRenderSkipRow();

  var fieldStyle = "width:100%;box-sizing:border-box;padding:10px 12px;background:var(--surface2);border:1px solid var(--border);border-radius:var(--radius-sm);color:var(--text);font-size:var(--fs-sm);outline:none;margin-top:10px;font-family:'DM Sans',sans-serif";
  var descStyle = 'font-size:var(--fs-xs);color:var(--text-muted);line-height:1.6;margin-bottom:2px';
  var titleStyle = 'font-family:Syne,sans-serif;font-size:var(--fs-base);font-weight:700;color:var(--text);margin-bottom:6px';

  var html = '';

  if (wsState.step === 0) {
    html +=
      '<div style="' + titleStyle + '">' + t('ws_step_goal_title') + '</div>' +
      '<div style="' + descStyle + '">' + t('ws_step_goal_desc') + '</div>' +
      '<div id="ws-goal-pills" style="display:flex;flex-wrap:wrap;gap:8px;margin-top:10px">' +
        ['sat', 'ielts', 'cefr', 'other'].map(function (code) {
          var isSel = wsState.goal === code;
          var label = code === 'sat' ? t('ws_goal_sat') : code === 'ielts' ? t('ws_goal_ielts') : code === 'cefr' ? t('ws_goal_cefr') : t('ws_goal_other');
          return '<button type="button" class="pe-prep-pill' + (isSel ? ' sel' : '') + '" data-goal="' + code + '"><span class="pe-prep-check">✅</span>' + label + '</button>';
        }).join('') +
      '</div>' +
      (wsState.goal === 'other' ?
        '<input id="ws-goal-other-input" type="text" maxlength="15" placeholder="' + t('ws_goal_other_ph') + '" value="' + esc(wsState.goalOther) + '" style="' + fieldStyle + '" />'
        : '') +
      '<div class="onboarding-tt-actions" style="margin-top:16px">' +
        '<button class="onboarding-btn onboarding-btn-primary" id="ws-next-btn" style="flex:1"' + (wsCanProceed() ? '' : ' disabled') + '>' + t('guide_next_btn') + '</button>' +
      '</div>';
  } else if (wsState.step === 1) {
    html +=
      '<div style="' + titleStyle + '">' + t('ws_step_ref_title') + '</div>' +
      '<div style="' + descStyle + '">' + t('ws_step_ref_desc') + '</div>' +
      '<div id="ws-ref-pills" style="display:flex;flex-wrap:wrap;gap:8px;margin-top:10px">' +
        ['ai', 'youtube', 'instagram', 'friend', 'other'].map(function (code) {
          var isSel = wsState.ref === code;
          var label = code === 'ai' ? t('ws_ref_ai') : code === 'youtube' ? t('ws_ref_youtube') : code === 'instagram' ? t('ws_ref_instagram') : code === 'friend' ? t('ws_ref_friend') : t('ws_ref_other');
          return '<button type="button" class="pe-prep-pill' + (isSel ? ' sel' : '') + '" data-ref="' + code + '"><span class="pe-prep-check">✅</span>' + label + '</button>';
        }).join('') +
      '</div>' +
      (wsState.ref === 'other' ?
        '<input id="ws-ref-other-input" type="text" maxlength="120" placeholder="' + t('ws_ref_other_ph') + '" value="' + esc(wsState.refOther) + '" style="' + fieldStyle + '" />'
        : '') +
      '<div class="onboarding-tt-actions" style="margin-top:16px">' +
        '<button class="onboarding-btn onboarding-btn-ghost" id="ws-back-btn">' + t('guide_back_btn') + '</button>' +
        '<button class="onboarding-btn onboarding-btn-primary" id="ws-next-btn"' + (wsCanProceed() ? '' : ' disabled') + '>' + t('guide_next_btn') + '</button>' +
      '</div>';
  } else if (wsState.step === 2) {
    if (!wsState.authMode) {
      html +=
        '<div style="' + titleStyle + '">' + (wsState.miniMode ? t('ws_account_link_title') : t('ws_step_auth_title')) + '</div>' +
        '<div style="' + descStyle + '">' + (wsState.miniMode ? t('ws_account_link_desc') : t('ws_step_auth_desc')) + '</div>' +
        '<div style="display:flex;flex-direction:column;gap:8px;margin-top:14px">' +
          (wsState.miniMode ? '' :
            '<button type="button" id="ws-mode-guest" style="padding:12px;border-radius:var(--radius-md);border:1px dashed var(--border-hover);background:transparent;color:var(--text-muted);font-size:var(--fs-sm);font-weight:600;cursor:pointer;font-family:\'DM Sans\',sans-serif">' + t('ws_auth_guest_btn') + '</button>' +
            '<div style="display:flex;align-items:center;gap:10px;margin:2px 0"><div style="flex:1;height:1px;background:var(--border)"></div><span style="font-size:var(--fs-2xs);color:var(--text-dim)">' + t('ws_login_or') + '</span><div style="flex:1;height:1px;background:var(--border)"></div></div>'
          ) +
          '<button type="button" id="ws-mode-register" style="padding:12px;border-radius:var(--radius-md);border:none;background:var(--accent);color:#fff;font-size:var(--fs-sm);font-weight:700;cursor:pointer;font-family:\'DM Sans\',sans-serif">' + t('ws_auth_register_btn') + '</button>' +
          '<button type="button" id="ws-mode-login" style="padding:12px;border-radius:var(--radius-md);border:1px solid var(--border-hover);background:var(--surface2);color:var(--text);font-size:var(--fs-sm);font-weight:600;cursor:pointer;font-family:\'DM Sans\',sans-serif">' + t('ws_auth_login_btn') + '</button>' +
        '</div>' +
        '<div class="onboarding-tt-actions" style="margin-top:16px">' +
          '<button class="onboarding-btn onboarding-btn-ghost" id="ws-back-btn" style="flex:1">' + t(wsState.miniMode ? 'btn_cancel' : 'guide_back_btn') + '</button>' +
        '</div>';
    } else if (wsState.authMode === 'register') {
      html +=
        '<div style="' + titleStyle + '">' + t('ws_reg_title') + '</div>' +
        '<div style="' + descStyle + '">' + t('ws_reg_desc') + '</div>' +
        '<button type="button" class="onboarding-btn onboarding-btn-ghost" id="ws-google-btn" style="width:100%;margin-bottom:10px">' + t('ws_reg_google_btn') + '</button>' +
        '<input id="ws-reg-name-input" type="text" maxlength="' + USERNAME_MAX_LEN + '" placeholder="' + t('ws_reg_name_ph') + '" value="' + esc(wsState.regName) + '" style="' + fieldStyle + '" />' +
        '<input id="ws-reg-email-input" type="email" placeholder="' + t('ws_reg_email_ph') + '" value="' + esc(wsState.regEmail || '') + '" style="' + fieldStyle + '" />' +
        '<input id="ws-reg-pass-input" type="password" placeholder="' + t('ws_reg_pass_ph') + '" value="' + esc(wsState.regPass || '') + '" style="' + fieldStyle + '" />' +
        '<div class="onboarding-tt-actions" style="margin-top:16px">' +
          '<button class="onboarding-btn onboarding-btn-ghost" id="ws-back-btn">' + t('guide_back_btn') + '</button>' +
          '<button class="onboarding-btn onboarding-btn-primary" id="ws-reg-submit-btn">' + t('ws_reg_submit_btn') + '</button>' +
        '</div>';
    } else if (wsState.authMode === 'login') {
      html +=
        '<div style="' + titleStyle + '">' + t('ws_login_title') + '</div>' +
        '<div style="' + descStyle + '">' + t('ws_login_desc_simple') + '</div>' +
        '<button type="button" class="onboarding-btn onboarding-btn-ghost" id="ws-google-btn" style="width:100%;margin-bottom:10px">' + t('ws_login_google_btn') + '</button>' +
        '<input id="ws-login-email-input" type="email" placeholder="' + t('ws_login_email_ph') + '" value="' + esc(wsState.loginEmail || '') + '" style="' + fieldStyle + '" />' +
        '<input id="ws-login-pass-input" type="password" placeholder="' + t('ws_login_pass_ph') + '" value="' + esc(wsState.loginPass || '') + '" style="' + fieldStyle + '" />' +
        '<div id="ws-forgot-link" style="text-align:right;font-size:12px;opacity:.75;cursor:pointer;margin-top:-4px;text-decoration:underline">' + _cl('Parolni unutdingizmi?', 'Forgot password?', 'Забыли пароль?') + '</div>' +
        '<div class="onboarding-tt-actions" style="margin-top:16px">' +
          '<button class="onboarding-btn onboarding-btn-ghost" id="ws-back-btn">' + t('guide_back_btn') + '</button>' +
          '<button class="onboarding-btn onboarding-btn-primary" id="ws-login-submit-btn">' + t('ws_login_submit_btn') + '</button>' +
        '</div>';
    }
  }

  body.innerHTML = html;
  wsAttachHandlers();
}

function wsAttachHandlers() {
  var nextBtn = document.getElementById('ws-next-btn');
  var backBtn = document.getElementById('ws-back-btn');
  if (nextBtn) nextBtn.onclick = wsNext;
  if (backBtn) backBtn.onclick = wsBack;

  var goalOtherInput = document.getElementById('ws-goal-other-input');
  if (goalOtherInput) goalOtherInput.oninput = function () {
    var cleaned = goalOtherInput.value
      .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}\u{2B00}-\u{2BFF}\u{FE00}-\u{FE0F}\u{200D}]/gu, '')
      .slice(0, 15);
    if (cleaned !== goalOtherInput.value) {
      var pos = goalOtherInput.selectionStart - (goalOtherInput.value.length - cleaned.length);
      goalOtherInput.value = cleaned;
      try { goalOtherInput.setSelectionRange(pos, pos); } catch(e) {}
    }
    wsState.goalOther = goalOtherInput.value;
    wsUpdateNextButtonState();
  };

  var refOtherInput = document.getElementById('ws-ref-other-input');
  if (refOtherInput) refOtherInput.oninput = function () { wsState.refOther = refOtherInput.value; wsUpdateNextButtonState(); };

  document.querySelectorAll('#ws-goal-pills .pe-prep-pill').forEach(function (btn) {
    btn.onclick = function () { wsState.goal = btn.getAttribute('data-goal'); wsRenderStep(); };
  });
  document.querySelectorAll('#ws-ref-pills .pe-prep-pill').forEach(function (btn) {
    btn.onclick = function () { wsState.ref = btn.getAttribute('data-ref'); wsRenderStep(); };
  });

  // ── Yakuniy qadam: Mehmon (avtomatik ism) / O'zi tanlagan ism ──
  var modeGuestBtn = document.getElementById('ws-mode-guest');
  if (modeGuestBtn) modeGuestBtn.onclick = wsGuestLogin;
  var modeRegisterBtn = document.getElementById('ws-mode-register');
  if (modeRegisterBtn) modeRegisterBtn.onclick = function () { wsState.authMode = 'register'; wsRenderStep(); };
  var modeLoginBtn = document.getElementById('ws-mode-login');
  if (modeLoginBtn) modeLoginBtn.onclick = function () { wsState.authMode = 'login'; wsRenderStep(); };

  // Ro'yxatdan o'tish formasi — Supabase Auth orqali haqiqiy akkaunt yaratadi
  var regNameInput = document.getElementById('ws-reg-name-input');
  if (regNameInput) regNameInput.oninput = function () { wsState.regName = regNameInput.value; };
  var regEmailInput = document.getElementById('ws-reg-email-input');
  if (regEmailInput) regEmailInput.oninput = function () { wsState.regEmail = regEmailInput.value; };
  var regPassInput = document.getElementById('ws-reg-pass-input');
  if (regPassInput) regPassInput.oninput = function () { wsState.regPass = regPassInput.value; };
  var regSubmitBtn = document.getElementById('ws-reg-submit-btn');
  if (regSubmitBtn) regSubmitBtn.onclick = function () { wsSubmitRegister(); };

  // Kirish formasi — Supabase Auth orqali mavjud akkauntga kiradi
  var loginEmailInput = document.getElementById('ws-login-email-input');
  if (loginEmailInput) loginEmailInput.oninput = function () { wsState.loginEmail = loginEmailInput.value; };
  var loginPassInput = document.getElementById('ws-login-pass-input');
  if (loginPassInput) loginPassInput.oninput = function () { wsState.loginPass = loginPassInput.value; };
  var loginSubmitBtn = document.getElementById('ws-login-submit-btn');
  if (loginSubmitBtn) loginSubmitBtn.onclick = function () { wsSubmitLogin(); };
  var googleBtn = document.getElementById('ws-google-btn');
  if (googleBtn) googleBtn.onclick = function () { cloudGoogleSignIn(); };
  var forgotLink = document.getElementById('ws-forgot-link');
  if (forgotLink) forgotLink.onclick = function () { cloudForgotPassword(); };
}

function wsNext() {
  if (!wsCanProceed()) return; // ehtiyot chorasi — tugma disabled bo'lsa ham bosilib qolishining oldini oladi
  wsState.step++;
  wsRenderStep();
}

function wsBack() {
  // Yakuniy qadamda avval "Register/Login" tanlovi tanlangan bo'lsa,
  // Orqaga tugmasi avval o'sha tanlov ekraniga qaytaradi, keyin qadamlar bo'ylab.
  if (wsState.step === 2 && wsState.authMode) {
    wsState.authMode = null;
    wsRenderStep();
    return;
  }
  if (wsState.miniMode) {
    closeWelcomeSurvey();
    return;
  }
  if (wsState.step > 0) {
    wsState.step--;
    wsRenderStep();
  }
}


function wsSetAuthBusy(btnId, busy, busyLabel) {
  var btn = document.getElementById(btnId);
  if (!btn) return;
  if (busy) { btn.dataset.origLabel = btn.innerHTML; btn.innerHTML = busyLabel; btn.disabled = true; btn.style.opacity = '0.6'; }
  else { if (btn.dataset.origLabel) btn.innerHTML = btn.dataset.origLabel; btn.disabled = false; btn.style.opacity = '1'; }
}

/* wsSubmitRegister: blok boshiga (global var sifatida) ko'chirildi */

/* wsSubmitLogin: blok boshiga (global var sifatida) ko'chirildi */

function wsGuestLogin() {
  wsFinish('guest', 'ws_guest_success_toast');
}

// Global reyting shu jadvaldan o'qiydi (qarang: fbFetchLeaderboard), shuning
// uchun reytingda ko'rinishi kerak bo'lgan HAMMA maydon shu yerda yoziladi.
function _cloudTasksCompletedCount() {
  var n = 0;
  if (S.taskDoneLog) {
    Object.keys(S.taskDoneLog).forEach(function (id) { n += (S.taskDoneLog[id] || []).length; });
  }
  return n;
}

var _cloudSyncTimer = null;
function scheduleCloudSync(immediate) {
  if (!S.cloudLinked || !S.cloudUserId) return;
  // Bulutdan holat tiklanmaguncha profilni yozmaymiz (tasks_completed/coins
  // yangi qurilmada nol bo'lib bulutni bosib yubormasligi uchun).
  if (!window._cloudPullDone) return;
  if (_cloudSyncTimer) clearTimeout(_cloudSyncTimer);
  var run = async function () {
    _cloudSyncTimer = null;
    if (!S.cloudLinked || !S.cloudUserId) return;
    var photoUrl = (S.profile && S.profile.photo) || null;
    try { if (typeof cloudResolveAvatarUrl === 'function') photoUrl = await cloudResolveAvatarUrl(); } catch (e) {}
    var stamp = new Date().toISOString();
    window._lastProfilePushAt = stamp;
    supabase.from('profiles').upsert({
      id: S.cloudUserId,
      name: (S.profile && S.profile.name) || null,
      photo: photoUrl,
      country: (S.profile && S.profile.country) || null,
      language: (S.profile && S.profile.language) || null,
      target_subjects: (S.profile && S.profile.targetSubjects) || [],
      app_goal_other: (S.profile && S.profile.appGoalOther) || '',
      joined_date: (S.profile && S.profile.joinedDate) || null,
      coins: S.coins || 0,
      total_coins: S.totalCoins || 0,
      season_coins: Math.max(0, (S.coins || 0) - (S.reytingSeasonCoinsBase || 0)),
      xp: S.xp || 0,
      level: (typeof getLevel === 'function' ? getLevel(S.xp || 0).level : 1) || 1,
      streak: S.streak || 0,
      best_streak: S.bestStreak || S.streak || 0,
      tasks_completed: _cloudTasksCompletedCount(),
      updated_at: stamp
    }).then(function (r) {
      if (r.error) console.warn('[Cloud sync] xatolik:', r.error.message);
    });
  };
  if (immediate) run(); else _cloudSyncTimer = setTimeout(run, 1500);
}

// ---------------- GLOBAL REYTING: Supabase'dan ro'yxat olish ----------------
// fetchReytingList() shu funksiyani window.fbFetchLeaderboard orqali chaqiradi.
// scope: 'global' | 'local' (local — S.profile.country bo'yicha filtr)
// metric: 'coins' (season_coins ustuni) | 'streak' | 'xp' (default)
// subjectFilter: 'all' | 'ielts' | 'sat' | 'cefr'
window.fbFetchLeaderboard = async function (scope, metric, subjectFilter) {
  var col = metric === 'coins' ? 'season_coins' : (metric === 'streak' ? 'streak' : 'xp');
  var q = supabase.from('profiles')
    .select('id,name,photo,country,coins,total_coins,season_coins,xp,level,streak,best_streak,tasks_completed,joined_date,target_subjects,app_goal_other')
    .order(col, { ascending: false })
    .limit(100);
  if (scope === 'local') {
    var myCountry = (S.profile && S.profile.country) || null;
    if (!myCountry) return { list: [], noCountry: true };
    q = q.eq('country', myCountry);
  }
  if (subjectFilter && subjectFilter !== 'all') {
    q = q.contains('target_subjects', [subjectFilter]);
  }
  var res = await q;
  if (res.error) throw res.error;
  var list = (res.data || []).map(function (r) {
    return {
      id: r.id,
      name: r.name || '???',
      photo: r.photo || null,
      country: r.country || null,
      coins: r.coins || 0,
      totalCoins: r.total_coins || 0,
      seasonCoins: r.season_coins || 0,
      xp: r.xp || 0,
      level: r.level || (typeof getLevel === 'function' ? getLevel(r.xp || 0).level : 1),
      streak: r.streak || 0,
      streakRecord: r.best_streak || r.streak || 0,
      tasksCompleted: r.tasks_completed || 0,
      joinedDate: r.joined_date || null,
      targetSubjects: r.target_subjects || [],
      appGoalOther: r.app_goal_other || '',
      isMe: false
    };
  });
  return { list: list, noCountry: false };
};

/* wsCheckSupabaseSession: blok boshiga (global var sifatida) ko'chirildi */

// ============================================================
// 📡 REALTIME — boshqa qurilma/sessiyada o'zgarish bo'lsa avtomatik yangilanish
// ------------------------------------------------------------
// startRealtimeSync() login muvaffaqiyatli bo'lganda (wsFinish/
// wsCheckSupabaseSession ichida) chaqiriladi, stopRealtimeSync()
// esa cloudLogout() ichida — akkaunt almashganda eski kanal
// osilib qolmasligi uchun.
// ============================================================
var _realtimeChannel = null;

function startRealtimeSync() {
  if (!S.cloudLinked || !S.cloudUserId || _realtimeChannel) return;

  _realtimeChannel = supabase.channel('user-sync-' + S.cloudUserId)
    // --- Tasklar: shu akkaunt boshqa qurilmada o'zgartirsa ---
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'todos',
      filter: 'user_id=eq.' + S.cloudUserId
    }, function (payload) {
      if (payload.eventType === 'DELETE') {
        var delId = payload.old && payload.old.task_id;
        if (delId == null || !(delId in _lastSyncedTasks)) return; // o'zimiz o'chirgan edik
        delete _lastSyncedTasks[delId];
        S.tasks = (S.tasks || []).filter(function (tk) { return tk.id !== delId; });
      } else {
        var row = payload.new;
        if (!row) return;
        var json = JSON.stringify(row.task_data);
        if (_lastSyncedTasks[row.task_id] === json) return; // o'zimiz yuborgan yozuv, qayta ishlamaymiz
        _lastSyncedTasks[row.task_id] = json;
        var idx = (S.tasks || []).findIndex(function (tk) { return tk.id === row.task_id; });
        if (idx >= 0) S.tasks[idx] = row.task_data; else (S.tasks = S.tasks || []).push(row.task_data);
      }
      try { renderTaskList(); } catch (e) {}
      try { writeLocalTasks(S.tasks || []); } catch (e) {}
      toast(t('realtime_updated_toast'));
    })
    // --- Profil: shu akkaunt boshqa qurilmada/sessiyada o'zgartirsa (tanga, xp, streak...) ---
    .on('postgres_changes', {
      event: 'UPDATE', schema: 'public', table: 'profiles',
      filter: 'id=eq.' + S.cloudUserId
    }, function (payload) {
      var p = payload.new;
      if (!p) return;
      if (p.updated_at && p.updated_at === window._lastProfilePushAt) return; // o'zimiz yuborgan yozuv
      if ((p.coins || 0) === (S.coins || 0) && (p.xp || 0) === (S.xp || 0) && (p.streak || 0) === (S.streak || 0) && (p.total_coins || 0) === (S.totalCoins || 0)) return;
      S.coins = p.coins || 0;
      S.totalCoins = p.total_coins || 0;
      S.xp = p.xp || 0;
      S.streak = p.streak || 0;
      S.bestStreak = p.best_streak || S.streak || 0;
      try { render(); } catch (e) {}
      toast(t('realtime_updated_toast'));
    })
    // --- Do'stlik so'rovlari: menga kelgan yoki men yuborgan so'rov holati o'zgarsa ---
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'friend_requests',
      filter: 'to_id=eq.' + S.cloudUserId
    }, function () { friendsSyncFromCloud(); toast(t('realtime_updated_toast')); })
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'friend_requests',
      filter: 'from_id=eq.' + S.cloudUserId
    }, function () { friendsSyncFromCloud(); toast(t('realtime_updated_toast')); })
    // --- Do'stlik: yangi do'st qo'shilsa yoki o'chirilsa (ikkala tomondan ham) ---
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'friendships',
      filter: 'user_id=eq.' + S.cloudUserId
    }, function () { friendsSyncFromCloud(); toast(t('realtime_updated_toast')); })
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'friendships',
      filter: 'friend_id=eq.' + S.cloudUserId
    }, function () { friendsSyncFromCloud(); toast(t('realtime_updated_toast')); })
    // --- Party takliflari: menga kelgan yoki men (lider sifatida) yuborgan ---
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'party_invites',
      filter: 'to_id=eq.' + S.cloudUserId
    }, function () { partySyncFromCloud(); toast(t('realtime_updated_toast')); })
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'party_invites',
      filter: 'from_id=eq.' + S.cloudUserId
    }, function () { partySyncFromCloud(); toast(t('realtime_updated_toast')); })
    // --- 1v1 Musobaqa (duels): menga tegishli yangi/o'zgargan yozuvlar ---
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'duels',
      filter: 'from_id=eq.' + S.cloudUserId
    }, function () { duelsSyncFromCloud(); toast(t('realtime_updated_toast')); })
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'duels',
      filter: 'to_id=eq.' + S.cloudUserId
    }, function () { duelsSyncFromCloud(); toast(t('realtime_updated_toast')); })
    // --- World Party: ro'yxat (browse) barcha foydalanuvchilarga tegishli
    // bo'lgani uchun filtrsiz tinglaymiz (yangi partiya, a'zo o'zgarishi va h.k.) ---
    .on('postgres_changes', { event: '*', schema: 'public', table: 'world_parties' },
      function () { worldPartySyncFromCloud(); })
    .on('postgres_changes', { event: '*', schema: 'public', table: 'world_party_members' },
      function () { worldPartySyncFromCloud(); })
    // --- Do'kon xaridlari/ishlatilgan mukofotlar: boshqa qurilmada yangi yozuv bo'lsa ---
    .on('postgres_changes', {
      event: 'INSERT', schema: 'public', table: 'reward_log', filter: 'user_id=eq.' + S.cloudUserId
    }, function () { rewardLogSyncFromCloud(); })
    // --- Pomodoro: boshqa qurilmada yangi seans/tanaffus yozilsa ---
    .on('postgres_changes', {
      event: 'INSERT', schema: 'public', table: 'pomo_log', filter: 'user_id=eq.' + S.cloudUserId
    }, function () { if (typeof window.pomoSyncFromCloud === 'function') window.pomoSyncFromCloud(); })
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'pomo_break_stats', filter: 'user_id=eq.' + S.cloudUserId
    }, function () { if (typeof window.pomoSyncFromCloud === 'function') window.pomoSyncFromCloud(); })
    .subscribe();

  friendsSyncFromCloud();
  partySyncFromCloud();
  duelsSyncFromCloud();
  worldPartySyncFromCloud();
  rewardLogSyncFromCloud();
  if (typeof window.pomoSyncFromCloud === 'function') window.pomoSyncFromCloud();
}

function stopRealtimeSync() {
  if (_realtimeChannel) {
    supabase.removeChannel(_realtimeChannel);
    _realtimeChannel = null;
  }
  if (_partyChannel) {
    try { supabase.removeChannel(_partyChannel); } catch (e) {}
    _partyChannel = null;
    _partyChannelId = null;
  }
}

/* cloudLogout: blok boshiga (global var sifatida) ko'chirildi */

function wsFinish(method, toastKey) {
  if (!S.profile) S.profile = {};

  var nameVal = (wsState.name || '').trim();
  if (nameVal) {
    var currentName = S.profile.name;
    var valid = nameVal.length >= 3 && nameVal.length <= USERNAME_MAX_LEN &&
      USERNAME_ALLOWED_REGEX.test(nameVal) && !isUsernameBlocked(nameVal) && !isUsernameTaken(nameVal, currentName);
    if (valid) applyUsernameChange(nameVal);
  }

  if (wsState.goal) {
    S.profile.appGoal = wsState.goal;
    S.profile.appGoalOther = wsState.goal === 'other'
      ? (wsState.goalOther || '').trim().replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}\u{2B00}-\u{2BFF}\u{FE00}-\u{FE0F}\u{200D}]/gu, '').slice(0, 15)
      : '';
    if (!Array.isArray(S.profile.targetSubjects)) S.profile.targetSubjects = [];
    if (S.profile.targetSubjects.indexOf(wsState.goal) === -1) S.profile.targetSubjects.push(wsState.goal);
    if (wsState.goal === 'sat' || wsState.goal === 'ielts') {
      S.profile.prep = wsState.goal; // orqaga moslik uchun eski bitta-qiymatli maydon
    }
  }

  if (wsState.ref) {
    S.profile.referralSource = wsState.ref;
    S.profile.referralOther = wsState.ref === 'other' ? (wsState.refOther || '').trim() : '';
  }

  // Sozlamalar qadamida tanlangan Fon tovushlari / Qiyinlik.
  try { ensureAmbientFocusDefaults(); } catch (e) {}
  S.ambientFocusEnabled = !!wsState.ambientFocusEnabled;
  S.difficulty = (typeof DIFFICULTY_MULTIPLIERS !== 'undefined' && DIFFICULTY_MULTIPLIERS[wsState.difficulty]) ? wsState.difficulty : 'normal';

  S.profile.loginMethod = method;
  S.welcomeSurveyDone = true;
  save();

  try { updateHeaderUserTitle(); } catch (e) {}
  try { if (typeof renderProfile === 'function') renderProfile(); } catch (e) {}
  try { if (typeof updatePcToggleUI === 'function') updatePcToggleUI(); } catch (e) {}
  try { if (typeof updateFocusToggleUI === 'function') updateFocusToggleUI(); } catch (e) {}
  try { if (typeof updateDifficultySelectUI === 'function') updateDifficultySelectUI(); } catch (e) {}
  try { render(); } catch (e) {}
  try { updateIeltsTabVisibility(); } catch (e) {}

  closeWelcomeSurvey();
  if (typeof toast === 'function') toast(t(toastKey || 'onb_finish_toast'));

  setTimeout(function () {
    if (typeof showConfirmModal === 'function' && typeof startOnboardingTour === 'function') {
      showConfirmModal(t('onb_teach_prompt_msg'), function () {
        startOnboardingTour();
      }, { icon: '🧭', confirmLabel: t('onb_teach_prompt_yes') });
    }
  }, 450);

  if (document.getElementById('profile-edit-modal') && typeof showProfileEdit === 'function') {
    try { showProfileEdit(); } catch (e) {}
  }
}

