// Eslatma: FRIENDS_DEMO_DIRECTORY (soxta demo foydalanuvchilar ro'yxati)
// endi kerak emas — qidiruv endi supabase.from('profiles') orqali
// haqiqiy foydalanuvchilarni topadi (friendsRenderSearch funksiyasiga qarang).


function friendsGenerateId() {
  var base = (getDisplayUsername() || 'USER').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8) || 'USER';
  return base + '-' + Math.floor(1000 + Math.random() * 9000);
}

var FRIENDS_AVATAR_GRADIENTS = [
  ['#7C5CFC', '#5B3FD4'], ['#F5A623', '#D48806'], ['#34D399', '#059669'],
  ['#60A5FA', '#2563EB'], ['#F87171', '#DC2626'], ['#EC4899', '#BE185D'],
  ['#22D3EE', '#0891B2'], ['#A78BFA', '#7C3AED']
];
function friendsInitials(name) {
  var parts = String(name || '?').trim().split(/\s+/);
  var s = (parts[0] ? parts[0][0] : '') + (parts[1] ? parts[1][0] : '');
  return (s || '?').toUpperCase();
}
// f = {id,name,icon,avatarUrl}. Qaytaradi: { inner: <img> yoki matn HTML, cls, style }
function friendsAvatarParts(f) {
  if (f && f.avatarUrl) {
    return { inner: '<img src="' + esc(f.avatarUrl) + '" alt="' + esc(f.name || '') + '" />', cls: '', style: '' };
  }
  if (f && f.icon) {
    return { inner: esc(f.icon), cls: '', style: '' };
  }
  var h = _friendsHash(String((f && (f.id || f.name)) || '?'));
  var g = FRIENDS_AVATAR_GRADIENTS[h % FRIENDS_AVATAR_GRADIENTS.length];
  return {
    inner: esc(friendsInitials(f && f.name)),
    cls: ' fallback-gradient',
    style: 'background:linear-gradient(135deg,' + g[0] + ',' + g[1] + ');color:#fff;font-weight:800;'
  };
}
function friendsAvatarHtml(f, extraAttrs, showStatus) {
  var p = friendsAvatarParts(f);
  var dot = '';
  if (showStatus && f && f.id) {
    var online = friendsIsOnline(f.id);
    dot = '<span class="friend-status-dot' + (online ? ' online' : ' offline') + '" title="' + esc(t(online ? 'friends_status_online' : 'friends_status_offline')) + '"></span>';
  }
  return '<div class="friend-avatar' + p.cls + '"' + (p.style ? ' style="' + p.style + '"' : '') + (extraAttrs || '') + '>' + p.inner + dot + '</div>';
}
function friendsIsOnline(id) {
  var bucket = Math.floor(Date.now() / 300000); // har 5 daqiqada bir yangilanadi
  var h = _friendsHash(String(id) + ':' + bucket);
  return (h % 100) < 55; // taxminan ~55% ehtimollik bilan "onlayn"
}

