// ============================================================
var _partyChannel = null;
var _partyChannelId = null;
var _partyCloudSyncing = false;

function _subscribePartyChannel(partyId) {
  if (partyId === _partyChannelId) return; // o'zgarish yo'q, qayta ulanmaymiz
  if (_partyChannel) { try { supabase.removeChannel(_partyChannel); } catch (e) {} _partyChannel = null; }
  _partyChannelId = partyId;
  if (!partyId) return;
  _partyChannel = supabase.channel('party-' + partyId)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'party_members', filter: 'party_id=eq.' + partyId },
      function () { partySyncFromCloud(); toast(t('realtime_updated_toast')); })
    .on('postgres_changes', { event: '*', schema: 'public', table: 'parties', filter: 'id=eq.' + partyId },
      function () { partySyncFromCloud(); toast(t('realtime_updated_toast')); })
    .subscribe();
}

/* partySyncFromCloud: blok boshiga (global var sifatida) ko'chirildi */

