function ensureFriendsDefaults() {
  if (!S.friends) {
    S.friends = { myId: null, list: [], incoming: [], outgoing: [], banned: [], acceptRequestsEnabled: true, parties: [], challenges: [], challengesIncoming: [], challengesOutgoing: [], worldParties: [], partyInvitesIncoming: [], partyInvitesOutgoing: [], myWorldPartyId: null, nextChallengeId: 1, nextPartyId: 1, nextWorldPartyId: 1, seeded: false };
  }
  var F = S.friends;
  if (!F.myId) F.myId = friendsGenerateId();
  if (!Array.isArray(F.list)) F.list = [];
  if (!Array.isArray(F.incoming)) F.incoming = [];
  if (!Array.isArray(F.outgoing)) F.outgoing = [];
  if (!Array.isArray(F.banned)) F.banned = [];
  if (typeof F.acceptRequestsEnabled === 'undefined' || F.acceptRequestsEnabled === null) F.acceptRequestsEnabled = true;
  if (!Array.isArray(F.parties)) F.parties = [];
  if (!Array.isArray(F.challenges)) F.challenges = [];
  if (!Array.isArray(F.challengesIncoming)) F.challengesIncoming = [];
  if (!Array.isArray(F.challengesOutgoing)) F.challengesOutgoing = [];
  if (!Array.isArray(F.challengesHistory)) F.challengesHistory = [];
  if (!Array.isArray(F.partyChallengesHistory)) F.partyChallengesHistory = [];
  if (!Array.isArray(F.worldParties)) F.worldParties = [];
  if (!Array.isArray(F.worldPartiesHistory)) F.worldPartiesHistory = [];
  if (!Array.isArray(F.partyInvitesIncoming)) F.partyInvitesIncoming = [];
  if (!Array.isArray(F.partyInvitesOutgoing)) F.partyInvitesOutgoing = [];
  if (!F.seenRequestIds || typeof F.seenRequestIds !== 'object') F.seenRequestIds = {};
  if (!F.seenPartyInviteIds || typeof F.seenPartyInviteIds !== 'object') F.seenPartyInviteIds = {};
  if (!F.seenChallengeIds || typeof F.seenChallengeIds !== 'object') F.seenChallengeIds = {};
  if (F.myWorldPartyId === undefined) F.myWorldPartyId = null;
  if (!F.nextChallengeId) F.nextChallengeId = 1;
  if (!F.nextPartyId) F.nextPartyId = 1;
  if (!F.nextWorldPartyId) F.nextWorldPartyId = 1;
  if (!F.seeded) { F.seeded = true; }

  if (!F.cleanedFakeDemo) {
    var _FAKE_DEMO_IDS = ['AZIZ-1004', 'DILNOZA-6621'];
    F.list = (F.list || []).filter(function (u) { return _FAKE_DEMO_IDS.indexOf(u.id) === -1; });
    F.incoming = (F.incoming || []).filter(function (u) { return _FAKE_DEMO_IDS.indexOf(u.id) === -1; });
    F.outgoing = (F.outgoing || []).filter(function (u) { return _FAKE_DEMO_IDS.indexOf(u.id) === -1; });
    F.challengesIncoming = (F.challengesIncoming || []).filter(function (c) { return _FAKE_DEMO_IDS.indexOf(c.fromId) === -1; });
    F.challengesOutgoing = (F.challengesOutgoing || []).filter(function (c) { return _FAKE_DEMO_IDS.indexOf(c.opponentId) === -1; });
    F.partyInvitesIncoming = (F.partyInvitesIncoming || []).filter(function (inv) { return _FAKE_DEMO_IDS.indexOf(inv.fromId) === -1; });
    F.partyInvitesOutgoing = (F.partyInvitesOutgoing || []).filter(function (inv) { return _FAKE_DEMO_IDS.indexOf(inv.toId) === -1; });
    F.worldParties = (F.worldParties || []).filter(function (p) { return _FAKE_DEMO_IDS.indexOf(p.creatorId) === -1; });
    if (F.myWorldPartyId && !F.worldParties.some(function (p) { return p.id === F.myWorldPartyId; })) {
      F.myWorldPartyId = null;
    }
    F.cleanedFakeDemo = true;
  }
  friendsReconcileOutgoing();
  try { friendsCheckExpiry(); } catch (e) {}
}

function friendsReconcileOutgoing() {
  var F = S.friends;
  if (!F) return;
  (F.outgoing || []).slice().forEach(function (o) {
    // Eslatma: haqiqiy do'stlik so'rovlari endi Supabase orqali hal bo'ladi
    // (friendsSyncFromCloud/realtime), shuning uchun bu yerda soxta
    // "resolveAt" bo'yicha avtomatik hal qilish endi kerak emas.
  });
  (F.partyInvitesOutgoing || []).slice().forEach(function (inv) {
    // Eslatma: party takliflari endi Supabase orqali hal bo'ladi (partySyncFromCloud/realtime).
  });
  (F.challengesOutgoing || []).slice().forEach(function (c) {
    if (c.resolveAt && Date.now() >= c.resolveAt) _resolveChallengeOutgoing(c.id);
  });
}

// ---------------- MODAL OCHISH / YOPISH / TABLAR ----------------
var _friendsActiveTab = 'list';

function openFriendsModal() {
  ensureFriendsDefaults();
  document.getElementById('friends-modal-overlay').classList.add('open');
  friendsShowTab(_friendsActiveTab || 'list');
}
function closeFriendsModal() {
  document.getElementById('friends-modal-overlay').classList.remove('open');
}
function friendsOpenReyting() {
  closeFriendsModal();
  showTab('reyting');
}
function friendsShowTab(tab) {
  ensureFriendsDefaults();
  _friendsActiveTab = tab;
  if (tab === 'add') { (S.friends.incoming || []).forEach(function (r) { S.friends.seenRequestIds[r.id] = true; }); }
  if (tab === 'party') { (S.friends.partyInvitesIncoming || []).forEach(function (inv) { S.friends.seenPartyInviteIds[inv.id] = true; }); }
  if (tab === 'challenge') { (S.friends.challengesIncoming || []).forEach(function (c) { S.friends.seenChallengeIds[c.id] = true; }); }
  save();
  ['list', 'add', 'party', 'challenge'].forEach(function (k) {
    var panel = document.getElementById('friends-panel-' + k);
    var btn = document.getElementById('friends-tab-' + k);
    if (panel) panel.style.display = (k === tab) ? '' : 'none';
    if (btn) btn.classList.toggle('active', k === tab);
  });
  renderFriendsAll();
}

function renderFriendsAll() {
  ensureFriendsDefaults();
  renderFriendsMyCard();
  renderFriendsList();
  friendsRenderSearch();
  renderFriendsIncoming();
  renderFriendsOutgoing();
  renderFriendsParty();
  renderFriendsChallenges();
  updateFriendsBadges();
}

function updateFriendsBadges() {
  ensureFriendsDefaults();
  var F = S.friends;
  var incomingIds = {}; (F.incoming || []).forEach(function (r) { incomingIds[r.id] = true; });
  Object.keys(F.seenRequestIds).forEach(function (id) { if (!incomingIds[id]) delete F.seenRequestIds[id]; });
  var partyInviteIds = {}; (F.partyInvitesIncoming || []).forEach(function (inv) { partyInviteIds[inv.id] = true; });
  Object.keys(F.seenPartyInviteIds).forEach(function (id) { if (!partyInviteIds[id]) delete F.seenPartyInviteIds[id]; });
  var challengeIds = {}; (F.challengesIncoming || []).forEach(function (c) { challengeIds[c.id] = true; });
  Object.keys(F.seenChallengeIds).forEach(function (id) { if (!challengeIds[id]) delete F.seenChallengeIds[id]; });

  var n = (F.incoming || []).filter(function (r) { return !F.seenRequestIds[r.id]; }).length;
  var headerBadge = document.getElementById('friends-req-badge');
  if (headerBadge) { headerBadge.textContent = n; headerBadge.style.display = n ? 'flex' : 'none'; }
  var addBadge = document.getElementById('friends-add-badge');
  if (addBadge) { addBadge.textContent = n; addBadge.style.display = n ? 'inline-flex' : 'none'; }
  var cn = (F.challengesIncoming || []).filter(function (c) { return !F.seenChallengeIds[c.id]; }).length;
  var challengeBadge = document.getElementById('friends-challenge-badge');
  if (challengeBadge) { challengeBadge.textContent = cn; challengeBadge.style.display = cn ? 'inline-flex' : 'none'; }
  var pn = (F.partyInvitesIncoming || []).filter(function (inv) { return !F.seenPartyInviteIds[inv.id]; }).length;
  var partyBadge = document.getElementById('friends-party-badge');
  if (partyBadge) { partyBadge.textContent = pn; partyBadge.style.display = pn ? 'inline-flex' : 'none'; }
}

// ---------------- MENING KARTAM ----------------
function renderFriendsMyCard() {
  var lv = getLevel(S.xp || 0);
  var avatarEl = document.getElementById('friends-my-avatar');
  var nameEl = document.getElementById('friends-my-name');
  var idEl = document.getElementById('friends-my-id');
  if (avatarEl) avatarEl.textContent = lv.icon;
  if (nameEl) nameEl.textContent = getDisplayUsername();
  if (idEl) idEl.textContent = S.friends.myId;
}
function friendsCopyMyId() {
  var id = S.friends.myId;
  var done = function () { toast(t('friends_id_copied_toast')); };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(id).then(done).catch(done);
  } else { done(); }
}

function friendCardHtml(f, actionsHtml, viewable, showStatus) {
  var mutualChip = (f._mutualCount) ? ' <span class="friend-mutual-chip">' + t('friends_mutual_chip').replace('{n}', f._mutualCount) + '</span>' : '';
  var infoBlock = '<div style="min-width:0;flex:1">'
    + '<div class="friend-name">' + esc(f.name) + mutualChip + '</div>'
    + '<div class="friend-sub">' + esc(f.id) + (f.reason ? ' · 💬 ' + esc(f.reason.length > 40 ? f.reason.slice(0, 40) + '…' : f.reason) : '') + '</div>'
    + '</div>';
  // ✅ TUZATILDI: rasm/emoji yo'q holat uchun endi bo'sh doira o'rniga
  // barqaror gradient + bosh harflar (Avatar Fallback) chiqadi.
  var avatarAndInfo = friendsAvatarHtml(f, null, showStatus) + infoBlock;
  if (viewable) {
    avatarAndInfo = '<div class="friend-card-info" role="button" tabindex="0" '
      + 'onclick="showFriendProfileModal(\'' + esc(f.id) + '\')" '
      + 'onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();showFriendProfileModal(\'' + esc(f.id) + '\')}" '
      + 'title="' + esc(t('friends_view_profile_title')) + '" '
      + 'aria-label="' + esc(t('friends_view_profile_title')) + ': ' + esc(f.name || '') + '" '
      + 'style="cursor:pointer">' + avatarAndInfo + '</div>';
  } else {
    avatarAndInfo = '<div class="friend-card-info">' + avatarAndInfo + '</div>';
  }
  var actionsWrapped = actionsHtml ? '<div class="friend-card-actions">' + actionsHtml + '</div>' : '';
  return '<div class="friend-card">' + avatarAndInfo + actionsWrapped + '</div>';
}

// ---------------- DO'STLARIM RO'YXATI ----------------
// 🆕 QO'SHILDI: "Barchasi / Onlayn / Offlayn" filtri (friendsSetListFilter orqali boshqariladi)
var _friendsListFilter = 'all';
function friendsSetListFilter(mode) {
  _friendsListFilter = mode;
  ['all', 'online', 'offline'].forEach(function (k) {
    var btn = document.getElementById('friends-filter-' + k);
    if (btn) btn.classList.toggle('active', k === mode);
  });
  renderFriendsList();
}
function renderFriendsList() {
  var list = S.friends.list || [];
  var box = document.getElementById('friends-list-container');
  var empty = document.getElementById('friends-list-empty');
  var filterEmpty = document.getElementById('friends-list-filter-empty');
  renderFriendsBannedLink();
  if (!box) return;
  if (!list.length) {
    box.innerHTML = '';
    if (empty) empty.style.display = '';
    if (filterEmpty) filterEmpty.style.display = 'none';
    return;
  }
  if (empty) empty.style.display = 'none';
  var filtered = list.filter(function (f) {
    if (_friendsListFilter === 'online') return friendsIsOnline(f.id);
    if (_friendsListFilter === 'offline') return !friendsIsOnline(f.id);
    return true;
  });
  if (!filtered.length) {
    box.innerHTML = '';
    if (filterEmpty) filterEmpty.style.display = '';
    return;
  }
  if (filterEmpty) filterEmpty.style.display = 'none';
  box.innerHTML = filtered.map(function (f) {
    var actions = '<button class="friend-req-btn decline" onclick="friendsRemoveFriend(\'' + f.id + '\')" data-i18n="friends_remove_btn">O\'chirish</button>';
    return friendCardHtml(f, actions, true, true);
  }).join('');
}
function friendsRemoveFriend(userId) {
  showConfirmModal(esc(t('friends_remove_confirm')), function () {
    (S.friends.parties || []).forEach(function (p) {
      p.members = (p.members || []).filter(function (m) { return m.id !== userId; });
    });
    friendsPurgeRelatedRecords(userId);
    closeFriendProfileModal();
    (async function () {
      var res = await supabase.rpc('remove_friend', { p_other_id: userId });
      if (res.error) { toast('❌ ' + res.error.message); return; }
      await friendsSyncFromCloud();
    })();
  }, { icon: '👋' });
}
function friendsPurgeRelatedRecords(userId) {
  var F = S.friends;
  if (!F) return;
  F.challenges = (F.challenges || []).filter(function (c) {
    if (c.opponentId !== userId) return true;
    if (c.status === 'active') S.coins = (S.coins || 0) + c.stake;
    return false;
  });
  F.challengesOutgoing = (F.challengesOutgoing || []).filter(function (c) {
    if (c.opponentId !== userId) return true;
    S.coins = (S.coins || 0) + c.stake;
    return false;
  });
  F.challengesIncoming = (F.challengesIncoming || []).filter(function (c) { return c.fromId !== userId; });
  F.partyInvitesIncoming = (F.partyInvitesIncoming || []).filter(function (inv) { return inv.fromId !== userId; });
  F.partyInvitesOutgoing = (F.partyInvitesOutgoing || []).filter(function (inv) { return inv.toId !== userId; });
}

// ---------------- QIDIRISH / SO'ROV YUBORISH ----------------
function friendsRenderSearch() {
  var input = document.getElementById('friends-search-input');
  var box = document.getElementById('friends-search-results');
  if (!box) return;
  var q = (input && input.value || '').trim();
  if (!q) { box.innerHTML = ''; _friendsSearchResults = []; return; }
  if (!S.cloudLinked || !S.cloudUserId) {
    box.innerHTML = '<div style="color:var(--text-dim);font-size:var(--fs-xs);text-align:center;padding:10px 0">' + esc('Qidirish uchun avval tizimga kiring') + '</div>';
    return;
  }
  box.innerHTML = '<div style="color:var(--text-dim);font-size:var(--fs-xs);text-align:center;padding:10px 0">…</div>';
  var myReqId = ++_friendsSearchReqId;
  (async function () {
    var excludeIds = (S.friends.list || []).map(function (f) { return f.id; })
      .concat((S.friends.outgoing || []).map(function (f) { return f.id; }))
      .concat((S.friends.incoming || []).map(function (f) { return f.id; }))
      .concat((S.friends.banned || []).map(function (b) { return b.id; }))
      .concat([S.cloudUserId]);
    var query = supabase.from('profiles').select('id,name,photo,level,friend_code');
    var qUpper = q.toUpperCase();
    if (/^[A-Z0-9-]{3,}$/i.test(q)) {
      query = query.or('friend_code.ilike.' + qUpper + ',name.ilike.%' + q + '%');
    } else {
      query = query.ilike('name', '%' + q + '%');
    }
    var res = await query.limit(20);
    if (myReqId !== _friendsSearchReqId) return; // eskirgan so'rov, e'tiborsiz qoldiramiz
    if (res.error) { box.innerHTML = '<div style="color:#F87171;font-size:var(--fs-xs);text-align:center;padding:10px 0">Xatolik yuz berdi</div>'; return; }
    var results = (res.data || []).filter(function (u) { return excludeIds.indexOf(u.id) === -1; });
    _friendsSearchResults = results.map(function (u) { return { id: u.id, name: u.name, avatarUrl: u.photo || null, level: u.level || 1 }; });
    if (!results.length) {
      box.innerHTML = '<div style="color:var(--text-dim);font-size:var(--fs-xs);text-align:center;padding:10px 0">' + t('friends_search_none') + '</div>';
      return;
    }
    box.innerHTML = _friendsSearchResults.map(function (u) {
      var actions = '<button class="friend-req-btn accept" onclick="friendsOpenAddReasonModal(\'' + u.id + '\')" aria-label="' + esc(t('friends_send_btn')) + ' — ' + esc(u.name) + '" data-i18n="friends_send_btn">Yubor</button>';
      return friendCardHtml(u, actions, true, false);
    }).join('');
  })();
}
