function renderFriendsChallenges() {
  friendsCheckExpiry();
  friendsUpdateDueSnapshot();
  renderFriendsChallengeIncoming();
  var pending = S.friends.challengesOutgoing || [];
  var main = S.friends.challenges || [];
  var box = document.getElementById('friends-challenge-list');
  var empty = document.getElementById('friends-challenge-empty');
  if (!box) return;
  if (!pending.length && !main.length) { box.innerHTML = ''; if (empty) empty.style.display = ''; return; }
  if (empty) empty.style.display = 'none';

  var pendingHtml = pending.map(function (c) {
    var sub = friendsCriteriaLabel(c.criteria) + ' · 🪙 ' + c.stake + ' · ' + friendsDurationLabel(c.durationDays);
    return '<div class="friend-card" style="align-items:flex-start;flex-direction:column">'
      + '<div style="display:flex;width:100%;align-items:center;gap:10px">'
      + '<div class="friend-avatar">' + (c.opponentIcon || '⚔️') + '</div>'
      + '<div style="min-width:0;flex:1"><div class="friend-name">⚔️ ' + t('friends_you_label') + ' vs ' + esc(c.opponentName) + '</div><div class="friend-sub">' + sub + '</div></div>'
      + '<span style="font-size:var(--fs-2xs);font-weight:700;color:var(--gold)" data-i18n="friends_pending_label">' + t('friends_pending_label') + '</span>'
      + '</div>'
      + '<button class="friend-req-btn decline" style="width:100%;margin-top:8px" onclick="friendsCancelChallenge(\'' + c.id + '\',true)" data-i18n="friends_cancel_btn">Bekor qilish</button>'
      + '</div>';
  }).join('');

  var mainHtml = main.map(function (c) {
    var cmp = friendsCompareChallenge(c);
    var unit = c.criteria === 'coins' ? ' 🪙' : (c.criteria === 'tasks' ? ' ' + t('friends_unit_tasks') : '%');
    var sub = friendsCriteriaLabel(c.criteria) + ' · 🪙 ' + c.stake + ' · ' + friendsDurationLabel(c.durationDays);
    var statusChip = c.status === 'finished'
      ? '<span style="font-size:var(--fs-2xs);font-weight:700;color:' + (c.winner === 'me' ? 'var(--green)' : c.winner === 'draw' ? 'var(--text-muted)' : 'var(--red)') + '">' + (c.winner === 'me' ? t('friends_you_won') : c.winner === 'draw' ? t('friends_draw_label') : t('friends_you_lost')) + '</span>'
      : '<span style="font-size:var(--fs-2xs);font-weight:700;color:var(--info)">' + friendsTimeLeftLabel(c) + '</span>';
    var meBarPct = Math.min(100, Math.max(0, cmp.meVal));
    var oppBarPct = Math.min(100, Math.max(0, cmp.oppVal));
    var body = '<div style="margin:8px 0;width:100%">'
      + '<div class="duel-vs-bar" style="margin-bottom:6px"><span style="font-size:var(--fs-2xs);width:60px;color:var(--text-muted)">' + t('friends_you_label') + '</span><div class="duel-progress-track"><div class="duel-progress-fill" style="width:' + meBarPct + '%;background:var(--accent)"></div></div><span style="font-size:var(--fs-2xs);color:var(--text-dim)">' + cmp.meVal + unit + '</span></div>'
      + '<div class="duel-vs-bar"><span style="font-size:var(--fs-2xs);width:60px;color:var(--text-muted)">' + esc(c.opponentName) + '</span><div class="duel-progress-track"><div class="duel-progress-fill" style="width:' + oppBarPct + '%;background:var(--gold)"></div></div><span style="font-size:var(--fs-2xs);color:var(--text-dim)">' + cmp.oppVal + unit + '</span></div>'
      + '</div>';
    var actions = c.status === 'finished' ? '' : '<button class="friend-req-btn accept" onclick="friendsShowChallengeStats(\'' + c.id + '\')" data-i18n="friends_view_stats_btn">📊 Statistika</button>';
    var cancelBtn = c.status === 'finished' ? '' : '<button class="friend-req-btn decline" onclick="friendsCancelChallenge(\'' + c.id + '\',false)" data-i18n="friends_cancel_btn">Bekor qilish</button>';
    return '<div class="friend-card" style="align-items:flex-start;flex-direction:column">'
      + '<div style="display:flex;width:100%;align-items:center;gap:10px">'
      + '<div class="friend-avatar">' + (c.opponentIcon || '⚔️') + '</div>'
      + '<div style="min-width:0;flex:1"><div class="friend-name">⚔️ ' + t('friends_you_label') + ' vs ' + esc(c.opponentName) + '</div><div class="friend-sub">' + sub + '</div></div>'
      + statusChip
      + '</div>'
      + body
      + '<div style="display:flex;gap:8px;width:100%">' + actions + cancelBtn + '</div>'
      + '</div>';
  }).join('');

  box.innerHTML = pendingHtml + mainHtml;
}

// ---------------- KUN-KUNLIK STATISTIKA MODALI ----------------
function friendsShowChallengeStats(id) {
  var c = (S.friends.challenges || []).find(function (x) { return x.id === id; });
  if (!c) return;
  var startStr = dateStrFromTs(c.startAt);
  var elapsedDays = Math.min(c.durationDays, Math.floor((Date.now() - c.startAt) / 86400000) + 1);
  var rows = '';
  for (var i = 0; i < elapsedDays; i++) {
    var dStr = addDays(startStr, i);
    var meD = c.me.dailyLog[dStr] || { due: 0, done: 0, coins: 0 };
    var opD = c.opp.dailyLog[dStr] || { due: 0, done: 0, coins: 0 };
    rows += '<tr>'
      + '<td style="padding:6px 4px;border-bottom:1px solid var(--border);color:var(--text-muted)">' + (i + 1) + '-' + t('friends_day_label') + '</td>'
      + '<td style="padding:6px 4px;border-bottom:1px solid var(--border)">' + meD.done + '/' + meD.due + ' · 🪙' + meD.coins + '</td>'
      + '<td style="padding:6px 4px;border-bottom:1px solid var(--border)">' + opD.done + '/' + opD.due + ' · 🪙' + opD.coins + '</td>'
      + '</tr>';
  }
  var cmp = friendsCompareChallenge(c);
  var unit = c.criteria === 'coins' ? ' 🪙' : (c.criteria === 'tasks' ? ' ' + t('friends_unit_tasks') : '%');
  var titleEl = document.getElementById('friends-challenge-stats-title');
  if (titleEl) titleEl.textContent = '⚔️ ' + t('friends_you_label') + ' vs ' + c.opponentName;
  var oppColEl = document.getElementById('friends-challenge-stats-opp-col');
  if (oppColEl) oppColEl.textContent = c.opponentName;
  var summaryEl = document.getElementById('friends-challenge-stats-summary');
  if (summaryEl) {
    summaryEl.innerHTML =
      '<div style="font-size:var(--fs-2xs);color:var(--text-dim);margin-bottom:8px">' + friendsCriteriaLabel(c.criteria) + ' · 🪙 ' + c.stake + ' · ' + (c.status === 'finished' ? '' : friendsTimeLeftLabel(c)) + '</div>'
      + '<div class="duel-vs-bar" style="margin-bottom:6px"><span style="width:60px;font-size:var(--fs-2xs);color:var(--text-muted)">' + t('friends_you_label') + '</span><div class="duel-progress-track"><div class="duel-progress-fill" style="width:' + Math.min(100, Math.max(0, cmp.meVal)) + '%;background:var(--accent)"></div></div><span style="font-size:var(--fs-2xs)">' + cmp.meVal + unit + '</span></div>'
      + '<div class="duel-vs-bar"><span style="width:60px;font-size:var(--fs-2xs);color:var(--text-muted)">' + esc(c.opponentName) + '</span><div class="duel-progress-track"><div class="duel-progress-fill" style="width:' + Math.min(100, Math.max(0, cmp.oppVal)) + '%;background:var(--gold)"></div></div><span style="font-size:var(--fs-2xs)">' + cmp.oppVal + unit + '</span></div>';
  }
  var rowsEl = document.getElementById('friends-challenge-stats-rows');
  if (rowsEl) rowsEl.innerHTML = rows || '<tr><td colspan="3" style="text-align:center;color:var(--text-dim);padding:14px 0">' + t('friends_no_stats_yet') + '</td></tr>';
  document.getElementById('friends-challenge-stats-overlay').classList.add('open');
}
function closeChallengeStatsModal() {
  document.getElementById('friends-challenge-stats-overlay').classList.remove('open');
}


// ---------------- MOCK STATISTIKA (id bo'yicha barqaror) ----------------
function _friendsHash(str) {
  var h = 0;
  for (var i = 0; i < str.length; i++) { h = (h << 5) - h + str.charCodeAt(i); h |= 0; }
  return Math.abs(h);
}
function friendsMockStats(id) {
  var h = _friendsHash(id);
  var subjPool = ['ielts', 'sat', 'cefr', 'other'];
  var subjects = [subjPool[h % subjPool.length]];
  if (h % 3 === 0) subjects.push(subjPool[(h + 1) % subjPool.length]);
  var daysAgo = 10 + (h % 500);
  return {
    xp: 200 + (h % 4000),
    coins: 50 + (h % 900),
    maxStreak: 3 + (h % 40),
    subjects: subjects,
    joinedDate: new Date(Date.now() - daysAgo * 86400000).toISOString().slice(0, 10)
  };
}

// ---------------- FOYDALANUVCHINI TOPISH / MUNOSABAT HOLATI ----------------
function friendsFindPersonById(id) {
  var pools = [S.friends.list, S.friends.incoming, S.friends.outgoing, S.friends.banned, _friendsSearchResults];
  for (var i = 0; i < pools.length; i++) {
    var arr = pools[i] || [];
    var f = arr.find(function (x) { return x.id === id; });
    if (f) return f;
  }
  return null;
}
function friendsRelationStatus(id) {
  if ((S.friends.banned || []).some(function (b) { return b.id === id; })) return 'banned';
  if ((S.friends.list || []).some(function (f) { return f.id === id; })) return 'friend';
  if ((S.friends.outgoing || []).some(function (o) { return o.id === id; })) return 'outgoing';
  if ((S.friends.incoming || []).some(function (r) { return r.id === id; })) return 'incoming';
  return 'stranger';
}

